# -*- coding: utf-8 -*-
"""
QUANT TERMINAL PRO — Single-file launcher/app
실행 방법:
  1) 더블클릭 또는: python quant_terminal_pro_single.py
  2) 필요한 패키지가 없으면 자동 설치 후 Streamlit으로 재실행합니다.
"""

# ──────────────────────────────────────────────────────────────
# SINGLE FILE BOOTSTRAP
# ──────────────────────────────────────────────────────────────
import os as _os
import sys as _sys
import subprocess as _subprocess
import importlib.util as _importlib_util


def _qt_has_module(module_name: str) -> bool:
    try:
        return _importlib_util.find_spec(module_name) is not None
    except Exception:
        return False


def _qt_pip_install(packages):
    if not packages:
        return True
    print("[QUANT TERMINAL] Installing missing packages:", ", ".join(packages))
    cmd = [_sys.executable, "-m", "pip", "install", "--upgrade"] + list(packages)
    try:
        return _subprocess.call(cmd) == 0
    except Exception as e:
        print("[QUANT TERMINAL] pip install failed:", e)
        return False


def _qt_bootstrap():
    """앱 구동에 필요한 모든 필수 라이브러리를 전수 검사하고, 미설치 시 100% 자동 설치를 완료한 후 실행합니다."""
    if _os.environ.get("QT_NO_BOOTSTRAP") == "1":
        return

    print("[QUANT TERMINAL] ===================================================")
    print("[QUANT TERMINAL] 🚀 인공지능 단말기 구동을 위한 라이브러리 검사 엔진 시작...")
    print("[QUANT TERMINAL] ===================================================")

    # 1. upgrade pip first to prevent older pip installation issues on Windows/Mac
    try:
        _subprocess.call([_sys.executable, "-m", "pip", "install", "--upgrade", "pip"], stdout=_subprocess.DEVNULL, stderr=_subprocess.DEVNULL)
    except Exception:
        pass

    required = [
        ("streamlit", "streamlit"),
        ("numpy", "numpy"),
        ("pandas", "pandas"),
        ("plotly", "plotly"),
        ("yfinance", "yfinance"),
        ("requests", "requests"),
        ("lxml", "lxml"),
        ("html5lib", "html5lib"),
        ("bs4", "beautifulsoup4"),
        ("reportlab", "reportlab"),
        ("qrcode", "qrcode"),
        ("pandas_market_calendars", "pandas-market-calendars"),
        ("kaleido", "kaleido"),
        ("FinanceDataReader", "finance-datareader"),
    ]

    missing = []
    for mod, pkg in required:
        if not _qt_has_module(mod):
            missing.append(pkg)
            print(f"[QUANT TERMINAL] ❌ 미설치 감지: {pkg} (설치 대기 중)")
        else:
            print(f"[QUANT TERMINAL]  완벽 설치: {pkg}")

    if missing:
        print("[QUANT TERMINAL] ⚙️ 미설치된 패키지들의 전량 자동 설치를 개시합니다...")
        ok = _qt_pip_install(missing)
        if not ok:
            print("\n[QUANT TERMINAL] 🛑 필수 패키지 자동 설치 도중 예상치 못한 오류가 발생했습니다.")
            print("[QUANT TERMINAL] 아래 명령어를 관리자 권한 터미널에 직접 입력하여 설치해 주세요:")
            print(f"   {_sys.executable} -m pip install -U " + " ".join(missing))
            input("[QUANT TERMINAL] 종료하려면 엔터를 누르세요...")
            _sys.exit(1)
        else:
            print("[QUANT TERMINAL] 🎉 모든 패키지 설치 완료! 검증 및 정규화 단계를 시작합니다.")

    print("[QUANT TERMINAL] ===================================================")
    print("[QUANT TERMINAL]  시스템 환경 양호. 인공지능 트레이딩 터미널 기동 준비 완료!")
    print("[QUANT TERMINAL] ===================================================")

    # Detect if already running inside Streamlit.
    running_in_streamlit = False
    try:
        from streamlit.runtime.scriptrunner import get_script_run_ctx as _qt_get_ctx
        running_in_streamlit = _qt_get_ctx() is not None
    except Exception:
        running_in_streamlit = False

    # If user double-clicked / ran python file, start Streamlit server.
    if not running_in_streamlit and _os.environ.get("QT_STREAMLIT_CHILD") != "1":
        print("[QUANT TERMINAL] ===================================================")
        print("[QUANT TERMINAL] Streamlit 독립 실행 서버를 구동합니다...")
        print("[QUANT TERMINAL] 로컬 웹 주소: http://localhost:8501")
        print(f"[QUANT TERMINAL] 실행 파일: {_os.path.abspath(__file__)}")
        print("[QUANT TERMINAL] ===================================================")
        print("[QUANT TERMINAL] 브라우저가 자동으로 열리지 않으면 위 주소를 직접 주소창에 입력하세요.")
        print("[QUANT TERMINAL] 종료하려면 콘솔에서 Ctrl+C를 누르세요.")
        print("")
        env = dict(_os.environ)
        env["QT_STREAMLIT_CHILD"] = "1"
        # 파일 경로에 공백/한글이 있어도 안전하게 처리 (리스트 형태 전달)
        file_path = _os.path.abspath(__file__)
        cmd = [_sys.executable, "-m", "streamlit", "run", file_path, "--server.port", "8501", "--server.headless", "false"]
        try:
            # Popen으로 실행하고 종료까지 대기, 출력은 실시간으로 보여줌
            import time
            proc = _subprocess.Popen(cmd, env=env)
            print(f"[QUANT TERMINAL] Streamlit 프로세스 시작됨 (PID: {proc.pid})")
            print("[QUANT TERMINAL] 브라우저 대기 중...")
            # 프로세스가 끝날 때까지 대기
            ret = proc.wait()
            print(f"[QUANT TERMINAL] Streamlit 프로세스가 종료되었습니다 (코드: {ret})")
            if ret != 0:
                print(f"[QUANT TERMINAL] ⚠️ Streamlit이 비정상 종료되었습니다. 코드: {ret}")
                print("[QUANT TERMINAL] 아래 명령어를 직접 실행해보세요:")
                print(f"  {_sys.executable} -m streamlit run \"{file_path}\" --server.port 8501")
                input("[QUANT TERMINAL] 종료하려면 엔터를 누르세요...")
            _sys.exit(ret)
        except FileNotFoundError as fe:
            print(f"[QUANT TERMINAL] ❌ Streamlit 실행 파일을 찾을 수 없습니다: {fe}")
            print(f"[QUANT TERMINAL] Python: {_sys.executable}")
            print(f"[QUANT TERMINAL] Streamlit 설치 시도: {_sys.executable} -m pip install -U streamlit")
            try:
                _subprocess.call([_sys.executable, "-m", "pip", "install", "-U", "streamlit"])
                print("[QUANT TERMINAL] 재시도 중...")
                ret = _subprocess.call(cmd, env=env)
                _sys.exit(ret)
            except Exception as e2:
                print(f"[QUANT TERMINAL] 재시도 실패: {e2}")
                input("[QUANT TERMINAL] 종료하려면 엔터를 누르세요...")
                _sys.exit(1)
        except Exception as e:
            print(f"[QUANT TERMINAL] ❌ 실행 중 오류 발생: {e}")
            import traceback
            traceback.print_exc()
            print("")
            print(f"[QUANT TERMINAL] 수동 실행 명령어:")
            print(f"  {_sys.executable} -m streamlit run \"{file_path}\" --server.port 8501")
            input("[QUANT TERMINAL] 종료하려면 엔터를 누르세요...")
            _sys.exit(1)


_qt_bootstrap()

# ──────────────────────────────────────────────────────────────
# APPLICATION CODE STARTS BELOW
# ──────────────────────────────────────────────────────────────

