def _normalize_date_str(d):
    try:
        s = str(d).strip().replace('/', '-')
        import pandas as pd
        dt = pd.to_datetime(s)
        return dt.strftime('%Y-%m-%d')
    except Exception:
        try:
            return str(d).replace('/', '-')
        except Exception:
            return d

_original_yf_download = yf.download
def _patched_yf_download(*args, **kwargs):
    try:
        if 'start' in kwargs and kwargs['start'] is not None:
            kwargs['start'] = _normalize_date_str(kwargs['start'])
        if 'end' in kwargs and kwargs['end'] is not None:
            kwargs['end'] = _normalize_date_str(kwargs['end'])
    except Exception:
        pass
    return _original_yf_download(*args, **kwargs)
yf.download = _patched_yf_download


