def esc(x: object) -> str:

    return html.escape(str(x), quote=True)

def html_block(content: str) -> str:

    """Multi-line HTML safety helper: removes leading indentation that can turn blocks into markdown code fences."""

    return textwrap.dedent(content).strip()

def render_html(content: str) -> None:

    st.markdown(html_block(content), unsafe_allow_html=True)

def render_kpi_cards(cards: List[Dict], cols_per_row: int = 6) -> None:

    """Native-first KPI renderer. Uses Streamlit containers/metrics for stability."""

    if not cards:

        return

    for i in range(0, len(cards), cols_per_row):

        row = cards[i:i + cols_per_row]

        cols = st.columns(len(row))

        for col, card in zip(cols, row):

            with col:

                with st.container(border=True):

                    title = str(card.get("title", ""))

                    help_text = str(card.get("help", ""))

                    mode = str(card.get("mode", "text"))

                    h1, h2 = st.columns([8, 1])

                    h1.markdown(f"<span style='font-size:0.9375rem;color:{P['txt2']};letter-spacing:-0.01em;font-weight:800;line-height:1.35'>{title}</span>", unsafe_allow_html=True)

                    if help_text:

                        with h2.popover("❓"):

                            st.markdown(f"**💡 {title}**")

                            cur_val = str(card.get("value", "")).strip()

                            if cur_val:

                                st.caption(f"현재 값: {cur_val}")

                            st.markdown(help_text, unsafe_allow_html=True)

                    if mode == "metric":

                        st.metric(

                            label=title,

                            value=str(card.get("value", "")),

                            delta=card.get("delta"),

                            label_visibility="collapsed",

                        )

                    else:

                        value = str(card.get("value", ""))

                        sub = str(card.get("sub", ""))

                        st.markdown(f"<div style='font-size: 1.125rem; font-weight: 850; color: {P['txt']}; margin: 4px 0; line-height: 1.2;'>{value}</div>", unsafe_allow_html=True)

                        if sub:

                            st.markdown(f"<span style='font-size:0.9375rem;color:{P['txt2']}'>{sub}</span>", unsafe_allow_html=True)

def htmlish_to_markdown(text: str) -> str:

    out = html.unescape(str(text))

    out = re.sub(r"<br\s*/?>", "\n\n", out, flags=re.IGNORECASE)

    out = re.sub(r"</?strong>", "**", out, flags=re.IGNORECASE)

    out = re.sub(r"</?b>", "**", out, flags=re.IGNORECASE)

    out = re.sub(r"<[^>]+>", "", out)

    out = re.sub(r"\n{3,}", "\n\n", out)

    return out.strip()

def render_section_title(title: str, caption: str = "") -> None:

    st.markdown(f"#### {title}")

    if caption:

        st.caption(caption)

def render_report_card(title: str, body: str, icon: str = "") -> None:

    with st.container(border=True):

        ttl = f"{icon} {title}".strip()

        st.markdown(f"**{ttl}**")

        st.markdown(htmlish_to_markdown(body))

def render_info_lines(title: str, lines: List[str], icon: str = "") -> None:

    with st.container(border=True):

        ttl = f"{icon} {title}".strip()

        st.markdown(f"**{ttl}**")

        for line in lines:

            st.markdown(f"- {line}")


