def _as_lines(value) -> List[str]:
    """문자열/리스트/None을 설명 패널용 문장 리스트로 정규화합니다."""
    if value is None:
        return []
    if isinstance(value, (list, tuple)):
        return [str(x) for x in value if str(x).strip()]
    text = str(value).strip()
    if not text:
        return []
    # HTML br 또는 줄바꿈이 있으면 항목으로 분리
    text = re.sub(r"<br\s*/?>", "\n", text, flags=re.IGNORECASE)
    return [x.strip(" -•	") for x in text.splitlines() if x.strip(" -•	")]


def render_chart_box_meaning_panel(chart_key: str, expanded: bool = True, technical_lines=None, opinion_lines=None, conclusion: str = "") -> None:
    """각 차트 바로 하단에 현재 차트의 의미·의견·기술적 분석 결과를 개별 표시합니다."""
    guide = CHART_BOX_MEANING_GUIDES.get(chart_key)
    if not guide:
        return
    tech = _as_lines(technical_lines)
    opinions = _as_lines(opinion_lines) or guide.get("message", [])
    with st.container(border=True):
        st.markdown(f"**🧾 {guide['title']} — 현재 차트 해석 노트**")
        st.markdown(f"**① 현재 차트의 의미**  \n{guide['intent']}")
        if conclusion:
            st.markdown(f"**② 한 줄 의견**  \n{conclusion}")
        if tech:
            st.markdown("**③ 현재 기술적 분석 결과**")
            for item in tech:
                st.markdown(f"- {item}")
        if opinions:
            st.markdown("**④ 투자자에게 하고 싶은 말**")
            for item in opinions:
                st.markdown(f"- {item}")
        with st.expander("박스와 풍선의 역할 자세히 보기", expanded=expanded):
            st.markdown("**박스/풍선의 역할**")
            for item in guide.get("boxes", []):
                st.markdown(f"- {item}")


def render_dashboard_cards(cards: List[Dict], cols_per_row: int = 3) -> None:

    if not cards:

        return

    for i in range(0, len(cards), cols_per_row):

        row = cards[i:i + cols_per_row]

        cols = st.columns(len(row))

        for col, card in zip(cols, row):

            with col:

                with st.container(border=True):

                    head_cols = st.columns([8, 1])

                    head_cols[0].markdown(f"**{card.get('icon', '•')} {card.get('title', '')}**")

                    if card.get("help"):

                        with head_cols[1].popover("❓"):

                            st.markdown(f"**💡 {card.get('title', '도움말')}**")

                            cur_val = str(card.get("value", "")).strip()

                            if cur_val:

                                st.caption(f"현재 값: {cur_val}")

                            st.markdown(str(card.get("help")), unsafe_allow_html=True)

                    value = str(card.get("value", ""))

                    st.subheader(value)

                    if card.get("caption"):

                        st.markdown(f"<span style='font-size:0.9375rem;color:{P['txt2']}'>{str(card.get('caption'))}</span>", unsafe_allow_html=True)

                    if card.get("status") == "good":

                        msg = str(card.get("message", ""))
                        if msg:
                            st.markdown(f"<div style='background:rgba(0,212,168,0.18);border:1px solid rgba(0,212,168,0.35);border-radius:8px;padding:0.3rem 0.55rem;color:{P['ok']};font-size:0.8125rem;font-weight:700'>{msg}</div>", unsafe_allow_html=True)

                    elif card.get("status") == "warn":

                        msg = str(card.get("message", ""))
                        if msg:
                            st.markdown(f"<div style='background:rgba(255,209,102,0.18);border:1px solid rgba(255,209,102,0.35);border-radius:8px;padding:0.3rem 0.55rem;color:{P['warn']};font-size:0.8125rem;font-weight:700'>{msg}</div>", unsafe_allow_html=True)

                    elif card.get("status") == "bad":

                        msg = str(card.get("message", ""))
                        if msg:
                            st.markdown(f"<div style='background:rgba(255,77,109,0.18);border:1px solid rgba(255,77,109,0.35);border-radius:8px;padding:0.3rem 0.55rem;color:{P['up']};font-size:0.8125rem;font-weight:700'>{msg}</div>", unsafe_allow_html=True)

                    elif card.get("message"):

                        msg = str(card.get("message"))
                        if msg:
                            st.markdown(f"<div style='background:rgba(99,179,237,0.12);border:1px solid rgba(99,179,237,0.25);border-radius:8px;padding:0.3rem 0.55rem;color:{P['accent']};font-size:0.8125rem;font-weight:700'>{msg}</div>", unsafe_allow_html=True)

def select_focus_fib_level(level_table: pd.DataFrame, current_price: float) -> Dict:

    if level_table is None or level_table.empty:

        return {}

    core = level_table[level_table["비율"].isin(["0.382", "0.500", "0.618"])].copy()

    if core.empty:

        core = level_table.copy()

    core["dist"] = (core["가격"].astype(float) - float(current_price)).abs() / (float(current_price) + 1e-9)

    core["focus_score"] = core["강도 점수"].astype(float) * 0.6 + core["반응 횟수"].astype(float) * 8 - core["dist"] * 1000

    row = core.sort_values(["focus_score", "강도 점수", "반응 횟수"], ascending=False).iloc[0]

    return {

        "ratio": str(row["비율"]),

        "price": float(row["가격"]),

        "role": str(row["역할"]),

        "touches": int(row["반응 횟수"]),

        "strength": float(row["강도 점수"]),

        "comment": str(row["해석"]),

    }

def build_today_briefing(display_name: str, regime: Dict, trend_ctx: Dict, trade_plan: Dict, fib_template: Dict, focus_fib: Dict, flow_bias: str, flow_has_data: bool) -> str:

    parts = [

        f"{display_name}는 현재 {regime['regime']} 구간",

        f"차트 구조는 {trend_ctx['structure']}",

        f"실전 시그널은 {trade_plan['signal_grade']}등급({trade_plan['action']})",

    ]

    if focus_fib:

        parts.append(f"지금 가장 중요한 피보 레벨은 {focus_fib['ratio']}({focus_fib['price']:,.0f})")

    parts.append(f"자동 템플릿은 {fib_template['name']}")

    if flow_has_data:

        parts.append(f"최근 수급은 {flow_bias}")

    return " · ".join(parts) + "."

def assess_portfolio_position(name: str, qty: int, avg: float, cur: float) -> Dict:

    pnl_pct = (cur / avg - 1) * 100 if avg > 0 else 0.0

    pnl_amt = (cur - avg) * qty

    if pnl_pct >= 15:

        grade, action = "A", "수익구간 확대. 일부 익절 후 추세 보유 검토"

        status = "good"

    elif pnl_pct >= 5:

        grade, action = "B", "양호한 수익구간. 손절 상향하며 보유"

        status = "good"

    elif pnl_pct > -5:

        grade, action = "C", "중립 구간. 방향 확정 전 비중 유지"

        status = "warn"

    elif pnl_pct > -12:

        grade, action = "D", "손실 관리 구간. 지지 확인 전 추가매수 신중"

        status = "warn"

    else:

        grade, action = "E", "대손실 구간. 방어·손절 우선 검토"

        status = "bad"

    return {

        "종목": name,

        "수량": qty,

        "평단": avg,

        "현재가": cur,

        "평가손익": pnl_amt,

        "수익률": pnl_pct,

        "등급": grade,

        "액션": action,

        "status": status,

    }

def detect_flow_divergence(ind: Dict) -> Dict:

    has_data = float(ind["foreign_net"].abs().sum() + ind["institution_net"].abs().sum()) > 0

    if not has_data or len(ind["close"]) < 20:

        return {"available": False, "type": "none", "message": "수급 divergence를 계산할 데이터가 부족합니다.", "severity": "info"}

    price = ind["close"].astype(float)

    p20 = float(price.pct_change(20).iloc[-1])
    p20_100 = p20 * 100

    smart_flow20 = float((ind["foreign_net"] + ind["institution_net"]).tail(20).sum())

    smart_flow5 = float((ind["foreign_net"] + ind["institution_net"]).tail(5).sum())

    if p20 >= 0.05 and smart_flow20 < 0:

        return {"available": True, "type": "bearish", "severity": "warn", "message": "가격은 최근 20봉 기준 상승했지만 외국인·기관 합산 수급은 순유출입니다. 가격 상승 대비 수급 약화(bearish divergence) 가능성을 의심할 수 있습니다.", "caption": f"가격 {p20_100:+.2f}% / 스마트수급 {abbreviate_num(smart_flow20)}"}

    if p20 <= -0.05 and smart_flow20 > 0:

        return {"available": True, "type": "bullish", "severity": "ok", "message": "가격은 최근 20봉 기준 약세지만 외국인·기관 합산 수급은 순유입입니다. 가격 하락 대비 수급 개선(bullish divergence) 가능성을 볼 수 있습니다.", "caption": f"가격 {p20_100:+.2f}% / 스마트수급 {abbreviate_num(smart_flow20)}"}

    if smart_flow5 > 0 and smart_flow20 <= 0:

        return {"available": True, "type": "turning_positive", "severity": "info", "message": "장기 수급은 약했지만 최근 5봉 기준 외국인·기관 수급이 개선되고 있습니다. 초기 수급 반전 가능성 체크 구간입니다.", "caption": f"최근5봉 {abbreviate_num(smart_flow5)} / 최근20봉 {abbreviate_num(smart_flow20)}"}

    return {"available": True, "type": "none", "severity": "info", "message": "가격과 외국인·기관 수급 사이에 뚜렷한 divergence는 약한 편입니다.", "caption": f"가격 {p20_100:+.2f}% / 스마트수급 {abbreviate_num(smart_flow20)}"}

def build_rebalance_suggestions(assessed_rows: List[Dict], total_val: float) -> Dict:

    if not assessed_rows or total_val <= 0:

        return {"cards": [], "rows": pd.DataFrame(), "summary": []}

    rows = []

    for r in assessed_rows:

        value = float(r["현재가"]) * int(r["수량"])

        weight = value / (total_val + 1e-9) * 100

        suggestion = "유지"

        if weight >= 40:

            suggestion = "과대비중 경고: 일부 비중 축소 검토"

        if r["등급"] in ["D", "E"] and weight >= 15:

            suggestion = "손실 확대 + 비중 큼: 축소/손절 우선 검토"

        elif r["등급"] in ["A", "B"] and weight >= 25:

            suggestion = "수익 구간 + 비중 큼: 일부 익절 후 분산 검토"

        elif r["등급"] in ["A", "B"] and weight < 10:

            suggestion = "우량 성과 대비 비중 낮음: 재배분 후보"

        rows.append({**r, "비중(%)": weight, "리밸런싱 제안": suggestion})

    df = pd.DataFrame(rows).sort_values(["등급", "비중(%)"], ascending=[True, False]).reset_index(drop=True)

    overweight = df[df["비중(%)"] >= 35]

    risk_positions = df[df["등급"].isin(["D", "E"])]

    winners = df[df["등급"].isin(["A", "B"])]

    cards = [

        {"icon": "⚖️", "title": "과대 비중 종목 수", "value": str(len(overweight)), "caption": "35% 이상 비중 기준", "help": "한 종목 쏠림이 심하면 계좌 변동성이 커질 수 있습니다.", "message": "과대 비중 종목은 일부 익절/축소 후 분산을 검토하는 것이 좋습니다.", "status": "warn" if len(overweight) > 0 else "good"},

        {"icon": "🛑", "title": "방어 우선 종목 수", "value": str(len(risk_positions)), "caption": "D/E 등급 기준", "help": "손실 관리가 우선되는 종목 수입니다.", "message": "등급이 낮고 비중이 큰 종목부터 먼저 점검하세요.", "status": "bad" if len(risk_positions) > 0 else "good"},

        {"icon": "🔄", "title": "재배분 후보 수", "value": str(len(winners)), "caption": "A/B 등급 기준", "help": "성과가 양호해 추가 비중 배분을 고려할 수 있는 종목 수입니다.", "message": "수익과 추세가 좋은 종목은 재배분 후보가 될 수 있습니다.", "status": "good" if len(winners) > 0 else "info"},

    ]

    summary = []

    if len(overweight) > 0:

        summary.append(f"과대비중 종목: {', '.join(overweight['종목'].astype(str).head(3))}")

    if len(risk_positions) > 0:

        summary.append(f"방어 우선 종목: {', '.join(risk_positions['종목'].astype(str).head(3))}")

    if len(winners) > 0:

        summary.append(f"재배분 후보 종목: {', '.join(winners['종목'].astype(str).head(3))}")

    return {"cards": cards, "rows": df, "summary": summary}

def build_institutional_memo(display_name: str, regime: Dict, trend_ctx: Dict, trade_plan: Dict, scenario: Dict, focus_fib: Dict, flow_div: Dict) -> Dict:

    investment_points = [

        f"현재 레짐은 {regime['regime']}이며 추세 구조는 {trend_ctx['structure']}입니다.",

        f"실전 시그널은 {trade_plan['signal_grade']}등급으로, 핵심 지지 {fmt_price(trade_plan['support1'])} / 저항 {fmt_price(trade_plan['resist1'])}이 분기점입니다.",

    ]

    if focus_fib:

        investment_points.append(f"현재 최중요 피보 레벨은 {focus_fib.get('ratio')} ({fmt_price(focus_fib.get('price', np.nan))})이며, {focus_fib.get('comment','')}.")

    if flow_div.get("available"):

        investment_points.append(flow_div.get("message", ""))

    risks = [

        f"손절 기준은 {fmt_price(trade_plan['stop'])}이며 이탈 시 기존 시나리오가 훼손될 수 있습니다.",

        f"하락 시나리오 확률은 {scenario['bear_prob']:.0f}%로, 지지 붕괴 시 변동성 확대를 감안해야 합니다.",

    ]

    if trend_ctx['rsi_state'] == '과열권':

        risks.append("RSI 과열 상태이므로 상단 비율대에서는 추격매수보다 분할익절/눌림대기가 유리할 수 있습니다.")

    elif trend_ctx['rsi_state'] == '과매도권':

        risks.append("과매도 상태라도 지지 확인 전 성급한 진입은 반등 실패 리스크가 있습니다.")

    checklist = [

        f"현재가가 {fmt_price(trade_plan['resist1'])} 상단에서 종가 안착하는지 확인",

        "거래량이 20봉 평균 대비 유지/증가하는지 확인",

        "외국인·기관 수급이 가격 방향과 동조하는지 확인",

        f"핵심 피보 레벨 {focus_fib.get('ratio','N/A')}의 지지/저항 반응 확인" if focus_fib else "핵심 피보 레벨 반응 확인",

    ]

    conclusion = "긍정적이나 확인 필요" if trade_plan['signal_grade'] in ['A', 'B'] else "중립적 접근 권고" if trade_plan['signal_grade'] == 'C' else "보수적 접근 권고"

    return {"investment_points": investment_points, "risks": risks, "checklist": checklist, "conclusion": conclusion}

def build_investment_rating(final_score: float, trade_plan: Dict, scenario: Dict, flow_div: Dict) -> Dict:

    bull = float(scenario.get('bull_prob', 33))

    bear = float(scenario.get('bear_prob', 33))

    signal = str(trade_plan.get('signal_grade', 'C'))

    divergence = str(flow_div.get('type', 'none'))

    if final_score >= 78 and signal in ['A', 'B'] and bull >= bear + 10 and divergence != 'bearish':

        grade, eng, desc = '강력매수', 'Strong Buy', '추세, 시나리오, 수급이 동시에 우호적입니다.'

    elif final_score >= 68 and signal in ['A', 'B'] and divergence != 'bearish':

        grade, eng, desc = '매수', 'Buy', '구조는 양호하나 추격보다는 눌림/확인 후 접근이 유리합니다.'

    elif final_score >= 55 and signal in ['B', 'C']:

        grade, eng, desc = '중립', 'Neutral', '방향성은 있으나 확인 신호가 더 필요합니다.'

    elif final_score >= 45:

        grade, eng, desc = '비중축소', 'Reduce', '구조는 불안정하며 비중 관리가 우선입니다.'

    else:

        grade, eng, desc = '매도우위', 'Sell', '방어 우선 구간입니다. 지지 붕괴 시 리스크 관리가 필요합니다.'

    return {"grade": grade, "eng": eng, "desc": desc}

