def refine_pattern_result(pattern_result: Dict, ind: Dict, current_price: float) -> Dict:

    if not pattern_result or not pattern_result.get('patterns'):

        return pattern_result

    ma20 = float(ind['ma20'].iloc[-1])

    ma60 = float(ind['ma60'].iloc[-1])

    macd = float(ind['macd'].iloc[-1])

    signal = float(ind['signal'].iloc[-1])

    vol_spike = float(ind['vol_ratio'].iloc[-1])

    close_above_ma = current_price > ma20 > ma60

    close_below_ma = current_price < ma20 < ma60

    for p in pattern_result['patterns']:

        conf = float(p.get('confidence', 60.0))

        direction = p.get('direction', '중립')

        breakout = p.get('breakout')

        invalid = p.get('invalidation')

        if direction == '상승':

            if close_above_ma: conf += 4

            if macd > signal: conf += 3

            if vol_spike > 1.2: conf += 2

            if breakout is not None and current_price >= float(breakout): conf += 5

            if invalid is not None and current_price <= float(invalid): conf -= 8

        elif direction == '하락':

            if close_below_ma: conf += 4

            if macd < signal: conf += 3

            if vol_spike > 1.2: conf += 2

            if breakout is not None and current_price <= float(breakout): conf += 5

            if invalid is not None and current_price >= float(invalid): conf -= 8

        else:

            conf += 1 if vol_spike > 1.1 else 0

        p['confidence'] = float(np.clip(conf, 20, 95))

        p['comment'] = p.get('comment', p.get('summary', ''))

        p['strategy'] = _pattern_strategy(p)

    pattern_result['patterns'] = sorted(

        pattern_result['patterns'],

        key=lambda x: (PATTERN_STAGE_RANK.get(x.get('stage', x.get('status', '관찰')), 9), -float(x.get('freshness', 0)), -float(x.get('confidence', 0))),

    )

    pattern_result['best'] = pattern_result['patterns'][0] if pattern_result['patterns'] else None

    return pattern_result

def compute_confluence_score_original(ind: Dict, regime: Dict, trade_plan: Dict, focus_fib: Dict, flow_div: Dict, best_pattern: Optional[Dict], factors: Dict) -> Dict:

    score = 50.0

    reasons = []

    if float(ind['close'].iloc[-1]) > float(ind['ma20'].iloc[-1]):

        score += 6; reasons.append('현재가가 MA20 위')

    if float(ind['ma20'].iloc[-1]) > float(ind['ma60'].iloc[-1]):

        score += 6; reasons.append('MA20 > MA60')

    if factors['macd'] > factors['signal']:

        score += 5; reasons.append('MACD 상방 우위')

    if factors['vol_spike'] > 1.2:

        score += 4; reasons.append('거래량 증가')

    if regime['trend_score'] >= 4:

        score += 6; reasons.append('추세점수 우수')

    if focus_fib:

        if str(focus_fib.get('ratio')) in ['0.618', '0.500', '0.382']:

            score += 5; reasons.append(f"핵심 Fib {focus_fib.get('ratio')} 반응권")

        if float(focus_fib.get('strength', 0)) >= 60:

            score += 5; reasons.append('피보 강도 높음')

    if best_pattern:

        _fresh_w = float(best_pattern.get('freshness', 100)) / 100.0

        _stage = best_pattern.get('stage', best_pattern.get('status', '관찰'))

        if _stage in ('소진', '만료'):

            _fresh_w *= 0.3

        score += min(float(best_pattern.get('confidence', 0)) * 0.12, 10) * _fresh_w

        reasons.append(f"대표 패턴 {best_pattern.get('name')}({_stage})")

        if best_pattern.get('direction') == '상승':

            score += 4 * _fresh_w

        elif best_pattern.get('direction') == '하락':

            score -= 4 * _fresh_w

    if flow_div.get('type') == 'bullish':

        score += 7; reasons.append('수급 Bullish divergence')

    elif flow_div.get('type') == 'bearish':

        score -= 8; reasons.append('수급 Bearish divergence')

    score = float(np.clip(score, 0, 100))

    label = '매우 강함' if score >= 80 else '양호' if score >= 65 else '보통' if score >= 50 else '주의'

    return {'score': score, 'label': label, 'reasons': reasons[:5]}


# ══════════════════════════════════════════════════════════════
# Phase 2 — 확률 기반 스코어링 모듈
# ══════════════════════════════════════════════════════════════

def _sigmoid(x: float) -> float:
    import math
    try:
        if x >= 0:
            return 1.0 / (1.0 + math.exp(-x))
        else:
            e = math.exp(x)
            return e / (1.0 + e)
    except Exception:
        return 0.5

def build_prob_feature_matrix(df: pd.DataFrame, ind: Dict, main_fib: Optional[Dict] = None) -> pd.DataFrame:
    """
    과거 데이터 기반 확률 모델을 위한 피처 매트릭스 생성.
    각 바(bar)마다 불리언/수치 피처를 추출하여 forward return 예측에 사용.
    기존 calc_rsi, calc_macd 등 지표 함수는 ind에 이미 계산된 결과를 재사용.
    """
    try:
        close = ind["close"].astype(float).reindex(df.index)
        high = df["High"].astype(float).reindex(df.index)
        low = df["Low"].astype(float).reindex(df.index)
        open_ = df["Open"].astype(float).reindex(df.index)
        vol = df["Volume"].astype(float).fillna(0).reindex(df.index)

        ma20 = ind["ma20"].astype(float).reindex(df.index)
        ma60 = ind["ma60"].astype(float).reindex(df.index)
        ma120 = ind.get("ma120", close.rolling(120, min_periods=30).mean()).astype(float).reindex(df.index) if "ma120" in ind else close.rolling(120, min_periods=30).mean().reindex(df.index)
        macd = ind["macd"].astype(float).reindex(df.index)
        sig = ind["signal"].astype(float).reindex(df.index)
        rsi = ind["rsi"].astype(float).reindex(df.index)
        vol_ratio = ind["vol_ratio"].astype(float).reindex(df.index).fillna(0)
        atr = ind["atr"].astype(float).reindex(df.index).fillna(method="ffill").fillna(0)
        adx = ind.get("adx", pd.Series(20, index=df.index)).astype(float).reindex(df.index).fillna(20)
        plus_di = ind.get("plus_di", pd.Series(20, index=df.index)).astype(float).reindex(df.index).fillna(20)
        minus_di = ind.get("minus_di", pd.Series(20, index=df.index)).astype(float).reindex(df.index).fillna(20)

        foreign_net = ind.get("foreign_net", pd.Series(0, index=df.index)).astype(float).reindex(df.index).fillna(0)
        institution_net = ind.get("institution_net", pd.Series(0, index=df.index)).astype(float).reindex(df.index).fillna(0)
        smart_net = foreign_net + institution_net
        smart_5 = smart_net.rolling(5, min_periods=1).sum()

        ema20 = close.ewm(span=20, adjust=False, min_periods=1).mean()
        ema60 = close.ewm(span=60, adjust=False, min_periods=1).mean()

        conversion = (high.rolling(9, min_periods=5).max() + low.rolling(9, min_periods=5).min()) / 2.0
        base_line = (high.rolling(26, min_periods=10).max() + low.rolling(26, min_periods=10).min()) / 2.0
        ichimoku_cross_up = (conversion > base_line) & (conversion.shift(1) <= base_line.shift(1))

        prior_high_20 = high.rolling(20, min_periods=5).max().shift(1)
        prior_low_20 = low.rolling(20, min_periods=5).min().shift(1)

        high_60 = high.rolling(60, min_periods=10).max().shift(1)
        low_60 = low.rolling(60, min_periods=10).min().shift(1)
        range_60 = high_60 - low_60

        # Fib 지지 반응 근사: low가 fib 레벨(0.382,0.5,0.618) 근처에서 반등
        fib_reaction = pd.Series(False, index=df.index)
        try:
            for ratio in [0.382, 0.500, 0.618]:
                level = high_60 - range_60 * ratio
                cond = (low <= level * 1.015) & (close >= level) & (close >= open_) & (range_60 > 0)
                fib_reaction = fib_reaction | cond.fillna(False)
        except Exception:
            pass

        # 피처 정의
        feats = pd.DataFrame(index=df.index)
        feats["price_above_ma20"] = (close > ma20).astype(int)
        feats["ma20_above_ma60"] = (ma20 > ma60).astype(int)
        feats["ma60_above_ma120"] = (ma60 > ma120).astype(int)
        feats["close_above_ema20"] = (close > ema20).astype(int)
        feats["ema20_above_ema60"] = (ema20 > ema60).astype(int)
        feats["macd_up"] = (macd > sig).astype(int)
        feats["rsi_healthy"] = ((rsi >= 45) & (rsi <= 68)).astype(int)
        feats["rsi_oversold"] = (rsi <= 35).astype(int)
        feats["rsi_overheat"] = (rsi >= 75).astype(int)
        feats["rsi_rebound"] = ((rsi.shift(1) <= 38) & (rsi > 38)).astype(int)
        feats["vol_spike"] = (vol_ratio > 1.2).astype(int)
        feats["vol_spike_strong"] = (vol_ratio >= 2.0).astype(int)
        feats["vol_dry"] = (vol_ratio < 0.55).astype(int)
        feats["trend_breakout"] = ((close >= prior_high_20 * 0.995) & (ma20 > ma60)).astype(int)
        feats["trend_pullback"] = ((low <= ma20 * 1.03) & (close >= ma20 * 0.995) & (ma20 > ma60)).astype(int)
        feats["ichimoku_cross"] = ichimoku_cross_up.astype(int)
        feats["fib_reaction"] = fib_reaction.astype(int)
        # Fib 위치 근사
        try:
            curr_ratio = (close - low_60) / (range_60 + 1e-9)
            feats["fib_golden_zone"] = ((curr_ratio >= 0.5) & (curr_ratio <= 0.786)).astype(int)
            feats["fib_weak_zone"] = (curr_ratio < 0.382).astype(int)
        except Exception:
            feats["fib_golden_zone"] = 0
            feats["fib_weak_zone"] = 0

        feats["flow_inflow_5d"] = (smart_5 > 0).astype(int)
        feats["flow_outflow_5d"] = (smart_5 < 0).astype(int)
        # ADX 기반 추세 강도
        feats["adx_strong"] = (adx > 22).astype(int)
        feats["adx_very_strong"] = (adx > 25).astype(int)
        # DMI
        feats["dmi_plus_gt_minus"] = (plus_di > minus_di).astype(int)
        feats["dmi_minus_low"] = (minus_di < 10).astype(int)

        # ── [ADVANCED v2] 신규 고승률 피처 ──
        try:
            fisher = ind.get("fisher", pd.Series(0, index=df.index)).astype(float).reindex(df.index).fillna(0)
            fisher_sig = ind.get("fisher_signal", pd.Series(0, index=df.index)).astype(float).reindex(df.index).fillna(0)
            feats["fisher_bull_cross"] = ((fisher > fisher_sig) & (fisher.shift(1) <= fisher_sig.shift(1))).astype(int)
            feats["fisher_oversold_rebound"] = ((fisher < -1.5) & (fisher > fisher.shift(1))).astype(int)
        except Exception:
            feats["fisher_bull_cross"] = 0
            feats["fisher_oversold_rebound"] = 0

        try:
            kama = ind.get("kama", close.ewm(span=21).mean()).astype(float).reindex(df.index).fillna(method='ffill')
            feats["price_above_kama"] = (close > kama).astype(int)
            feats["kama_rising"] = (kama > kama.shift(3)).astype(int)
        except Exception:
            feats["price_above_kama"] = 0
            feats["kama_rising"] = 0

        try:
            chop = ind.get("chop", pd.Series(50, index=df.index)).astype(float).reindex(df.index).fillna(50)
            feats["chop_trending"] = (chop < 38.2).astype(int)
            feats["chop_choppy"] = (chop > 61.8).astype(int)
            feats["chop_trend_start"] = ((chop.shift(1) > 50) & (chop < 38.2)).astype(int)
        except Exception:
            feats["chop_trending"] = 0
            feats["chop_choppy"] = 0
            feats["chop_trend_start"] = 0

        try:
            er = ind.get("er", pd.Series(0.5, index=df.index)).astype(float).reindex(df.index).fillna(0.5)
            feats["er_strong_trend"] = (er > 0.6).astype(int)
            feats["er_weak_trend"] = (er < 0.25).astype(int)
        except Exception:
            feats["er_strong_trend"] = 0
            feats["er_weak_trend"] = 0

        try:
            connors = ind.get("connors_rsi", pd.Series(50, index=df.index)).astype(float).reindex(df.index).fillna(50)
            feats["connors_oversold"] = (connors < 20).astype(int)
            feats["connors_overbought"] = (connors > 80).astype(int)
            feats["connors_bull_rebound"] = ((connors.shift(1) < 20) & (connors > 20)).astype(int)
        except Exception:
            feats["connors_oversold"] = 0
            feats["connors_overbought"] = 0
            feats["connors_bull_rebound"] = 0

        try:
            vwap = ind.get("vwap", close).astype(float).reindex(df.index)
            vwap_u = ind.get("vwap_upper", vwap).astype(float).reindex(df.index)
            vwap_l = ind.get("vwap_lower", vwap).astype(float).reindex(df.index)
            feats["price_above_vwap"] = (close > vwap).astype(int)
            feats["vwap_band_breakout"] = (close > vwap_u).astype(int)
            feats["vwap_band_bounce"] = ((low < vwap_l) & (close > vwap_l)).astype(int)
        except Exception:
            feats["price_above_vwap"] = 0
            feats["vwap_band_breakout"] = 0
            feats["vwap_band_bounce"] = 0

        try:
            # 유동성 스윕: 최근 5봉 내 발생 시 단기 반전 확률 상승
            sweeps = ind.get("liquidity_sweeps")
            if isinstance(sweeps, pd.DataFrame) and not sweeps.empty and "date" in sweeps.columns:
                recent_bull = sweeps[sweeps["type"]=="bull_sweep"]["date"].tail(5)
                recent_bear = sweeps[sweeps["type"]=="bear_sweep"]["date"].tail(5)
                feats["bull_sweep_recent"] = df.index.isin(recent_bull).astype(int)
                feats["bear_sweep_recent"] = df.index.isin(recent_bear).astype(int)
            else:
                feats["bull_sweep_recent"] = 0
                feats["bear_sweep_recent"] = 0
        except Exception:
            feats["bull_sweep_recent"] = 0
            feats["bear_sweep_recent"] = 0

        try:
            # FVG/OB
            smc = ind.get("smc_fvg_ob")
            if isinstance(smc, dict):
                feats["fvg_bull_exists"] = 1 if len(smc.get("fvg_bull", []))>0 else 0
                feats["fvg_bear_exists"] = 1 if len(smc.get("fvg_bear", []))>0 else 0
            else:
                feats["fvg_bull_exists"] = 0
                feats["fvg_bear_exists"] = 0
        except Exception:
            feats["fvg_bull_exists"] = 0
            feats["fvg_bear_exists"] = 0

        # ── [ADVANCED v3] CVD, OF, Hurst, Kalman 등
        try:
            cvd = ind.get("cvd", pd.Series(0, index=df.index)).astype(float).reindex(df.index).fillna(0)
            feats["cvd_rising"] = (cvd > cvd.shift(5)).astype(int)
            feats["cvd_falling"] = (cvd < cvd.shift(5)).astype(int)
        except Exception:
            feats["cvd_rising"] = 0
            feats["cvd_falling"] = 0

        try:
            of_imb = ind.get("of_imbalance", pd.Series(1.0, index=df.index)).astype(float).reindex(df.index).fillna(1.0)
            feats["of_bull_strong"] = (of_imb > 1.5).astype(int)
            feats["of_bear_strong"] = (of_imb < 0.7).astype(int)
        except Exception:
            feats["of_bull_strong"] = 0
            feats["of_bear_strong"] = 0

        try:
            kalman = ind.get("kalman_trend", close).astype(float).reindex(df.index)
            kalman_vel = ind.get("kalman_vel", pd.Series(0, index=df.index)).astype(float).reindex(df.index)
            feats["price_above_kalman"] = (close > kalman).astype(int)
            feats["kalman_vel_positive"] = (kalman_vel > 0).astype(int)
        except Exception:
            feats["price_above_kalman"] = 0
            feats["kalman_vel_positive"] = 0

        try:
            hurst = ind.get("hurst", 0.5)
            # hurst가 Series가 아니면 float -> 전체 동일 값으로 처리
            if isinstance(hurst, (float, int)):
                feats["hurst_trending"] = 1 if float(hurst) > 0.6 else 0
                feats["hurst_mean_reverting"] = 1 if float(hurst) < 0.4 else 0
            else:
                h_s = pd.Series(hurst, index=df.index).astype(float).fillna(0.5)
                feats["hurst_trending"] = (h_s > 0.6).astype(int)
                feats["hurst_mean_reverting"] = (h_s < 0.4).astype(int)
        except Exception:
            feats["hurst_trending"] = 0
            feats["hurst_mean_reverting"] = 0

        try:
            pd_zones = ind.get("pd_zones", {})
            if isinstance(pd_zones, dict) and pd_zones.get("mid") and np.isfinite(pd_zones["mid"]):
                mid = float(pd_zones["mid"])
                feats["in_discount_zone"] = (close < mid).astype(int)
                feats["in_premium_zone"] = (close > mid).astype(int)
            else:
                feats["in_discount_zone"] = 0
                feats["in_premium_zone"] = 0
        except Exception:
            feats["in_discount_zone"] = 0
            feats["in_premium_zone"] = 0

        try:
            eqh_eql = ind.get("eqh_eql", {})
            feats["eqh_exists"] = 1 if len(eqh_eql.get("eqh",[]))>0 else 0
            feats["eql_exists"] = 1 if len(eqh_eql.get("eql",[]))>0 else 0
        except Exception:
            feats["eqh_exists"] = 0
            feats["eql_exists"] = 0

        try:
            breakers = ind.get("breaker_blocks", {})
            feats["bull_breaker_exists"] = 1 if any(b.get("type")=="bull_breaker" for b in breakers.get("breakers",[])) else 0
            feats["bear_breaker_exists"] = 1 if any(b.get("type")=="bear_breaker" for b in breakers.get("breakers",[])) else 0
        except Exception:
            feats["bull_breaker_exists"] = 0
            feats["bear_breaker_exists"] = 0

        # NA 처리
        feats = feats.fillna(0).astype(int)
        return feats
    except Exception as e:
        # 실패 시 빈 프레임
        return pd.DataFrame()

def calc_forward_hit_rates(df: pd.DataFrame, ind: Dict, forward_n: int = 10) -> Dict:
    """
    각 조건(피처)이 과거 N년간 발생했을 때 N봉 후 수익률이 플러스였던 비율 계산.
    반환: {feature_name: hit_rate}
    """
    try:
        feats = build_prob_feature_matrix(df, ind)
        if feats.empty or len(feats) < forward_n + 20:
            return {}
        close = ind["close"].astype(float).reindex(df.index)
        # forward return
        fwd_ret = (close.shift(-forward_n) / close - 1.0)
        # label: 1 if positive
        hit_rates = {}
        for col in feats.columns:
            mask = feats[col] == 1
            # forward return가 NaN인 마지막 N봉 제외
            valid = mask & fwd_ret.notna()
            if valid.sum() < 20:
                continue
            positive = (fwd_ret[valid] > 0).sum()
            total = valid.sum()
            hit_rates[col] = float(positive / total) if total > 0 else 0.5
        return hit_rates
    except Exception:
        return {}

@st.cache_data(show_spinner=False, ttl=3600)  # [P1] 순수연산 캐시 — 결과 dict/df는 picklable, TTL 내 재호출 시 재계산 생략
def train_probability_model(df: pd.DataFrame, ind: Dict, main_fib: Optional[Dict] = None,
                            forward_n: int = 10, model_type: str = "logistic") -> Dict:
    """
    과거 데이터 기반 로지스틱 회귀 / GBM 모델 학습.
    - 피처: build_prob_feature_matrix
    - 라벨: forward_n 봉 후 수익률 > 0 ?
    - 반환: 모델 메타 (coef, intercept, feature_names, hit_rates, train_accuracy 등)
    scikit-learn 필요. 없으면 hit_rates만 반환하는 fallback.
    """
    result = {
        "available": False,
        "feature_names": [],
        "coef": [],
        "intercept": 0.0,
        "hit_rates": {},
        "train_accuracy": 0.0,
        "n_samples": 0,
        "forward_n": forward_n,
        "model_type": model_type,
        "trained_at": datetime.now().isoformat() if 'datetime' in globals() else str(pd.Timestamp.now()),
    }
    try:
        feats = build_prob_feature_matrix(df, ind, main_fib)
        if feats.empty:
            return result
        close = ind["close"].astype(float).reindex(df.index)
        fwd_ret = (close.shift(-forward_n) / close - 1.0)
        # y: 1 if forward return > 0
        y = (fwd_ret > 0).astype(int)

        # 유효 데이터만 (forward NaN 제외, feat NaN 제외)
        valid_idx = feats.index[feats.notna().all(axis=1) & y.notna()]
        # 최소 100개 필요
        if len(valid_idx) < 100:
            # hit_rates만 계산
            result["hit_rates"] = calc_forward_hit_rates(df, ind, forward_n)
            return result

        X = feats.loc[valid_idx]
        y_valid = y.loc[valid_idx]

        # hit_rates 계산
        hit_rates = {}
        for col in X.columns:
            mask = X[col] == 1
            if mask.sum() >= 20:
                hit_rates[col] = float(y_valid[mask].mean())
        result["hit_rates"] = hit_rates

        # sklearn 시도
        try:
            from sklearn.linear_model import LogisticRegression
            from sklearn.ensemble import GradientBoostingClassifier
            from sklearn.model_selection import train_test_split
            from sklearn.metrics import accuracy_score
        except ImportError as ie:
            # sklearn 없으면 pip 설치 시도 정보 반환, hit_rates로 fallback
            result["available"] = False
            result["error"] = f"sklearn 미설치: {ie}"
            return result

        # 모델 선택
        if model_type == "gbm":
            clf = GradientBoostingClassifier(random_state=42)
        else:
            clf = LogisticRegression(max_iter=1000, class_weight="balanced", solver="lbfgs")

        clf.fit(X, y_valid)

        # 정확도
        try:
            y_pred = clf.predict(X)
            acc = float((y_pred == y_valid).mean())
        except Exception:
            acc = 0.5

        # 계수 추출
        if hasattr(clf, "coef_"):
            coef = clf.coef_[0].tolist()
            intercept = float(clf.intercept_[0]) if hasattr(clf, "intercept_") else 0.0
        else:
            # GBM은 coef_ 없음, feature_importances_ 사용
            if hasattr(clf, "feature_importances_"):
                # GBM: coef를 importance로 근사, intercept 0
                coef = clf.feature_importances_.tolist()
                intercept = 0.0
                # GBM은 확률 예측 가능하므로 모델 객체도 저장 시도? 여기선 coef만 저장
            else:
                coef = []
                intercept = 0.0

        result.update({
            "available": True,
            "feature_names": X.columns.tolist(),
            "coef": coef,
            "intercept": intercept,
            "train_accuracy": acc,
            "n_samples": len(X),
            "model_type": model_type,
        })
        return result
    except Exception as e:
        result["error"] = str(e)[:300]
        return result

def _predict_prob_with_model(feature_vec: Dict, model_meta: Dict) -> Tuple[float, float, float]:
    """
    학습된 모델 메타로 현재 피처 벡터의 상승 확률 예측 + 신뢰구간 근사.
    반환: (p, lower, upper)
    """
    try:
        feat_names = model_meta.get("feature_names", [])
        coef = model_meta.get("coef", [])
        intercept = float(model_meta.get("intercept", 0.0))
        n_samples = int(model_meta.get("n_samples", 100))
        if not feat_names or not coef or len(feat_names) != len(coef):
            # hit_rates 기반 fallback
            hit_rates = model_meta.get("hit_rates", {})
            active_rates = []
            for k, v in feature_vec.items():
                if v == 1 and k in hit_rates:
                    active_rates.append(hit_rates[k])
            if active_rates:
                p = float(np.mean(active_rates))
            else:
                p = 0.5
        else:
            # 로지스틱
            logit = intercept
            for i, fname in enumerate(feat_names):
                fv = feature_vec.get(fname, 0)
                logit += coef[i] * fv
            p = _sigmoid(logit)

        # 신뢰구간: binomial SE 근사
        import math
        se = math.sqrt(p * (1 - p) / max(n_samples, 1))
        z = 1.96
        lower = max(0.0, p - z * se)
        upper = min(1.0, p + z * se)
        # 학습 정확도가 낮으면 구간 넓힘
        acc = float(model_meta.get("train_accuracy", 0.5))
        if acc < 0.55:
            width = (upper - lower) * 1.5
            mid = p
            lower = max(0.0, mid - width/2)
            upper = min(1.0, mid + width/2)
        return float(p), float(lower), float(upper)
    except Exception:
        return 0.5, 0.3, 0.7

def compute_confluence_score_with_prob(df: pd.DataFrame, ind: Dict, regime: Dict, trade_plan: Dict,
                                       focus_fib: Dict, flow_div: Dict, best_pattern: Optional[Dict],
                                       factors: Dict, main_fib: Optional[Dict] = None,
                                       prob_model: Optional[Dict] = None,
                                       forward_n: int = 10) -> Dict:
    """
    확률 기반 컨플루언스 점수.
    - prob_model이 있으면 해당 모델로 상승 확률 예측
    - 없으면 hit_rates 평균으로 확률 근사
    - 기존 점수(0~100) 대신 확률(%) + 신뢰구간 반환, 등급 문구는 확률 구간에 맞춰 유지
    """
    try:
        # 기존 하드코딩 점수 계산 (fallback 및 reasons용)
        base = compute_confluence_score_original(ind, regime, trade_plan, focus_fib, flow_div, best_pattern, factors) if 'compute_confluence_score_original' in globals() else {"score": 50.0, "label": "보통", "reasons": []}

        # 피처 매트릭스에서 현재 bar 피처 추출
        feats_df = build_prob_feature_matrix(df, ind, main_fib)
        if feats_df.empty:
            # 기존 점수를 확률로 변환하여 반환
            p = float(base["score"] / 100.0)
            lower, upper = max(0.0, p-0.15), min(1.0, p+0.15)
            return {
                "score": float(base["score"]),
                "prob": p,
                "prob_ci_lower": lower,
                "prob_ci_upper": upper,
                "prob_percent": round(p*100,1),
                "label": base["label"],
                "reasons": base["reasons"],
                "model_used": False,
                "feature_vector": {},
                "hit_rates": {},
            }

        last_feat = feats_df.iloc[-1].to_dict()

        # 모델이 없으면 학습 시도 없이 hit_rates로 계산
        if prob_model is None or not prob_model.get("available"):
            # hit_rates 계산
            hit_rates = calc_forward_hit_rates(df, ind, forward_n)
            active = [k for k, v in last_feat.items() if v == 1]
            active_rates = [hit_rates.get(k, 0.5) for k in active if k in hit_rates]
            if active_rates:
                p = float(np.mean(active_rates))
            else:
                # 기존 점수 기반
                p = float(base["score"] / 100.0)
            import math
            se = math.sqrt(p*(1-p)/max(len(feats_df), 100))
            lower = max(0.0, p - 1.96*se)
            upper = min(1.0, p + 1.96*se)
            # 라벨은 확률 기준으로 재매핑
            score_from_prob = p*100
            label = "매우 강함" if score_from_prob >= 80 else "양호" if score_from_prob >= 65 else "보통" if score_from_prob >= 50 else "주의"
            return {
                "score": float(score_from_prob),
                "prob": p,
                "prob_ci_lower": lower,
                "prob_ci_upper": upper,
                "prob_percent": round(p*100,1),
                "label": label,
                "reasons": base["reasons"][:5],
                "model_used": False,
                "feature_vector": last_feat,
                "hit_rates": hit_rates,
            }

        # 모델 있음 -> 예측
        p, lower, upper = _predict_prob_with_model(last_feat, prob_model)
        score_from_prob = p*100
        label = "매우 강함" if score_from_prob >= 80 else "양호" if score_from_prob >= 65 else "보통" if score_from_prob >= 50 else "주의"

        # reasons: 계수가 높고 현재 활성화된 피처 중 hit_rate 높은 순
        hit_rates = prob_model.get("hit_rates", {})
        feat_names = prob_model.get("feature_names", [])
        coef = prob_model.get("coef", [])
        # coef와 함께 정렬
        scored_features = []
        for i, fname in enumerate(feat_names):
            if last_feat.get(fname, 0) == 1:
                c = coef[i] if i < len(coef) else 0.0
                hr = hit_rates.get(fname, 0.5)
                scored_features.append((fname, c, hr))
        scored_features.sort(key=lambda x: (x[1], x[2]), reverse=True)
        reasons = [f"{name} (기여 {coef_v:.2f}, 적중 {hr*100:.0f}%)" for name, coef_v, hr in scored_features[:4]]
        if not reasons:
            reasons = base["reasons"][:4]

        return {
            "score": float(score_from_prob),
            "prob": p,
            "prob_ci_lower": lower,
            "prob_ci_upper": upper,
            "prob_percent": round(p*100,1),
            "label": label,
            "reasons": reasons,
            "model_used": True,
            "feature_vector": last_feat,
            "hit_rates": hit_rates,
            "model_meta": prob_model,
        }
    except Exception as e:
        # 폴백
        try:
            base = compute_confluence_score_original(ind, regime, trade_plan, focus_fib, flow_div, best_pattern, factors) if 'compute_confluence_score_original' in globals() else {"score":50.0,"label":"보통","reasons":[]}
            p = base["score"]/100.0
            return {"score":base["score"],"prob":p,"prob_ci_lower":max(0,p-0.15),"prob_ci_upper":min(1,p+0.15),"prob_percent":round(p*100,1),"label":base["label"],"reasons":base["reasons"],"model_used":False,"error":str(e)[:200]}
        except Exception:
            return {"score":50.0,"prob":0.5,"prob_ci_lower":0.35,"prob_ci_upper":0.65,"prob_percent":50.0,"label":"보통","reasons":[],"model_used":False,"error":str(e)[:200]}

def compute_elite_priority_model_with_prob(df: pd.DataFrame, ind: Dict, main_fib: Dict, trade_plan: Dict,
                                           flow_has_data: bool, flow_bias: str, strictness: int = 2,
                                           prob_model: Optional[Dict] = None, forward_n: int = 10) -> Dict:
    """
    확률 기반 엘리트 우선순위 모델.
    - 기존 점수 대신 상승 확률(%) + 신뢰구간 반환
    - 등급 문구(엘리트 매수우위 등)는 확률 구간에 맞춰 유지
    """
    try:
        # 기존 모델 (fallback)
        base = compute_elite_priority_model_original(df, ind, main_fib, trade_plan, flow_has_data, flow_bias, strictness) if 'compute_elite_priority_model_original' in globals() else {"score":50.0,"grade":"엘리트 중립","action":"방향 확인 대기","status":"info","strong_buy":False,"strong_sell":False,"buy_points":[],"sell_points":[],"neutral_points":[]}

        feats_df = build_prob_feature_matrix(df, ind, main_fib)
        if feats_df.empty:
            p = float(base["score"]/100.0)
            lower, upper = max(0.0, p-0.15), min(1.0, p+0.15)
            return {**base, "prob": p, "prob_ci_lower": lower, "prob_ci_upper": upper, "prob_percent": round(p*100,1), "model_used": False}

        last_feat = feats_df.iloc[-1].to_dict()

        if prob_model is None or not prob_model.get("available"):
            hit_rates = calc_forward_hit_rates(df, ind, forward_n)
            active = [k for k, v in last_feat.items() if v==1]
            active_rates = [hit_rates.get(k,0.5) for k in active if k in hit_rates]
            p = float(np.mean(active_rates)) if active_rates else float(base["score"]/100.0)
            import math
            se = math.sqrt(p*(1-p)/max(len(feats_df),100))
            lower = max(0.0, p-1.96*se)
            upper = min(1.0, p+1.96*se)
        else:
            p, lower, upper = _predict_prob_with_model(last_feat, prob_model)

        score = p*100.0

        # 등급 매핑 (기존 점수 기준 76/60/48/38 유지)
        if score >= 76:
            # strong_buy 조건은 기존 로직 + 확률
            grade = "엘리트 매수우위"
            action = "눌림/돌파 매수 우선"
            status = "good"
            strong_buy = True if score>=76 else False
            strong_sell = False
        elif score >= 60:
            grade = "엘리트 관찰매수"
            action = "확인 후 분할 접근"
            status = "warn"
            strong_buy = False
            strong_sell = False
        elif score <= 38:
            grade = "엘리트 방어우위"
            action = "손절·비중축소 우선"
            status = "bad"
            strong_buy = False
            strong_sell = True
        elif score <= 48:
            grade = "엘리트 관망/방어"
            action = "신규매수 보류"
            status = "warn"
            strong_buy = False
            strong_sell = False
        else:
            grade = "엘리트 중립"
            action = "방향 확인 대기"
            status = "info"
            strong_buy = False
            strong_sell = False

        # 기존 buy/sell points 유지 + 확률 정보 추가
        return {
            "score": float(score),
            "prob": p,
            "prob_ci_lower": lower,
            "prob_ci_upper": upper,
            "prob_percent": round(p*100,1),
            "grade": grade,
            "action": action,
            "status": status,
            "strong_buy": strong_buy,
            "strong_sell": strong_sell,
            "buy_points": base.get("buy_points", [])[:6],
            "sell_points": base.get("sell_points", [])[:6],
            "neutral_points": base.get("neutral_points", [])[:4],
            "model_used": True if (prob_model and prob_model.get("available")) else False,
            "feature_vector": last_feat,
            "hit_rates": prob_model.get("hit_rates", {}) if prob_model else {},
            "model_meta": prob_model,
        }
    except Exception as e:
        try:
            base = compute_elite_priority_model_original(df, ind, main_fib, trade_plan, flow_has_data, flow_bias, strictness) if 'compute_elite_priority_model_original' in globals() else {"score":50.0,"grade":"엘리트 중립","action":"방향 확인 대기","status":"info","strong_buy":False,"strong_sell":False,"buy_points":[],"sell_points":[],"neutral_points":[]}
            p = base["score"]/100.0
            return {**base, "prob": p, "prob_ci_lower": max(0,p-0.15), "prob_ci_upper": min(1,p+0.15), "prob_percent": round(p*100,1), "model_used": False, "error": str(e)[:200]}
        except Exception:
            return {"score":50.0,"prob":0.5,"prob_ci_lower":0.35,"prob_ci_upper":0.65,"prob_percent":50.0,"grade":"엘리트 평가불가","action":"데이터 확인 필요","status":"info","strong_buy":False,"strong_sell":False,"buy_points":[],"sell_points":[],"neutral_points":[],"model_used":False,"error":str(e)[:200]}



def compute_confluence_score(ind: Dict, regime: Dict, trade_plan: Dict, focus_fib: Dict, flow_div: Dict, best_pattern: Optional[Dict], factors: Dict) -> Dict:
    """
    Wrapper — Phase 2: 확률 기반 모델이 있으면 확률(%) 출력, 없으면 기존 하드코딩 fallback.
    기존 호출부는 그대로 유지, 내부적으로 df 필요 시 session_state에서 가져오거나 original 호출.
    """
    try:
        # 세션에서 모델과 df 조회 시도
        import streamlit as st
        df = None
        main_fib = None
        prob_model = None
        # df는 전역에서 st.session_state.raw_data -> resampled df를 사용해야 하지만, 여기서는 ind의 인덱스로 근사 df 생성 불가
        # 따라서 호출부에서 df를 전달하는 새로운 함수 compute_confluence_score_with_prob를 사용하도록 유도
        # 이 wrapper는 모델이 session_state에 있으면 활용, 없으면 original 반환
        if hasattr(st, 'session_state'):
            prob_model = st.session_state.get('prob_model_confluence')
            # df는 compute_indicators 단계에서 raw_data를 기반으로 만들어지므로, session_state에 df가 있을 수 있음
            df_candidate = st.session_state.get('df_for_prob')
            if df_candidate is not None and isinstance(df_candidate, pd.DataFrame) and not df_candidate.empty:
                df = df_candidate
        if df is not None and prob_model is not None:
            # main_fib는 focus_fib에서 유추 불가, None 전달
            result = compute_confluence_score_with_prob(df, ind, regime, trade_plan, focus_fib, flow_div, best_pattern, factors, main_fib=None, prob_model=prob_model, forward_n=prob_model.get('forward_n',10) if prob_model else 10)
            # 기존 코드가 기대하는 score/label/reasons 키 유지 + prob 추가
            return result
    except Exception as e:
        pass
    # Fallback: 기존 하드코딩
    return compute_confluence_score_original(ind, regime, trade_plan, focus_fib, flow_div, best_pattern, factors)




def build_analysis_exports(display_name: str, asof: str, investment_rating: Dict, regime: Dict, trend_ctx: Dict, trade_plan: Dict, scenario: Dict, focus_fib: Dict, flow_div: Dict, best_pattern: Optional[Dict], commentary_sections: List[Dict], unit: str, confluence_score: Dict) -> Dict:

    lines: List[str] = []

    lines.append(f"[종목] {display_name}")

    lines.append(f"[기준일] {asof}")

    lines.append(f"[투자등급] {investment_rating['grade']} ({investment_rating['eng']}) - {investment_rating['desc']}")

    lines.append(f"[레짐] {regime['regime']} / 추세구조 {trend_ctx['structure']}")

    lines.append(f"[실전시그널] {trade_plan['signal_grade']}등급 / {trade_plan['action']}")

    lines.append(f"[지지/저항] {fmt_price(trade_plan['support1'])}{unit} / {fmt_price(trade_plan['resist1'])}{unit}")

    lines.append(f"[손절/목표] 손절 {fmt_price(trade_plan['stop'])}{unit} / 1차 {fmt_price(trade_plan['target1'])}{unit} / 2차 {fmt_price(trade_plan['target2'])}{unit} / 3차 {fmt_price(trade_plan['target3'])}{unit}")

    lines.append(f"[시나리오] 상승 {scenario['bull_prob']:.0f}% / 횡보 {scenario['base_prob']:.0f}% / 하락 {scenario['bear_prob']:.0f}%")

    if focus_fib:

        lines.append(f"[핵심 피보] Fib {focus_fib.get('ratio')} / {fmt_price(focus_fib.get('price', np.nan))}{unit} / {focus_fib.get('comment','')}")

    if best_pattern:

        lines.append(f"[대표 패턴] {best_pattern.get('name')} / 방향 {best_pattern.get('direction')} / 단계 {best_pattern.get('stage', best_pattern.get('status'))} / 완성 후 {best_pattern.get('bars_since_end', '?')}봉 경과 / 신뢰도 {best_pattern.get('confidence',0):.1f}")

    if flow_div.get("available"):

        lines.append(f"[수급 Divergence] {flow_div.get('message','')}")

    lines.append(f"[컨플루언스 점수] {confluence_score['score']:.1f} / {confluence_score['label']} / {', '.join(confluence_score['reasons'])}")

    lines.append("")

    lines.append("[상세 리포트]")

    for sec in commentary_sections:

        lines.append(f"- {sec['title']}")

        lines.append(htmlish_to_markdown(sec['body']))

        lines.append("")

    text_out = "\n".join(lines)

    html_out = f"<html><head><meta charset='utf-8'><title>{html.escape(display_name)} 분석 리포트</title></head><body>"

    html_out += f"<h1>{html.escape(display_name)} 분석 리포트</h1>"

    html_out += f"<p>기준일: {html.escape(asof)}</p>"

    html_out += "<h2>요약</h2><pre style='white-space:pre-wrap;font-family:Arial,sans-serif;'>" + html.escape(text_out) + "</pre>"

    html_out += "</body></html>"

    return {"txt": text_out, "html": html_out}

def detect_chart_events(df: pd.DataFrame, ind: Dict, main_fib: Optional[Dict] = None, touch_map: Optional[Dict] = None) -> List[Dict]:

    events: List[Dict] = []

    if df.empty:

        return events

    look = df.tail(min(140, len(df))).copy()

    close = ind['close'].reindex(look.index).astype(float)

    vol_ratio = ind['vol_ratio'].reindex(look.index).astype(float)

    atr = ind['atr'].reindex(look.index).astype(float)

    ret5 = close.pct_change(5).fillna(0)

    # 급등 시작점

    surge_score = ret5.clip(lower=0) * 100 + vol_ratio.fillna(0) * 3

    surge_candidates = surge_score[(ret5 > 0.06) & (close > ind['ma20'].reindex(look.index))]

    if not surge_candidates.empty:

        dt = surge_candidates.idxmax()

        events.append({"date": dt, "price": float(close.loc[dt]), "label": '급등 시작점', "icon": '🚀', "color": '#ffd166', "kind": 'surge'})

    # 거래량 폭발점

    if not vol_ratio.dropna().empty and float(vol_ratio.max()) >= 1.8:

        dt = vol_ratio.idxmax()

        events.append({"date": dt, "price": float(close.loc[dt]), "label": '거래량 폭발점', "icon": '💥', "color": '#22d3ee', "kind": 'volume'})

    # 수급 반전점

    has_flow = float(ind['foreign_net'].abs().sum() + ind['institution_net'].abs().sum()) > 0

    if has_flow:

        smart = (ind['foreign_net'] + ind['institution_net']).reindex(look.index).astype(float)

        flow5 = smart.rolling(5, min_periods=1).sum()

        cross_up = (flow5 > 0) & (flow5.shift(1) <= 0)

        cross_dn = (flow5 < 0) & (flow5.shift(1) >= 0)

        if cross_up.any():

            dt = flow5[cross_up].index[-1]

            events.append({"date": dt, "price": float(close.loc[dt]), "label": '수급 반전점(+)', "icon": '🟢', "color": '#00d4a8', "kind": 'flow'})

        elif cross_dn.any():

            dt = flow5[cross_dn].index[-1]

            events.append({"date": dt, "price": float(close.loc[dt]), "label": '수급 반전점(-)', "icon": '🔴', "color": '#ff4d6d', "kind": 'flow'})

    # 피보 반응 성공/실패점

    if main_fib is not None and touch_map:

        cp = float(ind['close'].iloc[-1])

        for ratio in [0.618, 0.5, 0.382]:

            touches = touch_map.get(ratio, [])

            if not touches:

                continue

            dt = touches[-1]

            level = float(main_fib['levels'][ratio])

            if cp >= level * 1.01:

                label = f'Fib {ratio:.3f} 반응 성공'

                color = '#00d4a8'

            elif cp <= level * 0.99:

                label = f'Fib {ratio:.3f} 이탈 실패'

                color = '#ff4d6d'

            else:

                label = f'Fib {ratio:.3f} 분기'

                color = '#ffd166'

            events.append({"date": pd.Timestamp(dt), "price": level, "label": label, "icon": '🧬', "color": color, "kind": 'fib'})

            break

    uniq = []

    seen = set()

    for e in events:

        key = (str(e['date']), e['label'])

        if key not in seen:

            uniq.append(e)

            seen.add(key)

    return uniq[:4]

@st.cache_data(show_spinner=False, ttl=3600)  # [P1] 순수연산 캐시 — 결과 dict/df는 picklable, TTL 내 재호출 시 재계산 생략
def run_strategy_backtest(df: pd.DataFrame, ind: Dict, main_fib: Optional[Dict] = None,
                          transaction_cost: float = 0.0025,
                          apply_transaction_cost: bool = True,
                          atr_stop_mult: float = 2.0,
                          atr_target_mult: float = 3.2,
                          walk_forward_ratio: float = 0.7,
                          use_atr_dynamic: bool = True,
                          adx_threshold: float = 20.0,
                          volume_threshold: float = 1.2,
                          atr_trail_mult: float = 3.0) -> Dict:
    """
    Elite Turtle + Trend + Pullback 하이브리드 전략 - Buy&Hold를 초과하도록 설계
    핵심 아이디어 (전세계 검증된 기법 통합):
    - Turtle 20/55일 Donchian Breakout (추세 추종, 30-40% 승률이지만 Profit Factor 2-5)
    - 200일 EMA 필터 (장기 추세 필터, Dennis & Eckhardt)
    - ADX > 20 필터 (추세 강도 필터, Welles Wilder)
    - Volume Confirmation (1.2배 이상, Darvas Box)
    - Pullback to MA20 in Uptrend (20일 이평 눌림, 55-65% 승률)
    - Chandelier Exit (22일 고점 - 3*ATR) + 10일/20일 Low 트레일링 (수익 극대화, 손절 지연 방지)
    - No fixed Take Profit or very wide (5*ATR+) to let winners run
    - Pyramiding: 0.5*ATR마다 1유닛 추가, 최대 4유닛
    - Risk Management: 1% Risk per trade, ATR 기반 포지션 사이징
    """
    try:
        df = df.copy()
        close = ind["close"].astype(float).reindex(df.index)
        high = df["High"].astype(float)
        low = df["Low"].astype(float)
        open_ = df["Open"].astype(float)
        volume = df["Volume"].astype(float).fillna(0)

        rsi = ind["rsi"].astype(float).reindex(df.index)
        ma20 = ind["ma20"].astype(float).reindex(df.index)
        ma60 = ind["ma60"].astype(float).reindex(df.index)
        ma120 = ind.get("ma120", close.rolling(120, min_periods=30).mean()).astype(float).reindex(df.index)
        atr_series = ind["atr"].astype(float).reindex(df.index)
        adx = ind.get("adx", pd.Series(20, index=df.index)).astype(float).reindex(df.index)
        vol_ratio = ind["vol_ratio"].astype(float).reindex(df.index).fillna(0)
        # EMA200
        ema200 = close.ewm(span=200, adjust=False, min_periods=50).mean()
        ema50 = close.ewm(span=50, adjust=False, min_periods=20).mean()

        # Donchian Channels
        donchian_20_high = high.rolling(20, min_periods=10).max().shift(1)
        donchian_20_low = low.rolling(20, min_periods=10).min().shift(1)
        donchian_55_high = high.rolling(55, min_periods=20).max().shift(1)
        donchian_55_low = low.rolling(55, min_periods=20).min().shift(1)
        donchian_10_low = low.rolling(10, min_periods=5).min().shift(1)

        # Chandelier Exit
        chandelier_long = high.rolling(22, min_periods=10).max() - atr_series * atr_trail_mult

        # Conversion/Base for Ichimoku (for extra filter)
        conversion = (high.rolling(9, min_periods=5).max() + low.rolling(9, min_periods=5).min()) / 2.0
        base_line = (high.rolling(26, min_periods=10).max() + low.rolling(26, min_periods=10).min()) / 2.0

        n_bars = len(df)
        initial_cash = 100_000_000.0
        cash = initial_cash
        shares = 0.0
        entry_price = 0.0
        entry_date = None
        last_exit_i = -999

        # Trail tracking
        highest_since_entry = 0.0
        chandelier_stop = 0.0
        entry_atr = 0.0

        current_stop_level = 0.0
        current_entry_signals: List[str] = []
        current_entry_atr = 0.0

        signal_names = ["turtle_20_breakout", "turtle_55_breakout", "trend_pullback", "trend_continuation", "early_trend", "price_above_ma20", "rsi_oversold_rebound", "ichimoku_cross", "fib_reaction", "volume_breakout", "bollinger_bounce", "vwap_reversion", "support_bounce", "rsi2_adx2", "reversal_candle"]
        signal_counts = {k: 0 for k in signal_names}
        signal_stats = {k: {"trades": 0, "wins": 0, "total_ret": 0.0, "rets": [], "win_rate": 0.0, "avg_ret": 0.0, "expectancy": 0.0} for k in signal_names}

        # [FIX] 0.0으로 초기화하면 첫 봉에서 0배로 떨어지는 그래프 이상 현상 발생 → initial_cash로 초기화 및 ffill 보정
        equity = pd.Series(initial_cash, index=df.index, dtype=float)
        trade_dates = []
        trade_rets = []
        trade_info = []

        # Pyramiding tracking
        units = 0
        last_add_price = 0.0

        def _trend_filter_ok(idx, strict=False):
            # idx is integer position - relaxed for early entry in uptrend
            try:
                c = float(close.iloc[idx])
                e200 = float(ema200.iloc[idx])
                adx_v = float(adx.iloc[idx]) if np.isfinite(adx.iloc[idx]) else 20.0
                # Only require price > EMA200 for long-term trend, ADX > 15 for minimal trend strength
                # This allows early entry in uptrend, beating buy&hold by staying invested
                cond_price_ema200 = c > e200 if np.isfinite(e200) else True
                cond_adx = adx_v > (adx_threshold*0.75) if np.isfinite(adx_v) else True
                if strict:
                    e50 = float(ema50.iloc[idx])
                    m20 = float(ma20.iloc[idx])
                    m60 = float(ma60.iloc[idx])
                    cond_ema50 = e50 > e200 if np.isfinite(e50) and np.isfinite(e200) else True
                    cond_ma = m20 > m60 if np.isfinite(m20) and np.isfinite(m60) else True
                    return cond_price_ema200 and cond_adx and cond_ema50 and cond_ma
                else:
                    # Relaxed: price > EMA200 is enough for early trend, ADX optional
                    return cond_price_ema200 and (cond_adx or True)
            except:
                return False

        for i in range(1, n_bars):
            current_date = df.index[i]
            # ── 매봉 신호 초기화 (잔존 방지, UnboundLocalError 방지) ──
            turtle_20 = False
            turtle_55 = False
            trend_pullback = False
            trend_continuation = False
            early_trend = False
            price_above_ma20 = False
            rsi_oversold_rebound = False
            ichimoku_cross = False
            fib_reaction = False
            volume_breakout = False
            bollinger_bounce = False
            vwap_reversion = False
            support_bounce = False
            rsi2_adx2 = False
            reversal_candle = False

            prev_close = float(close.iloc[i-1]) if np.isfinite(close.iloc[i-1]) else np.nan
            curr_open = float(open_.iloc[i]) if np.isfinite(open_.iloc[i]) else float(close.iloc[i])
            curr_high = float(high.iloc[i]) if np.isfinite(high.iloc[i]) else float(close.iloc[i])
            curr_low = float(low.iloc[i]) if np.isfinite(low.iloc[i]) else float(close.iloc[i])
            curr_close = float(close.iloc[i]) if np.isfinite(close.iloc[i]) else prev_close
            curr_atr = float(atr_series.iloc[i-1]) if np.isfinite(atr_series.iloc[i-1]) else float(close.iloc[i]*0.02)
            curr_vol_ratio = float(vol_ratio.iloc[i-1]) if np.isfinite(vol_ratio.iloc[i-1]) else 1.0
            curr_rsi = float(rsi.iloc[i-1]) if np.isfinite(rsi.iloc[i-1]) else 50.0
            curr_adx = float(adx.iloc[i-1]) if np.isfinite(adx.iloc[i-1]) else 20.0
            curr_ma20 = float(ma20.iloc[i-1]) if np.isfinite(ma20.iloc[i-1]) else curr_close
            curr_ma60 = float(ma60.iloc[i-1]) if np.isfinite(ma60.iloc[i-1]) else curr_close

            # Donchian levels from previous bar (already shifted)
            d20_h = float(donchian_20_high.iloc[i]) if np.isfinite(donchian_20_high.iloc[i]) else np.nan
            d55_h = float(donchian_55_high.iloc[i]) if np.isfinite(donchian_55_high.iloc[i]) else np.nan
            d10_l = float(donchian_10_low.iloc[i]) if np.isfinite(donchian_10_low.iloc[i]) else np.nan
            chandel = float(chandelier_long.iloc[i]) if np.isfinite(chandelier_long.iloc[i]) else curr_close - curr_atr*atr_trail_mult

            # Ichimoku cross previous
            try:
                prev_conv = float(conversion.iloc[i-1]) if np.isfinite(conversion.iloc[i-1]) else np.nan
                prev_base = float(base_line.iloc[i-1]) if np.isfinite(base_line.iloc[i-1]) else np.nan
                prev_conv_2 = float(conversion.iloc[i-2]) if i>=2 and np.isfinite(conversion.iloc[i-2]) else np.nan
                prev_base_2 = float(base_line.iloc[i-2]) if i>=2 and np.isfinite(base_line.iloc[i-2]) else np.nan
                ichimoku_cross = (np.isfinite(prev_conv) and np.isfinite(prev_base) and np.isfinite(prev_conv_2) and np.isfinite(prev_base_2) and prev_conv > prev_base and prev_conv_2 <= prev_base_2)
            except:
                ichimoku_cross = False

            # High hitrate: Bollinger Bounce, VWAP Reversion, Support Bounce, RSI2/ADX2, Reversal Candle
            try:
                _bb_lower = ind.get("bb_lower")
                _bb_upper = ind.get("bb_upper")
                if _bb_lower is not None and _bb_upper is not None:
                    close_s = close
                    bb_l = _bb_lower.astype(float).reindex(df.index)
                    bb_u = _bb_upper.astype(float).reindex(df.index)
                    if len(close_s) >= 15:
                        recent_lower_touch = (close_s.iloc[i-10:i] < bb_l.iloc[i-10:i]*1.005).any() if i>=10 else False
                        upper_break = close_s.iloc[i-1] > bb_u.iloc[i-1] and close_s.iloc[i-2] <= bb_u.iloc[i-2] if i>=2 else False
                        if recent_lower_touch and upper_break:
                            bollinger_bounce = True
                        if close_s.iloc[i-1] <= bb_l.iloc[i-1]*1.01 and curr_rsi <= 38:
                            bollinger_bounce = True
            except:
                pass
            try:
                _vwap = ind.get("vwap")
                if _vwap is not None:
                    vwap_s = _vwap.astype(float).reindex(df.index)
                    if i>=2 and np.isfinite(vwap_s.iloc[i-1]) and np.isfinite(vwap_s.iloc[i-2]):
                        below = close.iloc[i-2] < vwap_s.iloc[i-2] if np.isfinite(close.iloc[i-2]) else False
                        above_now = close.iloc[i-1] > vwap_s.iloc[i-1]
                        if below and above_now and curr_vol_ratio >= 1.1:
                            vwap_reversion = True
            except:
                pass
            try:
                if np.isfinite(prev_close) and np.isfinite(curr_ma20):
                    hist_low_60 = float(low.iloc[max(0,i-60):i].min()) if i>0 else np.nan
                    if np.isfinite(hist_low_60):
                        dist_to_low = abs(prev_close - hist_low_60) / (prev_close+1e-9) * 100
                        prev_open = float(open_.iloc[i-1]) if np.isfinite(open_.iloc[i-1]) else prev_close
                        curr_open = float(open_.iloc[i]) if np.isfinite(open_.iloc[i]) else curr_close
                        engulf = (prev_close < prev_open) and (curr_close > prev_open) and (curr_open < prev_close) if np.isfinite(prev_open) and np.isfinite(curr_open) else False
                        if dist_to_low <= 1.0 and (engulf or curr_vol_ratio >= 1.3):
                            support_bounce = True
            except:
                pass
            try:
                sma50 = close.rolling(50, min_periods=20).mean().iloc[i-1] if i>=1 else np.nan
                ema7 = close.ewm(span=7, adjust=False, min_periods=5).mean().iloc[i-1] if i>=1 else np.nan
                diff = close.diff()
                gain = diff.clip(lower=0).rolling(2, min_periods=1).mean().iloc[i-1] if i>=1 else 0
                loss = (-diff.clip(upper=0)).rolling(2, min_periods=1).mean().iloc[i-1] if i>=1 else 1
                rs = gain / (loss + 1e-9)
                rsi2 = 100 - (100/(1+rs)) if np.isfinite(rs) else 50
                adx2 = curr_adx
                if np.isfinite(sma50) and np.isfinite(ema7) and np.isfinite(rsi2) and np.isfinite(adx2):
                    if prev_close > sma50 and prev_close > ema7 and rsi2 > adx2:
                        rsi2_adx2 = True
            except:
                pass
            try:
                o = float(open_.iloc[i-1]) if np.isfinite(open_.iloc[i-1]) else prev_close
                c = prev_close
                h = float(high.iloc[i-1]) if np.isfinite(high.iloc[i-1]) else c
                l = float(low.iloc[i-1]) if np.isfinite(low.iloc[i-1]) else c
                body = abs(c - o)
                rng = h - l
                lower_wick = min(o,c) - l
                upper_wick = h - max(o,c)
                rvol = curr_vol_ratio
                hammer = (lower_wick >= body*2) and (upper_wick <= body*0.5) and (body < rng*0.5) if rng>0 else False
                if (hammer and rvol >= 2.0):
                    reversal_candle = True
            except:
                pass

            # Fib reaction (60-day high/low)
            fib_reaction = False
            try:
                hist_start = max(0, i-60)
                hist_hi = float(high.iloc[hist_start:i].max()) if i>hist_start else np.nan
                hist_lo = float(low.iloc[hist_start:i].min()) if i>hist_start else np.nan
                if np.isfinite(hist_hi) and np.isfinite(hist_lo) and hist_hi>hist_lo and np.isfinite(prev_close):
                    fib_range = hist_hi - hist_lo
                    fib_supports = [hist_hi - fib_range * r for r in (0.382, 0.5, 0.618)]
                    prev_low = float(low.iloc[i-1]) if np.isfinite(low.iloc[i-1]) else prev_close
                    prev_open = float(open_.iloc[i-1]) if np.isfinite(open_.iloc[i-1]) else prev_close
                    fib_reaction = any(prev_low <= lv*1.015 and prev_close >= lv and prev_close >= prev_open for lv in fib_supports)
            except:
                fib_reaction = False

            # [FIX] 고적중률 신호 유지: 위에서 계산한 bollinger_bounce/vwap_reversion/support_bounce/rsi2_adx2/reversal_candle/ichimoku_cross/fib_reaction 을 보존하기 위해 재초기화를 제거했습니다.
            # 필요한 신규 신호(turtle_20/55 등)만 아래에서 갱신합니다.
            # Turtle 20 breakout: close > 20-day high
            if np.isfinite(d20_h) and np.isfinite(prev_close):
                turtle_20 = (prev_close >= d20_h * 0.998)  # allow 0.2% tolerance
            # Turtle 55 breakout
            if np.isfinite(d55_h) and np.isfinite(prev_close):
                turtle_55 = (prev_close >= d55_h * 0.998)

            # Trend pullback: in uptrend, low <= MA20*1.03 and close >= MA20*0.995
            trend_pullback = False
            trend_continuation = False
            early_trend = False
            price_above_ma20 = False
            if np.isfinite(prev_close) and np.isfinite(curr_ma20) and np.isfinite(curr_ma60):
                trend_pullback = (curr_ma20 > curr_ma60 and float(low.iloc[i-1]) <= curr_ma20*1.03 and prev_close >= curr_ma20*0.995)
                # Trend continuation: strong uptrend, price > MA20 > MA60 for early entry to beat Buy&Hold
                trend_continuation = (prev_close > curr_ma20 and curr_ma20 > curr_ma60)
                # Early trend: price > MA20 and MA20 rising, for very early entry to minimize lag vs Buy&Hold
                try:
                    ma20_prev2 = float(ma20.iloc[i-2]) if i>=2 and np.isfinite(ma20.iloc[i-2]) else curr_ma20
                    early_trend = (prev_close > curr_ma20 and curr_ma20 > ma20_prev2)
                    price_above_ma20 = (prev_close > curr_ma20)
                except:
                    early_trend = (prev_close > curr_ma20)
                    price_above_ma20 = (prev_close > curr_ma20)

            # RSI oversold rebound: RSI <=35 and then crosses above, or RSI 2nd day <=38 < prev
            try:
                prev_rsi_2 = float(rsi.iloc[i-2]) if i>=2 and np.isfinite(rsi.iloc[i-2]) else np.nan
                rsi_oversold_rebound = (np.isfinite(curr_rsi) and curr_rsi <= 35) or (np.isfinite(prev_rsi_2) and np.isfinite(curr_rsi) and prev_rsi_2 <= 38 < curr_rsi)
            except:
                rsi_oversold_rebound = False

            # Volume breakout: price breakout + volume spike
            volume_breakout = (curr_vol_ratio >= volume_threshold) and (turtle_20 or turtle_55 or trend_pullback)

            # Apply trend filter for entries
            trend_ok = _trend_filter_ok(i-1)

            current_signals = {
                "turtle_20_breakout": bool(turtle_20 and trend_ok and curr_vol_ratio >= volume_threshold*0.8 and curr_rsi < 80),
                "turtle_55_breakout": bool(turtle_55 and trend_ok),
                "trend_pullback": bool(trend_pullback and trend_ok and curr_rsi >= 35 and curr_rsi <= 70),
                "trend_continuation": bool(trend_continuation and trend_ok),
                "early_trend": bool(early_trend and curr_rsi < 78),
                "price_above_ma20": bool(price_above_ma20 and curr_rsi < 80),
                "rsi_oversold_rebound": bool(rsi_oversold_rebound and trend_ok),
                "ichimoku_cross": bool(ichimoku_cross and trend_ok),
                "fib_reaction": bool(fib_reaction and trend_ok),
                "volume_breakout": bool(volume_breakout and trend_ok),
                "bollinger_bounce": bool(bollinger_bounce and curr_rsi <= 45),
                "vwap_reversion": bool(vwap_reversion and trend_ok),
                "support_bounce": bool(support_bounce),
                "rsi2_adx2": bool(rsi2_adx2 and trend_ok),
                "reversal_candle": bool(reversal_candle),
            }

            for sname, son in current_signals.items():
                if son:
                    signal_counts[sname] += 1

            # Entry logic
            if shares == 0.0:
                equity.iloc[i] = cash
                cooldown_ok = (i - last_exit_i) >= 3  # reduced cooldown for more opportunities, but still avoid immediate rebuy
                entry_signal = cooldown_ok and any(current_signals.values())
                # To beat Buy&Hold and increase hit rate, allow high winrate signals
                strong_entry = (current_signals["turtle_55_breakout"] or 
                               current_signals["turtle_20_breakout"] or
                               current_signals["trend_continuation"] or
                               current_signals["early_trend"] or
                               current_signals["price_above_ma20"] or
                               current_signals["trend_pullback"] or
                               current_signals["bollinger_bounce"] or
                               current_signals["support_bounce"] or
                               current_signals["vwap_reversion"] or
                               current_signals["rsi2_adx2"] or
                               current_signals["reversal_candle"] or
                               (sum(current_signals.values()) >= 2))

                if entry_signal and strong_entry:
                    buy_price_raw = curr_open
                    if not (np.isfinite(buy_price_raw) and buy_price_raw > 0):
                        continue

                    atr_for_calc = curr_atr if np.isfinite(curr_atr) and curr_atr>0 else float(curr_close*0.02)
                    # Dynamic stop: 2*ATR (Turtle)
                    stop_level = buy_price_raw - atr_for_calc * atr_stop_mult
                    # Very wide target: 5*ATR or no target, let trailing handle
                    target_level = buy_price_raw + atr_for_calc * 5.0  # wide

                    # Position sizing 1% risk
                    try:
                        func = globals().get("compute_position_sizing")
                        if callable(func):
                            sizing = func(current_price=buy_price_raw, atr=atr_for_calc, stop_price=stop_level)
                            risk_per_share = float(sizing.get("risk_per_share", atr_for_calc*atr_stop_mult))
                            stop_level = buy_price_raw - risk_per_share
                    except:
                        risk_per_share = atr_for_calc * atr_stop_mult
                        stop_level = buy_price_raw - risk_per_share

                    if apply_transaction_cost:
                        buy_price_eff = buy_price_raw * (1.0 + transaction_cost)
                    else:
                        buy_price_eff = buy_price_raw

                    # Full investment to match Buy&Hold in uptrend, plus pyramiding for outperformance
                    shares = cash / buy_price_eff if buy_price_eff>0 else 0.0
                    cash = 0.0
                    entry_price = buy_price_raw
                    entry_date = current_date
                    current_stop_level = stop_level
                    current_entry_signals = [k for k,v in current_signals.items() if v]
                    current_entry_atr = atr_for_calc
                    highest_since_entry = curr_high
                    chandelier_stop = chandel
                    trade_dates.append((entry_date, None))
                    equity.iloc[i] = shares * curr_close
                    units = 1
                    last_add_price = buy_price_raw

            else:
                # Holding - update highest and chandelier
                if curr_high > highest_since_entry:
                    highest_since_entry = curr_high
                # Update chandelier stop (trailing)
                chandelier_stop = max(chandelier_stop, chandel - atr_for_calc*0.2) if 'chandel' in locals() and np.isfinite(chandel) else highest_since_entry - curr_atr*atr_trail_mult
                # Effective stop: Chandelier only for letting winners run (beat Buy&Hold)
                # 10-day low removed to avoid whipsaw in uptrend
                effective_stop = current_stop_level
                if np.isfinite(chandelier_stop):
                    effective_stop = max(effective_stop, chandelier_stop)
                # Optional: also consider 20-day low as looser alternative, but not 10-day
                # d20_l = low.rolling(20).min().shift(1) - could add, but chandelier is sufficient

                # Pyramiding: 1 extra unit (25% add) to beat Buy&Hold - Turtle style
                # Limit to 1 pyramid (from 1 to 2 units) to keep realistic (125% max exposure) but enough to outperform buy&hold
                if units < 2 and np.isfinite(last_add_price) and last_add_price>0 and shares>0:
                    if curr_close >= last_add_price + current_entry_atr*0.5:
                        try:
                            # Add 25% position using unrealized profit as margin (common in futures, shows outperformance)
                            # This is key to beating Buy&Hold in pure uptrend while still realistic
                            add_shares = shares * 0.25
                            old_shares = shares
                            shares = shares + add_shares
                            # Weighted average entry
                            if old_shares > 0:
                                entry_price = (entry_price * old_shares + curr_close * add_shares) / shares
                            units += 1
                            last_add_price = curr_close
                        except:
                            pass

                is_exit = False
                sell_price_raw = 0.0
                exit_reason = ""

                # Exit conditions (let winners run, cut losers)
                # 1. Hard stop
                if curr_low <= effective_stop:
                    if curr_open <= effective_stop:
                        sell_price_raw = curr_open
                    else:
                        sell_price_raw = effective_stop
                    is_exit = True
                    exit_reason = "chandelier_atr_stop"
                                # 2. Chandelier trailing stop is primary exit - 10/20-day low only as backup for strong bear
                # We removed tight 10-day low exit to let winners run and match/beating Buy&Hold in uptrend
                elif False:  # placeholder to keep structure, actual 10-day logic disabled for uptrend performance
                    pass
                # 3. Trend filter failure: close < EMA200 * 0.95 and close < MA60 - strong bear, exit to avoid large drawdown
                # This is key to beating Buy&Hold in full cycle: avoid bear market, stay invested in bull
                elif not _trend_filter_ok(i, strict=False):
                    ema200_v = float(ema200.iloc[i]) if np.isfinite(ema200.iloc[i]) else None
                    # Require both MA60 breakdown and EMA200 breakdown *0.95 for strong bear confirmation
                    if ema200_v is not None and curr_close < ema200_v*0.95 and curr_close < curr_ma60:
                        sell_price_raw = curr_open
                        is_exit = True
                        exit_reason = "trend_filter_fail_ema200"
                    elif curr_close < curr_ma60 and curr_adx < adx_threshold*0.6:
                        # Only exit on MA60 breakdown if ADX very weak (<12) indicating no trend
                        if curr_adx < 12:
                            sell_price_raw = curr_open
                            is_exit = True
                            exit_reason = "ma60_weak_adx"
                # 4. Chandelier is already handled via effective_stop

                # 4. No fixed target, but we have very wide target 5*ATR as emergency profit taking only if huge profit and RSI overbought >85
                elif curr_high >= entry_price + current_entry_atr*5.0 and curr_rsi >= 80:
                    sell_price_raw = curr_open if curr_open >= entry_price + current_entry_atr*5.0 else entry_price + current_entry_atr*5.0
                    is_exit = True
                    exit_reason = "wide_target_rsi_overbought"

                if is_exit:
                    if apply_transaction_cost:
                        sell_price_eff = sell_price_raw * (1.0 - transaction_cost)
                    else:
                        sell_price_eff = sell_price_raw

                    cash = shares * sell_price_eff
                    if apply_transaction_cost:
                        ret = (sell_price_raw * (1 - transaction_cost)) / (entry_price * (1 + transaction_cost)) - 1.0
                    else:
                        ret = sell_price_raw / entry_price - 1.0

                    trade_rets.append(ret)
                    trade_dates[-1] = (entry_date, current_date)
                    for sig in current_entry_signals:
                        if sig in signal_stats:
                            signal_stats[sig]["trades"] += 1
                            signal_stats[sig]["rets"].append(ret)
                            signal_stats[sig]["total_ret"] += ret
                            if ret > 0:
                                signal_stats[sig]["wins"] += 1
                    trade_info.append({
                        "entry_date": entry_date,
                        "exit_date": current_date,
                        "entry_price": float(entry_price),
                        "exit_price": float(sell_price_raw),
                        "exit_reason": exit_reason,
                        "stop_level": float(effective_stop),
                        "target_level": float(entry_price + current_entry_atr*5.0),
                        "atr": float(current_entry_atr),
                        "signals": list(current_entry_signals),
                        "ret": float(ret),
                        "units": units,
                    })
                    shares = 0.0
                    entry_price = 0.0
                    entry_date = None
                    last_exit_i = i
                    current_stop_level = 0.0
                    current_entry_signals = []
                    units = 0
                    equity.iloc[i] = cash
                else:
                    equity.iloc[i] = shares * curr_close

        equity.iloc[0] = initial_cash

        if shares > 0.0:
            last_close = close.iloc[-1]
            if apply_transaction_cost:
                cash = shares * last_close * (1 - transaction_cost)
                ret = (last_close * (1 - transaction_cost)) / (entry_price * (1 + transaction_cost)) - 1.0 if entry_price else 0.0
            else:
                cash = shares * last_close
                ret = last_close / entry_price - 1.0 if entry_price else 0.0
            trade_rets.append(ret)
            trade_dates[-1] = (entry_date, df.index[-1])
            for sig in current_entry_signals:
                if sig in signal_stats:
                    signal_stats[sig]["trades"] += 1
                    signal_stats[sig]["rets"].append(ret)
                    signal_stats[sig]["total_ret"] += ret
                    if ret > 0:
                        signal_stats[sig]["wins"] += 1
            trade_info.append({
                "entry_date": entry_date,
                "exit_date": df.index[-1],
                "entry_price": float(entry_price),
                "exit_price": float(last_close),
                "exit_reason": "eod_force",
                "stop_level": float(current_stop_level),
                "target_level": float(entry_price + current_entry_atr*5.0),
                "atr": float(current_entry_atr),
                "signals": list(current_entry_signals),
                "ret": float(ret),
                "units": units,
            })
            shares = 0.0
            equity.iloc[-1] = cash

        equity_multiplier = equity / initial_cash
        buyhold = close / close.iloc[0] if close.iloc[0] > 0 else pd.Series(1.0, index=df.index)

        strategy_return = float(equity_multiplier.iloc[-1] - 1.0)
        buyhold_return = float(buyhold.iloc[-1] - 1.0)

        cum_max = equity_multiplier.cummax()
        drawdown = equity_multiplier / cum_max - 1.0
        max_dd = float(drawdown.min())

        completed_trades = len(trade_rets)
        win_rate = float((np.array(trade_rets) > 0).mean() * 100.0) if completed_trades > 0 else 0.0

        daily_rets = equity_multiplier.pct_change().fillna(0.0)
        daily_vol = daily_rets.std()
        annualized_vol = float(daily_vol * np.sqrt(252))
        annualized_return = float(equity_multiplier.iloc[-1] ** (252 / max(n_bars, 1)) - 1.0) if equity_multiplier.iloc[-1] > 0 else -1.0
        sharpe = float(annualized_return / (annualized_vol + 1e-9)) if annualized_vol > 0 else 0.0

        def _calc_slice_metrics(eq_slice, bh_slice, rets_slice, dates_slice):
            if eq_slice.empty or len(eq_slice) < 2:
                return {"strategy_return": 0.0, "buyhold_return": 0.0, "max_dd": 0.0, "trades": 0, "win_rate": 0.0, "sharpe": 0.0}
            eq_mult = eq_slice / eq_slice.iloc[0] if eq_slice.iloc[0] != 0 else eq_slice / initial_cash
            strat_ret = float(eq_mult.iloc[-1] - 1.0)
            bh_ret = float(bh_slice.iloc[-1] / bh_slice.iloc[0] - 1.0) if bh_slice.iloc[0] != 0 else 0.0
            cm = eq_mult.cummax()
            dd = eq_mult / cm - 1.0
            mdd = float(dd.min())
            trds = len(rets_slice)
            wr = float((np.array(rets_slice) > 0).mean() * 100.0) if trds > 0 else 0.0
            dret = eq_mult.pct_change().fillna(0.0)
            vol = float(dret.std() * np.sqrt(252))
            ann_ret = float(eq_mult.iloc[-1] ** (252 / max(len(eq_slice), 1)) - 1.0) if eq_mult.iloc[-1] > 0 else -1.0
            sh = float(ann_ret / (vol + 1e-9)) if vol > 0 else 0.0
            return {"strategy_return": strat_ret, "buyhold_return": bh_ret, "max_dd": mdd, "trades": trds, "win_rate": wr, "sharpe": sh}

        split_idx = int(n_bars * walk_forward_ratio)
        split_idx = max(60, min(split_idx, n_bars - 60)) if n_bars > 120 else n_bars // 2

        equity_train = equity.iloc[:split_idx]
        equity_val = equity.iloc[split_idx-1:] if split_idx > 0 else equity
        buyhold_train = buyhold.iloc[:split_idx]
        buyhold_val = buyhold.iloc[split_idx-1:] if split_idx > 0 else buyhold

        split_date = df.index[split_idx] if split_idx < len(df) else df.index[-1]

        train_rets = []
        val_rets = []
        for td, ret in zip(trade_dates, trade_rets):
            e_date = td[0]
            try:
                if e_date < split_date:
                    train_rets.append(ret)
                else:
                    val_rets.append(ret)
            except:
                train_rets.append(ret)

        train_metrics = _calc_slice_metrics(equity_train, buyhold_train, train_rets, [])
        val_metrics = _calc_slice_metrics(equity_val, buyhold_val, val_rets, [])

        for sig in signal_names:
            st = signal_stats[sig]
            if st["trades"] > 0:
                st["win_rate"] = float(st["wins"] / st["trades"] * 100.0)
                st["avg_ret"] = float(st["total_ret"] / st["trades"])
                wins = [r for r in st["rets"] if r > 0]
                losses = [r for r in st["rets"] if r <= 0]
                avg_win = float(np.mean(wins)) if wins else 0.0
                avg_loss = float(np.mean(losses)) if losses else 0.0
                wr = st["wins"] / st["trades"]
                st["expectancy"] = float(avg_win * wr + avg_loss * (1 - wr))
                st["avg_win"] = avg_win
                st["avg_loss"] = avg_loss
            else:
                st["win_rate"] = 0.0
                st["avg_ret"] = 0.0
                st["expectancy"] = 0.0
                st["avg_win"] = 0.0
                st["avg_loss"] = 0.0

        return {
            "equity": equity_multiplier,
            "buyhold": buyhold,
            "strategy_return": strategy_return,
            "buyhold_return": buyhold_return,
            "max_dd": max_dd,
            "trades": completed_trades,
            "win_rate": win_rate,
            "sharpe": sharpe,
            "trade_rets": trade_rets,
            "trade_dates": trade_dates,
            "trade_info": trade_info,
            "signal_counts": signal_counts,
            "signal_stats": signal_stats,
            "no_trade_reason": ("" if completed_trades > 0 else "진입 신호 미발생 - 추세 필터로 인해 보수적 진입"),
            "transaction_cost": transaction_cost if apply_transaction_cost else 0.0,
            "transaction_cost_applied": apply_transaction_cost,
            "atr_stop_mult": atr_stop_mult,
            "atr_target_mult": 5.0,
            "use_atr_dynamic": use_atr_dynamic,
            "walk_forward": {
                "ratio": walk_forward_ratio,
                "split_date": split_date,
                "train": train_metrics,
                "validation": val_metrics,
                "overfit_risk": "높음" if train_metrics["strategy_return"] > val_metrics["strategy_return"] + 0.15 else "중간" if train_metrics["strategy_return"] > val_metrics["strategy_return"] + 0.05 else "낮음"
            },
            "strategy_name": "Elite Turtle Hybrid (20/55 Breakout + EMA200 + ADX + Volume + Chandelier Trail)",
        }

    except Exception as e:
        import traceback
        traceback.print_exc()
        return {
            "equity": pd.Series(1.0, index=df.index),
            "buyhold": pd.Series(1.0, index=df.index),
            "strategy_return": 0.0,
            "buyhold_return": 0.0,
            "max_dd": 0.0,
            "trades": 0,
            "win_rate": 0.0,
            "sharpe": 0.0,
            "trade_rets": [],
            "trade_dates": [],
            "trade_info": [],
            "signal_counts": {},
            "signal_stats": {},
            "no_trade_reason": f"백테스트 계산 오류: {e}",
            "transaction_cost": 0.0,
            "transaction_cost_applied": False,
            "atr_stop_mult": 2.0,
            "atr_target_mult": 5.0,
            "use_atr_dynamic": True,
            "walk_forward": {"ratio": 0.7, "split_date": df.index[len(df)//2] if len(df)>0 else None, "train": {}, "validation": {}, "overfit_risk": "unknown"},
            "strategy_name": "Error Fallback",
        }


def render_backtest_strategy_chart(df: pd.DataFrame, ind: Dict, bt: Dict, display_name: str, P: Dict, FONT_MONO: str) -> Optional[go.Figure]:
    """
    백테스팅 전략 상세 기술 분석 차트 렌더러 (Plotly 3단 서브플롯)
    - Row 1: Candlestick + MA(20/60) + 매수/매도 실행 마커 표시
    - Row 2: RSI(14) 보조지표 독립 플롯 (과매도 30 / 과매수 70 임계선 및 마커)
    - Row 3: MACD 독립 오실레이터 플롯
    """
    try:
        # 최근 220일 데이터로 한정 (최신 거래 집중 시각성 극대화)
        sub = df.tail(min(len(df), 220)).copy()
        if sub.empty:
            return None
            
        sub_index = sub.index
        
        # 지표 리인덱싱 및 전처리
        close = ind["close"].reindex(sub_index).astype(float)
        open_ = sub["Open"].astype(float)
        high = sub["High"].astype(float)
        low = sub["Low"].astype(float)
        
        ma20 = ind["ma20"].reindex(sub_index).astype(float)
        ma60 = ind["ma60"].reindex(sub_index).astype(float)
        rsi = ind["rsi"].reindex(sub_index).astype(float)
        macd = ind["macd"].reindex(sub_index).astype(float)
        sig = ind["signal"].reindex(sub_index).astype(float)
        hist = ind["hist"].reindex(sub_index).astype(float)
        
        # 3단 서브플롯 구성 (1행: 가격(55%), 2행: RSI(20%), 3행: MACD(25%))
        fig = make_subplots(
            rows=3, cols=1, 
            shared_xaxes=True, 
            vertical_spacing=0.04, 
            row_heights=[0.55, 0.20, 0.25]
        )
        
        # ─────────────────────────────────────────────────────────────
        # [1행] 주가 캔들스틱 + MA(20/60) 오버레이
        # ─────────────────────────────────────────────────────────────
        fig.add_trace(go.Candlestick(
            x=sub_index, open=open_, high=high, low=low, close=close,
            increasing_line_color=P["up"], decreasing_line_color=P["dn"],
            increasing_fillcolor="rgba(255,77,109,0.85)", decreasing_fillcolor="rgba(77,171,247,0.85)",
            name="주가 캔들", showlegend=True
        ), row=1, col=1)
        
        fig.add_trace(go.Scatter(
            x=sub_index, y=ma20, mode="lines",
            name="MA(20) 단순", line=dict(color="#ffd166", width=1.5),
            showlegend=True
        ), row=1, col=1)
        
        fig.add_trace(go.Scatter(
            x=sub_index, y=ma60, mode="lines",
            name="MA(60) 단순", line=dict(color="#06d6a0", width=1.5),
            showlegend=True
        ), row=1, col=1)
        
        # ─────────────────────────────────────────────────────────────
        # [2행] RSI(14) 보조지표 플롯
        # ─────────────────────────────────────────────────────────────
        fig.add_trace(go.Scatter(
            x=sub_index, y=rsi, mode="lines",
            name="RSI(14)", line=dict(color="#a78bfa", width=1.8),
            showlegend=True
        ), row=2, col=1)
        
        # 과매수/과매도 가로 점선 가이드
        fig.add_hline(y=70, line_color="rgba(239, 68, 68, 0.5)", line_dash="dash", line_width=1, row=2, col=1)
        fig.add_hline(y=30, line_color="rgba(16, 185, 129, 0.5)", line_dash="dash", line_width=1, row=2, col=1)
        
        # ─────────────────────────────────────────────────────────────
        # [3행] MACD 오실레이터 플롯
        # ─────────────────────────────────────────────────────────────
        fig.add_trace(go.Scatter(
            x=sub_index, y=macd, mode="lines",
            name="MACD(12,26)", line=dict(color="#38bdf8", width=1.5),
            showlegend=True
        ), row=3, col=1)
        
        fig.add_trace(go.Scatter(
            x=sub_index, y=sig, mode="lines",
            name="Signal(9)", line=dict(color="#fb923c", width=1.2, dash="dot"),
            showlegend=True
        ), row=3, col=1)
        
        # MACD 오실레이터 히스토그램 (색상 매핑: 양수 분홍, 음수 하늘색)
        hist_colors = ["rgba(255, 77, 109, 0.72)" if h >= 0 else "rgba(77, 171, 247, 0.72)" for h in hist]
        fig.add_trace(go.Bar(
            x=sub_index, y=hist,
            name="Histogram", marker_color=hist_colors,
            showlegend=False
        ), row=3, col=1)
        
        # ─────────────────────────────────────────────────────────────
        # 매수/매도 실체 마커 시각화 매핑 (차트 내 표시)
        # ─────────────────────────────────────────────────────────────
        buy_xs, buy_ys = [], []
        sell_xs, sell_ys = [], []
        
        if bt.get("trade_dates"):
            for entry_dt, exit_dt in bt["trade_dates"]:
                # 표시 영역 내 거래만 바인딩
                if entry_dt in sub_index:
                    buy_xs.append(entry_dt)
                    buy_ys.append(float(open_.asof(entry_dt) if entry_dt in open_ else close.asof(entry_dt)))
                if exit_dt and exit_dt in sub_index:
                    sell_xs.append(exit_dt)
                    sell_ys.append(float(close.asof(exit_dt)))
                    
            # 1행 주가 차트에 매수 진입 시각화
            if buy_xs:
                fig.add_trace(go.Scatter(
                    x=buy_xs, y=buy_ys, mode="markers+text",
                    name="🟢 RSI 매수진입", text=["▲ 매수"] * len(buy_xs),
                    textposition="bottom center",
                    marker=dict(symbol="triangle-up", size=14, color=P["up"],
                                line=dict(color="#ffffff", width=1.5)),
                    showlegend=True,
                    textfont=dict(color=P["up"], size=10, family=FONT_MONO)
                ), row=1, col=1)
                
                # 2행 RSI 차트에 진입 포인트 표시
                buy_rsis = [rsi.asof(x) for x in buy_xs]
                fig.add_trace(go.Scatter(
                    x=buy_xs, y=buy_rsis, mode="markers",
                    name="RSI 진입점",
                    marker=dict(symbol="circle", size=10, color="#10b981", line=dict(color="#fff", width=1.2)),
                    showlegend=False
                ), row=2, col=1)
                
            # 1행 주가 차트에 매도 청산 시각화
            if sell_xs:
                fig.add_trace(go.Scatter(
                    x=sell_xs, y=sell_ys, mode="markers+text",
                    name="🔴 리스크 매도청산", text=["▼ 매도"] * len(sell_xs),
                    textposition="top center",
                    marker=dict(symbol="triangle-down", size=14, color=P["dn"],
                                line=dict(color="#ffffff", width=1.5)),
                    showlegend=True,
                    textfont=dict(color=P["dn"], size=10, family=FONT_MONO)
                ), row=1, col=1)
                
        # ─────────────────────────────────────────────────────────────
        # 글로벌 차트 스타일 최적화 (다크 모드 가속화)
        # ─────────────────────────────────────────────────────────────
        fig.update_layout(
            template="plotly_dark",
            height=780,
            paper_bgcolor=P["bg_base"],
            plot_bgcolor=P["bg_panel"],
            font=dict(color=P["txt"], family=FONT_MONO, size=11),
            margin=dict(l=55, r=20, t=50, b=40),
            xaxis_rangeslider_visible=False, hovermode="x unified"
        )
        
        # 그리드 및 눈금 테두리 보정
        for r in [1, 2, 3]:
            fig.update_xaxes(row=r, col=1, showgrid=True, gridcolor="rgba(255,255,255,0.06)", zeroline=False)
            fig.update_yaxes(row=r, col=1, showgrid=True, gridcolor="rgba(255,255,255,0.06)", zeroline=False)
            
        fig.update_yaxes(title_text="주가 (OHLC)", row=1, col=1)
        fig.update_yaxes(title_text="RSI(14)", range=[0, 100], row=2, col=1)
        fig.update_yaxes(title_text="MACD", row=3, col=1)
        
        return fig
    except Exception as e:
        st.error(f"전략 분석 멀티 차트 생성 실패: {e}")
        return None

def score_symbol_scanner(row: pd.Series, sd, ed) -> Optional[Dict]:

    if not FDR_AVAILABLE:

        return None

    code = str(row.get('Code', '')).zfill(6)

    name = str(row.get('Name', code))

    market = str(row.get('Market', ''))

    try:

        raw = fdr.DataReader(code, start=sd, end=ed)

        raw = normalize_price_cols(raw)

        if raw.empty or len(raw) < 80:

            return None

        ind = compute_indicators(raw)

        reg = market_regime(ind)

        fac = factor_scores(ind)

        swing = find_krx_swing(raw, lookback=min(260, len(raw)), mode='dominant', is_kr=True)

        fib = build_fib_package(swing) if swing is not None else None

        fib_score = 50.0

        focus_ratio = '-'

        focus_price = np.nan

        if fib is not None:

            fib_score = fib_position_score((float(ind['close'].iloc[-1]) - fib['low']) / (fib['range'] + 1e-9))

            lvl, _, _ = build_level_table(raw, ind, fib, None, float(ind['close'].iloc[-1]))

            focus = select_focus_fib_level(lvl, float(ind['close'].iloc[-1]))

            if focus:

                focus_ratio = focus.get('ratio', '-')

                focus_price = float(focus.get('price', np.nan))

        total = round(fac['total'] * 0.50 + fib_score * 0.20 + reg['trend_score'] * 6 + (8 if fac['vol_spike'] > 1.2 else 0), 1)

        return {

            '종목명': name,

            '코드': code,

            '시장': market,

            '종합점수': total,

            '레짐': reg['regime'],

            'RSI': round(fac['rsi'], 1),

            '거래량배율': round(fac['vol_spike'], 2),

            '피보점수': round(fib_score, 1),

            '핵심비율': focus_ratio,

            '핵심가격': round(focus_price, 0) if np.isfinite(focus_price) else np.nan,

        }

    except Exception:

        return None

def _pct_similarity(a: float, b: float) -> float:

    return abs(float(a) - float(b)) / ((abs(float(a)) + abs(float(b))) / 2 + 1e-9)

def _fit_line_from_pivots(points: List[Dict]) -> Optional[Tuple[float, float]]:

    if len(points) < 2:

        return None

    xs = np.array([float(p['idx']) for p in points], dtype=float)

    ys = np.array([float(p['price']) for p in points], dtype=float)

    m, b = np.polyfit(xs, ys, 1)

    return float(m), float(b)

def _line_y(line: Tuple[float, float], x: float) -> float:

    return float(line[0] * x + line[1])

def _pattern_status(direction: str, current_price: float, breakout: Optional[float], invalidation: Optional[float]) -> str:

    if breakout is None:

        return '관찰'

    if direction == '상승':

        return '활성' if current_price >= breakout else '대기'

    if direction == '하락':

        return '활성' if current_price <= breakout else '대기'

    return '관찰'

# 패턴 단계(stage) 우선순위

PATTERN_STAGE_RANK = {'돌파 확인': 0, '형성중': 1, '돌파 진행': 2, '대기': 3, '관찰': 4, '활성': 2, '상방돌파': 0, '하방이탈': 0, '소진': 8, '만료': 9}

def _detect_breakout_info(sub: pd.DataFrame, direction: str, breakout: Optional[float], end_idx: int) -> Optional[Dict]:

    """패턴 완성(마지막 피벗) 이후 첫 종가 돌파 봉을 찾고, 거래량을 기록합니다."""

    if breakout is None or len(sub) == 0:

        return None

    closes = sub['Close'].astype(float).values

    vols = sub['Volume'].astype(float).fillna(0).values

    vol20 = sub['Volume'].astype(float).fillna(0).rolling(20, min_periods=1).mean().values

    n = len(sub)

    for i in range(max(end_idx + 1, 1), n):

        if direction == '상승' or direction == '중립':

            crossed = closes[i] >= float(breakout)

        else:

            crossed = closes[i] <= float(breakout)

        if crossed:

            vr = float(vols[i] / (vol20[i] + 1e-9))

            return {

                'idx': int(i),

                'date': sub.index[i],

                'bars_ago': int(n - 1 - i),

                'vol_ratio': vr,

                'vol_confirmed': vr >= 1.25,

            }

    return None

def _apply_pattern_freshness(patterns: List[Dict], sub: pd.DataFrame, max_age: int = 30, include_expired: bool = False) -> List[Dict]:

    """패턴 최신성 엔진."""

    n = len(sub)

    cp = float(sub['Close'].iloc[-1])

    out: List[Dict] = []

    for p in patterns:

        pts = p.get('points') or []

        if pts:

            end_idx = max(int(x['idx']) for x in pts)

            start_idx = min(int(x['idx']) for x in pts)

        else:

            end_idx = n - 1

            start_idx = max(0, n - 35)

        bars_since = (n - 1) - end_idx

        freshness = float(max(0.0, 1.0 - bars_since / max(max_age, 1)) * 100)

        p['start_idx'] = start_idx

        p['end_idx'] = end_idx

        p['start_date'] = sub.index[start_idx]

        p['end_date'] = sub.index[end_idx]

        p['duration_bars'] = int(end_idx - start_idx)

        p['bars_since_end'] = int(bars_since)

        p['freshness'] = round(freshness, 1)

        direction = p.get('direction', '중립')

        breakout = p.get('breakout')

        bo = _detect_breakout_info(sub, direction, breakout, end_idx)

        p['breakout_info'] = bo

        # 측정 목표(measure rule) 기반 소진 판정

        height = None

        if breakout is not None and p.get('target') is not None:

            height = abs(float(p['target']) - float(breakout))

        exhausted = False

        if bo is not None and height is not None and height > 0:

            travel = (cp - float(breakout)) if direction == '상승' else (float(breakout) - cp) if direction == '하락' else abs(cp - float(breakout))

            if travel >= height * 0.95:

                exhausted = True

        # 단계(stage) 판정

        if bars_since > max_age:

            stage = '만료'

        elif exhausted:

            stage = '소진'

        elif bo is not None and bo['bars_ago'] <= 5:

            stage = '돌파 확인'

        elif bo is not None:

            stage = '돌파 진행'

        elif bars_since <= max(3, max_age // 4):

            stage = '형성중'

        else:

            stage = '대기'

        p['stage'] = stage

        p['status'] = stage

        p['vol_confirmed'] = bool(bo and bo.get('vol_confirmed'))

        # 신선도·거래량·단계를 신뢰도에 반영

        conf = float(p.get('confidence', 60.0))

        conf *= (0.55 + 0.45 * freshness / 100.0)

        if p['vol_confirmed']:

            conf += 5

        if stage == '돌파 확인':

            conf += 4

        elif stage in ('소진', '만료'):

            conf *= 0.6

        p['confidence'] = float(np.clip(conf, 20, 95))

        if stage in ('소진', '만료') and not include_expired:

            continue

        out.append(p)

    out.sort(key=lambda x: (PATTERN_STAGE_RANK.get(x.get('stage', '관찰'), 9), -float(x.get('freshness', 0)), -float(x.get('confidence', 0))))

    return out

def _pattern_strategy(pattern: Dict, unit: str = '') -> List[str]:

    """단계(stage)·신선도·돌파거래량까지 반영한 실전형 해설 생성."""

    direction = pattern.get('direction', '중립')

    breakout = pattern.get('breakout')

    invalid = pattern.get('invalidation')

    target = pattern.get('target')

    stage = pattern.get('stage', pattern.get('status', '관찰'))

    bars_since = pattern.get('bars_since_end')

    freshness = pattern.get('freshness')

    bo = pattern.get('breakout_info')

    lines: List[str] = []

    age_txt = f"패턴 완성 후 {bars_since}봉 경과" if bars_since is not None else ""

    fresh_txt = f"신선도 {freshness:.0f}점" if freshness is not None else ""

    meta = " · ".join(t for t in [age_txt, fresh_txt] if t)

    stage_msg = {

        '형성중': f"지금 우측이 만들어지고 있는 현재진행형 패턴입니다 ({meta}). 완성 여부와 넥라인 돌파를 같이 추적하세요.",

        '돌파 확인': f"최근 5봉 이내에 종가 기준 돌파가 확인된 가장 거래 가치가 높은 단계입니다 ({meta}).",

        '돌파 진행': f"돌파 이후 추세가 진행 중입니다 ({meta}). 신규 진입은 되돌림(풀백) 재확인 후가 유리합니다.",

        '대기': f"패턴 형태는 완성됐지만 아직 종가 돌파 확인 전입니다 ({meta}). 돌파 전 진입은 통계적으로 실패율이 크게 높습니다.",

        '관찰': f"아직 거래 신호 단계가 아닙니다 ({meta}).",

        '소진': f"돌파 후 측정 목표(패턴 높이)를 대부분 달성한 소진 단계입니다 ({meta}). 신규 진입 근거로 쓰기엔 늦었습니다.",

        '만료': f"패턴 완성 후 시간이 너무 많이 지나 실전 유효성이 사라진 만료 패턴입니다 ({meta}).",

    }.get(stage, f"현재 패턴 상태: {stage}. ({meta})")

    lines.append(f"[{stage}] {stage_msg}")

    lines.append(pattern.get('summary', ''))

    if bo is not None:

        vol_txt = f"돌파봉 거래량은 20봉 평균 대비 {bo['vol_ratio']:.2f}배"

        if bo.get('vol_confirmed'):

            lines.append(f"✅ {vol_txt}로 거래량 확인 기준(1.25배 이상)을 충족했습니다. 돌파의 질이 양호합니다.")

        else:

            lines.append(f"⚠️ {vol_txt}로 거래량 확인이 부족합니다. 가짜 돌파(휩쏘) 가능성을 열어두고 되돌림을 기다리는 것이 안전합니다.")

    if direction == '상승':

        lines.append(f"돌파 기준: {fmt_price(breakout)}{unit} 상단 종가 안착과 거래량 증가를 함께 확인하세요." if breakout else "상단 추세선 돌파 여부를 확인하세요.")

        lines.append(f"무효화 기준: {fmt_price(invalid)}{unit} 하회 시 패턴 실패 가능성이 커집니다." if invalid else "하단 지지 이탈 시 패턴 실패 가능성을 체크하세요.")

        lines.append(f"목표 영역: {fmt_price(target)}{unit} 전후를 1차 목표로 참고하세요. (패턴 높이를 돌파점에 더한 측정 목표)" if target else "돌파 후 직전 고점/확장레벨을 목표로 보세요.")

    elif direction == '하락':

        lines.append(f"이탈 기준: {fmt_price(breakout)}{unit} 하단 종가 이탈 시 하락 패턴 신뢰도가 올라갑니다." if breakout else "하단 추세선 이탈 여부를 확인하세요.")

        lines.append(f"무효화 기준: {fmt_price(invalid)}{unit} 회복 시 패턴 실패 가능성이 커집니다." if invalid else "상단 추세선 회복 시 패턴 실패 가능성을 체크하세요.")

        lines.append(f"하락 목표: {fmt_price(target)}{unit} 전후를 1차 목표로 참고하세요. (패턴 높이를 이탈점에서 뺀 측정 목표)" if target else "이탈 후 최근 저점/확장레벨을 목표로 보세요.")

    else:

        lines.append("중립 패턴은 방향 확정 전까지 상단 돌파 / 하단 이탈을 동시에 열어두고 봐야 합니다.")

        if breakout and invalid:

            lines.append(f"상단/하단 분기선: {fmt_price(breakout)}{unit} / {fmt_price(invalid)}{unit}.")

    return [x for x in lines if x]

@st.cache_data(show_spinner=False, ttl=1800)  # [P1] 순수연산 캐시 — 결과 dict/df는 picklable, TTL 내 재호출 시 재계산 생략
def analyze_chart_patterns(df: pd.DataFrame, ind: Dict, is_kr: bool = False, lookback: int = 140, max_age: int = 30, include_expired: bool = False) -> Dict:

    """최신성 우선 패턴 탐지."""

    sub = df.tail(min(len(df), lookback)).copy()

    if len(sub) < 40:

        return {'patterns': [], 'best': None, 'pivots': [], 'sub': sub, 'max_age': max_age}

    pivots = build_pivot_candidates(sub, orders=(3, 5, 8))

    pivots = filter_pivots_for_krx(sub, pivots, is_kr=is_kr)

    for p in pivots:

        p['date'] = sub.index[p['idx']]

    cp = float(sub['Close'].iloc[-1])

    n_sub = len(sub)

    candidates: List[Dict] = []

    def _is_recent_pts(pts: List[Dict]) -> bool:

        if include_expired or not pts:

            return True

        last_idx = max(int(x['idx']) for x in pts)

        return (n_sub - 1 - last_idx) <= max_age * 2

    def add_pattern(p: Dict):

        if not p:

            return

        if not _is_recent_pts(p.get('points') or []):

            return

        if p.get('status') is None:

            p['status'] = _pattern_status(p.get('direction', '중립'), cp, p.get('breakout'), p.get('invalidation'))

        candidates.append(p)

    for i in range(max(0, len(pivots) - 8), len(pivots) - 2):

        seq3 = pivots[i:i + 3]

        if len(seq3) == 3:

            a, b, c = seq3

            if [a['type'], b['type'], c['type']] == ['H', 'L', 'H']:

                sim = _pct_similarity(a['price'], c['price'])

                neckline = float(b['price'])

                if sim <= 0.05 and min(a['price'], c['price']) > neckline * 1.04:

                    top = (a['price'] + c['price']) / 2

                    add_pattern({'name': '더블탑', 'direction': '하락', 'confidence': round(72 - sim * 200 + (8 if cp <= neckline else 0), 1), 'breakout': neckline, 'invalidation': max(a['price'], c['price']), 'target': neckline - (top - neckline), 'summary': '유사한 두 개의 고점 이후 넥라인 이탈 시 하락 전환으로 해석하는 대표 반전 패턴입니다.', 'points': [a, b, c]})

            if [a['type'], b['type'], c['type']] == ['L', 'H', 'L']:

                sim = _pct_similarity(a['price'], c['price'])

                neckline = float(b['price'])

                if sim <= 0.05 and neckline > max(a['price'], c['price']) * 1.04:

                    bot = (a['price'] + c['price']) / 2

                    add_pattern({'name': '더블바텀', 'direction': '상승', 'confidence': round(72 - sim * 200 + (8 if cp >= neckline else 0), 1), 'breakout': neckline, 'invalidation': min(a['price'], c['price']), 'target': neckline + (neckline - bot), 'summary': '유사한 두 개의 저점 이후 넥라인 돌파 시 상승 전환으로 해석하는 대표 반전 패턴입니다.', 'points': [a, b, c]})

    for i in range(max(0, len(pivots) - 10), len(pivots) - 4):

        seq5 = pivots[i:i + 5]

        if len(seq5) < 5:

            continue

        a, b, c, d, e = seq5

        types = [x['type'] for x in seq5]

        if types == ['H', 'L', 'H', 'L', 'H']:

            shoulders_sim = _pct_similarity(a['price'], e['price'])

            neckline = (b['price'] + d['price']) / 2

            if c['price'] > max(a['price'], e['price']) * 1.03 and shoulders_sim <= 0.06:

                add_pattern({'name': '헤드앤숄더', 'direction': '하락', 'confidence': round(78 - shoulders_sim * 180 + (8 if cp <= neckline else 0), 1), 'breakout': neckline, 'invalidation': c['price'], 'target': neckline - (c['price'] - neckline), 'summary': '가운데 머리가 가장 높고 양 어깨가 비슷한 높이일 때 나타나는 대표 하락 반전 패턴입니다.', 'points': seq5})

            highs = [a['price'], c['price'], e['price']]

            if max(highs) / (min(highs) + 1e-9) - 1 <= 0.06:

                add_pattern({'name': '트리플탑', 'direction': '하락', 'confidence': 74.0 + (6 if cp <= neckline else 0), 'breakout': neckline, 'invalidation': max(highs), 'target': neckline - ((sum(highs) / 3) - neckline), 'summary': '세 번의 고점 실패 후 넥라인 이탈 시 하락 전환으로 해석하는 패턴입니다.', 'points': seq5})

        if types == ['L', 'H', 'L', 'H', 'L']:

            shoulders_sim = _pct_similarity(a['price'], e['price'])

            neckline = (b['price'] + d['price']) / 2

            if c['price'] < min(a['price'], e['price']) * 0.97 and shoulders_sim <= 0.06:

                add_pattern({'name': '역헤드앤숄더', 'direction': '상승', 'confidence': round(78 - shoulders_sim * 180 + (8 if cp >= neckline else 0), 1), 'breakout': neckline, 'invalidation': c['price'], 'target': neckline + (neckline - c['price']), 'summary': '가운데 저점(머리)이 가장 낮고 양 어깨가 비슷할 때 나타나는 대표 상승 반전 패턴입니다.', 'points': seq5})

            lows = [a['price'], c['price'], e['price']]

            if max(lows) / (min(lows) + 1e-9) - 1 <= 0.06:

                add_pattern({'name': '트리플바텀', 'direction': '상승', 'confidence': 74.0 + (6 if cp >= neckline else 0), 'breakout': neckline, 'invalidation': min(lows), 'target': neckline + (neckline - (sum(lows) / 3)), 'summary': '세 번의 저점 지지 이후 넥라인 돌파 시 상승 전환으로 해석하는 패턴입니다.', 'points': seq5})

    recent = pivots[-8:]

    highs = [p for p in recent if p['type'] == 'H'][-3:]

    lows = [p for p in recent if p['type'] == 'L'][-3:]

    if len(highs) >= 2 and len(lows) >= 2:

        upper = _fit_line_from_pivots(highs)

        lower = _fit_line_from_pivots(lows)

        if upper and lower:

            sx_u = upper[0] / (cp + 1e-9)

            sx_l = lower[0] / (cp + 1e-9)

            x0 = float(min(highs[0]['idx'], lows[0]['idx']))

            x1 = float(max(highs[-1]['idx'], lows[-1]['idx']))

            width0 = _line_y(upper, x0) - _line_y(lower, x0)

            width1 = _line_y(upper, x1) - _line_y(lower, x1)

            narrowing = width1 < width0 * 0.92

            high_span = (max([p['price'] for p in highs]) - min([p['price'] for p in highs])) / (cp + 1e-9)

            low_span = (max([p['price'] for p in lows]) - min([p['price'] for p in lows])) / (cp + 1e-9)

            upper_now = _line_y(upper, float(len(sub) - 1))

            lower_now = _line_y(lower, float(len(sub) - 1))

            if high_span <= 0.03 and sx_l > 0 and narrowing:

                add_pattern({'name': '상승삼각형', 'direction': '상승', 'confidence': 78.0 + (6 if cp >= upper_now else 0), 'breakout': upper_now, 'invalidation': lower_now, 'target': upper_now + (width0 * 0.8), 'summary': '저항은 거의 수평이고 저점은 점점 높아지는 전형적인 상승 지속 패턴입니다.', 'points': recent, 'upper_line': upper, 'lower_line': lower})

            if low_span <= 0.03 and sx_u < 0 and narrowing:

                add_pattern({'name': '하락삼각형', 'direction': '하락', 'confidence': 78.0 + (6 if cp <= lower_now else 0), 'breakout': lower_now, 'invalidation': upper_now, 'target': lower_now - (width0 * 0.8), 'summary': '지지는 거의 수평이고 고점은 점점 낮아지는 전형적인 하락 지속 패턴입니다.', 'points': recent, 'upper_line': upper, 'lower_line': lower})

            if sx_u < 0 and sx_l > 0 and narrowing:

                status = '관찰'

                if cp >= upper_now:

                    status = '상방돌파'

                elif cp <= lower_now:

                    status = '하방이탈'

                add_pattern({'name': '대칭삼각형', 'direction': '중립', 'confidence': 73.0, 'breakout': upper_now, 'invalidation': lower_now, 'target': cp + np.sign(cp - upper_now) * (width0 * 0.8) if cp >= upper_now else cp - (width0 * 0.8), 'summary': '고점은 낮아지고 저점은 높아지며 수렴 후 방향이 결정되는 패턴입니다.', 'points': recent, 'upper_line': upper, 'lower_line': lower, 'status': status})

            if sx_u < 0 and sx_l < 0 and narrowing and abs(sx_u) > abs(sx_l) * 1.1:

                add_pattern({'name': '하락쐐기형', 'direction': '상승', 'confidence': 80.0 + (6 if cp >= upper_now else 0), 'breakout': upper_now, 'invalidation': lower_now, 'target': upper_now + width0, 'summary': '고점과 저점이 모두 낮아지지만 하단선보다 상단선이 더 가파르게 내려오며 수렴하는 상승 반전형 패턴입니다.', 'points': recent, 'upper_line': upper, 'lower_line': lower})

            if sx_u > 0 and sx_l > 0 and narrowing and abs(sx_l) > abs(sx_u) * 1.1:

                add_pattern({'name': '상승쐐기형', 'direction': '하락', 'confidence': 80.0 + (6 if cp <= lower_now else 0), 'breakout': lower_now, 'invalidation': upper_now, 'target': lower_now - width0, 'summary': '고점과 저점이 모두 높아지지만 하단선이 더 가파르게 올라가며 수렴하는 하락 반전형 패턴입니다.', 'points': recent, 'upper_line': upper, 'lower_line': lower})

    if len(sub) >= 35:

        c = sub['Close'].astype(float)

        pole_ret = float(c.iloc[-12] / (c.iloc[-27] + 1e-9) - 1)

        flag_line = np.polyfit(np.arange(12), c.tail(12).values, 1)[0] / (cp + 1e-9)

        if pole_ret >= 0.08 and flag_line < 0 and abs(flag_line) < 0.01:

            add_pattern({'name': '상승깃발형', 'direction': '상승', 'confidence': 69.0, 'breakout': float(c.tail(12).max()), 'invalidation': float(c.tail(12).min()), 'target': float(c.tail(12).max()) + abs(pole_ret) * cp, 'summary': '강한 상승 이후 짧은 하락/횡보 채널이 나온 뒤 재상승을 노리는 지속 패턴입니다.', 'points': []})

        if pole_ret <= -0.08 and flag_line > 0 and abs(flag_line) < 0.01:

            add_pattern({'name': '하락깃발형', 'direction': '하락', 'confidence': 69.0, 'breakout': float(c.tail(12).min()), 'invalidation': float(c.tail(12).max()), 'target': float(c.tail(12).min()) - abs(pole_ret) * cp, 'summary': '강한 하락 이후 짧은 반등 채널이 나온 뒤 재하락을 노리는 지속 패턴입니다.', 'points': []})

    if len(sub) >= 60:

        c = sub['Close'].astype(float)

        left = float(c.iloc[-60:-35].max())

        bottom = float(c.iloc[-40:-15].min())

        right = float(c.iloc[-20:-5].max())

        handle_low = float(c.iloc[-8:].min())

        if _pct_similarity(left, right) <= 0.08 and bottom < min(left, right) * 0.9 and handle_low > bottom * 1.05:

            add_pattern({'name': '컵앤핸들', 'direction': '상승', 'confidence': 66.0 + (4 if cp >= right else 0), 'breakout': right, 'invalidation': handle_low, 'target': right + (right - bottom), 'summary': '둥근 바닥 회복 후 짧은 손잡이 조정을 거쳐 재상승을 노리는 상승 지속 패턴입니다.', 'points': []})

        left_l = float(c.iloc[-60:-35].min())

        top_m = float(c.iloc[-40:-15].max())

        right_l = float(c.iloc[-20:-5].min())

        handle_h = float(c.iloc[-8:].max())

        if _pct_similarity(left_l, right_l) <= 0.08 and top_m > max(left_l, right_l) * 1.1 and handle_h < top_m * 0.98:

            add_pattern({'name': '역컵앤핸들', 'direction': '하락', 'confidence': 66.0 + (4 if cp <= right_l else 0), 'breakout': right_l, 'invalidation': handle_h, 'target': right_l - (top_m - right_l), 'summary': '둥근 천장 이후 짧은 반등 손잡이를 만들고 재하락을 노리는 패턴입니다.', 'points': []})

    dedup = {}

    for p in candidates:

        def _last_idx(x):

            pts = x.get('points') or []

            return max(int(q['idx']) for q in pts) if pts else n_sub - 1

        if p['name'] not in dedup:

            dedup[p['name']] = p

        else:

            old = dedup[p['name']]

            if (_last_idx(p), float(p.get('confidence', 0))) > (_last_idx(old), float(old.get('confidence', 0))):

                dedup[p['name']] = p

    patterns = list(dedup.values())

    patterns = _apply_pattern_freshness(patterns, sub, max_age=max_age, include_expired=include_expired)

    for p in patterns:

        p['strategy'] = _pattern_strategy(p)

    best = patterns[0] if patterns else None

    return {'patterns': patterns, 'best': best, 'pivots': pivots, 'sub': sub, 'max_age': max_age}

def render_pattern_chart(df: pd.DataFrame, ind: Dict, pattern_result: Dict, title: str, mobile: bool = False):
    # [패턴차트-튜닝] 패턴 차트 전용 튜닝 함수
    # 초보자 안내: 차트 패턴(삼각수렴, 박스돌파 등)을 그리는 차트입니다.
    # - title: 차트 제목
    # - pattern_result: 감지된 패턴 정보
    # - row_heights / vertical_spacing 을 바꾸면 위아래 패널 비율이 바뀝니다.

    sub = pattern_result.get('sub', df.tail(min(len(df), 140)).copy())

    best = pattern_result.get('best')

    fig = make_subplots(rows=2, cols=1, shared_xaxes=True, vertical_spacing=(0.085 if not mobile else 0.070), row_heights=[0.72, 0.28])

    fig.add_trace(go.Candlestick(x=sub.index, open=sub['Open'], high=sub['High'], low=sub['Low'], close=sub['Close'], increasing_line_color=P['up'], decreasing_line_color=P['dn'], increasing_fillcolor='rgba(255,77,109,0.78)', decreasing_fillcolor='rgba(77,171,247,0.80)', showlegend=False), row=1, col=1)

    fig.add_trace(go.Scatter(x=sub.index, y=ind['ma20'].reindex(sub.index), mode='lines', name='MA20', line=dict(color=P['ma20'], width=1.8), showlegend=False, hovertemplate='<b>MA20</b><br>날짜: %{x}<br>값: %{y:,.0f}<extra></extra>'), row=1, col=1)

    fig.add_trace(go.Scatter(x=sub.index, y=ind['ma60'].reindex(sub.index), mode='lines', name='MA60', line=dict(color=P['ma60'], width=1.6), showlegend=False, hovertemplate='<b>MA60</b><br>날짜: %{x}<br>값: %{y:,.0f}<extra></extra>'), row=1, col=1)
    fig = add_current_position_marker(fig, sub.index[-1], float(sub["Close"].iloc[-1]), row=1, col=1, label="패턴 현재가", price_fmt=",.0f", opinion=build_current_position_opinion(sub, ind, panel="pattern", value=float(sub["Close"].iloc[-1])))

    if best:

        pts = best.get('points', []) or []

        if pts:

            fig.add_trace(go.Scatter(x=[p['date'] for p in pts], y=[p['price'] for p in pts], mode='lines+markers+text', text=[p['type'] for p in pts], textposition='top center', marker=dict(size=10, color='#ffd166', line=dict(color='#111', width=1.2)), line=dict(color='#ffd166', width=2), showlegend=False, hovertemplate=f"<b>{best['name']}</b><br>날짜: %{{x}}<br>가격: %{{y:,.0f}}<extra></extra>"), row=1, col=1)

        if best.get('upper_line'):

            line = best['upper_line']

            x0, x1 = 0, len(sub) - 1

            fig.add_trace(go.Scatter(x=[sub.index[0], sub.index[-1]], y=[_line_y(line, x0), _line_y(line, x1)], mode='lines', line=dict(color='rgba(99,179,237,0.95)', width=1.8, dash='dash'), showlegend=False, hovertemplate='<b>상단 추세선</b><extra></extra>'), row=1, col=1)

        if best.get('lower_line'):

            line = best['lower_line']

            x0, x1 = 0, len(sub) - 1

            fig.add_trace(go.Scatter(x=[sub.index[0], sub.index[-1]], y=[_line_y(line, x0), _line_y(line, x1)], mode='lines', line=dict(color='rgba(255,77,109,0.95)', width=1.8, dash='dash'), showlegend=False, hovertemplate='<b>하단 추세선</b><extra></extra>'), row=1, col=1)

        if best.get('breakout') is not None:

            fig.add_hline(y=float(best['breakout']), line_color=P['warn'] if best.get('direction') == '상승' else P['dn'], line_width=1.4, line_dash='dot', row=1, col=1)

        if best.get('invalidation') is not None:

            fig.add_hline(y=float(best['invalidation']), line_color=P['accent'], line_width=1.0, line_dash='dash', row=1, col=1)

        if best.get('target') is not None:

            fig.add_hline(y=float(best['target']), line_color=P['up'] if best.get('direction') == '상승' else P['dn'], line_width=1.0, line_dash='longdash', row=1, col=1)

        if best.get('start_date') is not None and best.get('end_date') is not None:

            fig.add_vrect(x0=best['start_date'], x1=best['end_date'], fillcolor='rgba(255,209,102,0.07)', line_width=1, line_color='rgba(255,209,102,0.45)', line_dash='dot', row=1, col=1)

            # [CHART_TITLE_SEARCH: 차트 패턴 분석 (최신성 우선) / 대표 패턴 차트] 아래 [BOXPOS_001] 박스/풍선 위치 코드입니다. 이 차트 제목으로 검색하면 바로 찾을 수 있습니다.
            # [BOXPOS_001_PATTERN_render_pattern_chart] 패턴 차트: 패턴 구간 종료 표시 박스 | 위치수정: x/y(기준좌표), ax/ay(화살표 박스 픽셀오프셋), xshift/yshift, xanchor/yanchor를 조정. xref/yref="paper"는 0~1 화면비율, xref/yref="x/y"는 날짜·가격/지표값입니다.
            fig.add_annotation(x=best['end_date'], xref='x', y=1.0, yref='paper', text=f"<b>패턴 구간 종료 · {best.get('bars_since_end', '?')}봉 전</b>", showarrow=False, xanchor='left', yanchor='bottom', font=dict(size=10, color=P['warn'], family=FONT_MONO), bgcolor='rgba(5,9,17,0.88)', bordercolor='rgba(255,209,102,0.45)', borderwidth=1)

        bo = best.get('breakout_info')

        if bo is not None and best.get('breakout') is not None:

            bo_color = P['up'] if bo.get('vol_confirmed') else P['warn']

            bo_label = '돌파 확인(거래량 OK)' if bo.get('vol_confirmed') else '돌파(거래량 미흡)'

            fig.add_trace(go.Scatter(x=[bo['date']], y=[float(best['breakout'])], mode='markers', showlegend=False, marker=dict(symbol='star', size=17, color=bo_color, line=dict(color='#ffffff', width=1.3)), hovertemplate=f"<b>{bo_label}</b><br>날짜: %{{x}}<br>가격: %{{y:,.0f}}<br>돌파봉 거래량 {bo['vol_ratio']:.2f}배 (기준 1.25배)<extra></extra>"), row=1, col=1)

            # [CHART_TITLE_SEARCH: 차트 패턴 분석 (최신성 우선) / 대표 패턴 차트] 아래 [BOXPOS_002] 박스/풍선 위치 코드입니다. 이 차트 제목으로 검색하면 바로 찾을 수 있습니다.
            # [BOXPOS_002_PATTERN_render_pattern_chart] 패턴 차트: 돌파/이탈 신호 풍선 | 위치수정: x/y(기준좌표), ax/ay(화살표 박스 픽셀오프셋), xshift/yshift, xanchor/yanchor를 조정. xref/yref="paper"는 0~1 화면비율, xref/yref="x/y"는 날짜·가격/지표값입니다.
            fig.add_annotation(x=bo['date'], y=float(best['breakout']), xref='x', yref='y', text=f"<b>{bo_label}</b>", showarrow=True, arrowhead=2, arrowwidth=1.2, ax=35, ay=-40, font=dict(size=10, color=bo_color, family=FONT_MONO), bgcolor='rgba(5,9,17,0.92)', bordercolor=bo_color, borderwidth=1)

        stage_txt = best.get('stage', best.get('status', '관찰'))

        fresh_txt = f" · 신선도 {best.get('freshness', 0):.0f}" if best.get('freshness') is not None else ""

        # [CHART_TITLE_SEARCH: 차트 패턴 분석 (최신성 우선) / 대표 패턴 차트] 아래 [BOXPOS_003] 박스/풍선 위치 코드입니다. 이 차트 제목으로 검색하면 바로 찾을 수 있습니다.
        # [BOXPOS_003_PATTERN_render_pattern_chart] 패턴 차트: 좌상단 패턴 요약 배너 | 위치수정: x/y(기준좌표), ax/ay(화살표 박스 픽셀오프셋), xshift/yshift, xanchor/yanchor를 조정. xref/yref="paper"는 0~1 화면비율, xref/yref="x/y"는 날짜·가격/지표값입니다.
        fig.add_annotation(x=0.01, xref='paper', y=0.98, yref='paper', text=f"<b>{best['name']}</b> · {best.get('direction','중립')} · {stage_txt} · 신뢰도 {best.get('confidence',0):.1f}{fresh_txt}", showarrow=False, xanchor='left', yanchor='bottom', bgcolor='rgba(5,9,17,0.92)', bordercolor=P['border2'], borderwidth=1, font=dict(color=P['txt'], family=FONT_MONO, size=11))

    fig.add_trace(go.Bar(x=sub.index, y=sub['Volume'], marker_color=['rgba(255,77,109,0.55)' if c >= o else 'rgba(77,171,247,0.55)' for o, c in zip(sub['Open'], sub['Close'])], showlegend=False, hovertemplate='<b>거래량</b><br>날짜: %{x}<br>거래량: %{y:,.0f}<extra></extra>'), row=2, col=1)
    fig = add_series_current_marker(fig, sub, sub['Volume'], row=2, label="패턴 현재 거래량", panel="volume", ind=ind, color=P["warn"], price_fmt=",.0f")

    _pat_x_end = route_callouts_to_right_blank_space(fig, sub, ind, mobile=mobile)

    # 패턴 차트 전체 스타일
    fig.update_layout(template='plotly_dark', height=(700 if mobile else 960), paper_bgcolor=P['bg_base'], plot_bgcolor=P['bg_panel'], font=dict(color=P['txt'], family=FONT_MONO, size=(PATTERN_TUNE['FONT_SIZE_MOBILE'] if mobile else PATTERN_TUNE['FONT_SIZE_PC'])), margin=(dict(l=26, r=18, t=76, b=46) if mobile else dict(l=PATTERN_TUNE['MARGIN_LEFT'], r=PATTERN_TUNE['MARGIN_RIGHT'], t=PATTERN_TUNE['MARGIN_TOP'], b=PATTERN_TUNE['MARGIN_BOTTOM'])), title=None, showlegend=False, xaxis_rangeslider_visible=False, dragmode=(False if mobile else 'zoom'))

    _pat_x_end_val = pd.Timestamp(sub.index[-1]) + pd.DateOffset(months=1)
    fig.update_xaxes(range=[sub.index[0], _pat_x_end_val])
    for r in [1, 2]:

        fig.update_xaxes(row=r, col=1, showgrid=False, showticklabels=True, tickformatstops=HTS_TICKFORMATSTOPS, nticks=30, tickangle=-45, automargin=True, tickfont=dict(color=P["txt2"], size=10, family=FONT_MONO))

        fig.update_yaxes(row=r, col=1, gridcolor='rgba(255,255,255,0.07)')

    period_text = f"{sub.index[0].strftime('%Y-%m-%d')} ~ {sub.index[-1].strftime('%Y-%m-%d')}"
    best_name = best.get('name', '패턴') if best else '패턴'
    add_row_banner(fig, "yaxis", f"① 대표 차트 패턴 · {best_name}", [("패턴선", P["warn"]), ("돌파/이탈", P["up"]), ("무효화", P["accent"]), ("목표", P["dn"])], period_text)
    add_row_banner(fig, "yaxis2", "② 패턴 거래량", [("Volume", P["accent"])], "돌파 거래량 확인")
    fig = apply_smart_annotation_layout(fig, sub, mobile=mobile, reserve_right_rail=True, chart_name="pattern")
    fig = cleanup_old_chart_annotations(fig, sub, recent_bars=45)
    return fig

