SETTINGS_FILE = SETTINGS_DIR / "user_settings.json"
PORTFOLIO_FILE = SETTINGS_DIR / "portfolio.json"
PRICE_ALERTS_FILE = SETTINGS_DIR / "price_alerts.json"

def load_app_version() -> str:
    try:
        if VERSION_FILE.exists():
            return VERSION_FILE.read_text(encoding="utf-8-sig").strip()
    except Exception:
        pass
    return "23.25"

APP_VERSION = load_app_version()

def load_json_file(path: Path, default):
    try:
        if path.exists():
            return json.loads(path.read_text(encoding="utf-8-sig"))
    except Exception:
        pass
    return default

def save_json_file(path: Path, data) -> bool:
    try:
        path.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")
        return True
    except Exception:
        return False

def save_text_file(path: Path, content: str, encoding: str = 'utf-8') -> bool:
    try:
        path.write_text(content, encoding=encoding)
        return True
    except Exception:
        return False

def save_binary_file(path: Path, content: bytes) -> bool:
    try:
        path.write_bytes(content)
        return True
    except Exception:
        return False

def normalize_watchlist(items) -> List[str]:
    out = []
    for x in items or []:
        s = str(x).strip()
        if s and s not in out:
            out.append(s)
    return out

def load_watchlist() -> List[str]:
    data = load_json_file(WATCHLIST_FILE, [])
    return normalize_watchlist(data if isinstance(data, list) else [])

def save_watchlist(items: List[str]) -> bool:
    return save_json_file(WATCHLIST_FILE, normalize_watchlist(items))

def load_user_settings() -> Dict:
    data = load_json_file(SETTINGS_FILE, {})
    return data if isinstance(data, dict) else {}

def save_user_settings(data: Dict) -> bool:
    return save_json_file(SETTINGS_FILE, data)

def load_portfolio_file() -> List[Dict]:
    data = load_json_file(PORTFOLIO_FILE, [])
    out = []
    if isinstance(data, list):
        for e in data:
            try:
                out.append({"name": str(e.get("name", "")), "qty": int(e.get("qty", 0)), "avg": float(e.get("avg", 0.0)), "cur": float(e.get("cur", 0.0))})
            except Exception:
                continue
    return out

def save_portfolio_file(items: List[Dict]) -> bool:
    return save_json_file(PORTFOLIO_FILE, items)

def load_price_alerts() -> List[Dict]:
    data = load_json_file(PRICE_ALERTS_FILE, [])
    out = []
    if isinstance(data, list):
        for e in data:
            try:
                out.append({"symbol": str(e.get("symbol", "")), "price": float(e.get("price", 0.0)), "direction": str(e.get("direction", "이상")), "memo": str(e.get("memo", ""))})
            except Exception:
                continue
    return out

def save_price_alerts(items: List[Dict]) -> bool:
    return save_json_file(PRICE_ALERTS_FILE, items)

def evaluate_price_alerts(alerts_list: List[Dict], symbol_name: str, current_price: float) -> List[Dict]:
    results = []
    for a in alerts_list:
        if str(a.get("symbol", "")).strip() != str(symbol_name).strip():
            continue
        target = float(a.get("price", 0.0))
        direction = str(a.get("direction", "이상"))
        hit = current_price >= target if direction == "이상" else current_price <= target
        gap_pct = (current_price / target - 1) * 100 if target > 0 else 0.0
        results.append({**a, "hit": hit, "gap_pct": gap_pct})
    return results

def figure_to_png_bytes(fig, width: int = 1600, height: int = 900, scale: int = 2):
    try:
        return fig.to_image(format="png", width=width, height=height, scale=scale)
    except Exception:
        try:
            import plotly.io as pio
            return pio.to_image(fig, format="png", width=width, height=height, scale=scale)
        except Exception:
            return None

def text_to_pdf_bytes(title: str, text: str):
    try:
        from reportlab.lib.pagesizes import A4
        from reportlab.pdfbase import pdfmetrics
        from reportlab.pdfbase.cidfonts import UnicodeCIDFont
        from reportlab.pdfgen import canvas
        buf = BytesIO()
        c = canvas.Canvas(buf, pagesize=A4)
        width, height = A4
        font_name = 'Helvetica'
        for candidate in ['HYSMyeongJo-Medium', 'HYGothic-Medium', 'Helvetica']:
            try:
                if candidate != 'Helvetica':
                    pdfmetrics.registerFont(UnicodeCIDFont(candidate))
                font_name = candidate
                break
            except Exception:
                continue
        y = height - 40
        c.setFont(font_name, 12)
        for line in [title, '-' * 60] + text.splitlines():
            if y < 40:
                c.showPage()
                c.setFont(font_name, 12)
                y = height - 40
            c.drawString(35, y, str(line)[:120])
            y -= 16
        c.save()
        return buf.getvalue()
    except Exception:
        return None

def render_figure_export_buttons(fig, base_name: str, include_png: bool = True) -> None:
    """차트 내보내기 버튼.

    성능 최적화: 기존에는 화면이 렌더링될 때마다 모든 Plotly 차트를 PNG로 즉시 변환했습니다.
    kaleido 변환은 매우 무거워서 탭이 많을수록 앱 초기 로딩이 크게 느려졌습니다.
    이제 HTML은 즉시 제공하고, PNG는 사용자가 버튼을 눌렀을 때만 생성합니다.
    """
    c1, c2, c3, c4 = st.columns(4)
    html_bytes = fig.to_html(include_plotlyjs='cdn').encode('utf-8')
    c1.download_button(f"🌐 HTML 다운로드", data=html_bytes, file_name=f"{base_name}.html", mime="text/html", use_container_width=True, help="가장 빠른 저장 방식입니다.")

    png_key = f"png_bytes_{base_name}"
    if include_png:
        if c2.button("🖼 PNG 생성", key=f"gen_png_{base_name}", use_container_width=True, help="누를 때만 PNG를 생성합니다. kaleido 설치가 필요합니다."):
            with st.spinner("PNG 생성 중..."):
                st.session_state[png_key] = figure_to_png_bytes(fig)
        if st.session_state.get(png_key) is not None:
            c2.download_button("⬇️ PNG 다운로드", data=st.session_state[png_key], file_name=f"{base_name}.png", mime="image/png", use_container_width=True, key=f"down_png_{base_name}")
    else:
        c2.info("PNG 비활성")

    if c3.button("💾 HTML 폴더저장", key=f"save_html_{base_name}", use_container_width=True):
        ok = save_binary_file(CHARTS_DIR / f"{base_name}.html", html_bytes)
        st.success(f"저장 완료: {CHARTS_DIR / (base_name + '.html')}") if ok else st.error("HTML 저장 실패")

    if st.session_state.get(png_key) is not None:
        if c4.button("💾 PNG 폴더저장", key=f"save_png_{base_name}", use_container_width=True):
            ok = save_binary_file(CHARTS_DIR / f"{base_name}.png", st.session_state[png_key])
            st.success(f"저장 완료: {CHARTS_DIR / (base_name + '.png')}") if ok else st.error("PNG 저장 실패")
    else:
        c4.caption("PNG는 생성 후 저장")

def load_text_file(path: Path) -> str:
    try:
        if path.exists():
            return path.read_text(encoding='utf-8-sig')
    except Exception:
        pass
    return ''

def get_local_ip() -> str:
    import socket
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        s.settimeout(1.5)
        s.connect(("8.8.8.8", 80))
        ip = s.getsockname()[0]
        s.close()
        return str(ip)
    except Exception:
        try:
            return str(socket.gethostbyname(socket.gethostname()))
        except Exception:
            return "127.0.0.1"

def get_server_port() -> int:
    try:
        from streamlit import config as st_config
        return int(st_config.get_option("server.port"))
    except Exception:
        return 8501

def make_qr_svg(url: str) -> Optional[str]:
    try:
        import qrcode
        import qrcode.image.svg
        img = qrcode.make(url, image_factory=qrcode.image.svg.SvgPathImage, box_size=12, border=2)
        buf = BytesIO()
        img.save(buf)
        return buf.getvalue().decode("utf-8")
    except Exception:
        return None

def render_mobile_access_panel() -> None:
    ip = get_local_ip()
    port = get_server_port()
    url = f"http://{ip}:{port}"
    st.markdown(f"**접속 주소** : `{url}`")
    st.caption("스마트폰이 PC와 같은 와이파이에 연결되어 있어야 합니다.")
    svg = make_qr_svg(url)
    if svg is not None:
        svg_inner = re.sub(r"<\?xml[^>]*\?>", "", svg).strip()
        st.markdown(f"<div style='background:#ffffff;border-radius:12px;padding:10px;width:190px;margin:0 auto;'>{svg_inner}</div>", unsafe_allow_html=True)
        st.caption("📷 폰 카메라로 QR을 스캔하면 바로 열립니다.")
    else:
        st.info("QR코드는 `pip install qrcode` 후 다시 실행하면 표시됩니다.")
    with st.expander("📡 접속이 안 될 때 점검", expanded=False):
        st.markdown("1. **같은 와이파이**인지 확인\n2. **Windows 방화벽**에서 Python 허용\n3. 회사망 등 AP 격리 환경에서는 기기 간 접속이 차단될 수 있습니다\n4. 어디서나 접속하려면 클라우드 배포 가이드를 참고하세요")


# =============================================================================
# [DRAGGABLE_BOX_UPGRADE] Plotly 차트 박스/풍선 마우스 이동 + 위치 영구 저장 모드
# -----------------------------------------------------------------------------
# 목적:
#   모든 Plotly 차트의 annotation 박스/풍선을 마우스로 직접 이동하고,
#   이동한 좌표를 브라우저 localStorage에 자동 저장하여 새로고침/재실행 후에도 유지합니다.
#
# 저장 방식:
#   - 저장 위치: 브라우저 localStorage
#   - 저장 키  : qt_annpos_v35::<차트키>
#   - 적용 범위: 같은 브라우저/같은 도메인에서 유지
#
# 한계:
#   - Python 서버 파일에 저장하는 방식이 아니므로 다른 브라우저/다른 PC에는 자동 동기화되지 않습니다.
#   - HTML/PNG 다운로드는 Python 원본 fig 기준이므로, 브라우저에서 드래그한 위치가 다운로드물에 반영되지는 않습니다.
# =============================================================================
DRAGGABLE_CHART_CONFIG = {
    "responsive": True,
    # 마우스 휠 스크롤 때 차트가 확대/축소되는 불편을 막기 위해 기본 OFF.
    # 확대는 Plotly 툴바의 zoom/pan 버튼으로 수행하세요.
    "scrollZoom": False,
    "displaylogo": False,
    "editable": True,
    "edits": {
        "annotationPosition": True,
        "annotationTail": True,
        "annotationText": False,
        "titleText": False,
        "axisTitleText": False,
        "legendText": False,
        "colorbarTitleText": False,
        "legendPosition": True,
        "shapePosition": True,
        "colorbarPosition": True,
    },
    "modeBarButtonsToAdd": ["drawline", "drawrect", "eraseshape"],
}

STATIC_CHART_CONFIG = {
    "responsive": True,
    "scrollZoom": False,
    "displaylogo": False,
}


def _chart_box_drag_enabled() -> bool:
    try:
        return bool(st.session_state.get("drag_boxes_mode", True))
    except Exception:
        return True


def _chart_box_persist_enabled() -> bool:
    try:
        return bool(st.session_state.get("persist_box_positions", True))
    except Exception:
        return True


def _chart_position_lock_enabled() -> bool:
    """박스·말풍선·차트 확대/이동 전체 잠금 여부."""
    try:
        return bool(st.session_state.get("lock_chart_positions", False))
    except Exception:
        return False


def _chart_scroll_zoom_enabled() -> bool:
    """마우스 휠 확대 허용 여부. 기본은 False."""
    try:
        return bool(st.session_state.get("chart_scroll_zoom_enabled", False)) and not _chart_position_lock_enabled()
    except Exception:
        return False


def _chart_group_select_enabled() -> bool:
    """차트별 주황색 버튼이 안 보일 때도 사이드바에서 그룹 선택 모드를 강제 활성화합니다."""
    try:
        return bool(st.session_state.get("group_select_mode", False)) and not _chart_position_lock_enabled()
    except Exception:
        return False


def _safe_chart_storage_key(chart_key: Optional[str] = None, fig=None) -> str:
    """localStorage용 차트 키 생성. chart_key가 없으면 호출 위치 기반으로 안정적인 키를 만듭니다."""
    try:
        import inspect
        if not chart_key:
            caller = inspect.stack()[2]
            fn = str(caller.function or "chart")
            ln = int(caller.lineno or 0)
            title = ""
            try:
                title = str(getattr(getattr(fig, "layout", None), "title", None).text or "")[:48]
            except Exception:
                title = ""
            chart_key = f"{fn}_{ln}_{title}"
    except Exception:
        chart_key = chart_key or "chart"
    key = re.sub(r"[^0-9A-Za-z가-힣_.:-]+", "_", str(chart_key)).strip("_")
    return key[:160] or "chart"


def _figure_component_height(fig, extra: int = 56) -> int:
    try:
        h = int(getattr(fig.layout, "height", None) or 650)
    except Exception:
        h = 650
    return max(360, min(2600, h + extra))


def prepare_draggable_annotations(fig):
    """annotation이 마우스 이벤트를 받도록 captureevents를 켭니다."""
    try:
        if getattr(fig.layout, "annotations", None):
            fig.update_annotations(captureevents=True)
    except Exception:
        pass
    return fig


def render_persistent_draggable_plotly_chart(fig, chart_key: Optional[str] = None, use_container_width: bool = True, **kwargs):
    """Plotly 차트를 HTML 컴포넌트로 렌더링하고 annotation 이동 좌표를 localStorage에 저장/복원합니다."""
    try:
        import uuid
        import json as _json
        import plotly.io as pio
        import streamlit.components.v1 as components

        fig = prepare_draggable_annotations(fig)
        storage_key = "qt_annpos_v35::" + _safe_chart_storage_key(chart_key, fig=fig)
        div_id = "qt_plot_" + uuid.uuid4().hex
        height = _figure_component_height(fig)
        plot_height = max(320, height - 46)

        config = dict(DRAGGABLE_CHART_CONFIG)
        locked = _chart_position_lock_enabled()
        config["scrollZoom"] = _chart_scroll_zoom_enabled()
        if locked or not _chart_box_drag_enabled():
            config["editable"] = False
            config["edits"] = {}
        if locked:
            # 저장된 위치를 보는 전용 모드: 휠 확대, 드래그 이동, 모드바 확대 버튼을 제거해 전체 위치를 고정합니다.
            config["scrollZoom"] = False
            config["modeBarButtonsToRemove"] = [
                "zoom2d", "pan2d", "select2d", "lasso2d", "zoomIn2d", "zoomOut2d",
                "autoScale2d", "resetScale2d", "drawline", "drawrect", "eraseshape"
            ]

        # CDN 방식은 HTML 크기를 작게 유지합니다. 네트워크가 막힌 환경에서는 st.plotly_chart fallback을 사용하세요.
        plot_html = pio.to_html(
            fig,
            include_plotlyjs="cdn",
            full_html=False,
            config=config,
            div_id=div_id,
            default_width="100%" if use_container_width else None,
            default_height=f"{plot_height}px",
            validate=False,
        )
        storage_key_js = _json.dumps(storage_key, ensure_ascii=False)
        drag_enabled_js = "true" if _chart_box_drag_enabled() else "false"
        persist_enabled_js = "true" if _chart_box_persist_enabled() else "false"
        # 연간 실적 막대 차트는 데이터 연도/범주가 갱신되므로 과거 x축 range 복원을 금지합니다.
        # annotation 위치 저장은 유지하되 축 범위만 항상 새 데이터 기준으로 렌더링합니다.
        _axis_reset_keys = ("fundamental_financial_trend", "backtest_performance")
        persist_axes_js = "false" if str(chart_key or "").startswith(_axis_reset_keys) else "true"
        lock_enabled_js = "true" if _chart_position_lock_enabled() else "false"
        group_default_js = "true" if _chart_group_select_enabled() else "false"

        html_doc = f"""
<div class="qt-persist-wrap" style="width:100%;">
  <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin:0 0 6px 0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;font-size:13px;color:#9db4cf;position:sticky;top:0;z-index:2147483647;background:rgba(5,9,17,0.88);padding:3px 0;">
    <button id="{div_id}_group" title="클릭 후 차트 위에서 마우스로 사각형 범위를 그리면 박스들이 선택됩니다. 선택 후 드래그하면 한꺼번에 이동합니다." style="background:linear-gradient(135deg,#f59e0b,#d97706);color:#08111f;border:1px solid rgba(255,209,102,0.95);border-radius:8px;padding:4px 10px;font-size:13px;font-weight:900;cursor:pointer;box-shadow:0 0 0 1px rgba(255,209,102,0.18);">□ 박스 범위선택</button>
    <button id="{div_id}_select_right" title="차트 오른쪽 rail에 있는 가격/지지/저항/상한가/하한가 박스들을 자동으로 선택합니다." style="background:#243b63;color:#e7f2ff;border:1px solid rgba(99,179,237,0.45);border-radius:7px;padding:3px 8px;font-size:13px;font-weight:800;cursor:pointer;">우측박스 전체선택</button>
    <button id="{div_id}_clear_sel" style="background:#13233a;color:#cfe8ff;border:1px solid rgba(99,179,237,0.28);border-radius:7px;padding:3px 8px;font-size:13px;cursor:pointer;">선택해제</button>
    <span style="padding:2px 7px;border:1px solid rgba(255,209,102,0.28);border-radius:999px;background:rgba(5,9,17,0.52);">📦 그룹선택 {'ON' if _chart_group_select_enabled() else 'OFF'}</span>
    <span style="padding:2px 7px;border:1px solid rgba(99,179,237,0.28);border-radius:999px;background:rgba(5,9,17,0.72);">🖱 박스 이동 {'OFF' if _chart_position_lock_enabled() else 'ON' if _chart_box_drag_enabled() else 'OFF'}</span>
    <span style="padding:2px 7px;border:1px solid rgba(99,179,237,0.18);border-radius:999px;background:rgba(5,9,17,0.52);">💾 위치 저장 {'ON' if _chart_box_persist_enabled() else 'OFF'}</span>
    <span style="padding:2px 7px;border:1px solid rgba(255,209,102,0.22);border-radius:999px;background:rgba(5,9,17,0.52);">🔒 전체 고정 {'ON' if _chart_position_lock_enabled() else 'OFF'}</span>
    <button id="{div_id}_reset" style="margin-left:auto;background:#13233a;color:#cfe8ff;border:1px solid rgba(99,179,237,0.35);border-radius:7px;padding:3px 8px;font-size:13px;cursor:pointer;">이 차트 위치 초기화</button>
    <span id="{div_id}_status" style="min-width:90px;text-align:right;color:#7fa6c8;"></span>
  </div>
  {plot_html}
</div>
<script>
(function() {{
  const gdId = { _json.dumps(div_id) };
  const storageKey = {storage_key_js};
  const dragEnabled = {drag_enabled_js};
  const persistEnabled = {persist_enabled_js};
  const persistAxes = {persist_axes_js};
  const lockEnabled = {lock_enabled_js};
  const groupDefault = {group_default_js};
  const statusEl = document.getElementById(gdId + '_status');
  const resetBtn = document.getElementById(gdId + '_reset');
  const groupBtn = document.getElementById(gdId + '_group');
  const selectRightBtn = document.getElementById(gdId + '_select_right');
  const clearSelBtn = document.getElementById(gdId + '_clear_sel');
  let applying = false;
  let groupMode = false;
  let selectedIdx = [];
  let groupOverlay = null;
  let selectRectEl = null;

  function setStatus(msg) {{
    if (statusEl) statusEl.textContent = msg || '';
  }}

  function cleanText(s) {{
    return String(s || '')
      .replace(/<[^>]*>/g, '')
      .replace(/[0-9.,:%+-]+/g, '#')
      .replace(new RegExp('\\\\s+', 'g'), ' ')
      .trim()
      .slice(0, 120);
  }}

  function snapshot(gd) {{
    const anns = (gd && gd.layout && gd.layout.annotations) ? gd.layout.annotations : [];
    return anns.map(function(a, i) {{
      return {{
        i: i,
        sig: cleanText(a.text),
        x: a.x,
        y: a.y,
        ax: a.ax,
        ay: a.ay,
        xref: a.xref,
        yref: a.yref,
        axref: a.axref,
        ayref: a.ayref,
        xanchor: a.xanchor,
        yanchor: a.yanchor,
        visible: a.visible
      }};
    }});
  }}

  function snapshotAxes(gd) {{
    const out = {{}};
    if (!gd || !gd.layout) return out;
    Object.keys(gd.layout).forEach(function(k) {{
      if (/^[xy]axis[0-9]*$/.test(k)) {{
        const ax = gd.layout[k] || {{}};
        if (Array.isArray(ax.range) && ax.range.length >= 2) {{
          out[k + '.range'] = [ax.range[0], ax.range[1]];
        }}
        if (ax.autorange !== undefined) out[k + '.autorange'] = ax.autorange;
      }}
    }});
    if (gd.layout.dragmode !== undefined) out['dragmode'] = gd.layout.dragmode;
    return out;
  }}

  function savePositions(gd) {{
    if (!persistEnabled || !dragEnabled || applying) return;
    try {{
      const payload = {{
        version: 3,
        savedAt: new Date().toISOString(),
        annotations: snapshot(gd),
        axes: persistAxes ? snapshotAxes(gd) : {{}}
      }};
      localStorage.setItem(storageKey, JSON.stringify(payload));
      setStatus('저장됨');
      setTimeout(function() {{ setStatus(''); }}, 1400);
    }} catch(e) {{
      setStatus('저장 실패');
      console.warn('annotation save failed', e);
    }}
  }}

  function applySavedPositions(gd) {{
    if (!persistEnabled || !gd || !gd.layout) return;
    let raw = null;
    try {{ raw = localStorage.getItem(storageKey); }} catch(e) {{ return; }}
    if (!raw) return;
    let payload = null;
    try {{ payload = JSON.parse(raw); }} catch(e) {{ return; }}
    const saved = Array.isArray(payload) ? payload : (payload.annotations || []);
    const savedAxes = (persistAxes && !Array.isArray(payload) && payload.axes && typeof payload.axes === 'object') ? payload.axes : {{}};
    if ((!Array.isArray(saved) || !saved.length) && !Object.keys(savedAxes).length) return;

    const anns = gd.layout.annotations || [];
    const used = {{}};
    const update = {{}};
    const props = ['x','y','ax','ay','xref','yref','axref','ayref','xanchor','yanchor','visible'];

    Object.keys(savedAxes).forEach(function(k) {{
      if (savedAxes[k] !== undefined && savedAxes[k] !== null) update[k] = savedAxes[k];
    }});

    saved.forEach(function(p, fallbackIndex) {{
      let idx = -1;
      if (p && p.sig) {{
        for (let i = 0; i < anns.length; i++) {{
          if (!used[i] && cleanText(anns[i].text) === p.sig) {{ idx = i; break; }}
        }}
      }}
      if (idx < 0 && Number.isInteger(p.i) && p.i >= 0 && p.i < anns.length && !used[p.i]) {{
        if (!p.sig || cleanText(anns[p.i].text) === p.sig) idx = p.i;
      }}
      if (idx < 0 || !anns[idx]) return;
      used[idx] = true;
      props.forEach(function(k) {{
        if (p[k] !== undefined && p[k] !== null) update['annotations[' + idx + '].' + k] = p[k];
      }});
    }});

    if (Object.keys(update).length) {{
      applying = true;
      Plotly.relayout(gd, update).then(function() {{
        applying = false;
        setStatus('복원됨');
        setTimeout(function() {{ setStatus(''); }}, 1400);
      }}).catch(function() {{ applying = false; }});
    }}
  }}


  function annNodes(gd) {{
    const raw = Array.from(gd.querySelectorAll('g.annotation, g[class*="annotation"]'));
    const seen = new Set();
    const out = [];
    raw.forEach(function(n) {{
      const g = n.closest('g.annotation') || n;
      if (!seen.has(g)) {{ seen.add(g); out.push(g); }}
    }});
    return out;
  }}

  function clearGroupSelection(gd) {{
    selectedIdx = [];
    annNodes(gd).forEach(function(n) {{
      n.classList.remove('qt-ann-selected');
      n.style.filter = '';
    }});
    setStatus(groupMode ? '그룹선택 ON' : '');
  }}

  function markGroupSelection(gd) {{
    const nodes = annNodes(gd);
    nodes.forEach(function(n, i) {{
      const on = selectedIdx.indexOf(i) >= 0;
      n.classList.toggle('qt-ann-selected', on);
      n.style.filter = on ? 'drop-shadow(0 0 5px #ffd166) drop-shadow(0 0 2px #ffffff)' : '';
    }});
    if (selectedIdx.length) setStatus('선택 ' + selectedIdx.length + '개');
  }}

  function rectsIntersect(a, b) {{
    return !(a.right < b.left || a.left > b.right || a.bottom < b.top || a.top > b.bottom);
  }}

  function axisNameFromRef(ref, xy) {{
    ref = String(ref || xy || '');
    ref = ref.replace(' domain', '');
    if (ref === xy) return xy + 'axis';
    const n = ref.replace(/[^0-9]/g, '');
    return xy + 'axis' + (n || '');
  }}

  function axisDelta(gd, ref, pixels, isY) {{
    try {{
      const full = gd._fullLayout || gd.layout || {{}};
      const axName = axisNameFromRef(ref, isY ? 'y' : 'x');
      const ax = full[axName];
      const size = full._size || {{w: gd.clientWidth || 800, h: gd.clientHeight || 500}};
      const domain = (ax && ax.domain) ? ax.domain : [0, 1];
      const pixSpan = Math.max(1, (isY ? size.h : size.w) * Math.abs(domain[1] - domain[0]));
      const range = (ax && ax.range) ? ax.range : [0, 1];
      let r0 = range[0], r1 = range[1];
      if (ax && ax.type === 'date') {{ r0 = new Date(r0).getTime(); r1 = new Date(r1).getTime(); }}
      else {{ r0 = Number(r0); r1 = Number(r1); }}
      if (!isFinite(r0) || !isFinite(r1)) return 0;
      const sign = isY ? -1 : 1;
      return sign * pixels * (r1 - r0) / pixSpan;
    }} catch(e) {{ return 0; }}
  }}

  function addDeltaToCoord(baseVal, delta, isDate) {{
    if (isDate) {{
      const t = new Date(baseVal).getTime();
      if (isFinite(t)) return new Date(t + delta).toISOString();
      return baseVal;
    }}
    const v = Number(baseVal);
    return isFinite(v) ? v + delta : baseVal;
  }}

  function buildGroupMoveUpdate(gd, bases, dx, dy) {{
    const update = {{}};
    const full = gd._fullLayout || gd.layout || {{}};
    bases.forEach(function(b) {{
      const i = b.i;
      const a = b.a || {{}};
      const showArrow = !!a.showarrow;
      if (showArrow) {{
        // 화살표 박스는 x/y(머리)가 실제 가격 위치, ax/ay(꼬리)가 박스 위치입니다.
        // 그룹 이동 시에는 머리가 아니라 박스 위치(ax/ay)를 이동합니다.
        if (!a.axref || a.axref === 'pixel') update['annotations[' + i + '].ax'] = (Number(a.ax || 0) + dx);
        else if (String(a.axref || '').indexOf('paper') >= 0 || String(a.axref || '').indexOf('domain') >= 0) update['annotations[' + i + '].ax'] = Number(a.ax || 0) + dx / Math.max(gd.clientWidth || 800, 1);
        else {{
          const axName = axisNameFromRef(a.axref || 'x', 'x');
          const isDate = full[axName] && full[axName].type === 'date';
          update['annotations[' + i + '].ax'] = addDeltaToCoord(a.ax, axisDelta(gd, a.axref || 'x', dx, false), isDate);
        }}
      }} else if (String(a.xref || '').indexOf('paper') >= 0 || String(a.xref || '').indexOf('domain') >= 0) update['annotations[' + i + '].x'] = Number(a.x || 0) + dx / Math.max(gd.clientWidth || 800, 1);
      else {{
        const axName = axisNameFromRef(a.xref || 'x', 'x');
        const isDate = full[axName] && full[axName].type === 'date';
        update['annotations[' + i + '].x'] = addDeltaToCoord(a.x, axisDelta(gd, a.xref || 'x', dx, false), isDate);
      }}
      if (showArrow) {{
        if (!a.ayref || a.ayref === 'pixel') update['annotations[' + i + '].ay'] = (Number(a.ay || 0) + dy);
        else if (String(a.ayref || '').indexOf('paper') >= 0 || String(a.ayref || '').indexOf('domain') >= 0) update['annotations[' + i + '].ay'] = Number(a.ay || 0) - dy / Math.max(gd.clientHeight || 500, 1);
        else {{
          const ayName = axisNameFromRef(a.ayref || 'y', 'y');
          const isDateY = full[ayName] && full[ayName].type === 'date';
          update['annotations[' + i + '].ay'] = addDeltaToCoord(a.ay, axisDelta(gd, a.ayref || 'y', dy, true), isDateY);
        }}
      }} else if (String(a.yref || '').indexOf('paper') >= 0 || String(a.yref || '').indexOf('domain') >= 0) update['annotations[' + i + '].y'] = Number(a.y || 0) - dy / Math.max(gd.clientHeight || 500, 1);
      else {{
        const ayName = axisNameFromRef(a.yref || 'y', 'y');
        const isDateY = full[ayName] && full[ayName].type === 'date';
        update['annotations[' + i + '].y'] = addDeltaToCoord(a.y, axisDelta(gd, a.yref || 'y', dy, true), isDateY);
      }}
    }});
    return update;
  }}

  function setupGroupMove(gd) {{
    if (lockEnabled) {{
      if (groupBtn) groupBtn.disabled = true;
      if (clearSelBtn) clearSelBtn.disabled = true;
      return;
    }}
    const wrap = gd.closest('.qt-persist-wrap') || gd.parentElement;
    if (!wrap) return;
    wrap.style.position = 'relative';
    const style = document.createElement('style');
    style.textContent = '.qt-select-rect{{position:absolute;border:1.5px dashed #ffd166;background:rgba(255,209,102,0.13);pointer-events:none;z-index:2147483646}}.qt-group-overlay{{position:absolute;z-index:2147483645;cursor:crosshair;background:rgba(0,0,0,0);}}.qt-group-overlay.moving{{cursor:move;}}';
    wrap.appendChild(style);
    groupOverlay = document.createElement('div');
    groupOverlay.className = 'qt-group-overlay';
    groupOverlay.style.display = 'none';
    wrap.appendChild(groupOverlay);

    function positionOverlay() {{
      const gr = gd.getBoundingClientRect();
      const wr = wrap.getBoundingClientRect();
      let left = gr.left, top = gr.top, right = gr.right, bottom = gr.bottom;
      // 오른쪽 rail의 박스들이 plot div 경계 밖으로 보이는 경우도 선택 가능하도록 annotation bbox까지 포함합니다.
      annNodes(gd).forEach(function(n) {{
        try {{
          const br = n.getBoundingClientRect();
          if (br.width || br.height) {{
            left = Math.min(left, br.left - 24);
            top = Math.min(top, br.top - 24);
            right = Math.max(right, br.right + 36);
            bottom = Math.max(bottom, br.bottom + 24);
          }}
        }} catch(e) {{}}
      }});
      groupOverlay.style.left = (left - wr.left) + 'px';
      groupOverlay.style.top = (top - wr.top) + 'px';
      groupOverlay.style.width = Math.max(40, right - left) + 'px';
      groupOverlay.style.height = Math.max(40, bottom - top) + 'px';
    }}

    function setGroupMode(on) {{
      groupMode = !!on;
      positionOverlay();
      groupOverlay.style.display = groupMode ? 'block' : 'none';
      if (groupBtn) {{
        groupBtn.textContent = groupMode ? '☑ 그룹선택 ON — 이동할 박스들을 드래그로 선택' : '□ 박스 범위선택';
        groupBtn.style.background = groupMode ? 'linear-gradient(135deg,#22c55e,#16a34a)' : 'linear-gradient(135deg,#f59e0b,#d97706)';
      }}
      if (!groupMode) clearGroupSelection(gd);
      else setStatus('드래그로 박스 범위 선택');
    }}

    if (groupBtn) groupBtn.onclick = function() {{ setGroupMode(!groupMode); }};
    if (selectRightBtn) selectRightBtn.onclick = function() {{
      setGroupMode(true);
      positionOverlay();
      const gr = gd.getBoundingClientRect();
      const threshold = gr.left + gr.width * 0.68;
      selectedIdx = [];
      annNodes(gd).forEach(function(n, i) {{
        try {{
          const br = n.getBoundingClientRect();
          const txt = (n.textContent || '').trim();
          // 오른쪽 rail 또는 가격/레벨 박스 키워드가 있는 annotation을 선택합니다.
          const isRight = br.left >= threshold || br.right >= gr.right - 12;
          const isLevel = /(상한|하한|지지|저항|현재가|POC|VAH|VAL|CPR|Fib|확장|AVWAP|ATR|스탑|중심|전환|기준)/.test(txt);
          if ((isRight || isLevel) && (br.width || br.height)) selectedIdx.push(i);
        }} catch(e) {{}}
      }});
      markGroupSelection(gd);
    }};
    if (clearSelBtn) clearSelBtn.onclick = function() {{ clearGroupSelection(gd); }};
    window.addEventListener('resize', positionOverlay);

    let mode = null, sx = 0, sy = 0, bases = [];
    groupOverlay.addEventListener('mousedown', function(e) {{
      if (!groupMode) return;
      e.preventDefault(); e.stopPropagation();
      positionOverlay();
      sx = e.clientX; sy = e.clientY;
      if (selectedIdx.length && !e.shiftKey && !e.altKey) {{
        mode = 'move';
        groupOverlay.classList.add('moving');
        const anns = gd.layout.annotations || [];
        bases = selectedIdx.map(function(i) {{ return {{i: i, a: Object.assign({{}}, anns[i] || {{}})}}; }});
      }} else {{
        mode = 'select';
        if (selectRectEl) selectRectEl.remove();
        selectRectEl = document.createElement('div');
        selectRectEl.className = 'qt-select-rect';
        wrap.appendChild(selectRectEl);
        selectRectEl.style.left = (sx - wrap.getBoundingClientRect().left) + 'px';
        selectRectEl.style.top = (sy - wrap.getBoundingClientRect().top) + 'px';
        selectRectEl.style.width = '0px'; selectRectEl.style.height = '0px';
      }}
    }});

    window.addEventListener('mousemove', function(e) {{
      if (!groupMode || !mode) return;
      e.preventDefault();
      if (mode === 'select' && selectRectEl) {{
        const wr = wrap.getBoundingClientRect();
        const x0 = Math.min(sx, e.clientX), y0 = Math.min(sy, e.clientY);
        const x1 = Math.max(sx, e.clientX), y1 = Math.max(sy, e.clientY);
        selectRectEl.style.left = (x0 - wr.left) + 'px';
        selectRectEl.style.top = (y0 - wr.top) + 'px';
        selectRectEl.style.width = (x1 - x0) + 'px';
        selectRectEl.style.height = (y1 - y0) + 'px';
      }} else if (mode === 'move') {{
        const dx = e.clientX - sx, dy = e.clientY - sy;
        Plotly.relayout(gd, buildGroupMoveUpdate(gd, bases, dx, dy));
      }}
    }}, true);

    window.addEventListener('mouseup', function(e) {{
      if (!groupMode || !mode) return;
      e.preventDefault();
      if (mode === 'select') {{
        const x0 = Math.min(sx, e.clientX), y0 = Math.min(sy, e.clientY);
        const x1 = Math.max(sx, e.clientX), y1 = Math.max(sy, e.clientY);
        const selRect = {{left:x0, top:y0, right:x1, bottom:y1}};
        selectedIdx = [];
        annNodes(gd).forEach(function(n, i) {{
          const br = n.getBoundingClientRect();
          if ((x1 - x0) > 8 && (y1 - y0) > 8 && rectsIntersect(selRect, br)) selectedIdx.push(i);
        }});
        if (selectRectEl) {{ selectRectEl.remove(); selectRectEl = null; }}
        markGroupSelection(gd);
      }} else if (mode === 'move') {{
        groupOverlay.classList.remove('moving');
        setTimeout(function() {{ savePositions(gd); markGroupSelection(gd); }}, 120);
      }}
      mode = null; bases = [];
    }}, true);

    if (groupDefault) setGroupMode(true);
  }}
  function initWhenReady(tries) {{
    const gd = document.getElementById(gdId);
    if (!gd || !window.Plotly || !gd.layout) {{
      if (tries > 0) setTimeout(function() {{ initWhenReady(tries - 1); }}, 120);
      return;
    }}
    try {{
      applySavedPositions(gd);
      if (lockEnabled) {{
        try {{ Plotly.relayout(gd, {{'dragmode': false}}); }} catch(e) {{}}
      }}
      if (dragEnabled && persistEnabled && !lockEnabled) {{
        gd.on('plotly_relayout', function(ev) {{
          const keys = Object.keys(ev || {{}});
          const changed = keys.some(function(k) {{
            return k.indexOf('annotations[') === 0 || k.indexOf('shapes[') === 0 || new RegExp('^[xy]axis[0-9]*[.]range').test(k) || new RegExp('^[xy]axis[0-9]*[.]autorange').test(k) || k === 'dragmode';
          }});
          if (changed && !lockEnabled) setTimeout(function() {{ savePositions(gd); }}, 80);
        }});
        gd.addEventListener('mouseup', function() {{ setTimeout(function() {{ savePositions(gd); }}, 220); }});
        gd.addEventListener('touchend', function() {{ setTimeout(function() {{ savePositions(gd); }}, 260); }});
      }}
      if (resetBtn) {{
        resetBtn.onclick = function() {{
          try {{ localStorage.removeItem(storageKey); }} catch(e) {{}}
          setStatus('초기화됨');
          setTimeout(function() {{ window.location.reload(); }}, 250);
        }};
      }}
      setupGroupMove(gd);
      window.addEventListener('resize', function() {{ try {{ Plotly.Plots.resize(gd); }} catch(e) {{}} }});
    }} catch(e) {{
      console.warn('persistent annotation init failed', e);
    }}
  }}
  initWhenReady(80);
}})();
</script>
"""
        return components.html(html_doc, height=height, scrolling=False)
    except Exception as e:
        st.caption(f"박스 위치 저장형 차트 렌더링 실패 → 기본 차트로 대체: {e}")
        return st.plotly_chart(fig, use_container_width=use_container_width, config=DRAGGABLE_CHART_CONFIG if _chart_box_drag_enabled() else STATIC_CHART_CONFIG, **kwargs)


# ── [이슈: 대비 보정] 배경색 휘도 기반 글자색 자동 선택 유틸 ─────────────────
def _qt_parse_bg_rgb(bg):
    """임의 색상 문자열(#hex / #rrggbbaa / rgb() / rgba()) → (r,g,b,alpha) 또는 None."""
    try:
        s = str(bg or "").strip().lower()
        if not s or s in ("none", "transparent"):
            return None
        if s.startswith("rgba"):
            parts = [p.strip() for p in s[5:-1].split(",")]
            r, g, b = (float(parts[0]), float(parts[1]), float(parts[2]))
            a = float(parts[3]) if len(parts) > 3 else 1.0
            return (r, g, b, max(0.0, min(1.0, a)))
        if s.startswith("rgb"):
            parts = [p.strip() for p in s[4:-1].split(",")]
            return (float(parts[0]), float(parts[1]), float(parts[2]), 1.0)
        if s.startswith("#"):
            h = s[1:]
            if len(h) == 3:
                return (int(h[0]*2, 16), int(h[1]*2, 16), int(h[2]*2, 16), 1.0)
            if len(h) >= 6:
                r, g, b = int(h[0:2], 16), int(h[2:4], 16), int(h[4:6], 16)
                a = float(int(h[6:8], 16)) / 255.0 if len(h) >= 8 else 1.0
                return (r, g, b, max(0.0, min(1.0, a)))
        _NAMED = {
            "white": (255,255,255,1.0), "whitesmoke": (245,245,245,1.0),
            "black": (0,0,0,1.0), "gold": (255,215,0,1.0),
            "yellow": (255,255,0,1.0), "orange": (255,165,0,1.0),
            "khaki": (240,230,140,1.0), "lemonchiffon": (255,250,205,1.0),
            "navy": (0,0,128,1.0), "red": (255,0,0,1.0),
        }
        return _NAMED.get(s)
    except Exception:
        return None


def _qt_rel_luminance(r, g, b):
    """WCAG 상대 휘도(linear)."""
    def _lin(c):
        c = float(c) / 255.0
        return c / 12.92 if c <= 0.03928 else ((c + 0.055) / 1.055) ** 2.4
    return 0.2126 * _lin(r) + 0.7152 * _lin(g) + 0.0722 * _lin(b)


def _qt_contrast_ratio(l1, l2):
    hi, lo = max(float(l1), float(l2)), min(float(l1), float(l2))
    return (hi + 0.05) / (lo + 0.05)


def _qt_fix_text_contrast(bg_color, font_color, default="#f1f5f9",
                          dark_on_light="#0b1220", light_on_dark="#f8fafc",
                          min_ratio=3.0):
    """말풍선/배지 배경색 기준 글자색 대비 보정.

    규칙: 밝은 배경→어두운 글자 / 어두운 배경→밝은 글자.
    현재 글자색의 대비가 min_ratio(WCAG) 이상이면 유지, 미만이면 다크/라이트 후보 중
    대비가 큰 쪽으로 교체. 반투명 rgba 배경은 다크 차트 캔버스(#050911) 위에 합성해 평가.
    색상 파싱 불가 시 font_color(없으면 default)를 그대로 반환.
    """
    parsed = _qt_parse_bg_rgb(bg_color)
    if parsed is None:
        return font_color or default
    r, g, b, a = parsed
    # 차트 다크 캔버스 위 합성 (불투명 유효색)
    er = r * a + 5 * (1 - a)
    eg = g * a + 9 * (1 - a)
    eb = b * a + 17 * (1 - a)
    lb = _qt_rel_luminance(er, eg, eb)
    cur = _qt_parse_bg_rgb(font_color)
    if cur is not None:
        lc = _qt_rel_luminance(cur[0], cur[1], cur[2])
        if _qt_contrast_ratio(lc, lb) >= min_ratio:
            return font_color
    dp = _qt_parse_bg_rgb(dark_on_light)
    lp = _qt_parse_bg_rgb(light_on_dark)
    ld = _qt_rel_luminance(dp[0], dp[1], dp[2])
    ll = _qt_rel_luminance(lp[0], lp[1], lp[2])
    return dark_on_light if _qt_contrast_ratio(ld, lb) >= _qt_contrast_ratio(ll, lb) else light_on_dark


def _enhance_all_annotations_readability(fig):
    """[FIX v16.0] 모든 풍선 도움말 가독성 개선 + 가격 라벨(지지/저항/현재가/CPR/ATR/POC)은 샤프/컴팩트 유지

    - 일반 배너: 폰트 11~13, pad 6, border 1.5, opacity 0.97
    - 가격 라벨(우측): 폰트 10~11 유지, pad 4, border 1.2, opacity 0.98 — 겹치지 않게 컴팩트
    - 글자색 대비: 어두운 배경→밝은 글자, 밝은 배경→어두운 글자 고대비
    - [P3-1] 앵커 통일: paper=중앙 고정 / 화살표·shift=방향 일치 (미지정 위치 출렁 제거)
    """
    try:
        if not getattr(fig.layout, 'annotations', None):
            return fig
        PRICE_KEYWORDS = ("지지","저항","현재가","POC","VAH","VAL","CPR","ATR","기준","전환","AVWAP","SuperTrend","Chandelier","Fib","확장","매물")
        for ann in fig.layout.annotations:
            try:
                txt = str(getattr(ann, 'text', '') or '')
                is_price_label = any(kw in txt for kw in PRICE_KEYWORDS)

                font = getattr(ann, 'font', None)
                bg_raw = getattr(ann, 'bgcolor', None)
                bg = str(bg_raw or '').lower()

                # 폰트 크기
                if font is not None:
                    sz = int(getattr(font, 'size', 0) or 0)
                    if is_price_label:
                        if sz > 0 and sz < 9:  # [이슈: 풍선 글꼴] 하한 7→9
                            font.size = 9
                    else:
                        if sz > 0 and sz < 11:
                            font.size = 11
                    col = str(getattr(font, 'color', '') or '')
                    if bg_raw and '0.001' not in str(bg_raw):  # 투명 마커 제외
                        _fixed_tc = _qt_fix_text_contrast(bg_raw, col)
                        if _fixed_tc and col and _fixed_tc.lower() != col:
                            font.color = _fixed_tc

                if bg_raw and isinstance(bg_raw, str) and 'rgba' in bg_raw:
                    if '0.001' not in bg_raw:
                        new_bg = re.sub(r'0\.8[0-9]|0\.9[0-2]', '0.97', bg_raw)
                        ann.bgcolor = new_bg
                        bg = new_bg.lower()

                bp = getattr(ann, 'borderpad', None)
                if bp is not None and isinstance(bp, (int, float)):
                    if is_price_label:
                        if bp < 1:
                            ann.borderpad = 1
                        elif bp > 3:
                            ann.borderpad = 1
                    else:
                        if bp < 6:
                            ann.borderpad = 6

                bw = getattr(ann, 'borderwidth', None)
                if bw is not None and isinstance(bw, (int, float)):
                    if not (bg_raw and '0.001' in str(bg_raw)):
                        if is_price_label:
                            if bw < 0.7 or bw > 1.6:
                                ann.borderwidth = 0.8
                        else:
                            if bw < 1.4:
                                ann.borderwidth = 1.5

                op = getattr(ann, 'opacity', None)
                if op is not None and isinstance(op, (int, float)) and op < 0.94:
                    if not (bg_raw and '0.001' in str(bg_raw)):
                        ann.opacity = 0.98 if is_price_label else 0.97
                # [P3-1] 앵커 규칙 통일 — Plotly 'auto' 기본값은 데이터 위치에 따라
                # 좌/우·상/하 정렬이 달라져 종목이나 기간이 바뀔 때 같은 박스가 반대편으로 튐.
                # 규칙: ① paper 좌표 박스 → center/middle 고정
                #       ② 데이터 좌표 + 화살표(ax/ay 픽셀 오프셋) → 화살표 방향과 정렬 일치
                #       ③ xshift/yshift만 있는 박스 → shift 방향과 정렬 일치 (없으면 center/bottom)
                # 명시한 앵커가 있는 박스는 절대 건드리지 않음 (xa/ya가 None이나 'auto'일 때만).
                try:
                    xref_s = str(getattr(ann, 'xref', '') or '')
                    yref_s = str(getattr(ann, 'yref', '') or '')
                    uses_paper = ('paper' in xref_s) or ('paper' in yref_s)
                    xa = getattr(ann, 'xanchor', None)
                    ya = getattr(ann, 'yanchor', None)
                    if xa in (None, 'auto') and not is_price_label:  # [이슈3b] 가격 레일은 compute_label_layout 패킹 관할 — 정규화 제외
                        if uses_paper:
                            ann.xanchor = 'center'
                        else:
                            ax_v = getattr(ann, 'ax', None)
                            xs_v = getattr(ann, 'xshift', None)
                            if ax_v is not None:
                                ann.xanchor = 'left' if float(ax_v) >= 0 else 'right'
                            elif xs_v is not None and float(xs_v) != 0:
                                ann.xanchor = 'left' if float(xs_v) >= 0 else 'right'
                            else:
                                ann.xanchor = 'center'
                    if ya in (None, 'auto') and not is_price_label:  # [이슈3b] 동일
                        if uses_paper:
                            ann.yanchor = 'middle'
                        else:
                            ay_v = getattr(ann, 'ay', None)
                            ys_v = getattr(ann, 'yshift', None)
                            if ay_v is not None:
                                ann.yanchor = 'top' if float(ay_v) > 0 else 'bottom'
                            elif ys_v is not None and float(ys_v) != 0:
                                ann.yanchor = 'bottom' if float(ys_v) > 0 else 'top'
                            else:
                                ann.yanchor = 'bottom'
                except Exception:
                    pass

            except Exception:
                continue
        return fig
    except Exception:
        return fig



# ══════════════════════════════════════════════════════════════════════════════
# [자동배치 v1] 차트 주석 박스 초기 충돌 자동 해소 패스 (승인: 전 가격축·보수적·수동저장 우선)
# ══════════════════════════════════════════════════════════════════════════════
def _hoist_chart_top_headers(fig, stack_gap_px: float = 10.0, top_pad_px: float = 2.0,
                             x_max_paper: float = 0.035, y_min_paper: float = 0.975):
    """[자동배치] 제목/범례 박스가 차트 본문을 가리지 않도록 하는 공통 자동 배치.

    1단계(차트 상단): 좌측 상단 박스(전체 제목 배너·1행 배너·서브플롯 제목)를
      플롯 영역 밖(상단 마진)으로 위→아래 스택 이격 + 상단 마진(t) 자동 확보.
    2단계(내부 행): 어떤 서브행의 도메인 상단에 붙어 있는 배너(y≈해당 축 domain top)를
      위해 그 행 도메인 상단을 배너 높이만큼 축소 → 전용 스트립을 실제로 확보
      (같은 상단을 쓰는 보조축 동기화. 차트 높이/마진 확정 후라 픽셀 정확).
    주석 순서·개수·텍스트·x좌표 불변 → 수동 드래그 저장(localStorage 인덱스) 복원과 공존.
    """
    try:
        anns = list(getattr(fig.layout, 'annotations', None) or [])
        if not anns:
            return fig
        try:
            H = float(getattr(fig.layout, 'height', None) or 700.0)
        except Exception:
            H = 700.0
        if H < 240.0:
            H = 700.0
        m = getattr(fig.layout, 'margin', None)

        def _mget(name, dflt):
            try:
                v = getattr(m, name, None) if m is not None else None
                return float(v) if isinstance(v, (int, float)) else float(dflt)
            except Exception:
                return float(dflt)

        mt0 = _mget('t', 60.0)
        mb0 = _mget('b', 40.0)
        plot_h0 = max(H - mt0 - mb0, 120.0)
        _tag_re = re.compile(r'<[^>]+>')

        def _est_h_px(ann):
            try:
                txt = str(getattr(ann, 'text', '') or '')
                parts = txt.split('<br>') if '<br>' in txt else txt.split(chr(10))
                n_lines = max(1, len(parts))
                fs = float(getattr(getattr(ann, 'font', None), 'size', None) or 12.0)
                pad = getattr(ann, 'borderpad', None)
                pad = float(pad) if isinstance(pad, (int, float)) else 4.0
                bw = getattr(ann, 'borderwidth', None)
                bw = float(bw) if isinstance(bw, (int, float)) else 0.0
                # [FINAL23] plotly 실측 줄높이 보정: fs*1.25 (1.32는 배너류에서 최대 +7px 과대 → 잔여 여백 원인)
                return max(14.0, n_lines * fs * 1.25 + 2 * pad + 2 * bw)
            except Exception:
                return 24.0

        def _is_top_header(ann):
            try:
                if str(getattr(ann, 'xref', '') or '') != 'paper':
                    return False
                if str(getattr(ann, 'yref', '') or '') != 'paper':
                    return False
                if bool(getattr(ann, 'showarrow', False)):
                    return False
                if '📍' in str(getattr(ann, 'text', '') or ''):
                    return False  # 현재가 카드(FINAL16 고정 존)
                xa = str(getattr(ann, 'xanchor', 'left') or 'left')
                if xa != 'left':
                    return False
                xv = float(getattr(ann, 'x', 0.5) or 0.5)
                yv_raw = getattr(ann, 'y', None)
                if yv_raw is None:
                    return False
                return xv <= x_max_paper
            except Exception:
                return False

        # ── 1단계: 상단 스택 이격 ──
        _CIRCLED = '①②③④⑤⑥⑦⑧⑨⑩⑪⑫⑬⑭⑮'
        def _is_vis(ann):
            try:
                return getattr(ann, 'visible', True) is not False
            except Exception:
                return True

        heads = []
        for i, ann in enumerate(anns):
            try:
                if not _is_vis(ann):
                    continue
                if not _is_top_header(ann):
                    continue
                yv = float(getattr(ann, 'y'))
                if yv < y_min_paper:
                    continue
                plain = _tag_re.sub('', str(getattr(ann, 'text', '') or '')).strip()
                is_row = 1 if (plain and plain[0] in _CIRCLED) else 0
                try:
                    yshift = float(getattr(ann, 'yshift', 0) or 0)
                except Exception:
                    yshift = 0.0
                scr_top = mt0 - (yv - 1.0) * plot_h0 - yshift  # 현재 박스 상단의 캔버스-상단 기준 px(근사)
                heads.append({'i': i, 'ann': ann, 'h': _est_h_px(ann),
                              'is_row': is_row, 'scr': scr_top})
            except Exception:
                continue
        # ── [FINAL22] 상단 📍 현재값 칩 박스 그룹 수집 ──
        # apply_smart_annotation_layout / add_current_position_marker 가 만드는 상단 현재값 칩(📍)을
        # hoist에 편입한다. 어떤 차트든(메인/엘리트/Fib/엘리어트/CCI전략…) 칩 행 밑단이 차트 상단 끝선에
        # 밀착하고, 마진 축소 시 칩 상단이 캔버스 밖으로 잘리던 문제(FINAL21 미편입 부작용)를 방지한다.
        # x/xshift/yshift/텍스트/앵커는 보존하고 paper y만 그룹 균등 이동 → 수동 드래그 저장 위치와 공존.
        chips = []
        for i, ann in enumerate(anns):
            try:
                if not _is_vis(ann):
                    continue
                if str(getattr(ann, 'xref', '') or '') != 'paper':
                    continue
                if str(getattr(ann, 'yref', '') or '') != 'paper':
                    continue
                if bool(getattr(ann, 'showarrow', False)):
                    continue
                if '📍' not in str(getattr(ann, 'text', '') or ''):
                    continue
                yv_raw = getattr(ann, 'y', None)
                if yv_raw is None or float(yv_raw) < y_min_paper:
                    continue
                chips.append({'i': i, 'ann': ann, 'h': _est_h_px(ann)})
            except Exception:
                continue

        def _ann_w_px(ann):
            try:
                w = getattr(ann, 'width', None)
                if isinstance(w, (int, float)) and float(w) > 0:
                    return float(w)
                txt = str(getattr(ann, 'text', '') or '')
                parts = txt.split('<br>') if '<br>' in txt else txt.split(chr(10))
                n_chars = max(1, max(len(_tag_re.sub('', p)) for p in parts))
                fs = float(getattr(getattr(ann, 'font', None), 'size', None) or 12.0)
                pad = getattr(ann, 'borderpad', None)
                pad = float(pad) if isinstance(pad, (int, float)) else 4.0
                bw = getattr(ann, 'borderwidth', None)
                bw = float(bw) if isinstance(bw, (int, float)) else 0.0
                return min(n_chars * fs * 0.62 + 2 * pad + 2 * bw, 640.0)
            except Exception:
                return 160.0

        if heads or chips:
            # 전체 제목 배너가 가장 위, ①②… 행 배너는 그 아래 — 같은 부류끼리는 현재 화면 순서 유지
            heads.sort(key=lambda r: (r['is_row'], r['scr']))
            stack_h = (sum(hd['h'] for hd in heads) + stack_gap_px * (len(heads) - 1)) if heads else 0.0

            # [FINAL21] 사용자 요청: 제목/레벨 박스를 차트 상단 끝선에 '밀착'
            # ① 기존 마진이 필요치보다 크면 자동 축소(하한 52px) — 박스-차트 사이 공백 제거
            # ② 스택을 아래(플롯 쪽) 정렬: 마지막 박스 밑단이 플롯 상단 4px 위에 붙음 — 여백은 위쪽으로만
            # [FINAL22] ③ 📍 칩 행도 동일 밀착 기준 편입 — 필요 마진에 칩 높이(span)를 예약해 상단 잘림 방지,
            #           배너와 칩의 수평 여유(≥10px)가 있으면 같은 밴드(기존 마진 거의 유지), 좁으면 자동 적층
            try:
                W_fig = float(getattr(fig.layout, 'width', None) or 1280.0)
            except Exception:
                W_fig = 1280.0

            def _chip_geometry(mt_g, ph_g):
                rows = []
                for c in chips:
                    try:
                        a = c['ann']
                        yv = float(getattr(a, 'y', 1.0) or 1.0)
                        try:
                            ys = float(getattr(a, 'yshift', 0) or 0)
                        except Exception:
                            ys = 0.0
                        ya = str(getattr(a, 'yanchor', 'top') or 'top')
                        anc = mt_g - (yv - 1.0) * ph_g - ys
                        h = c['h']
                        if ya == 'middle':
                            t, b = anc - h / 2.0, anc + h / 2.0
                        elif ya == 'bottom':
                            t, b = anc - h, anc
                        else:
                            t, b = anc, anc + h
                        w = _ann_w_px(a)
                        try:
                            xv = float(getattr(a, 'x', 0.0) or 0.0) * W_fig
                            xs = float(getattr(a, 'xshift', 0) or 0)
                        except Exception:
                            xv, xs = 0.0, 0.0
                        xa = str(getattr(a, 'xanchor', 'left') or 'left')
                        cx = xv + xs
                        if xa == 'center':
                            lft = cx - w / 2.0
                        elif xa == 'right':
                            lft = cx - w
                        else:
                            lft = cx
                        rows.append({'ann': a, 't': t, 'b': b, 'l': lft, 'r': lft + w, 'h': h})
                    except Exception:
                        continue
                return rows

            def _heads_right_edge():
                rgt = 0.0
                for hd in heads:
                    try:
                        a = hd['ann']
                        xv = float(getattr(a, 'x', 0.0) or 0.0) * W_fig
                        rgt = max(rgt, xv + _ann_w_px(a))
                    except Exception:
                        continue
                return rgt

            # [FINAL23] '눈에 보이는 차트 상단선'(1행 y축 도메인 상단) 기준 밀착.
            # make_subplots 수직 간격으로 플롯 배경은 paper 1.0보다 dom_gap 만큼 아래에서 시작함
            # (메인 0.0236/엘리트 0.0248 ≈ 30~44px) → paper 끝 기준 밀착은 이 밴드만큼 공백으로 보여
            # 박스 밑단을 (플롯 배경 상단 - 4px)에 맞춘다. dom_top=1.0 차트는 기존과 동일.
            dom_top = 1.0
            try:
                for _n_dm in range(1, 41):
                    _nm_dm = 'yaxis' if _n_dm == 1 else f'yaxis{_n_dm}'
                    _ax_dm = getattr(fig.layout, _nm_dm, None)
                    if _ax_dm is None:
                        continue
                    _dom_dm = getattr(_ax_dm, 'domain', None)
                    if _dom_dm and len(_dom_dm) == 2:
                        _t_dm = float(_dom_dm[1])
                        if _t_dm > 0.85:
                            dom_top = min(dom_top, _t_dm)  # 1행(최상단) 시각적 플롯 상단 = 최소 도메인 상단
                E = min(max(1.0 - dom_top, 0.0), 0.20)
            except Exception:
                E = 0.0

            same_band = False
            span_band = 0.0
            new_mt = None
            for _pass in range(3):
                if _pass == 0:
                    need0 = stack_h + (stack_gap_px if (heads and chips) else 0.0) + top_pad_px + 6.0
                    # edge(mt) = mt + E*(H-mt-mb0) ≥ need0 를 푸는 고정점 초기값
                    guess0 = max((need0 - E * (H - mb0)) / max(1.0 - E, 0.5), 0.0)
                    guess = max(guess0, 52.0) if mt0 > guess0 else min(guess0, H * 0.45)
                else:
                    guess = new_mt
                ph_g = max(H - guess - mb0, 120.0)
                rows_g = _chip_geometry(guess, ph_g) if chips else []
                if rows_g:
                    span_band = max(r['b'] for r in rows_g) - min(r['t'] for r in rows_g)
                    same_band = bool(heads) and (min(r['l'] for r in rows_g) - _heads_right_edge() >= 10.0)
                else:
                    span_band, same_band = 0.0, False
                rows_h = max(stack_h, span_band) if same_band else (stack_h + (stack_gap_px if (heads and chips) else 0.0) + span_band)
                need_stack = max(rows_h + top_pad_px + 6.0, 0.0)
                need_mt = max((need_stack - E * (H - mb0)) / max(1.0 - E, 0.5), 0.0)
                cand = max(need_mt, 52.0) if mt0 > need_mt else min(need_mt, H * 0.45)  # 극단적 다중 박스 시 플롯 최소 55% 보장
                if new_mt is not None and abs(cand - new_mt) < 0.75:
                    new_mt = cand
                    break
                new_mt = cand
            plot_h = max(H - new_mt - mb0, 120.0)
            edge_px = new_mt + E * plot_h  # 눈에 보이는 차트 상단선(플롯 배경 위쪽 경계) 캔버스 y

            cursor_bottom = edge_px - 4.0
            if chips:
                # 칩 그룹 전체 균등 이동(줄 구조 보존)하여 그룹 밑단을 '보이는 차트 상단선' 4px 위에 밀착
                rows_f = _chip_geometry(new_mt, plot_h)
                if rows_f:
                    grp_bot = max(r['b'] for r in rows_f)
                    delta_px = grp_bot - (edge_px - 4.0)
                    if abs(delta_px) > 0.5:
                        for r in rows_f:
                            try:
                                r['ann'].y = float(getattr(r['ann'], 'y', 1.0) or 1.0) + delta_px / plot_h
                            except Exception:
                                pass
                    grp_top = min(r['t'] for r in rows_f) - delta_px
                    if not same_band:
                        cursor_bottom = grp_top - stack_gap_px
            for hd in reversed(heads):
                try:
                    ann = hd['ann']
                    # 박스 '상단'이 (cursor_bottom - 박스높이) px에 오도록 paper y 역산 (yanchor='top')
                    top_px = cursor_bottom - hd['h']
                    # 도메인 밴드 안(top_px>new_mt)이면 paper y<1이 정상 — 클램프 금지
                    ann.y = float(1.0 + (new_mt - top_px) / plot_h)
                    ann.yanchor = 'top'
                    try:
                        ann.yshift = 0
                    except Exception:
                        pass
                    cursor_bottom = top_px - stack_gap_px
                except Exception:
                    pass
            mt0 = new_mt
            plot_h0 = plot_h

        # ── 2단계: 내부 행 배너 전용 스트립(도메인 축소) ──
        try:
            shrunk = []
            for ann in anns:
                try:
                    if not _is_top_header(ann):
                        continue
                    ya = str(getattr(ann, 'yanchor', 'top') or 'top')
                    if ya != 'top':
                        continue
                    yv_raw = getattr(ann, 'y', None)
                    if yv_raw is None:
                        continue
                    yv = float(yv_raw)
                    if yv >= y_min_paper or yv < 0.15:
                        continue
                    if any(abs(yv - s) <= 0.004 for s in shrunk):
                        continue  # 같은 스트립 이중 축소 방지
                    box_h = _est_h_px(ann)
                    delta = (box_h + 8.0) / max(H, 300.0)
                    hit = False
                    for _n_ax in range(1, 41):
                        _nm_ax = 'yaxis' if _n_ax == 1 else f'yaxis{_n_ax}'
                        try:
                            _ax_obj = getattr(fig.layout, _nm_ax, None)
                            if _ax_obj is None:
                                continue
                            _dom_ax = list(getattr(_ax_obj, 'domain', None) or [])
                            if len(_dom_ax) != 2:
                                continue
                            if abs(float(_dom_ax[1]) - yv) <= 0.004 and (float(_dom_ax[1]) - delta) > (float(_dom_ax[0]) + 0.05):
                                _ax_obj.domain = [float(_dom_ax[0]), float(_dom_ax[1]) - delta]
                                hit = True
                        except Exception:
                            continue
                    if hit:
                        shrunk.append(yv)
                except Exception:
                    continue
        except Exception:
            pass

        try:
            fig.update_layout(margin=dict(t=mt0))
        except Exception:
            pass
        return fig
    except Exception:
        return fig


def _resolve_chart_annotation_collisions(fig, margin_px: float = 8.0, max_iter: int = 4):
    """렌더 직전, 캔들/OHLC 가격축 차트의 주석 박스 겹침을 최소 이동으로 해소.

    - 추정: 텍스트 줄수×폰트·borderpad/borderwidth → 추정 픽셀 박스
    - 고정 존: 우상단 카드(📍), 우측 가격 레일(지지/저항/현재가 등 — 자체 패킹 관할)
    - 이동: 신호 풍선(화살표 ax/ay 또는 xshift/yshift만 조정), 상단 paper 박스(아래로만)
    - 주석 순서·개수·텍스트는 절대 변경하지 않음 → 수동 드래그 저장(localStorage 인덱스) 복원과 공존
    """
    try:
        anns = list(getattr(fig.layout, 'annotations', None) or [])
        if len(anns) < 2:
            return fig
        # 가격축(캔들/OHLC) 차트 판별
        if not any(str(getattr(t, 'type', '')) in ('candlestick', 'ohlc') for t in (fig.data or [])):
            return fig

        try:
            W = float(getattr(fig.layout, 'width', None) or 1280.0)
        except Exception:
            W = 1280.0
        try:
            H = float(getattr(fig.layout, 'height', None) or 640.0)
        except Exception:
            H = 640.0

        # ── row=1 가격축 데이터 범위 추정 (yaxis.range 우선, 없으면 트레이스) ──
        x_min = x_max = None
        y_lo = y_hi = None
        try:
            for t in (fig.data or []):
                if str(getattr(t, 'type', '')) not in ('candlestick', 'ohlc'):
                    continue
                _xs_raw = list(t.x) if getattr(t, 'x', None) is not None else []  # [자동배치 v1.1] numpy 배열 or 금지(ValueError 회귀 수정)
                xs = pd.to_datetime(pd.Series(_xs_raw))
                if len(xs) == 0:
                    continue
                a, b = xs.min(), xs.max()
                x_min = a if x_min is None else min(x_min, a)
                x_max = b if x_max is None else max(x_max, b)
                try:
                    hi = pd.Series(list(t.high if getattr(t, 'high', None) is not None else t.close), dtype=float)
                    lo = pd.Series(list(t.low if getattr(t, 'low', None) is not None else t.close), dtype=float)
                    _hi, _lo = float(hi.max()), float(lo.min())
                    y_hi = _hi if y_hi is None else max(y_hi, _hi)
                    y_lo = _lo if y_lo is None else min(y_lo, _lo)
                except Exception:
                    continue
        except Exception:
            pass
        try:
            yr = getattr(fig.layout.yaxis, 'range', None)
            if yr is not None and len(yr) == 2:
                y_lo, y_hi = float(yr[0]), float(yr[1])
        except Exception:
            pass
        try:
            xr = getattr(fig.layout.xaxis, 'range', None)
            if xr is not None and len(xr) == 2:
                _xr = pd.to_datetime(pd.Series(list(xr)))
                x_min, x_max = _xr.iloc[0], _xr.iloc[1]
        except Exception:
            pass
        if x_min is None or y_lo is None or not np.isfinite(y_lo) or not np.isfinite(y_hi) or not (y_hi > y_lo):
            return fig  # 범위를 못 구하면 보수적으로 손대지 않음
        x_span_sec = max((x_max - x_min).total_seconds(), 1.0)
        y_span = float(y_hi - y_lo)

        try:
            xdom = list(getattr(fig.layout.xaxis, 'domain', None) or [0.0, 1.0])
        except Exception:
            xdom = [0.0, 1.0]
        try:
            ydom = list(getattr(fig.layout.yaxis, 'domain', None) or [0.0, 1.0])
        except Exception:
            ydom = [0.0, 1.0]
        plot_left = float(xdom[0]) * W
        plot_w = max(float(xdom[1] - xdom[0]) * W, 50.0)
        plot_top = (1.0 - float(ydom[1])) * H
        plot_h = max(float(ydom[1] - ydom[0]) * H, 50.0)

        TAG_RE = re.compile(r'<[^>]+>')

        def _est_wh(ann):
            try:
                txt = str(getattr(ann, 'text', '') or '')
                parts = txt.split('<br>') if '<br>' in txt else txt.split(chr(10))
                lines = [TAG_RE.sub('', p) for p in parts] or ['']
                fs = float(getattr(getattr(ann, 'font', None), 'size', None) or 10.0)
                pad = getattr(ann, 'borderpad', None)
                pad = float(pad) if isinstance(pad, (int, float)) else 4.0
                bwd = getattr(ann, 'borderwidth', None)
                bwd = float(bwd) if isinstance(bwd, (int, float)) else 0.0
                w = max(len(s) for s in lines) * fs * 0.62 + 2 * pad + 2 * bwd
                h = len(lines) * fs * 1.32 + 2 * pad + 2 * bwd
                return max(w, 10.0), max(h, 10.0)
            except Exception:
                return 60.0, 18.0

        def _anchor_px(ann):
            """주석 기준점 화면 px(top-origin). paper/데이터(x,y)/혼합(paper x + 데이터 y) 지원."""
            try:
                xref_s = str(getattr(ann, 'xref', '') or '')
                yref_s = str(getattr(ann, 'yref', '') or '')
                px_ = py_ = None
                if xref_s == 'paper':
                    px_ = float(getattr(ann, 'x', 0.5) or 0.5) * W
                elif xref_s in ('x', 'x1'):
                    xv = pd.to_datetime(pd.Series([getattr(ann, 'x', None)])).iloc[0]
                    px_ = plot_left + ((xv - x_min).total_seconds() / x_span_sec) * plot_w
                if yref_s == 'paper':
                    py_ = (1.0 - float(getattr(ann, 'y', 0.5) or 0.5)) * H
                elif yref_s in ('y', 'y1'):
                    yv = float(getattr(ann, 'y', np.nan))
                    if not np.isfinite(yv):
                        return None
                    py_ = plot_top + (1.0 - (yv - y_lo) / y_span) * plot_h
                if px_ is None or py_ is None:
                    return None
                return px_, py_
            except Exception:
                return None

        def _text_center_px(ann):
            base = _anchor_px(ann)
            if base is None:
                return None
            bx, by = base
            try:
                if bool(getattr(ann, 'showarrow', False)):
                    bx += float(getattr(ann, 'ax', 0) or 0)
                    by += float(getattr(ann, 'ay', 0) or 0)
                else:
                    bx += float(getattr(ann, 'xshift', 0) or 0)
                    by -= float(getattr(ann, 'yshift', 0) or 0)  # yshift+ = 위로
            except Exception:
                pass
            w, h = _est_wh(ann)
            xa = str(getattr(ann, 'xanchor', 'center') or 'center')
            ya = str(getattr(ann, 'yanchor', 'middle') or 'middle')
            cx = bx if xa == 'center' else (bx + w / 2.0 if xa == 'left' else bx - w / 2.0)
            cy = by if ya == 'middle' else (by + h / 2.0 if ya == 'top' else by - h / 2.0)
            return cx, cy, w, h

        RAIL_KW = ("지지", "저항", "현재가", "POC", "VAH", "VAL", "CPR", "ATR", "기준", "전환",
                   "Fib", "확장", "매물", "선물", "목표", "손절", "SuperTrend", "Chandelier")

        def _klass(ann):
            txt = str(getattr(ann, 'text', '') or '')
            if '📍' in txt:
                return 'card'
            _axr = str(getattr(ann, 'axref', None) or 'pixel')
            _ayr = str(getattr(ann, 'ayref', None) or 'pixel')
            if _axr != 'pixel' or _ayr != 'pixel':
                return 'other'  # 데이터 단위 오프셋(긴급 풍선 FINAL18) — px 오프셋 추정 로직 비적용
            xref_s = str(getattr(ann, 'xref', '') or '')
            yref_s = str(getattr(ann, 'yref', '') or '')
            if xref_s == 'paper' and yref_s == 'paper':
                xv = float(getattr(ann, 'x', 0.5) or 0.5)
                if xv >= 0.86 and any(k in txt for k in RAIL_KW):
                    return 'rail'
                return 'topbox'
            if xref_s == 'paper' and yref_s in ('y', 'y1'):
                return 'rail'  # 우측 레일 (add_price_labels 산출, 자체 패킹 관할)
            if xref_s in ('x', 'x1') and yref_s in ('y', 'y1'):
                if any(k in txt for k in RAIL_KW) and not bool(getattr(ann, 'showarrow', False)):
                    return 'rail'
                return 'signal'
            return 'other'

        items = []
        for idx, ann in enumerate(anns):
            try:
                if getattr(ann, 'visible', True) is False:
                    continue  # [FINAL23] 숨김 주석(route 비표시 처리)은 충돌 없는 유령 — 배치 대상 제외
            except Exception:
                pass
            k = _klass(ann)
            if k == 'other':
                continue
            est = _text_center_px(ann)
            if est is None:
                continue
            items.append({'i': idx, 'ann': ann, 'k': k,
                          'cx': est[0], 'cy': est[1], 'w': est[2], 'h': est[3]})
        if len(items) < 2:
            return fig

        MOVABLE = {'signal': 2, 'topbox': 1}  # card/rail = 고정 존

        def _move_signal(ann, dy_px, dx_px=0.0):
            try:
                if bool(getattr(ann, 'showarrow', False)):
                    ay = float(getattr(ann, 'ay', 0) or 0)
                    ax = float(getattr(ann, 'ax', 0) or 0)
                    ann.ay = float(np.clip(ay + dy_px, -320, 320))
                    if dx_px:
                        ann.ax = float(np.clip(ax + dx_px, -320, 320))
                else:
                    ys = float(getattr(ann, 'yshift', 0) or 0)
                    xs = float(getattr(ann, 'xshift', 0) or 0)
                    ann.yshift = float(np.clip(ys - dy_px, -320, 320))  # yshift+ = 위로
                    if dx_px:
                        ann.xshift = float(np.clip(xs + dx_px, -320, 320))
            except Exception:
                pass

        def _move_topbox(ann, dy_px):
            # paper 상단 박스는 아래로만 이동 (위로는 캔버스 밖)
            try:
                yv = float(getattr(ann, 'y', 0.5) or 0.5)
                ann.y = float(np.clip(yv - dy_px / H, 0.04, 1.10))
            except Exception:
                pass

        # [자동배치 v1.2] 캔버스 상·하단 클리핑 방지 — 신호 풍선 박스가 잘리면 최소량 안쪽으로
        for it in items:
            if it['k'] != 'signal':
                continue  # 카드/배너(여백 존 의도)·레일은 건드리지 않음
            top_edge = it['cy'] - it['h'] / 2.0
            bot_edge = it['cy'] + it['h'] / 2.0
            if top_edge < 2.0:
                dy = 2.0 - top_edge
                _move_signal(it['ann'], dy)
                it['cy'] += dy
            elif bot_edge > H - 2.0:
                dy = (H - 2.0) - bot_edge
                _move_signal(it['ann'], dy)
                it['cy'] += dy

        for _round in range(max_iter):
            moved_any = False
            for i in range(len(items)):
                for j in range(i + 1, len(items)):
                    a, b = items[i], items[j]
                    ra, rb = MOVABLE.get(a['k'], 0), MOVABLE.get(b['k'], 0)
                    if ra == 0 and rb == 0:
                        continue
                    ovx = (a['w'] + b['w']) / 2.0 + margin_px - abs(a['cx'] - b['cx'])
                    ovy = (a['h'] + b['h']) / 2.0 + margin_px - abs(a['cy'] - b['cy'])
                    if ovx <= 0 or ovy <= 0:
                        continue
                    # 이동 대상 = 가변 등수가 높은 쪽 (같으면 아래쪽 b 우선)
                    if ra > rb:
                        tgt, oth, _ = a, b, None
                    elif rb > ra:
                        tgt, oth, _ = b, a, None
                    else:
                        tgt = b if b['cy'] >= a['cy'] else a
                        oth = a if tgt is b else b
                    if oth['k'] == 'rail' and tgt['k'] == 'signal':
                        # 우측 레일과의 겹침 → 신호 풍선을 안쪽(왼)으로 수평 분리
                        dx = -(ovx + 4.0)
                        _move_signal(tgt['ann'], 0.0, dx)
                        tgt['cx'] += dx
                    elif tgt['k'] == 'signal':
                        dir_y = 1.0 if tgt['cy'] >= oth['cy'] else -1.0
                        _move_signal(tgt['ann'], dir_y * (ovy + 2.0))
                        tgt['cy'] += dir_y * (ovy + 2.0)
                    elif tgt['k'] == 'topbox':
                        _move_topbox(tgt['ann'], ovy + 2.0)
                        tgt['cy'] += ovy + 2.0
                    moved_any = True
            if not moved_any:
                break
        return fig
    except Exception:
        return fig


def render_draggable_plotly_chart(fig, use_container_width: bool = True, chart_key: Optional[str] = None, **kwargs):
    """모든 Plotly 차트를 이 함수로 출력하면 박스/풍선을 마우스로 이동하고 위치를 저장할 수 있습니다."""
    try:
        # [FIX] 모든 차트 출력 전에 풍선 도움말 가독성 전수 개선
        fig = _enhance_all_annotations_readability(fig)
        # [자동배치] 초기 충돌 해소 (수동 저장 위치는 클라이언트 복원이 우선 — 주석 순서/개수 불변)
        try:
            fig = _resolve_chart_annotation_collisions(fig)
        except Exception:
            pass
        # [자동배치] 제목/범례 박스 상단 마진 이격 + 내부 행 배너 전용 스트립 확보
        try:
            fig = _hoist_chart_top_headers(fig)
        except Exception:
            pass
        # 위치 저장/복원 또는 전체 고정이 켜져 있으면 HTML 컴포넌트 렌더러를 사용해야
        # 브라우저 localStorage의 박스 좌표와 차트 확대/축소 범위를 적용할 수 있습니다.
        if _chart_box_persist_enabled() or _chart_position_lock_enabled() or _chart_group_select_enabled():
            return render_persistent_draggable_plotly_chart(fig, chart_key=chart_key, use_container_width=use_container_width, **kwargs)
        if _chart_box_drag_enabled():
            fig = prepare_draggable_annotations(fig)
            cfg = dict(DRAGGABLE_CHART_CONFIG)
            cfg["scrollZoom"] = _chart_scroll_zoom_enabled()
            return st.plotly_chart(fig, use_container_width=use_container_width, config=cfg, **kwargs)
        cfg = dict(STATIC_CHART_CONFIG)
        cfg["scrollZoom"] = _chart_scroll_zoom_enabled()
        return st.plotly_chart(fig, use_container_width=use_container_width, config=cfg, **kwargs)
    except TypeError:
        try:
            fig = _enhance_all_annotations_readability(fig)
        except Exception:
            pass
        return st.plotly_chart(fig, use_container_width=use_container_width, **kwargs)


def show_plotly_chart(fig, **kwargs):
    """[P4] render_draggable_plotly_chart를 거치지 않는 직접 출력용 래퍼.

    v6~v15 대시보드 차트들이 st.plotly_chart로 직접 출력돼 [P3-1] 어노테이션
    앵커 정규화/폰트 교정(_enhance_all_annotations_readability)이 적용되지 않던 것을 통일.
    """
    try:
        fig = _enhance_all_annotations_readability(fig)
    except Exception:
        pass
    # [자동배치] 초기 충돌 해소
    try:
        fig = _resolve_chart_annotation_collisions(fig)
    except Exception:
        pass
    # [자동배치] 제목/범례 박스 상단 마진 이격 + 내부 행 배너 전용 스트립 확보
    try:
        fig = _hoist_chart_top_headers(fig)
    except Exception:
        pass
    return st.plotly_chart(fig, **kwargs)


