def safe_pkg_version(name: str) -> str:
    try:
        return pkg_version(name)
    except PackageNotFoundError:
        return 'not-installed'
    except Exception:
        return 'unknown'

def build_test_mode_report(raw_data: pd.DataFrame, df: pd.DataFrame, ind: Dict, scanner_df: pd.DataFrame) -> Dict:
    checks = []
    checks.append({'카테고리': '환경', '항목': 'Streamlit', '상태': '정상' if safe_pkg_version('streamlit') != 'not-installed' else '오류', '세부내용': safe_pkg_version('streamlit')})
    checks.append({'카테고리': '환경', '항목': 'Plotly', '상태': '정상' if safe_pkg_version('plotly') != 'not-installed' else '오류', '세부내용': safe_pkg_version('plotly')})
    checks.append({'카테고리': '환경', '항목': 'yfinance', '상태': '정상' if safe_pkg_version('yfinance') != 'not-installed' else '오류', '세부내용': safe_pkg_version('yfinance')})
    checks.append({'카테고리': '파일', '항목': 'watchlist.json', '상태': '정상' if WATCHLIST_FILE.exists() else '경고', '세부내용': str(WATCHLIST_FILE)})
    checks.append({'카테고리': '파일', '항목': 'user_settings.json', '상태': '정상' if SETTINGS_FILE.exists() else '경고', '세부내용': str(SETTINGS_FILE)})
    checks.append({'카테고리': '파일', '항목': 'charts export dir', '상태': '정상' if CHARTS_DIR.exists() else '오류', '세부내용': str(CHARTS_DIR)})
    checks.append({'카테고리': '파일', '항목': 'reports export dir', '상태': '정상' if REPORTS_DIR.exists() else '오류', '세부내용': str(REPORTS_DIR)})
    checks.append({'카테고리': '데이터', '항목': '원시 데이터', '상태': '정상' if raw_data is not None and not raw_data.empty else '오류', '세부내용': f"rows={len(raw_data) if raw_data is not None else 0}"})
    checks.append({'카테고리': '데이터', '항목': '분석 데이터', '상태': '정상' if df is not None and len(df) >= 40 else '경고', '세부내용': f"rows={len(df) if df is not None else 0}"})
    checks.append({'카테고리': '지표', '항목': 'RSI/ATR/MACD', '상태': '정상' if all(k in ind for k in ['rsi', 'atr', 'macd']) else '오류', '세부내용': '핵심 지표 생성 여부'})
    checks.append({'카테고리': '스캐너', '항목': 'scanner_results', '상태': '정상' if scanner_df is not None else '경고', '세부내용': f"rows={len(scanner_df) if scanner_df is not None and not scanner_df.empty else 0}"})
    summary = {'ok': sum(1 for c in checks if c['상태'] == '정상'), 'warn': sum(1 for c in checks if c['상태'] == '경고'), 'err': sum(1 for c in checks if c['상태'] == '오류')}
    return {'checks': pd.DataFrame(checks), 'summary': summary}

