def safe_float(x, default=np.nan) -> float:
    try:
        v = float(x)
        return v if np.isfinite(v) else default
    except Exception:
        return default

def fmt_price(x: float) -> str:
    if x is None or not np.isfinite(x):
        return "N/A"
    try:
        import streamlit as st
        is_kr = st.session_state.get("is_kr", True)
        convert_us_to_krw = st.session_state.get("convert_us_to_krw", True)
        rate = st.session_state.get("usd_krw_rate", 1.0)
    except Exception:
        is_kr = True
        convert_us_to_krw = True
        rate = 1.0

    if not is_kr:
        if convert_us_to_krw and rate > 1.0:
            # 해외주식 표기방법: 달러 (원화) - 예: 34.98달러 (52,015원)
            return f"{x:,.2f}달러 ({x * rate:,.0f}원)"
        else:
            return f"{x:,.2f}달러"
    else:
        return f"{x:,.0f}"

def fmt_price_kr_integrated(integrated, nxt, krx) -> str:
    """국내주식 표기방법: 통합가격 (NXT가격 / KRX가격) - 예: 통합 253,500 (NXT 253,500원 / KRX 255,000원)"""
    try:
        if integrated is None:
            return "N/A"
        # 통합 가격은 NXT 우선
        if nxt is not None and krx is not None:
            return f"통합 {integrated:,.0f}원 (NXT {nxt:,.0f}원 / KRX {krx:,.0f}원)"
        elif nxt is not None:
            return f"통합 {integrated:,.0f}원 (NXT {nxt:,.0f}원)"
        elif krx is not None:
            return f"통합 {integrated:,.0f}원 (KRX {krx:,.0f}원)"
        else:
            return f"{integrated:,.0f}원"
    except Exception:
        return f"{integrated:,.0f}원" if integrated else "N/A"


# [CLEANUP] fmt_pct 중복 정의 제거 — 이 사본(x: float, '+.2f%')는 모듈 로드 시 아래쪽 동명 정의(x, nd=1, signed=False)에 덮어써져 항상 미실행. 현재 동작 그대로 유지.
def is_korean_text(text: str) -> bool:
    return any("가" <= c <= "힣" for c in str(text))

def abbreviate_num(x) -> str:
    try:
        x = float(x)
    except Exception:
        return str(x)
    if not np.isfinite(x):
        return "N/A"
    ax = abs(x)
    sign = "-" if x < 0 else ""
    if ax >= 1e12: return f"{sign}{ax/1e12:.2f}T"
    if ax >= 1e9: return f"{sign}{ax/1e9:.2f}B"
    if ax >= 1e6: return f"{sign}{ax/1e6:.2f}M"
    if ax >= 1e3: return f"{sign}{ax/1e3:.1f}K"
    return f"{x:.2f}"

