@st.cache_data(show_spinner=False, ttl=3600)
def load_krx_stocks() -> pd.DataFrame:
    if not FDR_AVAILABLE:
        return pd.DataFrame()
    for market in ["KRX", "KOSPI", "KOSDAQ"]:
        try:
            df = fdr.StockListing(market)
            if df is not None and not df.empty:
                if "Market" not in df.columns:
                    df["Market"] = market
                df["Code"] = df["Code"].astype(str).str.zfill(6)
                return df
        except Exception:
            continue
    frames = []
    for market in ["KOSPI", "KOSDAQ"]:
        try:
            df = fdr.StockListing(market)
            if df is not None and not df.empty:
                df["Market"] = market
                df["Code"] = df["Code"].astype(str).str.zfill(6)
                frames.append(df)
        except Exception:
            continue
    return pd.concat(frames, ignore_index=True) if frames else pd.DataFrame()

def resolve_kr_candidates(code: str, market: str = "") -> List[str]:
    mk = str(market).upper()
    if "KOSDAQ" in mk:
        return [f"{code}.KQ", f"{code}.KS"]
    if "KOSPI" in mk:
        return [f"{code}.KS", f"{code}.KQ"]
    return [f"{code}.KS", f"{code}.KQ"]

def normalize_price_cols(df: pd.DataFrame) -> pd.DataFrame:
    out = df.copy()
    if isinstance(out.columns, pd.MultiIndex):
        out.columns = out.columns.get_level_values(0)
    out.columns = [str(c).strip() for c in out.columns]
    out = out.rename(columns={
        "Adj Close": "AdjClose", "adj close": "AdjClose",
        "open": "Open", "high": "High", "low": "Low", "close": "Close", "volume": "Volume",
    })
    for c in ["Open", "High", "Low", "Close", "Volume"]:
        if c not in out.columns:
            out[c] = 0.0 if c == "Volume" else np.nan
        out[c] = pd.to_numeric(out[c], errors="coerce")
    if "Close" not in out.columns and "AdjClose" in out.columns:
        out["Close"] = pd.to_numeric(out["AdjClose"], errors="coerce")
    if not isinstance(out.index, pd.DatetimeIndex):
        out.index = pd.to_datetime(out.index, errors="coerce")
    return out.dropna(subset=["Open", "High", "Low", "Close"]).sort_index()

def resample_data(df: pd.DataFrame, tf: str) -> pd.DataFrame:
    if df.empty or tf == "일봉":
        return df
    rule_map = {"주봉": "W-FRI", "월봉": "ME"}
    rule = rule_map.get(tf)
    if rule is None:
        return df
    try:
        return df.resample(rule).agg({"Open": "first", "High": "max", "Low": "min", "Close": "last", "Volume": "sum"}).dropna()
    except Exception:
        old = {"주봉": "W-FRI", "월봉": "M"}.get(tf, rule)
        return df.resample(old).agg({"Open": "first", "High": "max", "Low": "min", "Close": "last", "Volume": "sum"}).dropna()

def resolve_symbol_meta(query: str, market_type: str = "통합") -> Dict:
    query = str(query).strip()
    meta = {"query": query, "is_kr": False, "kr_code": "", "kr_market": "", "display_name": query, "download_symbol": query}
    query_upper = query.upper()
    
    # 1. 넥스트레이드(NXT)나 한국거래소(KRX) 강제가 아닌 경우에만 해외 매핑 선 검사
    if "KRX" not in market_type and "NXT" not in market_type:
        if query in GLOBAL_NAME_TO_TICKER:
            ticker = GLOBAL_NAME_TO_TICKER[query]
            meta.update({"is_kr": False, "display_name": f"{query} ({ticker})", "download_symbol": ticker})
            return meta
        elif query_upper in GLOBAL_NAME_TO_TICKER:
            ticker = GLOBAL_NAME_TO_TICKER[query_upper]
            meta.update({"is_kr": False, "display_name": f"{query} ({ticker})", "download_symbol": ticker})
            return meta

    if "US" in market_type:
        meta.update({"is_kr": False, "display_name": query_upper, "download_symbol": query_upper})
        return meta

    if query.isdigit() and len(query) == 6:
        meta.update({"is_kr": True, "kr_code": query.zfill(6), "kr_market": "KOSPI", "display_name": query.zfill(6)})
        return meta
    if query in KR_NAME_TO_CODE:
        meta.update({"is_kr": True, "kr_code": KR_NAME_TO_CODE[query], "kr_market": "KOSPI", "display_name": query})
        return meta
    krx = load_krx_stocks()
    if not krx.empty:
        try:
            if query.isdigit():
                m = krx[krx["Code"] == query.zfill(6)]
                if not m.empty:
                    r = m.iloc[0]
                    meta.update({"is_kr": True, "kr_code": str(r["Code"]), "kr_market": str(r.get("Market", "KOSPI")), "display_name": str(r.get("Name", query))})
                    return meta
            if is_korean_text(query):
                k2 = krx.copy()
                k2["NC"] = k2["Name"].astype(str).str.replace(" ", "", regex=False).str.upper()
                qn = query.replace(" ", "").upper()
                m = k2[k2["NC"] == qn]
                if m.empty:
                    m = k2[k2["Name"].astype(str).str.contains(query, case=False, na=False, regex=False)]
                if not m.empty:
                    r = m.iloc[0]
                    meta.update({"is_kr": True, "kr_code": str(r["Code"]), "kr_market": str(r.get("Market", "KOSPI")), "display_name": str(r.get("Name", query))})
                    return meta
        except Exception:
            pass

    if "KRX" in market_type or "NXT" in market_type:
        meta.update({"is_kr": True, "display_name": query})
        return meta

    if is_korean_text(query):
        meta.update({"is_kr": True, "display_name": query})
    else:
        meta.update({"is_kr": False, "display_name": query, "download_symbol": query})
    return meta

@st.cache_data(show_spinner=False, ttl=3600)
def fetch_usd_krw_rate() -> float:
    """실시간 USD/KRW 환율을 수집합니다."""
    try:
        import yfinance as yf
        ticker = yf.Ticker("USDKRW=X")
        df_rate = ticker.history(period="5d")
        if not df_rate.empty:
            return float(df_rate["Close"].iloc[-1])
    except Exception:
        pass
    return 1390.0 # 기본 fallback 환율 (2026 기준)

@st.cache_data(show_spinner=False, ttl=1800)
def yf_download_safe(symbol: str, start_dt, end_dt, interval: str = "1d") -> pd.DataFrame:
    for kwargs in [
        {"auto_adjust": True, "multi_level_index": False, "interval": interval},
        {"auto_adjust": True, "interval": interval},
        {"auto_adjust": False, "interval": interval},
    ]:
        try:
            raw = yf.download(symbol, start=start_dt, end=end_dt, progress=False, **kwargs)
            raw = normalize_price_cols(raw)
            if not raw.empty:
                return raw
        except Exception:
            continue
    return pd.DataFrame()

@st.cache_data(show_spinner=False, ttl=1800)

def get_realtime_price(query):
    """실시간 현재가 조회 - 개선: KRX/NXT 구분, 장중/장마감/휴일 처리, NXT를 통합 가격으로 사용"""
    meta = resolve_symbol_meta(query, market_type="통합")
    is_kr = meta.get("is_kr", False)
    cur, prev = None, None
    cur_krx, cur_nxt = None, None
    prev_krx, prev_nxt = None, None

    if is_kr and meta.get("kr_code"):
        code = meta["kr_code"]
        try:
            import requests
            from bs4 import BeautifulSoup
            url = f"https://finance.naver.com/item/main.naver?code={code}"
            res = requests.get(url, headers={'User-Agent': 'Mozilla/5.0'}, timeout=8)
            soup = BeautifulSoup(res.text, 'html.parser')

            # KRX와 NXT 각각의 rate_info div 파싱
            # KRX: id="rate_info_krx", NXT: id="rate_info_nxt"
            # 각각 내부의 .no_today .blind 에서 현재가 추출

            def _extract_price_from_rate_info(rate_info_id):
                try:
                    div = soup.find("div", {"id": rate_info_id})
                    if not div:
                        return None, None
                    # 현재가: .no_today .blind
                    today_p = div.select_one('.no_today')
                    cur_price = None
                    if today_p:
                        blind = today_p.select_one('.blind')
                        if blind and blind.text:
                            cur_price = int(blind.text.replace(',', '').strip())

                    # 전일대비로 이전 종가 계산 (가능하면)
                    exday_p = div.select_one('.no_exday')
                    prev_price = None
                    if exday_p and cur_price is not None:
                        blinds = exday_p.select('.blind')
                        if blinds and len(blinds) >= 1:
                            try:
                                change_val = int(blinds[0].text.replace(',', '').strip())
                                # 하락이면 음수
                                if exday_p.select_one('.ico_down') or exday_p.select_one('.ico_minus') or '하락' in exday_p.get_text():
                                    change_val = -change_val
                                # 전일 종가 = 현재가 - 전일대비
                                # 단, change_val이 전일대비 금액이 아닐 수도 있으므로, 전일가 직접 파싱 시도
                                # Naver의 no_info 테이블에서 전일가 찾기
                                prev_price = cur_price - change_val
                            except:
                                pass

                    # 추가로 전일 종가를 no_info 테이블에서 직접 찾기 (더 정확)
                    try:
                        # no_info 테이블에서 "전일" 찾기
                        # KRX/NXT 각각의 no_info가 있을 수 있음
                        info_table = div.find_next_sibling("table", {"class": "no_info"}) or soup.find("table", {"class": "no_info"})
                        # 더 정확히는 div 내부의 table
                        tables = div.find_all("table", {"class": "no_info"})
                        for tbl in tables:
                            # 전일 텍스트가 있는 td 찾기
                            if "전일" in tbl.get_text():
                                # 전일가 blind 찾기
                                # 구조: <span class="sptxt sp_txt2">전일</span> <em><span class="blind">279,500</span>
                                # 바로 뒤의 blind
                                # 전일 라벨 다음 em 내부 blind
                                # 간단히 테이블 내 모든 blind 중 전일 근처 찾기
                                # 여기서는 첫 번째 blind가 전일가일 가능성 높음? 아니면 두 번째?
                                # KRX 테이블: 전일가 279,500이 있음
                                # 전일가 직접 파싱을 위해 테이블 내 blind 중 전일가 위치 추정
                                blinds = tbl.select('.blind')
                                # 전일가는 보통 첫 번째 blind가 아닐 수 있음, 텍스트로 "전일" 근처 blind 찾기
                                # 간단히: 테이블 텍스트에 "전일"이 있고, 그 뒤에 blind가 있으면 그 blind가 전일가
                                # 여기서는 전일가가 279,500 등으로 표시됨, 현재가와 다름
                                # 현재 구현에서는 change로 계산한 prev가 있으면 그걸 사용, 없으면 None
                                pass
                    except:
                        pass

                    return cur_price, prev_price
                except Exception:
                    return None, None

            cur_krx, prev_krx = _extract_price_from_rate_info("rate_info_krx")
            cur_nxt, prev_nxt = _extract_price_from_rate_info("rate_info_nxt")

            # 통합 가격은 NXT 우선 (사용자 요구: NXT가 최종)
            # NXT가 있으면 NXT를 통합 가격으로, 없으면 KRX
            if cur_nxt is not None:
                cur = cur_nxt
                prev = prev_nxt
                # 세션에 KRX/NXT 각각 저장 (표기용)
                try:
                    import streamlit as st
                    st.session_state['last_nxt_price'] = float(cur_nxt) if cur_nxt else None
                    st.session_state['last_krx_price'] = float(cur_krx) if cur_krx else None
                    st.session_state['last_integrated_price'] = float(cur_nxt) if cur_nxt else float(cur_krx) if cur_krx else None
                except:
                    pass
            elif cur_krx is not None:
                cur = cur_krx
                prev = prev_krx
                try:
                    import streamlit as st
                    st.session_state['last_nxt_price'] = None
                    st.session_state['last_krx_price'] = float(cur_krx) if cur_krx else None
                    st.session_state['last_integrated_price'] = float(cur_krx) if cur_krx else None
                except:
                    pass
            else:
                # fallback: 기존 방식 (첫 번째 no_today)
                today_div = soup.select_one('.no_today')
                if today_div:
                    try:
                        cur = int(today_div.select_one('.blind').text.replace(',', ''))
                    except:
                        pass
                exday_div = soup.select_one('.no_exday')
                if exday_div and cur is not None:
                    try:
                        blinds = exday_div.select('.blind')
                        if blinds:
                            change_val = int(blinds[0].text.replace(',', ''))
                            if exday_div.select_one('.ico_down') or exday_div.select_one('.ico_minus'):
                                change_val = -change_val
                            prev = cur - change_val
                    except:
                        pass

            if cur is not None and prev is not None:
                return float(cur), float(prev), is_kr
            elif cur is not None:
                # prev가 없으면 cur로라도 반환 (change 계산은 나중에)
                return float(cur), float(cur), is_kr
        except Exception as e:
            # print(f"Naver KRX/NXT parsing error: {e}")
            pass

    # US 및 fallback: yfinance
    sym = meta.get("download_symbol", query)
    try:
        import yfinance as yf
        tkr = yf.Ticker(sym)
        c = tkr.fast_info.get("lastPrice")
        p = tkr.fast_info.get("previousClose")
        if c and p:
            # US도 세션에 저장 (통합 가격은 lastPrice)
            try:
                import streamlit as st
                st.session_state['last_nxt_price'] = None
                st.session_state['last_krx_price'] = None
                st.session_state['last_integrated_price'] = float(c)
            except:
                pass
            return float(c), float(p), is_kr
        hist = tkr.history(period="5d")
        if len(hist) >= 2:
            return float(hist['Close'].iloc[-1]), float(hist['Close'].iloc[-2]), is_kr
        elif len(hist) == 1:
            return float(hist['Close'].iloc[-1]), float(hist['Close'].iloc[-1]), is_kr
    except Exception:
        pass
    return cur, prev, is_kr


@st.cache_data(show_spinner=False, ttl=300)  # [P1] 네트워크 캐시 — 결과 dict/df는 picklable, TTL 내 재호출 시 재계산 생략
def get_krx_nxt_prices(query):
    """KRX와 NXT 가격을 모두 반환 (국내 주식 전용)"""
    meta = resolve_symbol_meta(query, market_type="통합")
    is_kr = meta.get("is_kr", False)
    if not is_kr or not meta.get("kr_code"):
        return {"is_kr": False}
    code = meta["kr_code"]
    result = {"is_kr": True, "krx": None, "nxt": None, "integrated": None, "krx_prev": None, "nxt_prev": None}
    try:
        import requests
        from bs4 import BeautifulSoup
        url = f"https://finance.naver.com/item/main.naver?code={code}"
        res = requests.get(url, headers={'User-Agent': 'Mozilla/5.0'}, timeout=8)
        soup = BeautifulSoup(res.text, 'html.parser')

        def _extract(id_):
            try:
                div = soup.find("div", {"id": id_})
                if not div:
                    return None, None
                today = div.select_one('.no_today')
                cur = None
                if today:
                    b = today.select_one('.blind')
                    if b:
                        cur = int(b.text.replace(',', '').strip())
                exday = div.select_one('.no_exday')
                prev = None
                if exday and cur is not None:
                    blinds = exday.select('.blind')
                    if blinds:
                        try:
                            ch = int(blinds[0].text.replace(',', '').strip())
                            if exday.select_one('.ico_down') or exday.select_one('.ico_minus'):
                                ch = -ch
                            prev = cur - ch
                        except:
                            pass
                return cur, prev
            except:
                return None, None

        krx_cur, krx_prev = _extract("rate_info_krx")
        nxt_cur, nxt_prev = _extract("rate_info_nxt")

        result["krx"] = float(krx_cur) if krx_cur is not None else None
        result["krx_prev"] = float(krx_prev) if krx_prev is not None else None
        result["nxt"] = float(nxt_cur) if nxt_cur is not None else None
        result["nxt_prev"] = float(nxt_prev) if nxt_prev is not None else None
        # 통합은 NXT 우선
        result["integrated"] = result["nxt"] if result["nxt"] is not None else result["krx"]
        result["integrated_prev"] = result["nxt_prev"] if result["nxt_prev"] is not None else result["krx_prev"]

    except Exception as e:
        pass
    return result


@st.cache_data(show_spinner=False, ttl=600)  # [P1] 래퍼 캐시 — 결과 dict/df는 picklable, TTL 내 재호출 시 재계산 생략
def download_price_data(query: str, start_dt, end_dt, market_type: str = "통합", timeframe: str = "일봉") -> Tuple[pd.DataFrame, Dict]:
    meta = resolve_symbol_meta(query, market_type=market_type)
    end_dl = pd.Timestamp(end_dt) + pd.Timedelta(days=1)
    
    # ── [고도화] 타임프레임별 다운로드 인터벌 계산 (yfinance 연동) ──
    interval = "1d"
    is_intraday = "분봉" in timeframe
    if is_intraday:
        if timeframe in ["1분봉", "3분봉"]:
            interval = "1m"
        else: # 5분봉, 10분봉
            interval = "5m"

    # 분봉(인트라데이) 분석일 경우, 데이터 품질을 위해 FDR을 우회하고 yfinance로 단일 통일합니다.
    if not is_intraday:
        if meta["is_kr"] and meta["kr_code"] and FDR_AVAILABLE:
            try:
                raw = fdr.DataReader(meta["kr_code"], start=start_dt, end=end_dt)
                raw = normalize_price_cols(raw)
                if not raw.empty:
                    return raw, meta
            except Exception:
                pass
    if meta["is_kr"] and meta["kr_code"]:
        for sym in resolve_kr_candidates(meta["kr_code"], meta["kr_market"]):
            raw = yf_download_safe(sym, start_dt, end_dl, interval=interval)
            if not raw.empty:
                meta["download_symbol"] = sym
                return raw, meta
    if not meta["is_kr"]:
        symbol = meta.get("download_symbol", query)
        raw = yf_download_safe(symbol, start_dt, end_dl, interval=interval)
        if not raw.empty:
            return raw, meta
    if FDR_AVAILABLE:
        try:
            raw = fdr.DataReader(query, start=start_dt, end=end_dt)
            raw = normalize_price_cols(raw)
            if not raw.empty:
                return raw, meta
        except Exception:
            pass
    return pd.DataFrame(), meta

@st.cache_data(show_spinner=False, ttl=300)
def download_intraday_data(symbol: str, interval: str = "15m", period: str = "5d") -> pd.DataFrame:
    try:
        import yfinance as yf
        df = yf.download(symbol, period=period, interval=interval)
        if df is not None and not df.empty:
            df = normalize_price_cols(df)
            return df
    except Exception as e:
        pass
    return pd.DataFrame()

@st.cache_data(show_spinner=False, ttl=1800)
def get_investor_data_naver(code: str, sd_str: str, ed_str: str) -> pd.DataFrame:
    try:
        import requests
    except Exception:
        requests = None
    all_rows: List[pd.DataFrame] = []
    sd_dt = pd.Timestamp(sd_str)
    ed_dt = pd.Timestamp(ed_str)
    for page in range(1, 35):
        url = f"https://finance.naver.com/item/frgn.naver?code={code}&page={page}"
        try:
            if requests is not None:
                r = requests.get(url, headers={"User-Agent": "Mozilla/5.0"}, timeout=8)
                html_text = r.text
            else:
                import urllib.request
                req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0"})
                with urllib.request.urlopen(req, timeout=8) as resp:
                    html_text = resp.read().decode("euc-kr", errors="ignore")
            tables = pd.read_html(StringIO(html_text))
        except Exception:
            break
        stop_early = False
        for t in tables:
            try:
                if isinstance(t.columns, pd.MultiIndex):
                    t.columns = [b if a == b else f"{a}_{b}" for a, b in t.columns]
                cols = [str(c) for c in t.columns]
                if not (any("날짜" in c for c in cols) and any("외국인" in c for c in cols)):
                    continue
                date_col = next(c for c in t.columns if "날짜" in str(c))
                t = t.dropna(how="all").dropna(subset=[date_col]).copy()
                t["_date"] = pd.to_datetime(t[date_col].astype(str).str.replace(".", "-", regex=False), errors="coerce")
                t = t.dropna(subset=["_date"])
                if t.empty:
                    continue
                all_rows.append(t)
                if pd.notna(t["_date"].min()) and t["_date"].min() < sd_dt:
                    stop_early = True
                break
            except Exception:
                continue
        if stop_early:
            break
    if not all_rows:
        return pd.DataFrame()
    df = pd.concat(all_rows, ignore_index=True).set_index("_date").sort_index()
    df = df.loc[sd_dt:ed_dt]
    if df.empty:
        return pd.DataFrame()
    result = pd.DataFrame(index=df.index)
    for col in df.columns:
        cs = str(col)
        if "기관" in cs and "순매매" in cs:
            result["institution_net"] = pd.to_numeric(df[col], errors="coerce").fillna(0)
        elif "외국인" in cs and "순매매" in cs:
            result["foreign_net"] = pd.to_numeric(df[col], errors="coerce").fillna(0)
    if "foreign_net" not in result.columns:
        result["foreign_net"] = 0.0
    if "institution_net" not in result.columns:
        result["institution_net"] = 0.0
    result["individual_net"] = -(result["foreign_net"] + result["institution_net"])
    return result

# ══════════════════════════════════════════════════════════════════════
# INDICATORS / FACTORS / RISK
# ══════════════════════════════════════════════════════════════════════

def calc_atr(df: pd.DataFrame, period: int = 14) -> pd.Series:
    h, l, c = df["High"].astype(float), df["Low"].astype(float), df["Close"].astype(float)
    tr = pd.concat([(h - l).abs(), (h - c.shift()).abs(), (l - c.shift()).abs()], axis=1).max(axis=1)
    return tr.rolling(period, min_periods=1).mean()

def calc_rsi(close: pd.Series, period: int = 14) -> pd.Series:
    diff = close.diff()
    gain = diff.clip(lower=0).rolling(period, min_periods=1).mean()
    loss = (-diff.clip(upper=0)).rolling(period, min_periods=1).mean()
    rs = gain / (loss + 1e-9)
    return 100 - (100 / (1 + rs))

def calc_macd(close: pd.Series, fast: int = 12, slow: int = 26, signal: int = 9):
    ef = close.ewm(span=fast, adjust=False, min_periods=1).mean()
    es = close.ewm(span=slow, adjust=False, min_periods=1).mean()
    macd = ef - es
    sig = macd.ewm(span=signal, adjust=False, min_periods=1).mean()
    hist = macd - sig
    return macd, sig, hist

def calc_bbands(close: pd.Series, period: int = 20, nstd: float = 2.0):
    mid = close.rolling(period, min_periods=1).mean()
    std = close.rolling(period, min_periods=1).std().fillna(0)
    upper = mid + nstd * std
    lower = mid - nstd * std
    width = (upper - lower) / (mid + 1e-9)
    pct_b = (close - lower) / (upper - lower + 1e-9)
    return mid, upper, lower, width, pct_b

def calc_vwap(df: pd.DataFrame) -> pd.Series:
    tp = (df["High"] + df["Low"] + df["Close"]) / 3
    vol = df["Volume"].astype(float).fillna(0)
    if float(vol.sum()) <= 0:
        return df["Close"].copy()
    return (tp * vol).cumsum() / (vol.cumsum() + 1e-9)

def calc_obv(df: pd.DataFrame) -> pd.Series:
    c = df["Close"].astype(float)
    v = df["Volume"].astype(float).fillna(0)
    return (np.sign(c.diff()).fillna(0) * v).cumsum()

def calc_adx(df: pd.DataFrame, period: int = 14):
    h = df["High"].astype(float)
    l = df["Low"].astype(float)
    c = df["Close"].astype(float)
    up = h.diff()
    dn = -l.diff()
    plus_dm = np.where((up > dn) & (up > 0), up, 0.0)
    minus_dm = np.where((dn > up) & (dn > 0), dn, 0.0)
    tr = pd.concat([(h - l).abs(), (h - c.shift()).abs(), (l - c.shift()).abs()], axis=1).max(axis=1)
    atr = tr.rolling(period, min_periods=1).mean()
    pdi = 100 * pd.Series(plus_dm, index=df.index).rolling(period, min_periods=1).mean() / (atr + 1e-9)
    mdi = 100 * pd.Series(minus_dm, index=df.index).rolling(period, min_periods=1).mean() / (atr + 1e-9)
    dx = 100 * (pdi - mdi).abs() / (pdi + mdi + 1e-9)
    adx = dx.rolling(period, min_periods=1).mean()
    return adx, pdi, mdi

@st.cache_data(show_spinner=False, ttl=1800)  # [P1] 순수연산 캐시 — 결과 dict/df는 picklable, TTL 내 재호출 시 재계산 생략
def compute_indicators(df: pd.DataFrame) -> Dict:
    close = df["Close"].astype(float)
    vol = df["Volume"].astype(float).fillna(0)
    ma20 = close.rolling(20, min_periods=1).mean()
    ma60 = close.rolling(60, min_periods=1).mean()
    ma120 = close.rolling(120, min_periods=1).mean()
    ema9 = close.ewm(span=9, adjust=False, min_periods=1).mean()
    atr = calc_atr_wilder(df, 14)
    rsi = calc_rsi_wilder(close, 14)
    macd, signal, hist = calc_macd(close)
    bb_mid, bb_upper, bb_lower, bb_width, pct_b = calc_bbands(close)
    vwap = calc_vwap(df)
    obv = calc_obv(df)
    adx, plus_di, minus_di = calc_adx_wilder(df, 14)
    vol20 = vol.rolling(20, min_periods=1).mean()
    zeros = pd.Series(0.0, index=df.index)
    return {
        "close": close, "vol": vol, "ma20": ma20, "ma60": ma60, "ma120": ma120, "ema9": ema9,
        "atr": atr, "rsi": rsi, "macd": macd, "signal": signal, "hist": hist,
        "bb_mid": bb_mid, "bb_upper": bb_upper, "bb_lower": bb_lower, "bb_width": bb_width, "pct_b": pct_b,
        "vwap": vwap, "obv": obv, "vol20": vol20, "vol_ratio": vol / (vol20 + 1e-9),
        "adx": adx, "plus_di": plus_di, "minus_di": minus_di,
        "foreign_net": zeros.copy(), "institution_net": zeros.copy(), "individual_net": zeros.copy(),
    }

def market_regime(ind: Dict) -> Dict:
    close = ind["close"]
    ema20 = close.ewm(span=20, adjust=False, min_periods=1).mean()
    ema60 = close.ewm(span=60, adjust=False, min_periods=1).mean()
    n = min(max(len(close) - 1, 2), 7)
    slope = (float(ema20.iloc[-1]) - float(ema20.iloc[-n])) / (abs(float(ema20.iloc[-n])) + 1e-9)
    trend_score = int(sum([
        float(ema20.iloc[-1]) > float(ema60.iloc[-1]),
        float(close.iloc[-1]) > float(ema20.iloc[-1]),
        float(ind["adx"].iloc[-1]) > 22,
        abs(slope) > 0.012,
        float(ind["vol_ratio"].iloc[-1]) > 1.0,
    ]))
    bbw_med = float(ind["bb_width"].rolling(60, min_periods=1).median().iloc[-1])
    atr_pct = float(ind["atr"].iloc[-1]) / (float(close.iloc[-1]) + 1e-9)
    vol_high = atr_pct > 0.028 or float(ind["bb_width"].iloc[-1]) > bbw_med * 1.25
    squeeze = float(ind["bb_width"].iloc[-1]) < bbw_med * 0.75 and float(ind["adx"].iloc[-1]) < 18
    if trend_score >= 4 and not vol_high:
        regime = "추세장"
    elif trend_score >= 3 and vol_high:
        regime = "고변동 추세"
    elif squeeze:
        regime = "박스권(스퀴즈)"
    elif float(ind["adx"].iloc[-1]) < 20:
        regime = "박스권"
    else:
        regime = "전환 국면"
    return {"regime": regime, "trend_score": trend_score, "adx": float(ind["adx"].iloc[-1]), "atr_pct": atr_pct * 100, "ema20": float(ema20.iloc[-1]), "ema60": float(ema60.iloc[-1]), "squeeze": squeeze}

@st.cache_data(show_spinner=False, ttl=3600)
def load_fundamentals(symbol: str) -> Dict:
    out = {"roe": np.nan, "pe": np.nan, "pb": np.nan, "ps": np.nan, "quality_score": 50.0, "value_score": 50.0}
    try:
        tkr = yf.Ticker(symbol)
        info = tkr.info or {}
        roe = info.get("returnOnEquity")
        pe = info.get("trailingPE")
        pb = info.get("priceToBook")
        ps = info.get("priceToSalesTrailing12Months")
        out["roe"] = float(roe) * 100 if roe is not None else np.nan
        out["pe"] = float(pe) if pe is not None else np.nan
        out["pb"] = float(pb) if pb is not None else np.nan
        out["ps"] = float(ps) if ps is not None else np.nan
        q = 50
        if np.isfinite(out["roe"]):
            q += 12 if out["roe"] >= 12 else (-10 if out["roe"] < 5 else 0)
        v = 50
        if np.isfinite(out["pe"]):
            v += 12 if out["pe"] < 15 else (-12 if out["pe"] > 40 else 0)
        if np.isfinite(out["pb"]):
            v += 10 if out["pb"] < 2 else (-10 if out["pb"] > 8 else 0)
        if np.isfinite(out["ps"]):
            v += 8 if out["ps"] < 3 else (-8 if out["ps"] > 10 else 0)
        out["quality_score"] = float(np.clip(q, 0, 100))
        out["value_score"] = float(np.clip(v, 0, 100))
    except Exception:
        pass
    return out

def factor_scores(ind: Dict, fund: Optional[Dict] = None) -> Dict:
    close = ind["close"]
    r5 = float(close.pct_change(5).fillna(0).iloc[-1])
    r20 = float(close.pct_change(20).fillna(0).iloc[-1])
    r60 = float(close.pct_change(60).fillna(0).iloc[-1])
    rsi = float(ind["rsi"].iloc[-1])
    momentum = 0.0
    momentum += 20 if r20 > 0 else 0
    momentum += 15 if r60 > 0 else 0
    momentum += 15 if float(ind["macd"].iloc[-1]) > float(ind["signal"].iloc[-1]) else 0
    momentum += 15 if rsi > 50 else 0
    momentum += 10 if r5 > 0 else 0
    momentum += 10 if float(close.iloc[-1]) > float(ind["ma20"].iloc[-1]) else 0
    momentum += 15 if float(ind["adx"].iloc[-1]) > 20 else 0
    volume = 0.0
    volume += 35 if float(ind["vol_ratio"].iloc[-1]) > 1.2 else (20 if float(ind["vol_ratio"].iloc[-1]) > 1.0 else 0)
    volume += 30 if float(close.iloc[-1]) > float(ind["vwap"].iloc[-1]) else 0
    obv_ma = float(ind["obv"].rolling(20, min_periods=1).mean().iloc[-1])
    volume += 35 if float(ind["obv"].iloc[-1]) > obv_ma else 0
    timing = 0.0
    timing += 20 if float(close.iloc[-1]) > float(ind["ma20"].iloc[-1]) else 0
    timing += 15 if float(ind["ma20"].iloc[-1]) > float(ind["ma60"].iloc[-1]) else 0
    timing += 15 if float(ind["pct_b"].iloc[-1]) > 0.5 else 0
    timing += 10 if 40 <= rsi <= 70 else 0
    timing += 15 if float(ind["adx"].iloc[-1]) > 20 else 0
    timing += 10 if float(close.iloc[-1]) > float(ind["ma120"].iloc[-1]) else 0
    quality = 55.0 if fund is None else float(fund.get("quality_score", 55.0))
    value = 50.0 if fund is None else float(fund.get("value_score", 50.0))
    total = round(momentum * 0.30 + volume * 0.18 + timing * 0.22 + quality * 0.17 + value * 0.13, 1)
    return {
        "momentum": round(momentum, 1), "volume": round(volume, 1), "timing": round(min(timing, 100), 1),
        "quality": round(min(quality, 100), 1), "value": round(min(value, 100), 1), "total": total,
        "rsi": rsi, "macd": float(ind["macd"].iloc[-1]), "signal": float(ind["signal"].iloc[-1]),
        "vol_spike": float(ind["vol_ratio"].iloc[-1]), "pct_b": float(ind["pct_b"].iloc[-1]),
    }


def compute_fundamental_risk_adjustment(fund: Optional[Dict]) -> Dict:
    """펀더멘털 과열/취약 리스크를 최종 투자점수에 반영합니다.

    기존 최종 등급은 기술적 구조 비중이 높아, 고PER·저ROE·고PBR 종목도
    차트가 좋으면 과도하게 긍정적으로 나올 수 있었습니다. 이 보정값은
    투자등급 산출 시 밸류에이션/수익성 리스크를 안전장치로 반영합니다.
    """
    if not isinstance(fund, dict):
        return {"adj": 0.0, "reasons": []}
    adj = 0.0
    reasons: List[str] = []
    pe = safe_float(fund.get("pe"), np.nan)
    pb = safe_float(fund.get("pb"), np.nan)
    ps = safe_float(fund.get("ps"), np.nan)
    roe = safe_float(fund.get("roe"), np.nan)
    value_score = safe_float(fund.get("value_score"), np.nan)
    quality_score = safe_float(fund.get("quality_score"), np.nan)

    if np.isfinite(pe):
        if pe <= 0:
            adj -= 5; reasons.append("PER 음수/적자 가능성")
        elif pe >= 70:
            adj -= 8; reasons.append(f"PER {pe:.1f}배 고평가 부담")
        elif pe >= 45:
            adj -= 5; reasons.append(f"PER {pe:.1f}배 과열권")
        elif 0 < pe <= 12:
            adj += 4; reasons.append(f"PER {pe:.1f}배 저평가 매력")
    if np.isfinite(pb):
        if pb >= 12:
            adj -= 6; reasons.append(f"PBR {pb:.1f}배 자산가치 부담")
        elif pb >= 7:
            adj -= 3; reasons.append(f"PBR {pb:.1f}배 다소 높음")
        elif 0 < pb <= 1.2:
            adj += 3; reasons.append(f"PBR {pb:.1f}배 자산가치 매력")
    if np.isfinite(ps):
        if ps >= 15:
            adj -= 4; reasons.append(f"PSR {ps:.1f}배 매출 대비 고평가")
        elif 0 < ps <= 1.5:
            adj += 2; reasons.append(f"PSR {ps:.1f}배 매출 대비 저평가")
    if np.isfinite(roe):
        if roe < 0:
            adj -= 7; reasons.append(f"ROE {roe:.1f}% 적자/자본효율 취약")
        elif roe < 5:
            adj -= 3; reasons.append(f"ROE {roe:.1f}% 낮은 수익성")
        elif roe >= 18:
            adj += 5; reasons.append(f"ROE {roe:.1f}% 우수한 자본효율")
    if np.isfinite(value_score) and value_score < 35:
        adj -= 3; reasons.append("밸류에이션 점수 낮음")
    if np.isfinite(quality_score) and quality_score >= 70:
        adj += 2; reasons.append("재무 품질 점수 양호")
    return {"adj": float(np.clip(adj, -15, 10)), "reasons": reasons[:5]}


def assess_analysis_reliability(raw_data: pd.DataFrame, df: pd.DataFrame, ind: Dict, meta: Dict, fundamentals: Optional[Dict], flow_has_data: bool) -> Dict:
    """데이터/분석 신뢰도를 점수화합니다.

    데이터 부족·최신성 부족·거래량 0·수급/재무 누락 등은 투자 판단의 신뢰도를 떨어뜨리므로
    별도 신뢰도 카드와 리포트에 반영합니다.
    """
    score = 100.0
    warnings_out: List[str] = []
    rows = len(df) if isinstance(df, pd.DataFrame) else 0
    if rows < 80:
        score -= 18; warnings_out.append(f"봉 수 부족({rows}개): 장기 추세 신뢰도 낮음")
    elif rows < 140:
        score -= 8; warnings_out.append(f"봉 수가 다소 적음({rows}개)")
    try:
        last_dt = pd.Timestamp(df.index[-1]).tz_localize(None)
        today = pd.Timestamp(datetime.today().date())
        stale_days = max((today - last_dt.normalize()).days, 0)
        if stale_days >= 14:
            score -= 20; warnings_out.append(f"데이터 기준일이 {stale_days}일 전")
        elif stale_days >= 5:
            score -= 8; warnings_out.append(f"최근 거래 데이터 지연 가능성({stale_days}일)")
    except Exception:
        score -= 8; warnings_out.append("데이터 기준일 확인 불가")
    try:
        vol_mean = float(df["Volume"].tail(20).fillna(0).mean())
        if vol_mean <= 0:
            score -= 15; warnings_out.append("최근 거래량 데이터가 0 또는 누락")
    except Exception:
        score -= 5; warnings_out.append("거래량 품질 확인 불가")
    try:
        core_nan = 0
        for k in ["rsi", "atr", "macd", "signal", "ma20", "ma60"]:
            v = ind.get(k)
            if v is None or not np.isfinite(float(v.iloc[-1])):
                core_nan += 1
        if core_nan:
            score -= core_nan * 6; warnings_out.append(f"핵심 기술지표 {core_nan}개 누락/NaN")
    except Exception:
        score -= 10; warnings_out.append("기술지표 품질 확인 실패")
    if meta.get("is_kr") and not flow_has_data:
        score -= 8; warnings_out.append("국내 수급 데이터 미확인")
    if not isinstance(fundamentals, dict) or not any(np.isfinite(safe_float(fundamentals.get(k), np.nan)) for k in ["pe", "pb", "roe"]):
        score -= 10; warnings_out.append("재무/밸류에이션 데이터 부족")
    score = float(np.clip(score, 0, 100))
    if score >= 85:
        grade, status = "높음", "good"
    elif score >= 70:
        grade, status = "보통 이상", "info"
    elif score >= 55:
        grade, status = "주의", "warn"
    else:
        grade, status = "낮음", "bad"
    return {"score": score, "grade": grade, "status": status, "warnings": warnings_out[:6]}

# ══════════════════════════════════════════════════════════════════════
# ADVANCED WAVE DETECTION FOR KRX
# ══════════════════════════════════════════════════════════════════════

def detect_local_extrema(values: np.ndarray, order: int = 5, mode: str = "max") -> List[int]:
    out: List[int] = []
    if len(values) < order * 2 + 1:
        return out
    for i in range(order, len(values) - order):
        window = values[i - order:i + order + 1]
        center = values[i]
        if mode == "max":
            if center == np.max(window) and int(np.argmax(window)) == order:
                out.append(i)
        else:
            if center == np.min(window) and int(np.argmin(window)) == order:
                out.append(i)
    return out

def build_pivot_candidates(df: pd.DataFrame, orders: Tuple[int, ...] = (3, 5, 8, 13)) -> List[Dict]:
    sub = df.copy()
    highs = sub["High"].values.astype(float)
    lows = sub["Low"].values.astype(float)
    vol = sub["Volume"].astype(float).fillna(0)
    vol_ratio = vol / (vol.rolling(20, min_periods=1).mean() + 1e-9)
    pool: Dict[Tuple[int, str], Dict] = {}
    n = len(sub)
    for order in orders:
        hi_idx = detect_local_extrema(highs, order=order, mode="max")
        lo_idx = detect_local_extrema(lows, order=order, mode="min")
        for i in hi_idx:
            left = max(0, i - order * 2)
            right = min(n - 1, i + order * 2)
            prom = (highs[i] - np.min(lows[left:right + 1])) / (highs[i] + 1e-9)
            score = order * 1.2 + prom * 100 + safe_float(vol_ratio.iloc[i], 1.0) * 3
            key = (i, "H")
            if key not in pool or score > pool[key]["score"]:
                pool[key] = {"idx": i, "type": "H", "price": float(highs[i]), "score": float(score)}
        for i in lo_idx:
            left = max(0, i - order * 2)
            right = min(n - 1, i + order * 2)
            prom = (np.max(highs[left:right + 1]) - lows[i]) / (lows[i] + 1e-9)
            score = order * 1.2 + prom * 100 + safe_float(vol_ratio.iloc[i], 1.0) * 3
            key = (i, "L")
            if key not in pool or score > pool[key]["score"]:
                pool[key] = {"idx": i, "type": "L", "price": float(lows[i]), "score": float(score)}
    return sorted(pool.values(), key=lambda x: x["idx"])

def filter_pivots_for_krx(df: pd.DataFrame, candidates: List[Dict], is_kr: bool = False) -> List[Dict]:
    if not candidates:
        return []
    close = df["Close"].astype(float)
    atr = calc_atr_wilder(df, 14)
    atr_pct_med = float((atr / (close + 1e-9)).tail(min(60, len(df))).median())
    min_move = max(0.035 if is_kr else 0.045, atr_pct_med * (2.4 if is_kr else 2.0))
    min_bars = 4 if is_kr else 5
    filtered: List[Dict] = [candidates[0]]
    for cand in candidates[1:]:
        prev = filtered[-1]
        if cand["type"] == prev["type"]:
            better = cand["price"] > prev["price"] if cand["type"] == "H" else cand["price"] < prev["price"]
            if better or cand["score"] > prev["score"]:
                filtered[-1] = cand
            continue
        move = abs(cand["price"] / (prev["price"] + 1e-9) - 1)
        gap = cand["idx"] - prev["idx"]
        if move >= min_move and gap >= min_bars:
            filtered.append(cand)
        else:
            if cand["score"] > prev["score"] and move >= min_move * 0.7:
                filtered[-1] = cand
    return filtered

def choose_swing_from_pivots(df: pd.DataFrame, pivots: List[Dict], mode: str = "dominant") -> Optional[Dict]:
    if len(pivots) < 2:
        return None
    last_idx = len(df) - 1
    best = None
    best_score = -1e18
    for i in range(len(pivots) - 1):
        a, b = pivots[i], pivots[i + 1]
        if a["type"] == b["type"]:
            continue
        low_price = min(a["price"], b["price"])
        high_price = max(a["price"], b["price"])
        move_pct = high_price / (low_price + 1e-9) - 1
        bars = max(1, b["idx"] - a["idx"])
        recency = 1.0 / (1.0 + max(0, last_idx - b["idx"]) / 40)
        score = move_pct * 180 + min(bars, 80) * 0.18 + a["score"] * 0.12 + b["score"] * 0.12
        if mode == "recent":
            score += recency * 35 + b["score"] * 0.12
        else:
            score += recency * 12 + move_pct * 55
        if score > best_score:
            direction = "up" if a["type"] == "L" and b["type"] == "H" else "down"
            best_score = score
            best = {
                "name": mode, "direction": direction,
                "start_date": df.index[a["idx"]], "end_date": df.index[b["idx"]],
                "low_date": df.index[a["idx"]] if a["type"] == "L" else df.index[b["idx"]],
                "high_date": df.index[a["idx"]] if a["type"] == "H" else df.index[b["idx"]],
                "low_price": float(low_price), "high_price": float(high_price),
                "range": float(high_price - low_price),
                "a_idx": int(a["idx"]), "b_idx": int(b["idx"]), "score": float(score),
            }
    return best

def find_krx_swing(df: pd.DataFrame, lookback: int = 260, mode: str = "dominant", is_kr: bool = False) -> Optional[Dict]:
    sub = df.tail(min(len(df), lookback)).copy()
    if len(sub) < 25:
        return None
    pivots = build_pivot_candidates(sub, orders=(3, 5, 8, 13))
    pivots = filter_pivots_for_krx(sub, pivots, is_kr=is_kr)
    chosen = choose_swing_from_pivots(sub, pivots, mode=mode)
    if chosen is not None and chosen["range"] > 0:
        chosen["pivots"] = pivots
        return chosen
    hi_date, lo_date = sub["High"].idxmax(), sub["Low"].idxmin()
    direction = "down" if hi_date < lo_date else "up"
    return {
        "name": mode, "direction": direction,
        "start_date": hi_date if direction == "down" else lo_date,
        "end_date": lo_date if direction == "down" else hi_date,
        "low_date": lo_date, "high_date": hi_date,
        "low_price": float(sub.loc[lo_date, "Low"]), "high_price": float(sub.loc[hi_date, "High"]),
        "range": float(sub.loc[hi_date, "High"] - sub.loc[lo_date, "Low"]),
        "pivots": pivots, "score": 0.0,
    }

def build_fib_package(swing: Optional[Dict]) -> Optional[Dict]:
    if swing is None:
        return None
    low = float(swing["low_price"])
    high = float(swing["high_price"])
    span = float(high - low)
    if not np.isfinite(span) or span <= 0:
        return None
    ratios = [0.0, 0.236, 0.382, 0.5, 0.618, 0.786, 1.0]
    levels = {r: low + span * r for r in ratios}
    ext_up = {1.272: high + span * 0.272, 1.618: high + span * 0.618, 2.0: high + span}
    ext_dn = {1.272: low - span * 0.272, 1.618: low - span * 0.618, 2.0: low - span}
    return {"swing": swing, "low": low, "high": high, "range": span, "levels": levels, "ext_up": ext_up, "ext_dn": ext_dn}

def cluster_count(mask: pd.Series, min_gap: int = 4) -> int:
    idx = np.flatnonzero(mask.values)
    if len(idx) == 0:
        return 0
    c = 1
    last = idx[0]
    for cur in idx[1:]:
        if cur - last > min_gap:
            c += 1
        last = cur
    return c

def compress_touch_indices(indices: np.ndarray, min_gap: int = 5) -> List[int]:
    if len(indices) == 0:
        return []
    keep = [int(indices[0])]
    last = int(indices[0])
    for i in indices[1:]:
        ii = int(i)
        if ii - last > min_gap:
            keep.append(ii)
            last = ii
    return keep

def detect_level_touches(df: pd.DataFrame, level: float, tol: float, min_gap: int = 5) -> List[int]:
    mask = ((df["Low"] <= level + tol) & (df["High"] >= level - tol)) | (abs(df["Close"] - level) <= tol)
    idx = np.flatnonzero(mask.values)
    return compress_touch_indices(idx, min_gap=min_gap)

def locate_price_zone(levels: Dict[float, float], price: float) -> Dict:
    items = sorted(levels.items(), key=lambda x: x[1])
    if price <= items[0][1]:
        return {"state": "below_range", "lower": items[0], "upper": items[1]}
    if price >= items[-1][1]:
        return {"state": "above_range", "lower": items[-2], "upper": items[-1]}
    for i in range(1, len(items)):
        a, b = items[i - 1], items[i]
        if a[1] <= price <= b[1]:
            return {"state": "inside", "lower": a, "upper": b}
    return {"state": "inside", "lower": items[0], "upper": items[-1]}

def merge_confluence_rows(rows: List[Dict], tol: float) -> List[Dict]:
    if not rows:
        return []
    rows = sorted(rows, key=lambda x: x["price"])
    merged = [rows[0].copy()]
    for row in rows[1:]:
        prev = merged[-1]
        if abs(row["price"] - prev["price"]) <= tol:
            prev["price"] = (prev["price"] + row["price"]) / 2
            prev["labels"] = prev["labels"] + [t for t in row["labels"] if t not in prev["labels"]]
        else:
            merged.append(row.copy())
    return merged

def build_level_table(df: pd.DataFrame, ind: Dict, main_fib: Dict, recent_fib: Optional[Dict], current_price: float) -> Tuple[pd.DataFrame, List[Dict], Dict[float, List[int]]]:
    levels = main_fib["levels"]
    later_anchor = max(main_fib["swing"]["low_date"], main_fib["swing"]["high_date"])
    react_df = df.loc[df.index >= later_anchor].copy()
    if react_df.empty:
        react_df = df.copy()
    atr = float(ind["atr"].iloc[-1])
    tol = max(atr * 0.40, current_price * 0.005)
    ma20 = float(ind["ma20"].iloc[-1])
    ma60 = float(ind["ma60"].iloc[-1])
    ma120 = float(ind["ma120"].iloc[-1])
    vwap = float(ind["vwap"].iloc[-1])
    recent_levels = recent_fib["levels"] if recent_fib else {}
    rows: List[Dict] = []
    raw_confluence: List[Dict] = []
    touch_map: Dict[float, List[int]] = {}
    for ratio, level in levels.items():
        touch_idx = detect_level_touches(react_df, level, tol, min_gap=4)
        touch_map[ratio] = [react_df.index[i] for i in touch_idx]
        touches = len(touch_idx)
        gap_pct = (current_price / level - 1) * 100
        role = "지지 후보" if level <= current_price else "저항 후보"
        dist_pct = abs(current_price - level) / (current_price + 1e-9) * 100
        confluence_tags = []
        if abs(level - ma20) / current_price <= 0.012:
            confluence_tags.append("MA20")
        if abs(level - ma60) / current_price <= 0.015:
            confluence_tags.append("MA60")
        if abs(level - ma120) / current_price <= 0.020:
            confluence_tags.append("MA120")
        if abs(level - vwap) / current_price <= 0.012:
            confluence_tags.append("VWAP")
        if recent_levels:
            near_recent = [f"최근 {r:.3f}" for r, lv in recent_levels.items() if abs(level - lv) / current_price <= 0.008]
            confluence_tags.extend(near_recent)
        if confluence_tags:
            raw_confluence.append({"price": float(level), "labels": [f"메인 {ratio:.3f}"] + confluence_tags})
        importance = "핵심" if ratio in [0.382, 0.5, 0.618] else ("중요" if ratio in [0.236, 0.786] else "기준")
        if touches >= 4:
            comment = "반복 지지/저항이 매우 자주 발생한 핵심 반응대"
        elif dist_pct <= 1.5:
            comment = "현재가와 매우 가까워 실전 분기선 역할"
        elif confluence_tags:
            comment = "복수 지표가 겹친 컨플루언스 구간"
        else:
            comment = "구조 기준선으로 참고할 가격대"
        strength = round(touches * 22 + len(confluence_tags) * 18 + max(0, 12 - dist_pct * 3), 1)
        rows.append({"비율": f"{ratio:.3f}", "가격": float(level), "현재가 괴리(%)": round(gap_pct, 2), "역할": role, "반응 횟수": int(touches), "컨플루언스": ", ".join(confluence_tags) if confluence_tags else "-", "중요도": importance, "강도 점수": strength, "해석": comment})
    confluence = merge_confluence_rows(raw_confluence, tol=max(tol, current_price * 0.004))
    table = pd.DataFrame(rows).sort_values("가격", ascending=False).reset_index(drop=True)
    return table, confluence, touch_map

def analyze_trend_context(ind: Dict, current_price: float) -> Dict:
    ma20, ma60, ma120 = [float(ind[k].iloc[-1]) for k in ["ma20", "ma60", "ma120"]]
    rsi = float(ind["rsi"].iloc[-1])
    macd = float(ind["macd"].iloc[-1])
    signal = float(ind["signal"].iloc[-1])
    vol_ratio = float(ind["vol_ratio"].iloc[-1])
    bb_upper = float(ind["bb_upper"].iloc[-1])
    bb_lower = float(ind["bb_lower"].iloc[-1])
    if current_price > ma20 > ma60 > ma120:
        structure = "상승 정배열"
    elif current_price < ma20 < ma60 < ma120:
        structure = "하락 역배열"
    else:
        structure = "혼조 / 전환 구간"
    if rsi >= 70:
        rsi_state = "과열권"
    elif rsi <= 30:
        rsi_state = "과매도권"
    else:
        rsi_state = "중립권"
    if macd > signal:
        macd_state = "MACD 상방 우위"
    else:
        macd_state = "MACD 하방 우위"
    if current_price >= bb_upper:
        bb_state = "볼린저 상단 근접 / 과열 경계"
    elif current_price <= bb_lower:
        bb_state = "볼린저 하단 근접 / 반등 경계"
    else:
        bb_state = "볼린저 중립 범위"
    return {"structure": structure, "rsi": rsi, "rsi_state": rsi_state, "macd_state": macd_state, "vol_ratio": vol_ratio, "bb_state": bb_state, "ma20": ma20, "ma60": ma60, "ma120": ma120}

def fib_position_score(current_ratio: float) -> float:
    if current_ratio >= 1.0: return 85
    if current_ratio >= 0.786: return 78
    if current_ratio >= 0.618: return 70
    if current_ratio >= 0.5: return 60
    if current_ratio >= 0.382: return 52
    if current_ratio >= 0.236: return 45
    return 35

def build_trade_plan(ind: Dict, main_fib: Dict, level_table: pd.DataFrame, hold_qty: int = 0, avg_price: float = 0.0) -> Dict:
    """
    Phase 5 개선: 시나리오별 구체적 대응 행동을 수치로 명시
    - 비중 축소 %, 추가 매수 조건, 손절 실행 조건을 수치화
    """
    price = float(ind["close"].iloc[-1])
    atr = float(ind["atr"].iloc[-1])
    zone = locate_price_zone(main_fib["levels"], price)
    supports = level_table[level_table["가격"] <= price].sort_values("가격", ascending=False)
    resists = level_table[level_table["가격"] > price].sort_values("가격", ascending=True)
    s1 = float(supports.iloc[0]["가격"]) if not supports.empty else main_fib["low"]
    s2 = float(supports.iloc[1]["가격"]) if len(supports) >= 2 else main_fib["low"]
    r1 = float(resists.iloc[0]["가격"]) if not resists.empty else main_fib["high"]
    r2 = float(resists.iloc[1]["가격"]) if len(resists) >= 2 else main_fib["ext_up"][1.272]
    dip_entry = s1 * 1.002
    breakout_entry = r1 * 1.003
    stop = min(s1 - atr * 0.55, price - atr * 1.2)
    if stop >= price:
        stop = price - atr * 1.2
    target1 = r1
    target2 = r2
    target3 = float(main_fib["ext_up"][1.272]) if price <= main_fib["high"] else float(main_fib["ext_up"][1.618])
    if target1 <= price:
        target1 = max(price + atr * 1.5, r1)
    if target2 <= target1:
        target2 = max(target1 + atr * 1.5, r2)
    if target3 <= target2:
        target3 = max(target2 + atr * 1.8, float(main_fib["ext_up"][1.272]))
    per_share_risk = max(price - stop, 1e-9)
    rr1 = (target1 - price) / per_share_risk
    rr2 = (target2 - price) / per_share_risk
    rr3 = (target3 - price) / per_share_risk
    current_ratio = (price - main_fib["low"]) / (main_fib["range"] + 1e-9)
    macd_up = float(ind["macd"].iloc[-1]) > float(ind["signal"].iloc[-1])
    vol_good = float(ind["vol_ratio"].iloc[-1]) > 1.1
    rsi = float(ind["rsi"].iloc[-1])
    ma20 = float(ind["ma20"].iloc[-1])
    ma60 = float(ind["ma60"].iloc[-1])

    # 기본 등급/액션 (기존 유지)
    if zone["state"] == "inside" and zone["lower"][0] >= 0.618 and macd_up:
        signal_grade = "A"
        action = "강한 추세 보유 / 눌림 매수 우세"
        tactical = "0.618 이상에서 버티고 있어 추세 재개형 구조. 추격보다 0.618~0.786 되돌림 확인 후 분할 접근이 유리합니다."
        reduce_pct = 0
        add_buy_pct = 20
        add_buy_cond = f"{fmt_price(s1*0.995)}~{fmt_price(s1*1.01)} 구간에서 양봉 전환 + 거래량 20일 평균 대비 110% 이상 시 20% 분할 매수"
        stop_exec_cond = f"종가 기준 {fmt_price(stop)} 하회 시 전량 손절, {fmt_price(s1*0.98)} 하회 시 50% 비중 축소"
    elif price > r1 and macd_up and vol_good:
        signal_grade = "A"
        action = "실전 돌파 매수 구간"
        tactical = "핵심 저항 상단 종가 안착 + 거래량 동반 시 추세 추종형 진입이 유효합니다."
        reduce_pct = 0
        add_buy_pct = 30
        add_buy_cond = f"{fmt_price(breakout_entry)} 상단 종가 안착 + 거래량 1.2배 이상 시 30% 추격 매수, 이후 {fmt_price(r1*0.99)} 눌림 시 15% 추가"
        stop_exec_cond = f"돌파 실패 후 {fmt_price(r1*0.98)} 하회 시 30% 축소, {fmt_price(stop)} 이탈 시 전량 손절"
    elif zone["state"] == "inside" and 0.382 <= current_ratio < 0.618:
        signal_grade = "B"
        action = "중립 박스 / 확인 후 진입"
        tactical = "중간 비율대라 방향 확정 전까지는 추격 금지. 0.618 돌파 확인 또는 0.382 재지지 확인이 먼저입니다."
        reduce_pct = 10
        add_buy_pct = 10
        add_buy_cond = f"박스 하단 {fmt_price(s1*1.002)} 지지 확인 + RSI 40→50 돌파 시 10% 탐색 매수"
        stop_exec_cond = f"{fmt_price(s1*0.97)} 하회 시 30% 축소, {fmt_price(stop)} 하회 시 70% 축소"
    elif price <= s1 * 1.01 and rsi <= 38:
        signal_grade = "B"
        action = "기술적 반등 감시 구간"
        tactical = "핵심 지지권 근처입니다. 양봉 전환·거래량 회복이 붙을 때만 단기 반등형 접근이 가능합니다."
        reduce_pct = 20
        add_buy_pct = 15
        add_buy_cond = f"{fmt_price(s1*0.995)}~{fmt_price(s1*1.015)}에서 장대양봉(몸통 55% 이상) + 거래량 1.5배 시 15% 반등 매수, 손절 {fmt_price(s1*0.97)}"
        stop_exec_cond = f"{fmt_price(s1*0.97)} 종가 이탈 시 50% 손절, {fmt_price(stop)} 이탈 시 전량 손절"
    elif price < s1 and float(ind["macd"].iloc[-1]) < float(ind["signal"].iloc[-1]):
        signal_grade = "D"
        action = "지지 이탈 / 방어 우선"
        tactical = "지지선 이탈 후 모멘텀까지 약합니다. 신규 매수보다 현금 비중과 손절 라인 관리가 우선입니다."
        reduce_pct = 50
        add_buy_pct = 0
        add_buy_cond = f"신규 매수 금지. 재진입 조건: {fmt_price(s1*1.02)} 상단 종가 회복 + 거래량 1.1배 이상 + MACD 상방 전환 시에만 10% 탐색"
        stop_exec_cond = f"현재가 {fmt_price(price)}가 {fmt_price(s1)} 하회 중. {fmt_price(stop)} 하회 시 전량 손절, 반등 시 {fmt_price(r1*0.95)}~{fmt_price(r1)}에서 50% 추가 축소"
    else:
        signal_grade = "C"
        action = "관망 또는 소액 탐색"
        tactical = "구조가 애매하므로 리스크를 작게 유지하고 확인 신호를 기다리는 것이 유리합니다."
        reduce_pct = 20
        add_buy_pct = 5
        add_buy_cond = f"관망 중 소액 탐색: {fmt_price(s1*1.002)} 지지 확인 + RSI 45 돌파 시 5% 이내"
        stop_exec_cond = f"{fmt_price(stop)} 하회 시 전량 손절, {fmt_price(s1*0.98)} 하회 시 30% 축소"

    holder_comment = ""
    if hold_qty > 0 and avg_price > 0:
        pnl_pct = (price / avg_price - 1) * 100
        if pnl_pct >= 12 and price >= r1 * 0.99:
            holder_comment = f"보유자는 핵심 저항권 {fmt_price(r1)} 접근 시 20~30% 분할 익절 후 나머지 물량은 추세 보유 전략이 효율적입니다. 2차 목표 {fmt_price(target2)}에서 30% 추가 익절, 최종 3차 {fmt_price(target3)}에서 50% 익절 후 추세 종료 시까지 홀딩."
        elif pnl_pct < 0 and price <= s1 * 1.01:
            holder_comment = f"손실 보유자는 무작정 물타기보다 지지 확인 후 대응이 바람직합니다. {fmt_price(s1*0.97)} 재이탈 시 손절 우선, {fmt_price(s1*1.01)} 지지 확인 시에만 10% 물타기 허용."
        else:
            holder_comment = f"보유자는 손절 기준을 {fmt_price(stop)} (또는 0.382={fmt_price(main_fib['levels'][0.382])}) 하단으로 명확히 두고 관리하는 것이 좋습니다. 손절가 하회 시 기계적 손절 실행."

    # Phase 5: 구체적 대응 행동 수치화
    position_actions = {
        "reduce_pct_on_resistance": 30 if signal_grade in ["A","B"] else 50,
        "reduce_pct_on_support_break": 50 if signal_grade in ["C","B"] else 70,
        "reduce_pct_current": reduce_pct,
        "add_buy_pct": add_buy_pct,
        "add_buy_condition": add_buy_cond,
        "stop_execution_condition": stop_exec_cond,
        "trailing_stop": float(price - atr*1.5),
        "partial_profit_1": {"price": float(target1), "pct": 30, "condition": f"{fmt_price(target1)} 도달 시 30% 분할 익절"},
        "partial_profit_2": {"price": float(target2), "pct": 30, "condition": f"{fmt_price(target2)} 도달 시 30% 추가 익절"},
        "partial_profit_3": {"price": float(target3), "pct": 40, "condition": f"{fmt_price(target3)} 도달 시 40% 최종 익절 후 추세 추종"},
    }

    return {
        "signal_grade": signal_grade,
        "action": action,
        "tactical": tactical,
        "holder_comment": holder_comment,
        "dip_entry": float(dip_entry),
        "breakout_entry": float(breakout_entry),
        "stop": float(stop),
        "target1": float(target1),
        "target2": float(target2),
        "target3": float(target3),
        "rr1": float(rr1),
        "rr2": float(rr2),
        "rr3": float(rr3),
        "support1": float(s1),
        "support2": float(s2),
        "resist1": float(r1),
        "resist2": float(r2),
        # Phase 5 신규
        "position_actions": position_actions,
        "reduce_pct": reduce_pct,
        "add_buy_pct": add_buy_pct,
        "add_buy_condition": add_buy_cond,
        "stop_execution_condition": stop_exec_cond,
    }



def build_scenarios(ind: Dict, main_fib: Dict, trade_plan: Dict, factors: Dict, regime: Dict) -> Dict:
    """
    Phase 5 개선: 시나리오별 구체적 대응 행동 수치 명시
    """
    price = float(ind["close"].iloc[-1])
    atr = float(ind["atr"].iloc[-1])
    bull = 36; base = 34; bear = 30
    if price > float(ind["ma20"].iloc[-1]): bull += 8
    else: bear += 8
    if float(ind["macd"].iloc[-1]) > float(ind["signal"].iloc[-1]): bull += 7
    else: bear += 7
    if regime["trend_score"] >= 4: bull += 10
    if factors["rsi"] >= 70: bear += 4
    elif factors["rsi"] <= 35: bull += 4
    if factors["vol_spike"] > 1.3: bull += 5
    if price < trade_plan["support1"]: bear += 10; bull -= 5
    total = max(bull + base + bear, 1)

    bull_prob = bull / total * 100
    base_prob = base / total * 100
    bear_prob = bear / total * 100

    bull_low = price
    bull_high = max(trade_plan["target2"], price + atr * 2.2)
    base_low = trade_plan["support1"]
    base_high = trade_plan["resist1"]
    bear_low = min(main_fib["ext_dn"][1.272], price - atr * 2.2)
    bear_high = price

    # Phase 5: 시나리오별 구체적 대응 행동 수치화
    # 상승 지속 시나리오
    bull_action = {
        "scenario": "상승 지속",
        "prob": bull_prob,
        "price_range": f"{fmt_price(bull_low)} ~ {fmt_price(bull_high)}",
        "position": f"기존 비중 유지 + {20 if bull_prob>50 else 10}% 추가 매수 가능",
        "add_buy_condition": f"{fmt_price(trade_plan['breakout_entry'])} 상단 종가 안착 + 거래량 20일 평균 대비 120% 이상 + RSI 50 이상 유지 시 20% 분할 매수, 이후 {fmt_price(trade_plan['resist1']*0.99)} 눌림 시 10% 추가",
        "reduce_condition": f"저항 {fmt_price(trade_plan['resist1'])} 돌파 실패 후 {fmt_price(trade_plan['resist1']*0.98)} 하회 시 20% 비중 축소",
        "stop_condition": f"절대 방어선 {fmt_price(trade_plan['stop'])} 종가 하회 시 전량 손절, {fmt_price(trade_plan['support1']*0.97)} 하회 시 50% 축소",
        "target_action": f"1차 목표 {fmt_price(trade_plan['target1'])}에서 30% 익절, 2차 {fmt_price(trade_plan['target2'])}에서 30% 익절, 3차 {fmt_price(trade_plan['target3'])}에서 40% 익절 후 트레일링 스탑 {fmt_price(price - atr*1.5)}로 전환",
        "reduce_pct": 0,
        "add_pct": 20,
    }

    # 횡보/조정 시나리오
    base_action = {
        "scenario": "횡보/조정",
        "prob": base_prob,
        "price_range": f"{fmt_price(base_low)} ~ {fmt_price(base_high)}",
        "position": "중립 비중 유지, 신규 진입 보류 또는 10% 이내 소액 탐색",
        "add_buy_condition": f"지지 {fmt_price(trade_plan['support1']*1.002)} 부근에서 양봉 전환 + 거래량 회복 시 10% 탐색 매수, 손절 {fmt_price(trade_plan['support1']*0.97)}",
        "reduce_condition": f"{fmt_price(trade_plan['support1']*0.97)} 하회 시 30% 축소, {fmt_price(trade_plan['resist1'])} 상단 실패 시 20% 축소",
        "stop_condition": f"{fmt_price(trade_plan['stop'])} 하회 시 70% 축소, {fmt_price(trade_plan['support2']*0.98)} 하회 시 전량 손절",
        "target_action": f"박스권 상단 {fmt_price(trade_plan['resist1'])}에서 30% 분할 익절, 하단 {fmt_price(trade_plan['support1'])}에서 10% 재매수",
        "reduce_pct": 20,
        "add_pct": 10,
    }

    # 추세 붕괴 시나리오
    bear_action = {
        "scenario": "추세 붕괴",
        "prob": bear_prob,
        "price_range": f"{fmt_price(bear_low)} ~ {fmt_price(bear_high)}",
        "position": "방어 우선, 비중 50~100% 축소",
        "add_buy_condition": "신규 매수 금지. 재진입 조건: " + f"{fmt_price(trade_plan['support1']*1.03)} 상단 종가 회복 + 거래량 1.2배 + MACD 상방 전환 시에만 10% 탐색",
        "reduce_condition": f"현재가 {fmt_price(price)}가 지지 {fmt_price(trade_plan['support1'])} 하회 중. 즉시 50% 축소, 반등 시 {fmt_price(trade_plan['resist1']*0.95)}~{fmt_price(trade_plan['resist1'])}에서 30% 추가 축소",
        "stop_condition": f"{fmt_price(trade_plan['stop'])} 하회 시 전량 손절. 손절 미이행 시 {fmt_price(bear_low)}까지 추가 하락 리스크 {((bear_low/price)-1)*100:.1f}%",
        "target_action": f"하락 시 목표 없음. 반등 목표는 {fmt_price(trade_plan['resist1'])}에서 전량 정리",
        "reduce_pct": 70,
        "add_pct": 0,
    }

    return {
        "bull_prob": bull_prob,
        "base_prob": base_prob,
        "bear_prob": bear_prob,
        "bull_low": bull_low,
        "bull_high": bull_high,
        "base_low": base_low,
        "base_high": base_high,
        "bear_low": bear_low,
        "bear_high": bear_high,
        # Phase 5 신규: 시나리오별 구체적 대응
        "bull_action": bull_action,
        "base_action": base_action,
        "bear_action": bear_action,
        "actions": [bull_action, base_action, bear_action],
    }


def build_alerts(ind: Dict, regime: Dict, trade_plan: Dict, main_fib: Dict, level_table: pd.DataFrame) -> List[Tuple[str, str, str]]:
    alerts: List[Tuple[str, str, str]] = []
    price = float(ind["close"].iloc[-1])
    rsi = float(ind["rsi"].iloc[-1])
    vol_spike = float(ind["vol_ratio"].iloc[-1])
    macd_up = float(ind["macd"].iloc[-1]) > float(ind["signal"].iloc[-1])
    current_ratio = (price - main_fib["low"]) / (main_fib["range"] + 1e-9)
    recent_vol = float(ind["vol"].tail(20).mean()) if "vol" in ind else 0.0
    if recent_vol <= 0:
        alerts.append(("warn", "🪫", "최근 거래량이 0에 가깝습니다. VWAP·거래량 기반 신호와 등급의 신뢰도가 낮으니 가격 구조 위주로 판단하세요."))
    if vol_spike >= 2.0:
        alerts.append(("hot", "🔴", "거래량 폭발: 최근 20봉 평균 대비 2배 이상 증가. 추세 가속 혹은 분배 가능성 동시 경계."))
    elif vol_spike >= 1.4:
        alerts.append(("warn", "🟡", "거래량 증가: 가격대 돌파·이탈 신호의 신뢰도가 높아질 수 있는 구간."))
    if rsi >= 74:
        alerts.append(("warn", "⚠️", f"RSI 과열 구간({rsi:.1f}). 상단 비율권에서는 추격매수보다 분할익절·눌림대기 우선."))
    elif rsi <= 30:
        alerts.append(("ok", "💎", f"RSI 과매도({rsi:.1f}). 핵심 피보나치 지지권과 겹치면 기술적 반등 후보."))
    if abs(price - trade_plan["support1"]) / price <= 0.01:
        alerts.append(("info", "📌", f"현재가가 핵심 지지 {fmt_price(trade_plan['support1'])} 근처. 종가 지지 여부가 중요합니다."))
    if abs(price - trade_plan["resist1"]) / price <= 0.01:
        alerts.append(("warn", "🚧", f"현재가가 핵심 저항 {fmt_price(trade_plan['resist1'])} 근처. 거래량 동반 돌파 여부 확인 필요."))
    if current_ratio >= 0.618 and macd_up:
        alerts.append(("ok", "✅", "0.618 이상 + MACD 상방: 추세 재개형 피보나치 구조가 유지되고 있습니다."))
    if current_ratio < 0.382 and not macd_up:
        alerts.append(("hot", "🔻", "0.382 하회 + MACD 약세: 되돌림보다 구조적 재하락 가능성에 유의해야 합니다."))
    if regime["regime"] == "박스권(스퀴즈)":
        alerts.append(("info", "🌪", "변동성 스퀴즈: 방향성 한 번 정해지면 빠른 추세 전개 가능성이 있습니다."))
    if not alerts:
        alerts.append(("ok", "✅", "현재 특별한 위험 경보는 약한 편입니다."))
    return alerts

def build_fib_commentary(df: pd.DataFrame, ind: Dict, main_fib: Dict, recent_fib: Optional[Dict], level_table: pd.DataFrame, confluence: List[Dict], trade_plan: Dict, unit: str) -> List[Dict]:
    price = float(ind["close"].iloc[-1])
    current_ratio = (price - main_fib["low"]) / (main_fib["range"] + 1e-9)
    current_ratio = float(np.clip(current_ratio, -2, 3))
    zone = locate_price_zone(main_fib["levels"], price)
    trend_ctx = analyze_trend_context(ind, price)
    low_date = pd.Timestamp(main_fib["swing"]["low_date"]).strftime("%Y-%m-%d")
    high_date = pd.Timestamp(main_fib["swing"]["high_date"]).strftime("%Y-%m-%d")
    swing_dir = main_fib["swing"]["direction"]
    swing_range_pct = (main_fib["high"] / (main_fib["low"] + 1e-9) - 1) * 100
    if current_ratio >= 0.786: ratio_zone_txt = "상단 고비율 회복 구간(0.786 이상)"
    elif current_ratio >= 0.618: ratio_zone_txt = "강한 회복 / 추세 재개 분기 구간(0.618~0.786)"
    elif current_ratio >= 0.382: ratio_zone_txt = "중립 균형 구간(0.382~0.618)"
    elif current_ratio >= 0.236: ratio_zone_txt = "초기 반등 / 약한 회복 구간(0.236~0.382)"
    else: ratio_zone_txt = "저점 재시험 경계 구간(0.236 미만)"
    conf_text = ""
    if confluence:
        near = sorted(confluence, key=lambda x: abs(x["price"] - price))[:3]
        conf_text = " / ".join([f"{fmt_price(c['price'])}{unit} ({', '.join(c['labels'])})" for c in near])
    else:
        conf_text = "뚜렷한 다중 컨플루언스는 약한 편입니다."
    if zone["state"] == "inside":
        zone_text = f"현재가는 메인 피보나치 <strong>{zone['lower'][0]:.3f}</strong> ({fmt_price(zone['lower'][1])}{unit})와 <strong>{zone['upper'][0]:.3f}</strong> ({fmt_price(zone['upper'][1])}{unit}) 사이에서 힘겨루기 중입니다."
    elif zone["state"] == "above_range":
        zone_text = "현재가는 메인 스윙 1.000 상단을 넘어선 상태입니다. 이후 목표가는 피보나치 확장 1.272·1.618 체계로 보는 것이 더 적합합니다."
    else:
        zone_text = "현재가는 메인 스윙 0.000 하단부에 근접해 있습니다. 여기서 지지 실패가 나오면 구조적 재하락으로 해석해야 합니다."
    return [
        {"title": "1) 메인 스윙 구조 해석", "body": f"이번 피보나치의 메인 기준 파동은 <strong>{low_date}</strong> 저점 <strong>{fmt_price(main_fib['low'])}{unit}</strong> ~ <strong>{high_date}</strong> 고점 <strong>{fmt_price(main_fib['high'])}{unit}</strong> 범위입니다. 전체 파동폭은 <strong>{fmt_price(main_fib['range'])}{unit}</strong>, 변동률은 약 <strong>{swing_range_pct:.2f}%</strong>입니다. 현재 위치는 <strong>{ratio_zone_txt}</strong>으로 읽는 것이 타당합니다."},
        {"title": "2) 현재 가격 구간의 의미", "body": zone_text},
        {"title": "3) 핵심 지지·저항 사다리", "body": f"현재 실전 기준에서 가장 중요한 상단 저항은 <strong>{fmt_price(trade_plan['resist1'])}{unit}</strong>, 하단 1차 지지 후보는 <strong>{fmt_price(trade_plan['support1'])}{unit}</strong>입니다."},
        {"title": "4) 컨플루언스(중첩 신호) 분석", "body": f"가장 주목할 중첩대는 <strong>{conf_text}</strong> 입니다."},
        {"title": "5) 보조지표 동조 여부", "body": f"현재 추세 구조는 <strong>{trend_ctx['structure']}</strong>입니다. RSI는 <strong>{trend_ctx['rsi']:.1f}</strong>로 <strong>{trend_ctx['rsi_state']}</strong>, MACD는 <strong>{trend_ctx['macd_state']}</strong>입니다."},
        {"title": "6) 실전 매매 시나리오", "body": f"<strong>눌림 매수</strong>: <strong>{fmt_price(trade_plan['support1'])}{unit}</strong> 부근 재지지 확인 후 진입. <strong>돌파 매수</strong>: <strong>{fmt_price(trade_plan['breakout_entry'])}{unit}</strong> 상단 종가 안착 + 거래량 동반. <strong>목표가</strong>: 1차 <strong>{fmt_price(trade_plan['target1'])}{unit}</strong>, 2차 <strong>{fmt_price(trade_plan['target2'])}{unit}</strong>, 3차 <strong>{fmt_price(trade_plan['target3'])}{unit}</strong>"},
        {"title": "7) 매수/매도 시그널 업그레이드 해설", "body": f"현재 시그널은 <strong>{esc(trade_plan['action'])}</strong>이며, 실전 문구로 풀면 <strong>{esc(trade_plan['tactical'])}</strong> 입니다."},
        {"title": "8) 차트 하단 기술적 해설", "body": "피보나치 0.236은 매우 얕은 되돌림, 0.382는 첫 확인선, 0.500은 심리적 균형점, 0.618은 핵심 황금비, 0.786은 구조 반전 직전의 마지막 확인선입니다."},
    ]

def select_fibonacci_template(main_fib: Dict) -> Dict:
    direction = str(main_fib["swing"].get("direction", "up"))
    if direction == "up":
        return {"name": "상승형 템플릿", "summary": "저점에서 고점까지 상승한 뒤 되돌림 구간을 분석하는 구조입니다.", "start_label": "1) 최초로 상승이 시작된 자리", "turn_label": "2) 되돌림이 시작되는 자리"}
    return {"name": "하락형 템플릿", "summary": "고점에서 저점까지 하락한 뒤 반등 되돌림 구간을 분석하는 구조입니다.", "start_label": "1) 최초로 하락이 시작된 자리", "turn_label": "2) 되돌림이 시작되는 자리"}

