            fig.add_annotation(x=dt, y=float(low.loc[dt]), xref="x", yref="y", text=lbl, showarrow=True, ax=40, ay=55, arrowhead=2, font=dict(color=P["dn"], size=10), bgcolor="rgba(5,9,17,0.95)", bordercolor=P["dn"], borderwidth=1.2, row=1, col=1)
