def build_cci_commentary(res: Dict) -> List[str]:
    if not res.get("available"):
        return ["CCI+DMI+BI 전략 계산 데이터가 부족합니다."]
    latest = res.get("latest", {})
    return [
        f"현재 CCI 전략 판정은 **{res.get('decision')}**, 점수는 **{res.get('score',0):.0f}/100**입니다.",
        f"CCI {latest.get('CCI', np.nan):.1f}, -DI {latest.get('-DI', np.nan):.1f}, BI {latest.get('BI', np.nan):.1f}, 거래량배율 {latest.get('거래량배율', np.nan):.2f}입니다.",
        "강한 매수 조건은 CCI +100 돌파, -DI 10선 아래 우하향, BI 우상향, 거래량 증가가 동시에 나오는 경우입니다.",
        "-DI가 30선 위로 올라가거나 CCI가 0선 아래로 밀리면 단기 매매는 관망 또는 방어가 유리합니다.",
    ]


def build_elite_chart_commentary(elite_model: Dict, elite_breakdown_rows: List[Dict]) -> List[str]:
    strong = [r for r in elite_breakdown_rows if str(r.get('현재판정','')).startswith('🟢')]
    weak = [r for r in elite_breakdown_rows if str(r.get('현재판정','')).startswith('🔴')]
    lines = [f"엘리트 모델 현재 판정은 **{elite_model.get('grade')}**, 점수는 **{elite_model.get('score',0):.0f}점**입니다. 액션은 **{elite_model.get('action')}**입니다."]
    if strong:
        lines.append("매수 우위 기법: " + ", ".join([str(x.get('기법')) for x in strong[:5]]))
    if weak:
        lines.append("방어 우위 기법: " + ", ".join([str(x.get('기법')) for x in weak[:5]]))
    if not strong and not weak:
        lines.append("대부분 기법이 중립권입니다. 추격보다 명확한 돌파/지지 확인 후 대응하세요.")
    return lines

