def render_monte_carlo_projection(df: pd.DataFrame, P: Dict, FONT_MONO: str) -> Optional[go.Figure]:
    """
    몬테카를로 시뮬레이션 기반 향후 30 영업일 주가 예측 채널
    - 실제 역사적 변동성 및 로그 수익률을 기초로 1,000회 모의 연산 수행
    - 5% (약세 시나리오), 50% (기본 시나리오), 95% (강세 시나리오) 분위수 도출 및 밴드 가시화
    """
    try:
        if len(df) < 20:
            return None
            
        # 역사적 로그 수익률 산출
        close_prices = df["Close"].astype(float)
        returns = np.log(close_prices / close_prices.shift(1)).dropna()
        
        # 일별 평균 수익률(mu) 및 변동성(sigma) 추정
        mu = returns.mean()
        sigma = returns.std()
        
        # 데이터 정규화 및 수치 예외처리
        if pd.isna(mu) or pd.isna(sigma) or sigma == 0:
            mu, sigma = 0.0, 0.01
            
        S_0 = float(close_prices.iloc[-1])
        n_days = 30
        n_paths = 1000
        
        # 몬테카를로 기하 브라운 운동(GBM) 연산
        np.random.seed(42)
        shocks = np.random.normal(0, 1, (n_days, n_paths))
        paths = np.zeros((n_days + 1, n_paths))
        paths[0, :] = S_0
        
        for t in range(1, n_days + 1):
            paths[t, :] = paths[t-1, :] * np.exp((mu - 0.5 * sigma**2) + sigma * shocks[t-1, :])
            
        # 상/하단 분위수 선출
        bull_boundary = np.percentile(paths, 95, axis=1) # 95% 분위수
        median_path = np.percentile(paths, 50, axis=1)   # 50% 분위수 (중앙 경로)
        bear_boundary = np.percentile(paths, 5, axis=1)  # 5% 분위수
        
        # 향후 30일 영업일 날짜 인덱스 연장 생성
        last_dt = df.index[-1]
        if isinstance(last_dt, pd.Timestamp):
            future_dates = pd.date_range(start=last_dt + pd.Timedelta(days=1), periods=n_days, freq="B")
            proj_dates = [last_dt] + list(future_dates)
        else:
            proj_dates = [f"D+{i}" for i in range(n_days + 1)]
            
        # 실제 과거 주가 최근 20일 봉 결합 표시
        hist_sub = df.tail(20).copy()
        hist_idx = hist_sub.index
        hist_close = hist_sub["Close"].astype(float)
        
        fig = go.Figure()
        
        # 1. 역사적 주가 플롯
        fig.add_trace(go.Scatter(
            x=hist_idx, y=hist_close, mode="lines+markers",
            name="실제 과거 주가 (최근 20봉)",
            line=dict(color="#e2e8f0", width=2),
            marker=dict(size=4)
        ))
        
        # 2. 95% 강세 분위선
        fig.add_trace(go.Scatter(
            x=proj_dates, y=bull_boundary, mode="lines",
            name="📈 95% 신뢰구간 (강세 한계)",
            line=dict(color=P["up"], width=1.5, dash="dash"),
            showlegend=True
        ))
        
        # 3. 5% 약세 분위선 (영역 투명 채우기)
        fig.add_trace(go.Scatter(
            x=proj_dates, y=bear_boundary, mode="lines",
            name="📉 5% 신뢰구간 (약세 한계)",
            line=dict(color=P["dn"], width=1.5, dash="dash"),
            fill="tonexty", fillcolor="rgba(255, 255, 255, 0.05)",
            showlegend=True
        ))
        
        # 4. 50% 중간 경로 (중앙 전망선)
        fig.add_trace(go.Scatter(
            x=proj_dates, y=median_path, mode="lines+markers",
            name="➡️ 50% 중간 전망 (기본전망)",
            line=dict(color="#38bdf8", width=2.5),
            marker=dict(size=3)
        ))
        
        fig.update_layout(
            template="plotly_dark",
            height=330,
            paper_bgcolor="rgba(0,0,0,0)",
            plot_bgcolor=P["bg_panel"],
            font=dict(color=P["txt"], family=FONT_MONO, size=11),
            margin=dict(l=10, r=10, t=45, b=10),
            hovermode="x unified",
            # 흰 배경+흰 글자로 보이던 통합 Hover를 고대비 다크 풍선으로 고정합니다.
            hoverlabel=dict(
                bgcolor="rgba(5,9,17,0.98)",
                bordercolor="#38bdf8",
                font=dict(color="#f8fafc", size=12, family=FONT_MONO),
                namelength=-1,
            ),
            legend=dict(
                orientation="h", yanchor="bottom", y=1.08,
                xanchor="right", x=1,
                font=dict(color="#e2e8f0", size=10, family=FONT_MONO),
                bgcolor="rgba(5,9,17,0.72)",
                bordercolor="rgba(56,189,248,0.28)", borderwidth=1,
            )
        )
        return fig
    except Exception as e:
        return None

def _settings_idx(options, value, default_idx=0):
    try:
        return options.index(value)
    except Exception:
        return default_idx

