# ANALYSIS UPGRADE — Enhanced analysis engine
# ═══════════════════════════════════════════════════════════════


"""
🔬 ANALYSIS ENGINE UPGRADE — 세계 최고 수준 분석 엔진
   ■ Wilder's RSI / ATR / ADX (정확한 공식)
   ■ RSI 다이버전스 자동 탐지 (Regular & Hidden)
   ■ ATR 기반 포지션 사이징 (Kelly + Risk Management)
   ■ 향상된 마켓 레짐 (변동성 Percentile + 구조 분류)
   ■ 스마트머니 컨셉 (오더블록 / 페어밸류갭)
   ■ 거래량 프로파일 VA (Value Area)
   ■ 멀티 시그널 컨플루언스 엔진
"""


# ══════════════════════════════════════════════════════════════════════
#  1. 수정된 핵심 지표 (Wilder's 공식 적용)
# ══════════════════════════════════════════════════════════════════════

def calc_rsi_wilder(close: pd.Series, period: int = 14) -> pd.Series:
    """정확한 Wilder's RSI (RMA 스무딩)."""
    close = close.astype(float)
    delta = close.diff()

    gain = delta.clip(lower=0.0)
    loss = (-delta).clip(lower=0.0)

    # Wilder's smoothing = RMA = EMA(alpha=1/period)
    avg_gain = gain.ewm(alpha=1.0 / period, adjust=False, min_periods=period).mean()
    avg_loss = loss.ewm(alpha=1.0 / period, adjust=False, min_periods=period).mean()

    rs = avg_gain / (avg_loss + 1e-10)
    rsi = 100.0 - (100.0 / (1.0 + rs))

    rsi[avg_loss == 0] = 100.0
    return rsi

def calc_atr_wilder(df: pd.DataFrame, period: int = 14) -> pd.Series:
    """정확한 Wilder's ATR."""
    high = df["High"].astype(float)
    low = df["Low"].astype(float)
    close = df["Close"].astype(float)

    tr1 = high - low
    tr2 = (high - close.shift(1)).abs()
    tr3 = (low - close.shift(1)).abs()
    tr = pd.concat([tr1, tr2, tr3], axis=1).max(axis=1)

    atr = tr.ewm(alpha=1.0 / period, adjust=False, min_periods=period).mean()
    return atr

def calc_adx_wilder(df: pd.DataFrame, period: int = 14) -> Tuple[pd.Series, pd.Series, pd.Series]:
    """정확한 Wilder's ADX / +DI / -DI."""
    high = df["High"].astype(float)
    low = df["Low"].astype(float)
    close = df["Close"].astype(float)

    up_move = high.diff()
    down_move = -low.diff()

    plus_dm = pd.Series(np.where((up_move > down_move) & (up_move > 0), up_move, 0.0),
                        index=df.index)
    minus_dm = pd.Series(np.where((down_move > up_move) & (down_move > 0), down_move, 0.0),
                         index=df.index)

    tr1 = high - low
    tr2 = (high - close.shift(1)).abs()
    tr3 = (low - close.shift(1)).abs()
    tr = pd.concat([tr1, tr2, tr3], axis=1).max(axis=1)

    atr = tr.ewm(alpha=1.0 / period, adjust=False, min_periods=period).mean()
    plus_di = 100.0 * plus_dm.ewm(alpha=1.0 / period, adjust=False, min_periods=period).mean() / (atr + 1e-10)
    minus_di = 100.0 * minus_dm.ewm(alpha=1.0 / period, adjust=False, min_periods=period).mean() / (atr + 1e-10)

    dx = 100.0 * (plus_di - minus_di).abs() / (plus_di + minus_di + 1e-10)
    adx = dx.ewm(alpha=1.0 / period, adjust=False, min_periods=period).mean()

    return adx, plus_di, minus_di

# ══════════════════════════════════════════════════════════════════════
#  2. RSI 다이버전스 자동 탐지 (Regular & Hidden)
# ══════════════════════════════════════════════════════════════════════

def detect_rsi_divergence(close: pd.Series, rsi: pd.Series, lookback: int = 60) -> Dict:
    """RSI 다이버전스 자동 탐지."""
    close = close.astype(float).tail(lookback)
    rsi = rsi.astype(float).tail(lookback)

    if len(close) < 20:
        return {"type": "none", "strength": 0, "message": "데이터 부족"}

    highs_idx = []
    lows_idx = []

    n = len(close)
    order = min(5, n // 4)

    for i in range(order, n - order):
        window_high = close.iloc[i - order:i + order + 1]
        window_low = close.iloc[i - order:i + order + 1]

        if close.iloc[i] == window_high.max() and close.iloc[i] == window_high.iloc[order]:
            highs_idx.append(i)
        if close.iloc[i] == window_low.min() and close.iloc[i] == window_low.iloc[order]:
            lows_idx.append(i)

    result = {"type": "none", "strength": 0, "message": "뚜렷한 다이버전스 없음",
              "detail": "", "severity": "info"}

    # Regular Bearish Divergence
    if len(highs_idx) >= 2:
        i1, i2 = highs_idx[-2], highs_idx[-1]
        price_high1 = close.iloc[i1]
        price_high2 = close.iloc[i2]
        rsi_high1 = rsi.iloc[i1]
        rsi_high2 = rsi.iloc[i2]

        if price_high2 > price_high1 and rsi_high2 < rsi_high1:
            strength = min(100, abs(rsi_high1 - rsi_high2) * 3 + abs(price_high2 / price_high1 - 1) * 200)
            result = {
                "type": "bearish_regular",
                "strength": strength,
                "message": f"🔴 Regular Bearish Divergence: 가격은 신고가({price_high2:,.0f})이나 RSI는 하락({rsi_high1:.0f}→{rsi_high2:.0f}). 추세 약화·전환 경고.",
                "detail": f"가격: {price_high1:,.0f}→{price_high2:,.0f} (상승) vs RSI: {rsi_high1:.0f}→{rsi_high2:.0f} (하락)",
                "severity": "warn",
            }

    # Regular Bullish Divergence
    if len(lows_idx) >= 2 and result["type"] == "none":
        i1, i2 = lows_idx[-2], lows_idx[-1]
        price_low1 = close.iloc[i1]
        price_low2 = close.iloc[i2]
        rsi_low1 = rsi.iloc[i1]
        rsi_low2 = rsi.iloc[i2]

        if price_low2 < price_low1 and rsi_low2 > rsi_low1:
            strength = min(100, abs(rsi_low2 - rsi_low1) * 3 + abs(price_low1 / price_low2 - 1) * 200)
            result = {
                "type": "bullish_regular",
                "strength": strength,
                "message": f"🟢 Regular Bullish Divergence: 가격은 신저가({price_low2:,.0f})이나 RSI는 상승({rsi_low1:.0f}→{rsi_low2:.0f}). 하락 약화·반등 가능.",
                "detail": f"가격: {price_low1:,.0f}→{price_low2:,.0f} (하락) vs RSI: {rsi_low1:.0f}→{rsi_low2:.0f} (상승)",
                "severity": "ok",
            }

    # Hidden Bullish Divergence
    if len(lows_idx) >= 2 and result["type"] == "none":
        i1, i2 = lows_idx[-2], lows_idx[-1]
        price_low1 = close.iloc[i1]
        price_low2 = close.iloc[i2]
        rsi_low1 = rsi.iloc[i1]
        rsi_low2 = rsi.iloc[i2]

        if price_low2 > price_low1 and rsi_low2 < rsi_low1:
            result = {
                "type": "bullish_hidden",
                "strength": 60,
                "message": "📊 Hidden Bullish Divergence: 추세 지속 신호. 가격은 높은 저점, RSI는 낮은 저점.",
                "detail": "추세 지속형 매수 신호",
                "severity": "info",
            }

    # Hidden Bearish Divergence
    if len(highs_idx) >= 2 and result["type"] == "none":
        i1, i2 = highs_idx[-2], highs_idx[-1]
        price_high1 = close.iloc[i1]
        price_high2 = close.iloc[i2]
        rsi_high1 = rsi.iloc[i1]
        rsi_high2 = rsi.iloc[i2]

        if price_high2 < price_high1 and rsi_high2 > rsi_high1:
            result = {
                "type": "bearish_hidden",
                "strength": 60,
                "message": "📊 Hidden Bearish Divergence: 하락 추세 지속 신호. 가격은 낮은 고점, RSI는 높은 고점.",
                "detail": "추세 지속형 매도 신호",
                "severity": "info",
            }

    return result

# ══════════════════════════════════════════════════════════════════════
#  3. ATR 기반 포지션 사이징 (리스크 관리)
# ══════════════════════════════════════════════════════════════════════

# ══════════════════════════════════════════════════════════════
# Phase 3 — 후행성 완화 모듈
# 1) Multi-timeframe confirmation
# 2) 거래량/수급 기반 선행 신호 (OBV, 외국인/기관 divergence)
# 3) Regime 기반 가중치 자동 전환
# ══════════════════════════════════════════════════════════════

def detect_obv_divergence(close: pd.Series, obv: pd.Series, lookback: int = 60) -> Dict:
    """
    OBV 다이버전스 탐지 — detect_rsi_divergence와 동일한 패턴으로 구현
    - Regular Bullish: 가격은 신저가, OBV는 상승 (매집 선행)
    - Regular Bearish: 가격은 신고가, OBV는 하락 (분배 선행)
    """
    try:
        close = close.astype(float).tail(lookback)
        obv = obv.astype(float).tail(lookback)
        if len(close) < 20:
            return {"type": "none", "strength": 0, "message": "데이터 부족", "severity": "info"}
        # 피벗 탐색 (RSI와 동일)
        highs_idx = []
        lows_idx = []
        n = len(close)
        order = min(5, n // 4)
        for i in range(order, n - order):
            wh = close.iloc[i-order:i+order+1]
            wl = close.iloc[i-order:i+order+1]
            if close.iloc[i] == wh.max() and close.iloc[i] == wh.iloc[order]:
                highs_idx.append(i)
            if close.iloc[i] == wl.min() and close.iloc[i] == wl.iloc[order]:
                lows_idx.append(i)

        result = {"type": "none", "strength": 0, "message": "OBV 뚜렷한 다이버전스 없음", "detail": "", "severity": "info"}

        if len(highs_idx) >= 2:
            i1, i2 = highs_idx[-2], highs_idx[-1]
            p1, p2 = float(close.iloc[i1]), float(close.iloc[i2])
            o1, o2 = float(obv.iloc[i1]), float(obv.iloc[i2])
            if p2 > p1 and o2 < o1:
                result = {
                    "type": "bearish_regular",
                    "strength": min(100, abs(o1-o2)/max(abs(o1)+1e-9,1)*100 + abs(p2/p1-1)*200),
                    "message": f"🔴 OBV Bearish Divergence: 가격은 신고가({p2:,.0f})이나 OBV 하락({o1:,.0f}→{o2:,.0f}). 거래량 기반 분배 선행 신호.",
                    "detail": f"가격 {p1:,.0f}→{p2:,.0f} 상승 vs OBV {o1:,.0f}→{o2:,.0f} 하락",
                    "severity": "warn",
                }
        if len(lows_idx) >= 2 and result["type"] == "none":
            i1, i2 = lows_idx[-2], lows_idx[-1]
            p1, p2 = float(close.iloc[i1]), float(close.iloc[i2])
            o1, o2 = float(obv.iloc[i1]), float(obv.iloc[i2])
            if p2 < p1 and o2 > o1:
                result = {
                    "type": "bullish_regular",
                    "strength": min(100, abs(o2-o1)/max(abs(o1)+1e-9,1)*100 + abs(p1/p2-1)*200),
                    "message": f"🟢 OBV Bullish Divergence: 가격은 신저가({p2:,.0f})이나 OBV 상승({o1:,.0f}→{o2:,.0f}). 세력 매집 선행 신호.",
                    "detail": f"가격 {p1:,.0f}→{p2:,.0f} 하락 vs OBV {o1:,.0f}→{o2:,.0f} 상승",
                    "severity": "ok",
                }
        return result
    except Exception as e:
        return {"type": "none", "strength": 0, "message": f"OBV 다이버전스 계산 오류: {e}", "severity": "info"}

def detect_smart_flow_divergence(close: pd.Series, foreign_net: pd.Series, institution_net: pd.Series, lookback: int = 60) -> Dict:
    """
    수급 기반 선행 신호 — 외국인/기관 합산 누적 흐름이 가격보다 먼저 방향 전환하는 경우 탐지
    detect_rsi_divergence 패턴 재사용
    """
    try:
        close = close.astype(float).tail(lookback)
        smart = (foreign_net.astype(float) + institution_net.astype(float)).tail(lookback)
        if len(close) < 20 or float(smart.abs().sum()) == 0:
            return {"type": "none", "strength": 0, "message": "수급 데이터 부족", "severity": "info", "available": False}
        # 스마트머니 누적
        smart_cum = smart.cumsum()
        # 피벗
        highs_idx = []
        lows_idx = []
        n = len(close)
        order = min(5, n // 4)
        for i in range(order, n - order):
            wh = close.iloc[i-order:i+order+1]
            wl = close.iloc[i-order:i+order+1]
            if close.iloc[i] == wh.max() and close.iloc[i] == wh.iloc[order]:
                highs_idx.append(i)
            if close.iloc[i] == wl.min() and close.iloc[i] == wl.iloc[order]:
                lows_idx.append(i)

        result = {"type": "none", "strength": 0, "message": "수급 뚜렷한 다이버전스 없음", "detail": "", "severity": "info", "available": True}

        if len(highs_idx) >= 2:
            i1, i2 = highs_idx[-2], highs_idx[-1]
            p1, p2 = float(close.iloc[i1]), float(close.iloc[i2])
            s1, s2 = float(smart_cum.iloc[i1]), float(smart_cum.iloc[i2])
            if p2 > p1 and s2 < s1:
                result = {
                    "type": "bearish_regular",
                    "strength": 75,
                    "message": f"🔴 수급 Bearish Divergence: 가격은 신고가({p2:,.0f})이나 외국인·기관 누적 수급 하락({s1:,.0f}→{s2:,.0f}). 가격보다 수급이 먼저 꺾인 분배 선행 신호.",
                    "detail": f"가격 상승 vs 수급 누적 하락",
                    "severity": "warn",
                    "available": True,
                }
        if len(lows_idx) >= 2 and result["type"] == "none":
            i1, i2 = lows_idx[-2], lows_idx[-1]
            p1, p2 = float(close.iloc[i1]), float(close.iloc[i2])
            s1, s2 = float(smart_cum.iloc[i1]), float(smart_cum.iloc[i2])
            if p2 < p1 and s2 > s1:
                result = {
                    "type": "bullish_regular",
                    "strength": 75,
                    "message": f"🟢 수급 Bullish Divergence: 가격은 신저가({p2:,.0f})이나 외국인·기관 누적 수급 상승({s1:,.0f}→{s2:,.0f}). 가격보다 수급이 먼저 돌아선 매집 선행 신호.",
                    "detail": f"가격 하락 vs 수급 누적 상승",
                    "severity": "ok",
                    "available": True,
                }

        # 최근 5봉 vs 20봉 방향 전환 (선행)
        if result["type"] == "none":
            smart_5 = float(smart.tail(5).sum())
            smart_20 = float(smart.tail(20).sum())
            price_5 = float(close.pct_change(5).iloc[-1] * 100)
            if price_5 < -3 and smart_5 > 0 and smart_20 <= 0:
                result = {
                    "type": "bullish_turning",
                    "strength": 60,
                    "message": f"📈 수급 선행 반전: 가격은 5봉간 {price_5:.1f}% 하락했으나 최근 5봉 수급은 순유입({smart_5:,.0f}). 매집 초기 신호.",
                    "detail": "가격 하락 + 수급 유입",
                    "severity": "ok",
                    "available": True,
                }
            elif price_5 > 3 and smart_5 < 0 and smart_20 >= 0:
                result = {
                    "type": "bearish_turning",
                    "strength": 60,
                    "message": f"📉 수급 선행 반전: 가격은 5봉간 {price_5:+.1f}% 상승했으나 최근 5봉 수급은 순유출({smart_5:,.0f}). 분배 초기 신호.",
                    "detail": "가격 상승 + 수급 유출",
                    "severity": "warn",
                    "available": True,
                }

        return result
    except Exception as e:
        return {"type": "none", "strength": 0, "message": f"수급 다이버전스 오류: {e}", "severity": "info", "available": False}

def detect_mtf_trend_alignment(df_daily: pd.DataFrame, ind_daily: Dict, raw_data: pd.DataFrame = None) -> Dict:
    """
    Multi-timeframe confirmation: 일봉 신호가 주봉 추세와 일치하는지 확인
    - 주봉 추세: 주봉 close > 주봉 MA20 > MA60, MACD 상방 등
    - 일봉 추세: 동일
    - 일치 시 신뢰도 +10, 불일치 시 '추세 충돌' 경고
    """
    try:
        # 주봉 리샘플링
        if raw_data is not None and not raw_data.empty:
            # raw_data는 일봉 원본일 수 있음
            try:
                # 주봉으로 리샘플
                weekly = raw_data.resample('W-FRI').agg({
                    'Open': 'first',
                    'High': 'max',
                    'Low': 'min',
                    'Close': 'last',
                    'Volume': 'sum'
                }).dropna()
            except Exception:
                weekly = df_daily.resample('W-FRI').agg({
                    'Open': 'first',
                    'High': 'max',
                    'Low': 'min',
                    'Close': 'last',
                    'Volume': 'sum'
                }).dropna()
        else:
            weekly = df_daily.resample('W-FRI').agg({
                'Open': 'first',
                'High': 'max',
                'Low': 'min',
                'Close': 'last',
                'Volume': 'sum'
            }).dropna()

        if len(weekly) < 20:
            return {"available": False, "weekly_trend": "데이터 부족", "daily_trend": "N/A", "alignment": True, "conflict_warning": None, "confidence_boost": 0, "weekly_score": 0}

        # 주봉 지표 간이 계산 (MA, MACD)
        w_close = weekly["Close"].astype(float)
        w_ma20 = w_close.rolling(20, min_periods=5).mean()
        w_ma60 = w_close.rolling(60, min_periods=10).mean()
        # MACD 간이
        w_ema12 = w_close.ewm(span=12, adjust=False, min_periods=1).mean()
        w_ema26 = w_close.ewm(span=26, adjust=False, min_periods=1).mean()
        w_macd = w_ema12 - w_ema26
        w_signal = w_macd.ewm(span=9, adjust=False, min_periods=1).mean()

        w_last_close = float(w_close.iloc[-1])
        w_last_ma20 = float(w_ma20.iloc[-1]) if not pd.isna(w_ma20.iloc[-1]) else w_last_close
        w_last_ma60 = float(w_ma60.iloc[-1]) if not pd.isna(w_ma60.iloc[-1]) else w_last_close
        w_last_macd = float(w_macd.iloc[-1]) if not pd.isna(w_macd.iloc[-1]) else 0.0
        w_last_signal = float(w_signal.iloc[-1]) if not pd.isna(w_signal.iloc[-1]) else 0.0

        # 주봉 추세 점수
        w_score = 0
        if w_last_close > w_last_ma20: w_score += 1
        if w_last_ma20 > w_last_ma60: w_score += 1
        if w_last_macd > w_last_signal: w_score += 1
        if w_last_close > w_last_ma60: w_score += 1

        if w_score >= 3:
            weekly_trend = "상승"
        elif w_score <= 1:
            weekly_trend = "하락"
        else:
            weekly_trend = "중립/횡보"

        # 일봉 추세 (ind_daily 기반)
        try:
            d_close = float(ind_daily["close"].iloc[-1])
            d_ma20 = float(ind_daily["ma20"].iloc[-1])
            d_ma60 = float(ind_daily["ma60"].iloc[-1])
            d_macd = float(ind_daily["macd"].iloc[-1])
            d_signal = float(ind_daily["signal"].iloc[-1])
        except Exception:
            d_close = float(df_daily["Close"].iloc[-1])
            d_ma20 = float(df_daily["Close"].rolling(20).mean().iloc[-1])
            d_ma60 = float(df_daily["Close"].rolling(60).mean().iloc[-1])
            d_macd = 0
            d_signal = 0

        d_score = 0
        if d_close > d_ma20: d_score += 1
        if d_ma20 > d_ma60: d_score += 1
        if d_macd > d_signal: d_score += 1
        if d_close > d_ma60: d_score += 1

        if d_score >= 3:
            daily_trend = "상승"
        elif d_score <= 1:
            daily_trend = "하락"
        else:
            daily_trend = "중립/횡보"

        # 정렬 여부
        if weekly_trend == daily_trend and weekly_trend != "중립/횡보":
            alignment = True
            conflict_warning = None
            confidence_boost = 10  # 신뢰도 +10
        elif weekly_trend != daily_trend and weekly_trend != "중립/횡보" and daily_trend != "중립/횡보":
            alignment = False
            conflict_warning = f"⚠️ 추세 충돌: 일봉 {daily_trend} vs 주봉 {weekly_trend} 불일치. 일봉 추격 시 주봉 저항/지지 충돌 위험. 주봉 추세 우선 관망 권장."
            confidence_boost = -15  # 신뢰도 -15
        else:
            alignment = True
            conflict_warning = None
            confidence_boost = 0
            if weekly_trend == "중립/횡보":
                conflict_warning = f"ℹ️ 주봉 중립/횡보: 방향성보다 박스권 대응 유리. 일봉 {daily_trend} 신호는 단기 트레이딩으로 한정."

        return {
            "available": True,
            "weekly_trend": weekly_trend,
            "daily_trend": daily_trend,
            "weekly_score": w_score,
            "daily_score": d_score,
            "alignment": alignment,
            "conflict_warning": conflict_warning,
            "confidence_boost": confidence_boost,
        }
    except Exception as e:
        return {"available": False, "weekly_trend": f"오류:{e}", "daily_trend": "N/A", "alignment": True, "conflict_warning": None, "confidence_boost": 0, "weekly_score": 0, "daily_score": 0}

def apply_regime_weighting(score_dict: Dict, regime: Dict, factors: Dict) -> Dict:
    """
    market_regime_enhanced 결과에 따라 지표군 가중치 자동 전환
    - 추세장: 추세추종형(MA, MACD, ADX) 가중치 ↑, 평균회귀(RSI 과매도, 볼밴, Fib) 가중치 ↓
    - 횡보장: 평균회귀형 우대, 추세추종형 가중치 ↓
    """
    try:
        regime_name = str(regime.get("regime", ""))
        score = float(score_dict.get("score", 50.0))
        prob = float(score_dict.get("prob", score/100.0))

        # 가중치 조정 계수
        adjustment = 0.0
        reason = []

        if "추세" in regime_name:
            # 추세장: 모멘텀/추세 점수가 높으면 추가 가산
            mom = float(factors.get("momentum", 50))
            timing = float(factors.get("timing", 50))
            if mom >= 60:
                adjustment += 5
                reason.append("추세장 + 모멘텀 우수 → 추세추종 가중 ↑")
            if timing >= 60:
                adjustment += 3
                reason.append("추세장 + 타이밍 우세")
            # RSI 과열은 감점 완화? 추세장에서는 과열이 오래 지속될 수 있으므로
            # 별도 조정 없음

        elif "박스" in regime_name or "스퀴즈" in regime_name:
            # 횡보장: 타이밍/밸류/피보 점수가 높으면 가산, 모멘텀 과열 시 감점
            timing = float(factors.get("timing", 50))
            rsi = float(factors.get("rsi", 50))
            if timing >= 60:
                adjustment += 4
                reason.append("횡보장 + 타이밍 우수 → 평균회귀 가중 ↑")
            if 40 <= rsi <= 65:
                adjustment += 3
                reason.append("횡보장 + RSI 중립 → 박스 매매 유리")
            if factors.get("vol_spike", 1.0) > 1.5:
                adjustment -= 3
                reason.append("횡보장 + 거래량 폭발 → 가짜 돌파 경계")

        elif "고변동" in regime_name:
            # 고변동: 방어적 조정
            adjustment -= 4
            reason.append("고변동 혼조장 → 소극적, 신뢰도 하향")

        elif "하락" in regime_name:
            adjustment -= 6
            reason.append("하락장 → 방어 우선, 점수 하향")

        # 확률에 반영
        new_score = float(np.clip(score + adjustment, 0, 100))
        new_prob = float(np.clip(prob + adjustment/100.0, 0.05, 0.95))
        # 신뢰구간도 조정
        ci_low = float(score_dict.get("prob_ci_lower", new_prob-0.15))
        ci_up = float(score_dict.get("prob_ci_upper", new_prob+0.15))
        ci_low = float(np.clip(ci_low + adjustment/200.0, 0.0, 1.0))
        ci_up = float(np.clip(ci_up + adjustment/200.0, 0.0, 1.0))

        score_dict["score"] = new_score
        score_dict["prob"] = new_prob
        score_dict["prob_percent"] = round(new_prob*100,1)
        score_dict["prob_ci_lower"] = ci_low
        score_dict["prob_ci_upper"] = ci_up
        if reason:
            # 기존 reasons에 추가
            existing = score_dict.get("reasons", [])
            score_dict["reasons"] = (existing[:3] + reason)[:6]
            score_dict["regime_adjustment"] = adjustment
            score_dict["regime_reasons"] = reason

        return score_dict
    except Exception as e:
        return score_dict


# ══════════════════════════════════════════════════════════════
# Phase 4 — 사후 검증(적중률 추적) 시스템
# 앱이 특정 날짜에 특정 종목에 대해 낸 판단(매수우위/관망/방어)을 로컬 파일(JSON)에 기록하고,
# N일 후 실제 수익률과 비교해 "이 앱의 실제 적중률"을 대시보드에 표시
# 기존 load_json_file/save_json_file 패턴 재사용
# ══════════════════════════════════════════════════════════════

PREDICTION_LOG_FILE = SETTINGS_DIR / "prediction_log.json"
PREDICTION_EVAL_FILE = SETTINGS_DIR / "prediction_eval.json"

def _judgment_to_direction(judgment: str) -> str:
    """
    판단을 방향으로 매핑: bullish / bearish / neutral
    """
    j = str(judgment).lower()
    # bullish keywords
    if any(k in j for k in ["매수우위", "강력매수", "매수", "관찰매수", "strong buy", "buy", "엘리트 매수", "상승"]):
        # 방어/매도 키워드가 함께 있으면 중립으로 보정
        if any(k in j for k in ["방어", "매도", "축소", "sell"]):
            # 매수우위인데 방어우위가 섞인 경우, 매수우위가 더 강하면 bullish로 유지
            if "매수우위" in j or "강력매수" in j:
                return "bullish"
            return "neutral"
        return "bullish"
    if any(k in j for k in ["방어", "매도", "비중축소", "관망", "중립", "sell", "reduce", "neutral"]):
        if "방어우위" in j or "매도우위" in j:
            return "bearish"
        if "관망" in j or "중립" in j:
            return "neutral"
        if "비중축소" in j:
            return "bearish"
        return "neutral"
    return "neutral"

def log_prediction(symbol: str, display_name: str, judgment: str, action: str,
                   prob: float, price_at_pred: float, final_score: float,
                   confluence_score: Dict, trade_plan: Dict, regime: Dict,
                   investment_rating: Dict, today_decision: Dict) -> Dict:
    """
    현재 분석 결과를 prediction_log.json에 기록
    - 같은 날짜+심볼이 이미 있으면 업데이트 (중복 방지)
    - 기존 load_json_file/save_json_file 패턴 재사용
    """
    try:
        today_str = datetime.now().strftime("%Y-%m-%d")
        # 기존 로그 로드
        logs = load_json_file(PREDICTION_LOG_FILE, [])
        if not isinstance(logs, list):
            logs = []

        # 새로운 엔트리
        entry = {
            "date": today_str,
            "datetime": datetime.now().isoformat(),
            "symbol": str(symbol),
            "display_name": str(display_name),
            "judgment": str(judgment),
            "action": str(action),
            "direction": _judgment_to_direction(judgment),
            "prob": float(prob) if prob is not None else 0.5,
            "price_at_pred": float(price_at_pred),
            "final_score": float(final_score) if final_score is not None else 0.0,
            "confluence_score": float(confluence_score.get("score", 0)) if isinstance(confluence_score, dict) else 0.0,
            "confluence_prob": float(confluence_score.get("prob", 0.5)) if isinstance(confluence_score, dict) else 0.5,
            "trade_plan": {
                "signal_grade": trade_plan.get("signal_grade"),
                "support1": trade_plan.get("support1"),
                "resist1": trade_plan.get("resist1"),
                "stop": trade_plan.get("stop"),
                "target1": trade_plan.get("target1"),
            } if isinstance(trade_plan, dict) else {},
            "regime": regime.get("regime") if isinstance(regime, dict) else str(regime),
            "investment_rating": investment_rating.get("grade") if isinstance(investment_rating, dict) else str(investment_rating),
            "today_decision": today_decision.get("action") if isinstance(today_decision, dict) else str(today_decision),
        }

        # 중복 체크: 같은 symbol + date가 있으면 업데이트
        updated = False
        for i, old in enumerate(logs):
            if old.get("symbol") == entry["symbol"] and old.get("date") == entry["date"]:
                logs[i] = entry
                updated = True
                break
        if not updated:
            logs.append(entry)

        # 최근 500개만 유지 (파일 크기 관리)
        logs = logs[-500:]

        save_json_file(PREDICTION_LOG_FILE, logs)
        return {"success": True, "updated": updated, "entry": entry, "total": len(logs)}
    except Exception as e:
        return {"success": False, "error": str(e)}

def evaluate_predictions(df: pd.DataFrame, eval_days: int = 10) -> Dict:
    """
    저장된 예측 로그를 읽어 N일 후 실제 수익률과 비교
    - df: 현재 종목의 일봉 데이터 (과거 예측을 평가하려면 해당 종목의 df가 필요하지만, 여기서는 공통 df로 근사)
    - eval_days: N일 후
    - 반환: summary + detailed rows
    """
    try:
        logs = load_json_file(PREDICTION_LOG_FILE, [])
        if not isinstance(logs, list) or len(logs) == 0:
            return {"total": 0, "evaluable": 0, "hits": 0, "accuracy": 0.0, "details": [], "message": "기록 없음"}

        # df 인덱스를 날짜로 변환
        df = df.copy()
        df.index = pd.to_datetime(df.index)
        close_series = df["Close"].astype(float) if "Close" in df.columns else None
        if close_series is None:
            # ind에서 close를 넘겨받을 수도 있으므로 여기서는 df가 Close를 가져야 함
            return {"total": len(logs), "evaluable": 0, "hits": 0, "accuracy": 0.0, "details": [], "message": "df에 Close 없음"}

        details = []
        hits = 0
        evaluable = 0

        for entry in logs:
            try:
                pred_date_str = entry.get("date")
                pred_date = pd.to_datetime(pred_date_str)
                symbol = entry.get("symbol")
                direction = entry.get("direction", "neutral")
                price_at_pred = float(entry.get("price_at_pred", 0))

                # N일 후 날짜
                target_date = pred_date + pd.Timedelta(days=eval_days)
                # 주말/휴장 고려: target_date 이후 가장 가까운 거래일 찾기 (forward fill)
                # df.index에서 pred_date 이후 eval_days 영업일 후를 찾음
                # 영업일 기준 N일 후: df.index에서 pred_date의 위치 + eval_days
                # pred_date가 df.index에 없을 수 있으므로, 가장 가까운 이전 거래일 찾기
                # 방법: df.index에서 pred_date 이상인 첫 번째 인덱스 찾기, 그 인덱스 + eval_days

                # pred_date 위치
                # df.index가 BDay가 아닐 수 있으므로, 단순히 pred_date 이후 eval_days 만큼 떨어진 거래일을 찾음
                pos = None
                # pred_date와 가장 가까운 df 인덱스
                try:
                    # pred_date가 df.index에 정확히 있으면 그 위치
                    if pred_date in df.index:
                        pos = df.index.get_loc(pred_date)
                    else:
                        # pred_date보다 큰 첫 번째 인덱스
                        future_idx = df.index[df.index >= pred_date]
                        if len(future_idx) > 0:
                            pos = df.index.get_loc(future_idx[0])
                        else:
                            # pred_date가 df보다 미래 -> 아직 평가 불가
                            continue
                except Exception:
                    # get_loc가 slice 반환할 수도 있음
                    try:
                        pos = int(df.index.searchsorted(pred_date))
                    except Exception:
                        pos = None

                if pos is None:
                    continue

                # pos가 int가 아니면 (slice) 처리
                if isinstance(pos, slice):
                    pos = pos.start
                if isinstance(pos, (np.ndarray, list)):
                    pos = int(pos[0]) if len(pos) > 0 else None
                if pos is None:
                    continue

                target_pos = pos + eval_days
                if target_pos >= len(df):
                    # 아직 N일 후 데이터 없음
                    continue

                # N일 후 가격
                price_target = float(close_series.iloc[target_pos])
                date_target = df.index[target_pos]

                ret = (price_target / price_at_pred - 1.0) if price_at_pred != 0 else 0.0

                # 적중 판정
                hit = False
                if direction == "bullish":
                    hit = ret > 0.01  # 1% 이상 상승이면 적중 (노이즈 필터)
                elif direction == "bearish":
                    hit = ret < -0.01
                else:  # neutral
                    hit = abs(ret) < 0.03  # 3% 이내 박스면 적중

                evaluable += 1
                if hit:
                    hits += 1

                details.append({
                    "pred_date": pred_date_str,
                    "target_date": date_target.strftime("%Y-%m-%d"),
                    "symbol": symbol,
                    "display_name": entry.get("display_name"),
                    "judgment": entry.get("judgment"),
                    "direction": direction,
                    "prob": entry.get("prob"),
                    "price_at_pred": price_at_pred,
                    "price_target": price_target,
                    "return_%": round(ret*100,2),
                    "hit": hit,
                    "eval_days": eval_days,
                })
            except Exception as e:
                # 개별 평가 실패는 무시
                continue

        accuracy = float(hits / evaluable * 100.0) if evaluable > 0 else 0.0

        # 방향별 정확도
        bullish_details = [d for d in details if d["direction"] == "bullish"]
        bearish_details = [d for d in details if d["direction"] == "bearish"]
        neutral_details = [d for d in details if d["direction"] == "neutral"]

        def _dir_acc(lst):
            if not lst:
                return 0.0
            return sum(1 for x in lst if x["hit"]) / len(lst) * 100.0

        summary = {
            "total": len(logs),
            "evaluable": evaluable,
            "hits": hits,
            "accuracy": round(accuracy,1),
            "bullish_accuracy": round(_dir_acc(bullish_details),1),
            "bearish_accuracy": round(_dir_acc(bearish_details),1),
            "neutral_accuracy": round(_dir_acc(neutral_details),1),
            "bullish_count": len(bullish_details),
            "bearish_count": len(bearish_details),
            "neutral_count": len(neutral_details),
            "details": details[-50:],  # 최근 50개만
            "all_details": details,
            "eval_days": eval_days,
            "message": f"{evaluable}개 평가 가능 / {len(logs)}개 전체 기록",
        }

        # 평가 결과도 파일로 저장 (선택)
        try:
            save_json_file(PREDICTION_EVAL_FILE, summary)
        except Exception:
            pass

        return summary
    except Exception as e:
        return {"total": 0, "evaluable": 0, "hits": 0, "accuracy": 0.0, "details": [], "message": f"오류: {e}", "error": str(e)}


# ══════════════════════════════════════════════════════════════
# 고적중률 기술적 분석 로직 - 전세계 베스트 중 승률 60%+ 전략 통합
# ══════════════════════════════════════════════════════════════

def detect_bollinger_bounce(df: pd.DataFrame, ind: Dict, lookback: int = 20) -> Dict:
    """
    볼린저 밴드 하단 이탈 후 상단 돌파 + 거래량 - 승률 55~65%
    TradeZella: "Buy when RSI drops below 30 and price is within 0.5% of lower BB. Target 20MA. Stop 1 ATR below"
    """
    try:
        close = ind["close"].astype(float)
        low = df["Low"].astype(float)
        bb_lower = ind["bb_lower"].astype(float) if "bb_lower" in ind else close.rolling(20).mean() - 2*close.rolling(20).std()
        bb_upper = ind["bb_upper"].astype(float) if "bb_upper" in ind else close.rolling(20).mean() + 2*close.rolling(20).std()
        bb_mid = ind["bb_mid"].astype(float) if "bb_mid" in ind else close.rolling(20).mean()
        rsi = ind["rsi"].astype(float)
        vol_ratio = ind["vol_ratio"].astype(float).fillna(1.0)

        # 최근 10봉 내 하단 터치
        recent_lower_touch = (close.tail(10) < bb_lower.tail(10)*1.005).any()
        # 현재 상단 돌파
        upper_break = close.iloc[-1] > bb_upper.iloc[-1] and close.iloc[-2] <= bb_upper.iloc[-2]
        # RSI 과매도에서 회복
        rsi_recover = rsi.iloc[-1] > 30 and rsi.iloc[-2] <= 35 if len(rsi)>=2 else False

        if recent_lower_touch and (upper_break or rsi_recover) and vol_ratio.iloc[-1] >= 1.2:
            return {
                "type": "bullish",
                "strength": 75,
                "message": f"🔥 볼린저 바운스: 10봉 내 하단 이탈 후 상단 돌파/RSI 회복 + 거래량 {vol_ratio.iloc[-1]:.1f}배. 승률 60%+ 고적중 패턴",
                "detail": "Bollinger 하단 터치 후 반등, 평균 회귀 고승률",
            }

        # 하단 근접 바운스 대기
        if close.iloc[-1] <= bb_lower.iloc[-1]*1.01 and rsi.iloc[-1] <= 35:
            return {
                "type": "watch_bullish",
                "strength": 60,
                "message": f"👀 볼린저 하단 근접: 현재가 {close.iloc[-1]:.0f} vs 하단 {bb_lower.iloc[-1]:.0f} ({(close.iloc[-1]/bb_lower.iloc[-1]-1)*100:+.1f}%) + RSI {rsi.iloc[-1]:.0f}. 반등 대기",
                "detail": "하단 터치, 반등 시 진입",
            }

        return {"type": "none", "strength": 0, "message": "볼린저 바운스 신호 없음"}
    except Exception as e:
        return {"type": "none", "strength": 0, "message": f"볼린저 오류: {e}"}

def detect_vwap_reversion(df: pd.DataFrame, ind: Dict) -> Dict:
    """
    VWAP 리버전 - 가격 VWAP 하회 후 상향 돌파 + 거래량, 승률 55~60%
    """
    try:
        close = ind["close"].astype(float)
        vwap = ind["vwap"].astype(float) if "vwap" in ind else None
        if vwap is None:
            # 간이 VWAP: (H+L+C)/3 * Volume 누적 / Volume 누적
            typical = (df["High"].astype(float) + df["Low"].astype(float) + df["Close"].astype(float))/3
            vwap = (typical * df["Volume"].astype(float)).cumsum() / df["Volume"].astype(float).cumsum()
        
        rsi = ind["rsi"].astype(float)
        vol_ratio = ind["vol_ratio"].astype(float).fillna(1.0)

        # VWAP 하회 후 상향 돌파
        below_vwap = close.iloc[-2] < vwap.iloc[-2] if len(close)>=2 else False
        above_vwap_now = close.iloc[-1] > vwap.iloc[-1]
        rsi_ok = rsi.iloc[-1] >= 40 and rsi.iloc[-1] <= 65

        if below_vwap and above_vwap_now and vol_ratio.iloc[-1] >= 1.1 and rsi_ok:
            return {
                "type": "bullish",
                "strength": 70,
                "message": f"📈 VWAP 리버전: VWAP {vwap.iloc[-1]:.0f} 하회 후 상향 돌파 + 거래량 {vol_ratio.iloc[-1]:.1f}배. 기관 평균단가 회복으로 신뢰도 높음",
                "detail": "VWAP 돌파, 추세 지속",
            }

        return {"type": "none", "strength": 0, "message": "VWAP 리버전 없음"}
    except Exception as e:
        return {"type": "none", "strength": 0, "message": f"VWAP 오류: {e}"}

def detect_support_bounce(df: pd.DataFrame, ind: Dict, level_table: pd.DataFrame, lookback: int = 10) -> Dict:
    """
    지지대 바운스 - 과거 60봉 내 3회 이상 지지된 레벨에서 bullish engulfing + 거래량, 승률 60%+
    Support and Resistance Trading: Look for stocks bouncing off established support levels with volume confirmation.
    """
    try:
        close = ind["close"].astype(float)
        open_ = df["Open"].astype(float)
        low = df["Low"].astype(float)
        high = df["High"].astype(float)
        vol_ratio = ind["vol_ratio"].astype(float).fillna(1.0)
        rsi = ind["rsi"].astype(float)

        if level_table is None or level_table.empty:
            return {"type": "none", "strength": 0, "message": "레벨 테이블 없음"}

        price = float(close.iloc[-1])
        # 지지 레벨 중 현재가 0.7% 이내인 것 중 반응 횟수 3회 이상
        supports = level_table[level_table["가격"] <= price*1.007].copy()
        if supports.empty:
            return {"type": "none", "strength": 0, "message": "근접 지지 없음"}

        supports = supports.sort_values("가격", ascending=False)
        best_support = supports.iloc[0]
        support_price = float(best_support["가격"])
        touches = int(best_support.get("반응 횟수", 0))

        dist_pct = abs(price - support_price) / (price+1e-9) * 100

        # bullish engulfing: prev close < prev open and current close > prev open and current open < prev close
        bullish_engulfing = False
        if len(close) >=2:
            prev_close = float(close.iloc[-2])
            prev_open = float(open_.iloc[-2])
            curr_close = float(close.iloc[-1])
            curr_open = float(open_.iloc[-1])
            bullish_engulfing = (prev_close < prev_open) and (curr_close > prev_open) and (curr_open < prev_close) and (curr_close > curr_open)

        if dist_pct <= 0.7 and touches >= 3 and (bullish_engulfing or vol_ratio.iloc[-1] >= 1.3) and rsi.iloc[-1] >= 35 and rsi.iloc[-1] <= 60:
            return {
                "type": "bullish",
                "strength": 80,
                "message": f"💎 지지대 바운스: {support_price:,.0f}원 (반응 {touches}회) 근접 {dist_pct:.2f}% + Bullish Engulfing + 거래량 {vol_ratio.iloc[-1]:.1f}배. 승률 65%+ 고적중",
                "detail": f"지지 {support_price:,.0f} / 터치 {touches}회 / Engulfing {bullish_engulfing}",
                "support_price": support_price,
                "touches": touches,
            }

        if dist_pct <= 1.5 and touches >=2:
            return {
                "type": "watch_bullish",
                "strength": 55,
                "message": f"👀 지지대 근접: {support_price:,.0f}원 ({dist_pct:.2f}%, {touches}회 지지). Bullish Engulfing 대기",
                "detail": f"지지 {support_price:,.0f}",
            }

        return {"type": "none", "strength": 0, "message": "지지대 바운스 없음"}
    except Exception as e:
        return {"type": "none", "strength": 0, "message": f"지지대 오류: {e}"}

def detect_rsi2_adx2_strategy(df: pd.DataFrame, ind: Dict) -> Dict:
    """
    Reddit Bitcoin 전략: Close > SMA50, Close > EMA7, RSI(2) > ADX(2) -> 진입, RSI(2) < ADX(2) -> 청산
    Backtest 2012-2025에서 Buy&Hold 초과, 낮은 MDD
    """
    try:
        close = ind["close"].astype(float)
        sma50 = close.rolling(50, min_periods=20).mean()
        ema7 = close.ewm(span=7, adjust=False, min_periods=5).mean()

        # RSI 2
        diff = close.diff()
        gain = diff.clip(lower=0).rolling(2, min_periods=1).mean()
        loss = (-diff.clip(upper=0)).rolling(2, min_periods=1).mean()
        rs = gain / (loss + 1e-9)
        rsi2 = 100 - (100 / (1 + rs))
        # ADX 2 - 간이: ADX period 2
        # ADX 계산 간이 버전: TR, +DM, -DM
        high = df["High"].astype(float)
        low = df["Low"].astype(float)
        tr = pd.concat([(high - low).abs(), (high - close.shift()).abs(), (low - close.shift()).abs()], axis=1).max(axis=1)
        atr2 = tr.rolling(2, min_periods=1).mean()
        # +DM, -DM 간이
        up_move = high.diff()
        down_move = -low.diff()
        plus_dm = ((up_move > down_move) & (up_move > 0)) * up_move
        minus_dm = ((down_move > up_move) & (down_move > 0)) * down_move
        plus_di = 100 * (plus_dm.rolling(2).mean() / (atr2 + 1e-9))
        minus_di = 100 * (minus_dm.rolling(2).mean() / (atr2 + 1e-9))
        dx = 100 * (abs(plus_di - minus_di) / (plus_di + minus_di + 1e-9))
        adx2 = dx.rolling(2).mean()

        c = float(close.iloc[-1])
        sma50_v = float(sma50.iloc[-1]) if not pd.isna(sma50.iloc[-1]) else c
        ema7_v = float(ema7.iloc[-1]) if not pd.isna(ema7.iloc[-1]) else c
        rsi2_v = float(rsi2.iloc[-1]) if not pd.isna(rsi2.iloc[-1]) else 50
        adx2_v = float(adx2.iloc[-1]) if not pd.isna(adx2.iloc[-1]) else 20

        # Entry: Close > SMA50 and Close > EMA7 and RSI2 > ADX2
        entry = (c > sma50_v) and (c > ema7_v) and (rsi2_v > adx2_v)
        exit_sig = (rsi2_v < adx2_v)

        if entry:
            return {
                "type": "bullish",
                "strength": 70,
                "message": f"🚀 RSI2/ADX2 전략: Close {c:.0f} > SMA50 {sma50_v:.0f} + EMA7 {ema7_v:.0f} + RSI2 {rsi2_v:.0f} > ADX2 {adx2_v:.0f}. Buy&Hold 초과 검증 전략 (2012-2025)",
                "detail": f"RSI2 {rsi2_v:.1f} > ADX2 {adx2_v:.1f}",
            }
        elif exit_sig:
            return {
                "type": "bearish",
                "strength": 60,
                "message": f"🔻 RSI2/ADX2 청산: RSI2 {rsi2_v:.0f} < ADX2 {adx2_v:.0f}. 추세 약화",
                "detail": "청산 신호",
            }
        else:
            return {"type": "none", "strength": 0, "message": "RSI2/ADX2 중립"}

    except Exception as e:
        return {"type": "none", "strength": 0, "message": f"RSI2/ADX2 오류: {e}"}

def detect_reversal_candle_high_hitrate(df: pd.DataFrame, ind: Dict) -> Dict:
    """
    Reversal Candle + RVOL>2 전략: 승률 63%, +20.36% 수익으로 Buy&Hold 초과 (TrendSpider 테스트)
    Hammer, Inverted Hammer, Doji, Engulfing + RVOL>2
    """
    try:
        close = ind["close"].astype(float)
        open_ = df["Open"].astype(float)
        high = df["High"].astype(float)
        low = df["Low"].astype(float)
        vol = df["Volume"].astype(float).fillna(0)
        vol_ma20 = vol.rolling(20, min_periods=5).mean()
        rvol = vol / (vol_ma20 + 1e-9)

        # 마지막 봉
        o = float(open_.iloc[-1])
        c = float(close.iloc[-1])
        h = float(high.iloc[-1])
        l = float(low.iloc[-1])
        r = float(rvol.iloc[-1]) if not pd.isna(rvol.iloc[-1]) else 0

        body = abs(c - o)
        rng = h - l
        lower_wick = min(o,c) - l
        upper_wick = h - max(o,c)

        # Hammer: lower wick >= 2*body, upper wick < body*0.5, body < range*0.4
        hammer = (lower_wick >= body*2) and (upper_wick <= body*0.5) and (body < rng*0.5) if rng>0 else False
        # Inverted Hammer: upper wick >=2*body
        inv_hammer = (upper_wick >= body*2) and (lower_wick <= body*0.5) and (body < rng*0.5) if rng>0 else False
        # Doji: body < range*0.1
        doji = (body < rng*0.1) if rng>0 else False
        # Bullish Engulfing
        bullish_engulf = False
        bearish_engulf = False
        if len(close)>=2:
            prev_o = float(open_.iloc[-2])
            prev_c = float(close.iloc[-2])
            # Bullish Engulfing: prev bearish, current bullish, current body engulfs prev
            if prev_c < prev_o and c > o and o < prev_c and c > prev_o:
                bullish_engulf = True
            if prev_c > prev_o and c < o and o > prev_c and c < prev_o:
                bearish_engulf = True

        if (hammer or inv_hammer or doji or bullish_engulf) and r >= 2.0:
            return {
                "type": "bullish",
                "strength": 80,
                "message": f"🔥 Reversal Candle 고적중: {'Hammer' if hammer else 'InvHammer' if inv_hammer else 'Doji' if doji else 'BullEngulf'} + RVOL {r:.1f} (승률 63%, +20.36% Buy&Hold 초과 검증)",
                "detail": f"RVOL {r:.1f} >2.0",
            }
        if bearish_engulf and r >= 2.0:
            return {
                "type": "bearish",
                "strength": 75,
                "message": f"💥 Bearish Engulfing + RVOL {r:.1f} - 고적중 하락 반전",
                "detail": "하락 반전",
            }

        return {"type": "none", "strength": 0, "message": "Reversal Candle 없음"}
    except Exception as e:
        return {"type": "none", "strength": 0, "message": f"Reversal 오류: {e}"}

def compute_high_hitrate_confluence(
    df: pd.DataFrame,
    ind: Dict,
    level_table: pd.DataFrame,
) -> Dict:
    """
    고적중률 신호들의 컨플루언스 점수
    """
    try:
        signals = []
        score = 50.0

        bb = detect_bollinger_bounce(df, ind)
        if bb["type"] == "bullish":
            score += 12
            signals.append(bb["message"])
        elif bb["type"] == "watch_bullish":
            score += 4
            signals.append(bb["message"])

        vwap = detect_vwap_reversion(df, ind)
        if vwap["type"] == "bullish":
            score += 10
            signals.append(vwap["message"])

        sr = detect_support_bounce(df, ind, level_table)
        if sr["type"] == "bullish":
            score += 15
            signals.append(sr["message"])
        elif sr["type"] == "watch_bullish":
            score += 5
            signals.append(sr["message"])

        rsi_adx = detect_rsi2_adx2_strategy(df, ind)
        if rsi_adx["type"] == "bullish":
            score += 10
            signals.append(rsi_adx["message"])
        elif rsi_adx["type"] == "bearish":
            score -= 8
            signals.append(rsi_adx["message"])

        rev = detect_reversal_candle_high_hitrate(df, ind)
        if rev["type"] == "bullish":
            score += 12
            signals.append(rev["message"])
        elif rev["type"] == "bearish":
            score -= 10
            signals.append(rev["message"])

        score = float(np.clip(score, 0, 100))
        label = "매우 강함" if score>=80 else "강함" if score>=65 else "보통" if score>=50 else "약함"

        return {
            "score": score,
            "label": label,
            "signals": signals[:6],
            "details": {
                "bollinger": bb,
                "vwap": vwap,
                "support": sr,
                "rsi_adx": rsi_adx,
                "reversal": rev,
            }
        }
    except Exception as e:
        return {"score": 50.0, "label": "보통", "signals": [], "details": {}, "error": str(e)}


def compute_position_sizing(current_price: float, atr: float, stop_price: float,
                            account_size: float = 10_000_000,
                            risk_pct: float = 1.0) -> Dict:
    """ATR 기반 포지션 사이징 (Volatility-Adjusted Risk Management)."""
    risk_per_share = abs(current_price - stop_price)

    if risk_per_share < atr * 0.3:
        risk_per_share = atr * 0.8
        stop_price = current_price - atr * 0.8 if stop_price < current_price else current_price + atr * 0.8

    risk_amount = account_size * (risk_pct / 100.0)
    max_shares = int(risk_amount / risk_per_share) if risk_per_share > 0 else 0
    max_investment = max_shares * current_price

    atr_stop_close = atr * 1.5      # 보수적
    atr_stop_medium = atr * 2.0     # 중간
    atr_stop_wide = atr * 3.0       # 넓음 (추세 추종용)

    win_rate = 0.55
    rr_ratio = 1.5
    kelly_pct = max(0, win_rate - (1 - win_rate) / rr_ratio)
    kelly_shares = int(account_size * kelly_pct * 0.5 / current_price) if current_price > 0 else 0  # Half-Kelly

    return {
        "risk_amount": risk_amount,
        "risk_per_share": risk_per_share,
        "max_shares": max_shares,
        "max_investment": max_investment,
        "investment_pct": max_investment / account_size * 100 if account_size > 0 else 0,
        "atr_stop_conservative": atr_stop_close,
        "atr_stop_medium": atr_stop_medium,
        "atr_stop_wide": atr_stop_wide,
        "kelly_pct": kelly_pct * 100,
        "kelly_shares": kelly_shares,
        "recommended_shares": min(max_shares, kelly_shares) if kelly_shares > 0 else max_shares,
        "account_size": account_size,
        "risk_pct": risk_pct,
    }

# ══════════════════════════════════════════════════════════════════════
#  4. 향상된 마켓 레짐 (변동성 Percentile + 구조적 분류)
# ══════════════════════════════════════════════════════════════════════

def market_regime_enhanced(ind: Dict) -> Dict:
    """향상된 마켓 레짐 분류."""
    close = ind["close"]
    atr = ind["atr"]
    adx = ind["adx"]
    bb_width = ind["bb_width"]
    vol_ratio = ind["vol_ratio"]

    ema20 = close.ewm(span=20, adjust=False, min_periods=1).mean()
    ema50 = close.ewm(span=50, adjust=False, min_periods=1).mean()
    ema200 = close.ewm(span=200, adjust=False, min_periods=1).mean()

    # 1) 변동성 Percentile
    atr_pct = (atr / (close + 1e-10)) * 100
    atr_pct_rank = float(atr_pct.tail(200).rank(pct=True).iloc[-1]) * 100

    # 2) 추세 구조 점수
    c = float(close.iloc[-1])
    trend_signals = [
        c > float(ema20.iloc[-1]),
        float(ema20.iloc[-1]) > float(ema50.iloc[-1]),
        float(ema50.iloc[-1]) > float(ema200.iloc[-1]) if len(ema200) >= 200 else True,
        float(adx.iloc[-1]) > 25,
        float(adx.iloc[-1]) > 20,
        float(vol_ratio.iloc[-1]) > 1.0,
    ]
    trend_score = sum(trend_signals)

    n_slope = min(10, len(ema20) - 1)
    ema_slope = (float(ema20.iloc[-1]) - float(ema20.iloc[-n_slope])) / \
                (abs(float(ema20.iloc[-n_slope])) + 1e-10)

    # 3) 스퀴즈 감지
    bb_mid = ind["bb_mid"]
    std20 = close.rolling(20, min_periods=1).std()
    keltner_upper = bb_mid + atr * 1.5
    keltner_lower = bb_mid - atr * 1.5
    squeeze = (float(bb_mid.iloc[-1]) + 2 * float(std20.iloc[-1]) < float(keltner_upper.iloc[-1])) and \
              (float(bb_mid.iloc[-1]) - 2 * float(std20.iloc[-1]) > float(keltner_lower.iloc[-1]))

    bbw_med = float(bb_width.rolling(100, min_periods=20).median().iloc[-1])
    bbw_now = float(bb_width.iloc[-1])

    # 4) 레짐 분류
    adx_val = float(adx.iloc[-1])

    if trend_score >= 5 and atr_pct_rank < 70:
        regime = "강한 추세장"
        strategy = "추세 추종 (눌림 매수, 손절 넓게, 비중 확대)"
    elif trend_score >= 4 and adx_val > 25:
        regime = "추세장"
        strategy = "추세 추종 (돌파/눌림 매수, 비중 유지)"
    elif trend_score <= 1 and atr_pct_rank < 70:
        regime = "강한 하락장"
        strategy = "방어 우선 (비중 축소, 매도 우세)"
    elif squeeze or bbw_now < bbw_med * 0.65:
        regime = "변동성 스퀴즈"
        strategy = "대기 (방향 확정 후 진입, 폭발적 움직임 임박 가능)"
    elif atr_pct_rank > 80:
        regime = "고변동 혼조장"
        strategy = "소극적 (비중 축소, 짧은 손절, 분할 매매)"
    elif adx_val < 20:
        regime = "박스권 (횡보)"
        strategy = "박스 매매 (지지 매수, 저항 매도)"
    else:
        regime = "전환 국면"
        strategy = "신중 접근 (방향 확인 후 소액 진입)"

    return {
        "regime": regime,
        "strategy": strategy,
        "trend_score": trend_score,
        "adx": adx_val,
        "atr_pct": float(atr_pct.iloc[-1]),
        "atr_pct_rank": atr_pct_rank,
        "ema_slope": ema_slope,
        "squeeze": squeeze,
        "volatility_level": "높음" if atr_pct_rank > 70 else "중간" if atr_pct_rank > 40 else "낮음",
        "ema20": float(ema20.iloc[-1]),
        "ema50": float(ema50.iloc[-1]),
        "ema200": float(ema200.iloc[-1]) if len(ema200) >= 200 else None,
    }

# ══════════════════════════════════════════════════════════════════════
#  5. 스마트머니 컨셉 (오더블록 / 페어밸류갭)
# ══════════════════════════════════════════════════════════════════════

def detect_smart_money_concepts(df: pd.DataFrame, lookback: int = 100) -> Dict:
    """스마트머니 컨셉 (Smart Money Concepts / ICT)."""
    sub = df.tail(min(len(df), lookback)).copy()
    if len(sub) < 20:
        return {"available": False, "order_blocks": [], "fvgs": [], "message": "데이터 부족"}

    highs = sub["High"].astype(float).values
    lows = sub["Low"].astype(float).values
    opens = sub["Open"].astype(float).values
    closes = sub["Close"].astype(float).values
    vols = sub["Volume"].astype(float).fillna(0).values
    dates = sub.index

    # ── 오더블록 탐지 ──
    order_blocks = []
    for i in range(2, len(sub) - 1):
        # 상승 오더블록
        if closes[i] > opens[i] and closes[i + 1] > closes[i]:
            if closes[i - 1] < opens[i - 1]:
                ob_high = max(opens[i - 1], closes[i - 1])
                ob_low = min(opens[i - 1], closes[i - 1])
                ob_vol = vols[i - 1]
                vol20 = np.mean(vols[max(0, i - 21):i - 1])
                if ob_vol > vol20 * 1.2:
                    order_blocks.append({
                        "type": "bullish",
                        "date": dates[i - 1],
                        "high": ob_high,
                        "low": ob_low,
                        "volume": ob_vol,
                        "vol_ratio": ob_vol / (vol20 + 1e-10),
                        "age_bars": len(sub) - 1 - (i - 1),
                    })

        # 하락 오더블록
        if closes[i] < opens[i] and closes[i + 1] < closes[i]:
            if closes[i - 1] > opens[i - 1]:
                ob_high = max(opens[i - 1], closes[i - 1])
                ob_low = min(opens[i - 1], closes[i - 1])
                ob_vol = vols[i - 1]
                vol20 = np.mean(vols[max(0, i - 21):i - 1])
                if ob_vol > vol20 * 1.2:
                    order_blocks.append({
                        "type": "bearish",
                        "date": dates[i - 1],
                        "high": ob_high,
                        "low": ob_low,
                        "volume": ob_vol,
                        "vol_ratio": ob_vol / (vol20 + 1e-10),
                        "age_bars": len(sub) - 1 - (i - 1),
                    })

    order_blocks = sorted(order_blocks, key=lambda x: x["age_bars"])[:5]

    # ── 페어밸류갭 탐지 ──
    fvgs = []
    for i in range(2, len(sub)):
        # Bullish FVG
        if lows[i] > highs[i - 2]:
            gap = lows[i] - highs[i - 2]
            gap_pct = gap / closes[i] * 100
            if gap_pct > 0.1:
                fvgs.append({
                    "type": "bullish",
                    "date": dates[i],
                    "gap_top": lows[i],
                    "gap_bottom": highs[i - 2],
                    "gap_size": gap,
                    "gap_pct": gap_pct,
                    "filled": False,
                    "age_bars": len(sub) - 1 - i,
                })

        # Bearish FVG
        if highs[i] < lows[i - 2]:
            gap = lows[i - 2] - highs[i]
            gap_pct = gap / closes[i] * 100
            if gap_pct > 0.1:
                fvgs.append({
                    "type": "bearish",
                    "date": dates[i],
                    "gap_top": lows[i - 2],
                    "gap_bottom": highs[i],
                    "gap_size": gap,
                    "gap_pct": gap_pct,
                    "filled": False,
                    "age_bars": len(sub) - 1 - i,
                })

    current_price = float(sub["Close"].iloc[-1])
    for fvg in fvgs:
        if fvg["type"] == "bullish" and current_price < fvg["gap_bottom"]:
            fvg["filled"] = True
        elif fvg["type"] == "bearish" and current_price > fvg["gap_top"]:
            fvg["filled"] = True

    fvgs = [f for f in fvgs if not f["filled"]]
    fvgs = sorted(fvgs, key=lambda x: x["age_bars"])[:5]

    return {
        "available": True,
        "order_blocks": order_blocks,
        "fvgs": fvgs,
        "current_price": current_price,
        "message": f"오더블록 {len(order_blocks)}개, 미충족 FVG {len(fvgs)}개 탐지" if order_blocks or fvgs else "유의미한 스마트머니 구조 미탐지",
    }

# ══════════════════════════════════════════════════════════════════════
#  6. 향상된 거래량 프로파일 (Value Area)
# ══════════════════════════════════════════════════════════════════════

def volume_profile_enhanced(df: pd.DataFrame, bins: int = 50) -> Dict:
    """향상된 거래량 프로파일 (Volume Profile + Value Area)."""
    if df.empty or len(df) < 10:
        return {"available": False, "poc": np.nan, "vah": np.nan, "val": np.nan}

    prices = df["Close"].astype(float)
    vols = df["Volume"].astype(float).fillna(0)

    mn, mx = float(prices.min()), float(prices.max())
    if np.isclose(mn, mx):
        return {"available": True, "poc": mn, "vah": mn, "val": mn,
                "va_pct": 100, "profile": []}

    edges = np.linspace(mn, mx, bins + 1)
    inds = np.clip(np.digitize(prices, edges, right=True), 1, len(edges) - 1)

    rows = []
    for i in range(1, len(edges)):
        mask = inds == i
        v = float(vols[mask].sum())
        rows.append({
            "low": float(edges[i - 1]),
            "high": float(edges[i]),
            "mid": (float(edges[i - 1]) + float(edges[i])) / 2,
            "volume": v,
        })

    vp = pd.DataFrame(rows)
    total_vol = float(vp["volume"].sum())
    vp["pct"] = vp["volume"] / (total_vol + 1e-10)

    poc_idx = int(vp["volume"].idxmax())
    poc = float(vp.loc[poc_idx, "mid"])

    # Value Area (CME 방식)
    target_pct = 0.70
    va_vol = vp.loc[poc_idx, "volume"]
    va_low_idx = poc_idx
    va_high_idx = poc_idx

    while va_vol / (total_vol + 1e-10) < target_pct:
        below_vol = vp.loc[va_low_idx - 1, "volume"] if va_low_idx > 0 else 0
        above_vol = vp.loc[va_high_idx + 1, "volume"] if va_high_idx < len(vp) - 1 else 0

        if below_vol >= above_vol and va_low_idx > 0:
            va_vol += below_vol
            va_low_idx -= 1
        elif va_high_idx < len(vp) - 1:
            va_vol += above_vol
            va_high_idx += 1
        elif va_low_idx > 0:
            va_vol += below_vol
            va_low_idx -= 1
        else:
            break

    vah = float(vp.loc[va_high_idx, "mid"])
    val = float(vp.loc[va_low_idx, "mid"])
    va_pct = va_vol / (total_vol + 1e-10) * 100

    return {
        "available": True,
        "poc": poc,
        "vah": vah,
        "val": val,
        "va_pct": va_pct,
        "profile": vp.to_dict("records"),
        "total_vol": total_vol,
        "above_va": float(prices.iloc[-1]) > vah,
        "below_va": float(prices.iloc[-1]) < val,
        "in_va": val <= float(prices.iloc[-1]) <= vah,
    }

# ══════════════════════════════════════════════════════════════════════
#  7. 향상된 컨플루언스 엔진 (Multi-Signal Weighted)
# ══════════════════════════════════════════════════════════════════════

def compute_confluence_enhanced(ind: Dict, regime: Dict, trade_plan: Dict,
                                rsi_div: Dict, smc: Dict, vp: Dict,
                                factors: Dict, focus_fib: Optional[Dict]) -> Dict:
    """향상된 컨플루언스 엔진 (Multi-Signal Weighted Scoring)."""
    score = 50.0
    reasons = []
    signals = {}

    # ── 1. 추세 방향 (25%) ──
    trend_score = 0
    if float(ind["close"].iloc[-1]) > float(ind["ma20"].iloc[-1]):
        trend_score += 1
    if float(ind["ma20"].iloc[-1]) > float(ind["ma60"].iloc[-1]):
        trend_score += 1
    if float(ind["adx"].iloc[-1]) > 25:
        trend_score += 1
    if regime.get("ema_slope", 0) > 0.01:
        trend_score += 1

    trend_norm = trend_score / 4.0
    trend_contribution = trend_norm * 25
    score += (trend_contribution - 12.5)
    signals["추세"] = f"{trend_norm * 100:.0f}%"
    if trend_score >= 3:
        reasons.append(f"강한 추세 정렬 ({trend_score}/4)")

    # ── 2. 모멘텀 (20%) ──
    mom_score = 0
    if factors["macd"] > factors["signal"]:
        mom_score += 1
    if factors["rsi"] > 50:
        mom_score += 1
    if factors["rsi"] < 70:
        mom_score += 1
    if factors["vol_spike"] > 1.2:
        mom_score += 1

    mom_norm = mom_score / 4.0
    mom_contribution = mom_norm * 20
    score += (mom_contribution - 10)
    signals["모멘텀"] = f"{mom_norm * 100:.0f}%"
    if mom_score >= 3:
        reasons.append(f"모멘텀 우세 ({mom_score}/4)")

    # ── 3. 구조 (피보나치) (20%) ──
    struct_score = 0
    if focus_fib:
        if str(focus_fib.get("ratio")) in ["0.618", "0.500", "0.382"]:
            struct_score += 2
        if float(focus_fib.get("strength", 0)) >= 60:
            struct_score += 1
        if focus_fib.get("role") == "지지 후보":
            struct_score += 1

    struct_norm = min(struct_score / 4.0, 1.0)
    struct_contribution = struct_norm * 20
    score += (struct_contribution - 10)
    signals["구조"] = f"{struct_norm * 100:.0f}%"
    if struct_score >= 3:
        reasons.append(f"피보나치 구조 양호 ({struct_score}/4)")

    # ── 4. 수급 (15%) ──
    flow_score = 0
    has_flow = float(ind.get("foreign_net", pd.Series([0])).abs().sum() +
                     ind.get("institution_net", pd.Series([0])).abs().sum()) > 0
    if has_flow:
        flow5 = float((ind["foreign_net"] + ind["institution_net"]).tail(5).sum())
        if flow5 > 0:
            flow_score += 2
        else:
            flow_score -= 1

    if smc.get("available"):
        cp = smc.get("current_price", 0)
        near_bullish_ob = any(
            ob["type"] == "bullish" and ob["low"] <= cp <= ob["high"] * 1.02
            for ob in smc.get("order_blocks", [])
        )
        if near_bullish_ob:
            flow_score += 1
            reasons.append("매수 오더블록 근처")

    flow_norm = (flow_score + 2) / 4.0
    flow_contribution = flow_norm * 15
    score += (flow_contribution - 7.5)
    signals["수급"] = f"{flow_norm * 100:.0f}%"

    # ── 5. 변동성 레짐 (10%) ──
    vol_rank = regime.get("atr_pct_rank", 50)
    if vol_rank < 70:
        score += 3
        signals["변동성"] = "적정"
    elif regime.get("squeeze"):
        score += 5
        signals["변동성"] = "스퀴즈"
        reasons.append("변동성 스퀴즈 (폭발 임박)")
    else:
        score -= 3
        signals["변동성"] = "높음"

    # ── 6. RSI 다이버전스 (10%) ──
    div = rsi_div.get("type", "none")
    if div == "bullish_regular":
        score += 8
        reasons.append("RSI Bullish Divergence (반등 신호)")
        signals["다이버전스"] = "🟢 매수"
    elif div == "bearish_regular":
        score -= 10
        reasons.append("RSI Bearish Divergence (전환 경고)")
        signals["다이버전스"] = "🔴 매도"
    elif div == "bullish_hidden":
        score += 4
        signals["다이버전스"] = "📈 지속"
    elif div == "bearish_hidden":
        score -= 5
        signals["다이버전스"] = "📉 지속"
    else:
        signals["다이버전스"] = "중립"

    if vp.get("available") and vp.get("in_va"):
        score += 2
        reasons.append("Value Area 내 위치 (균형)")

    score = float(np.clip(score, 0, 100))
    label = "매우 강함" if score >= 80 else "강함" if score >= 68 else "양호" if score >= 55 else "보통" if score >= 45 else "약함" if score >= 32 else "매우 약함"

    return {
        "score": score,
        "label": label,
        "reasons": reasons[:6],
        "signals": signals,
        "trend_alignment": trend_norm,
        "momentum_alignment": mom_norm,
    }

# ══════════════════════════════════════════════════════════════════════
#  8. 통합 업그레이드: compute_indicators 교체용
# ══════════════════════════════════════════════════════════════════════


def calc_supertrend(df: pd.DataFrame, period: int = 10, multiplier: float = 3.0) -> Tuple[pd.Series, pd.Series]:
    """정확한 SuperTrend 계산 (추세 추종 채널)."""
    high = df["High"].astype(float)
    low = df["Low"].astype(float)
    close = df["Close"].astype(float)
    
    hl = high - low
    hc = (high - close.shift(1)).abs()
    lc = (low - close.shift(1)).abs()
    tr = pd.concat([hl, hc, lc], axis=1).max(axis=1)
    
    atr = tr.ewm(alpha=1.0/period, adjust=False, min_periods=period).mean()
    if atr.isna().all():
        atr = tr.rolling(period, min_periods=1).mean()
        
    hl2 = (high + low) / 2
    basic_ub = hl2 + multiplier * atr
    basic_lb = hl2 - multiplier * atr
    
    final_ub = basic_ub.copy()
    final_lb = basic_lb.copy()
    
    for i in range(1, len(df)):
        # Upper band
        if basic_ub.iloc[i] < final_ub.iloc[i-1] or close.iloc[i-1] > final_ub.iloc[i-1]:
            final_ub.iloc[i] = basic_ub.iloc[i]
        else:
            final_ub.iloc[i] = final_ub.iloc[i-1]
            
        # Lower band
        if basic_lb.iloc[i] > final_lb.iloc[i-1] or close.iloc[i-1] < final_lb.iloc[i-1]:
            final_lb.iloc[i] = basic_lb.iloc[i]
        else:
            final_lb.iloc[i] = final_lb.iloc[i-1]
            
    supertrend = pd.Series(0.0, index=df.index)
    direction = pd.Series(1, index=df.index) # 1 for uptrend, -1 for downtrend
    
    for i in range(1, len(df)):
        if direction.iloc[i-1] == 1:
            if close.iloc[i] < final_lb.iloc[i]:
                direction.iloc[i] = -1
                supertrend.iloc[i] = final_ub.iloc[i]
            else:
                direction.iloc[i] = 1
                supertrend.iloc[i] = final_lb.iloc[i]
        else:
            if close.iloc[i] > final_ub.iloc[i]:
                direction.iloc[i] = 1
                supertrend.iloc[i] = final_lb.iloc[i]
            else:
                direction.iloc[i] = -1
                supertrend.iloc[i] = final_ub.iloc[i]
                
    return supertrend, direction

def calc_squeeze_momentum(df: pd.DataFrame, bb_period: int = 20, bb_mult: float = 2.0, kc_period: int = 20, kc_mult: float = 1.5) -> Tuple[pd.Series, pd.Series, pd.Series]:
    """Squeeze Momentum Indicator (by LazyBear)."""
    close = df["Close"].astype(float)
    high = df["High"].astype(float)
    low = df["Low"].astype(float)
    
    # Bollinger Bands
    bb_mid = close.rolling(bb_period).mean()
    bb_std = close.rolling(bb_period).std()
    bb_upper = bb_mid + bb_mult * bb_std
    bb_lower = bb_mid - bb_mult * bb_std
    
    # Keltner Channels using EMA and ATR
    hl = high - low
    hc = (high - close.shift(1)).abs()
    lc = (low - close.shift(1)).abs()
    tr = pd.concat([hl, hc, lc], axis=1).max(axis=1)
    atr = tr.ewm(span=kc_period, adjust=False).mean()
    
    kc_mid = close.ewm(span=kc_period, adjust=False).mean()
    kc_upper = kc_mid + kc_mult * atr
    kc_lower = kc_mid - kc_mult * atr
    
    # Squeeze ON state: Bollinger Bands inside Keltner Channels
    squeeze_on = (bb_lower > kc_lower) & (bb_upper < kc_upper)
    
    # Momentum value
    hh = high.rolling(kc_period).max()
    ll = low.rolling(kc_period).min()
    mid = (hh + ll) / 2
    avg = (mid + bb_mid) / 2
    val = close - avg
    
    # Fast rolling linear regression
    n = kc_period
    x = np.arange(n)
    sum_x = x.sum()
    sum_x2 = (x**2).sum()
    denom = n * sum_x2 - (sum_x**2)
    
    def lr_slope_intercept(y_slice):
        if len(y_slice) < n:
            return 0.0
        y = y_slice
        sum_y = y.sum()
        sum_xy = (x * y).sum()
        slope = (n * sum_xy - sum_x * sum_y) / denom
        intercept = (sum_y - slope * sum_x) / n
        return slope * (n - 1) + intercept
        
    lr_val = val.rolling(n).apply(lr_slope_intercept, raw=True)
    return lr_val, squeeze_on, val



def calc_keltner_channel(df: pd.DataFrame, period: int = 20, multiplier: float = 1.5):
    close = df["Close"].astype(float)
    mid = close.ewm(span=period, adjust=False, min_periods=1).mean()
    atr = calc_atr_wilder(df, period) if "calc_atr_wilder" in globals() else calc_atr(df, period)
    return mid, mid + multiplier * atr, mid - multiplier * atr


def calc_donchian_channel(df: pd.DataFrame, period: int = 20):
    high = df["High"].astype(float).rolling(period, min_periods=1).max()
    low = df["Low"].astype(float).rolling(period, min_periods=1).min()
    return high, low, (high + low) / 2


def calc_hma(close: pd.Series, period: int = 55) -> pd.Series:
    close = close.astype(float)
    def wma(s: pd.Series, n: int) -> pd.Series:
        weights = np.arange(1, n + 1, dtype=float)
        return s.rolling(n, min_periods=1).apply(lambda x: float(np.dot(x, weights[-len(x):]) / weights[-len(x):].sum()), raw=True)
    half = max(int(period / 2), 1)
    root = max(int(np.sqrt(period)), 1)
    return wma(2 * wma(close, half) - wma(close, period), root)


def calc_psar(df: pd.DataFrame, step: float = 0.02, max_step: float = 0.2) -> pd.Series:
    high = df["High"].astype(float).values
    low = df["Low"].astype(float).values
    if len(df) == 0:
        return pd.Series(dtype=float, index=df.index)
    psar = np.zeros(len(df), dtype=float)
    bull = True
    af = step
    ep = high[0]
    psar[0] = low[0]
    for i in range(1, len(df)):
        prev = psar[i - 1]
        if bull:
            psar[i] = prev + af * (ep - prev)
            if i >= 2:
                psar[i] = min(psar[i], low[i-1], low[i-2])
            if low[i] < psar[i]:
                bull = False; psar[i] = ep; ep = low[i]; af = step
            elif high[i] > ep:
                ep = high[i]; af = min(af + step, max_step)
        else:
            psar[i] = prev + af * (ep - prev)
            if i >= 2:
                psar[i] = max(psar[i], high[i-1], high[i-2])
            if high[i] > psar[i]:
                bull = True; psar[i] = ep; ep = high[i]; af = step
            elif low[i] < ep:
                ep = low[i]; af = min(af + step, max_step)
    return pd.Series(psar, index=df.index)


def calc_mfi(df: pd.DataFrame, period: int = 14) -> pd.Series:
    tp = (df["High"].astype(float) + df["Low"].astype(float) + df["Close"].astype(float)) / 3
    mf = tp * df["Volume"].astype(float).fillna(0)
    pos = mf.where(tp.diff() > 0, 0.0).rolling(period, min_periods=1).sum()
    neg = mf.where(tp.diff() < 0, 0.0).rolling(period, min_periods=1).sum().abs()
    return 100 - (100 / (1 + pos / (neg + 1e-9)))


def calc_stoch_rsi(rsi: pd.Series, period: int = 14, smooth_k: int = 3, smooth_d: int = 3):
    rsi = rsi.astype(float)
    mn = rsi.rolling(period, min_periods=1).min()
    mx = rsi.rolling(period, min_periods=1).max()
    raw = (rsi - mn) / (mx - mn + 1e-9) * 100
    k = raw.rolling(smooth_k, min_periods=1).mean()
    d = k.rolling(smooth_d, min_periods=1).mean()
    return k, d


def calc_anchored_vwap(df: pd.DataFrame, lookback: int = 120) -> pd.Series:
    """최근 lookback 내 거래량 가중 스윙 저점/고점 중 더 가까운 핵심 피벗에 앵커를 둔 AVWAP."""
    if len(df) < 5:
        return calc_vwap(df)
    sub = df.tail(min(len(df), lookback))
    # 최근 변곡점 후보: 거래량이 큰 저점/고점 중 현재가와 방향성이 맞는 지점
    low_idx = sub["Low"].astype(float).idxmin()
    high_idx = sub["High"].astype(float).idxmax()
    anchor = low_idx if sub.index.get_loc(low_idx) >= sub.index.get_loc(high_idx) else high_idx
    base = df.loc[anchor:].copy()
    tp = (base["High"] + base["Low"] + base["Close"]) / 3
    vol = base["Volume"].astype(float).fillna(0)
    avwap_part = (tp * vol).cumsum() / (vol.cumsum() + 1e-9)
    out = pd.Series(np.nan, index=df.index, dtype=float)
    out.loc[avwap_part.index] = avwap_part
    return out.ffill()


# ──────────────────────────────────────────────────────────────
# v24.7 ELITE CHART ENGINE — latest overlays / deduplicated helpers
# ──────────────────────────────────────────────────────────────
def calc_vwma(df: pd.DataFrame, period: int = 20) -> pd.Series:
    """Volume Weighted Moving Average: 기관/세력 평균 체결 흐름을 더 민감하게 반영."""
    close = df["Close"].astype(float)
    vol = df["Volume"].astype(float).fillna(0)
    return (close * vol).rolling(period, min_periods=1).sum() / (vol.rolling(period, min_periods=1).sum() + 1e-9)


def calc_zlema(series: pd.Series, period: int = 34) -> pd.Series:
    """Zero-Lag EMA: 일반 EMA보다 늦게 꺾이는 단점을 줄인 최신 트렌드 추적선."""
    s = series.astype(float)
    lag = max(int((period - 1) / 2), 1)
    adj = s + (s - s.shift(lag))
    return adj.ewm(span=period, adjust=False, min_periods=1).mean()


def calc_t3(series: pd.Series, period: int = 8, volume_factor: float = 0.7) -> pd.Series:
    """Tillson T3: 단타 노이즈를 줄이면서 추세 전환을 빠르게 보여주는 부드러운 추세선."""
    s = series.astype(float)
    e1 = s.ewm(span=period, adjust=False, min_periods=1).mean()
    e2 = e1.ewm(span=period, adjust=False, min_periods=1).mean()
    e3 = e2.ewm(span=period, adjust=False, min_periods=1).mean()
    e4 = e3.ewm(span=period, adjust=False, min_periods=1).mean()
    e5 = e4.ewm(span=period, adjust=False, min_periods=1).mean()
    e6 = e5.ewm(span=period, adjust=False, min_periods=1).mean()
    a = float(volume_factor)
    c1 = -a ** 3
    c2 = 3 * a ** 2 + 3 * a ** 3
    c3 = -6 * a ** 2 - 3 * a - 3 * a ** 3
    c4 = 1 + 3 * a + a ** 3 + 3 * a ** 2
    return c1 * e6 + c2 * e5 + c3 * e4 + c4 * e3


def calc_chandelier_exit(df: pd.DataFrame, atr: pd.Series, period: int = 22, mult: float = 3.0) -> Tuple[pd.Series, pd.Series]:
    """Chandelier Exit: 보유자는 추세 스탑, 신규자는 추격 금지/손절 기준으로 사용."""
    high = df["High"].astype(float)
    low = df["Low"].astype(float)
    atr = atr.astype(float)
    long_stop = high.rolling(period, min_periods=1).max() - atr * mult
    short_stop = low.rolling(period, min_periods=1).min() + atr * mult
    return long_stop, short_stop


def calc_cpr_levels(df: pd.DataFrame) -> Dict[str, float]:
    """Central Pivot Range: 데이트레이더가 많이 쓰는 중심가/가치영역."""
    try:
        if len(df) < 2:
            row = df.iloc[-1]
        else:
            row = df.iloc[-2]
        h, l, c = float(row["High"]), float(row["Low"]), float(row["Close"])
        pivot = (h + l + c) / 3.0
        bc = (h + l) / 2.0
        tc = pivot * 2.0 - bc
        if tc < bc:
            tc, bc = bc, tc
        return {"CPR_TC": tc, "CPR_P": pivot, "CPR_BC": bc}
    except Exception:
        return {}


def add_latest_price_overlays(fig, df: pd.DataFrame, ind: Dict, show_cpr: bool = True, show_chandelier: bool = True, show_zlema: bool = True, price_label_items: Optional[List[Dict]] = None):
    """메인 가격 차트에 최신 실전 오버레이(ZLEMA/T3/VWMA, Chandelier, CPR)를 일괄 추가."""
    try:
        if show_zlema:
            for nm, key, col, wd, dash in [
                ("ZLEMA34", "zlema34", "#00e5ff", 1.55, "solid"),
                ("T3-8", "t3_8", "#ff5ec4", 1.45, "dot"),
                ("VWMA20", "vwma20", "#ffd166", 1.25, "dash"),
            ]:
                if key in ind:
                    fig.add_trace(go.Scatter(x=df.index, y=ind[key], mode="lines", name=nm,
                                             line=dict(color=col, width=wd, dash=dash), showlegend=False,
                                             hovertemplate=f"<b>{nm}</b> %{{y:,.0f}}<extra></extra>"), row=1, col=1)
        if show_chandelier and "ch_long" in ind and "ch_short" in ind:
            close = ind.get("close", df["Close"]).astype(float)
            ch_long = ind["ch_long"].where(close >= ind["ch_long"])
            ch_short = ind["ch_short"].where(close <= ind["ch_short"])
            fig.add_trace(go.Scatter(x=df.index, y=ch_long, mode="lines", name="Chandelier Long Stop",
                                     line=dict(color="rgba(0,212,168,0.80)", width=1.55, dash="dashdot"), showlegend=False,
                                     hovertemplate="<b>추세 스탑</b> %{y:,.0f}<extra></extra>"), row=1, col=1)
            fig.add_trace(go.Scatter(x=df.index, y=ch_short, mode="lines", name="Chandelier Short Stop",
                                     line=dict(color="rgba(255,77,109,0.80)", width=1.55, dash="dashdot"), showlegend=False,
                                     hovertemplate="<b>하락 스탑</b> %{y:,.0f}<extra></extra>"), row=1, col=1)
            try:
                last_close = float(close.iloc[-1]); stop = float(ind["ch_long"].iloc[-1] if last_close >= float(ind["ch_long"].iloc[-1]) else ind["ch_short"].iloc[-1])
                hover_text_atr = build_financial_tooltip_text("ATR 스탑", stop, last_close)
                # [CHART_TITLE_SEARCH: 메인 차트] 아래 [BOXPOS_050] 박스/풍선 위치 코드입니다. 이 차트 제목으로 검색하면 바로 찾을 수 있습니다.
                # [BOXPOS_050_MAIN_add_latest_price_overlays] 메인 최신 오버레이: Chandelier ATR 스탑 풍선 | 위치수정: x/y(기준좌표), ax/ay(화살표 박스 픽셀오프셋), xshift/yshift, xanchor/yanchor를 조정. xref/yref="paper"는 0~1 화면비율, xref/yref="x/y"는 날짜·가격/지표값입니다.
                # v16.4: ATR 스탑도 price_label_items로 통합하여 겹치지 않게 정렬 (기존 ax=295는 오른쪽 rail과 겹침 원인)
                if isinstance(price_label_items, list):
                    price_label_items.append({"y": float(stop), "text": f"ATR 스탑 {stop:,.0f}",
                                              "color": "#5b8ef4", "text_color": "#f8fafc", "bgcolor": "rgba(245,158,11,0.96)",
                                              "font_size": 10, "border_width": 0.8, "priority": 2, "label_prefix": "◀ "})
                else:
                    fig.add_annotation(x=df.index[-1], y=stop, xref="x", yref="y",
                                       text=f"<b>🛡 ATR 스탑</b><br>{stop:,.0f}", showarrow=True, arrowhead=2, ax=48, ay=0,
                                       font=dict(size=10, color="#f8fafc", family=FONT_MONO), bgcolor="rgba(245,158,11,0.96)",
                                       bordercolor="#5b8ef4", borderwidth=0.8, borderpad=1,
                                       hovertext=hover_text_atr,
                                       hoverlabel=dict(bgcolor="rgba(13,22,40,0.96)", bordercolor="#5b8ef4", font=dict(color="#ffffff", family=FONT_MONO)),
                                       row=1, col=1)
            except Exception:
                pass
        if show_cpr:
            cpr = ind.get("cpr_levels") or calc_cpr_levels(df)
            for key, label, color, dash in [
                ("CPR_TC", "CPR 상단", "rgba(255,209,102,0.60)", "dot"),
                ("CPR_P", "CPR 중심", "rgba(255,209,102,0.90)", "solid"),
                ("CPR_BC", "CPR 하단", "rgba(255,209,102,0.60)", "dot"),
            ]:
                val = cpr.get(key, np.nan) if isinstance(cpr, dict) else np.nan
                if np.isfinite(val):
                    fig.add_hline(y=float(val), line_color=color, line_width=(1.45 if key == "CPR_P" else 0.95), line_dash=dash, row=1, col=1)
                    # [CHART_TITLE_SEARCH: 메인 차트] 아래 [BOXPOS_051] 박스/풍선 위치 코드입니다. 이 차트 제목으로 검색하면 바로 찾을 수 있습니다.
                    # [BOXPOS_051_MAIN_add_latest_price_overlays] 메인 최신 오버레이: CPR 가격 라벨 | 위치수정: x/y(기준좌표), ax/ay(화살표 박스 픽셀오프셋), xshift/yshift, xanchor/yanchor를 조정. xref/yref="paper"는 0~1 화면비율, xref/yref="x/y"는 날짜·가격/지표값입니다.
                    if isinstance(price_label_items, list):
                        price_label_items.append({"y": float(val), "text": f"{label} {float(val):,.0f}",
                                                  "color": color, "text_color": "#1a1a1a", "bgcolor": "rgba(255,232,160,0.94)",
                                                  "font_size": 10, "border_width": 1, "priority": 2, "label_prefix": "◀ "})
                    else:
                        fig.add_annotation(x=0.998, xref="paper", y=float(val), yref="y", text=f"{label} {float(val):,.0f}",
                                           showarrow=False, xanchor="right", yanchor="middle",
                                           font=dict(size=10, color="#1a1a1a", family=FONT_MONO), bgcolor="rgba(255,232,160,0.94)",
                                           bordercolor="rgba(255,209,102,0.85)", borderwidth=1, borderpad=2)
    except Exception:
        pass
    return fig

# =============================================================================
# [ADVANCED PREDICTION UPGRADE v2] — 예측율/적중율 향상을 위한 신규 지표/로직
# =============================================================================

def calc_fisher_transform(close: pd.Series, period: int = 10) -> Tuple[pd.Series, pd.Series]:
    """Fisher Transform: 과매수/과매도를 극단적으로 선명하게 뽑아내어 변곡점 적중율 향상.
    반환: (fisher, signal)
    """
    try:
        c = close.astype(float)
        median = (c.rolling(period).max() + c.rolling(period).min()) / 2.0
        # Value를 -0.999~0.999로 정규화
        raw = pd.Series(0.0, index=c.index)
        high = c.rolling(period).max()
        low = c.rolling(period).min()
        denom = (high - low).replace(0, np.nan)
        value = ((c - low) / denom - 0.5) * 2.0
        value = value.clip(-0.999, 0.999)
        # Fisher 재귀 공식
        fisher = pd.Series(0.0, index=c.index)
        for i in range(1, len(c)):
            try:
                prev = fisher.iloc[i-1]
                curr_val = value.iloc[i]
                if pd.isna(curr_val): 
                    fisher.iloc[i] = prev
                    continue
                fisher.iloc[i] = 0.5 * np.log((1 + curr_val) / (1 - curr_val + 1e-9)) + 0.5 * prev
            except Exception:
                fisher.iloc[i] = fisher.iloc[i-1]
        fisher = fisher.fillna(0)
        signal = fisher.ewm(span=3, adjust=False).mean()
        return fisher, signal
    except Exception:
        z = pd.Series(0.0, index=close.index)
        return z, z

def calc_kama(close: pd.Series, er_period: int = 10, fast: int = 2, slow: int = 30) -> pd.Series:
    """Kaufman Adaptive Moving Average: 효율성 비율(ER)로 변동성 적응 -> 횡보장 필터, 추세장 적중율↑"""
    try:
        c = close.astype(float)
        # Efficiency Ratio
        change = (c - c.shift(er_period)).abs()
        volatility = c.diff().abs().rolling(er_period).sum()
        er = (change / volatility.replace(0, np.nan)).fillna(0)
        fast_sc = 2 / (fast + 1)
        slow_sc = 2 / (slow + 1)
        sc = (er * (fast_sc - slow_sc) + slow_sc) ** 2
        kama = pd.Series(c.iloc[0], index=c.index, dtype=float)
        for i in range(1, len(c)):
            kama.iloc[i] = kama.iloc[i-1] + sc.iloc[i] * (c.iloc[i] - kama.iloc[i-1]) if not pd.isna(sc.iloc[i]) else kama.iloc[i-1]
        return kama.fillna(method='ffill').fillna(c)
    except Exception:
        return close.ewm(span=21, adjust=False).mean()

def calc_choppiness_index(df: pd.DataFrame, period: int = 14) -> pd.Series:
    """CHOP Index: 0~100, >61.8 횡보, <38.2 추세. 추세/횡보 레짐 판정 정확도 향상"""
    try:
        high = df["High"].astype(float)
        low = df["Low"].astype(float)
        close = df["Close"].astype(float)
        atr = (high - low).rolling(1).sum()  # TrueRange 간소화: high-low
        # 실제 TR
        tr1 = high - low
        tr2 = (high - close.shift()).abs()
        tr3 = (low - close.shift()).abs()
        tr = pd.concat([tr1, tr2, tr3], axis=1).max(axis=1)
        atr_sum = tr.rolling(period).sum()
        high_period = high.rolling(period).max()
        low_period = low.rolling(period).min()
        range_sum = high_period - low_period
        chop = 100 * np.log10((atr_sum / range_sum.replace(0, np.nan)).replace(0, np.nan)) / np.log10(period)
        return chop.fillna(50.0).clip(0, 100)
    except Exception:
        return pd.Series(50.0, index=df.index)

def calc_efficiency_ratio(close: pd.Series, period: int = 10) -> pd.Series:
    """Efficiency Ratio: 추세 강도를 0~1로. 0.5 이상 강추세, 0.3 이하 약추세."""
    try:
        c = close.astype(float)
        change = (c - c.shift(period)).abs()
        vol = c.diff().abs().rolling(period).sum()
        er = (change / vol.replace(0, np.nan)).fillna(0).clip(0,1)
        return er
    except Exception:
        return pd.Series(0.5, index=close.index)

def calc_connors_rsi(close: pd.Series, rsi_period: int = 3, streak_period: int = 2, pct_rank_period: int = 100) -> pd.Series:
    """Connors RSI: 단기 과매수/과매도 적중율 개선 (0~100, 90이상 과매수, 10이하 과매도)"""
    try:
        c = close.astype(float)
        rsi = calc_rsi_wilder(c, rsi_period)
        # Streak
        diff = c.diff()
        streak = pd.Series(0, index=c.index, dtype=float)
        cur = 0
        for i in range(1, len(c)):
            if diff.iloc[i] > 0:
                cur = cur + 1 if cur >=0 else 1
            elif diff.iloc[i] < 0:
                cur = cur - 1 if cur <=0 else -1
            else:
                cur = 0
            streak.iloc[i] = cur
        streak_rsi = calc_rsi_wilder(streak, streak_period)
        # Percent rank of price change
        roc = c.pct_change()
        def rolling_percent_rank(s):
            try:
                return pd.Series(s).rank(pct=True).iloc[-1]*100
            except:
                return 50.0
        pct_rank = roc.rolling(pct_rank_period).apply(lambda x: pd.Series(x).rank(pct=True).iloc[-1]*100 if len(x) else 50.0, raw=False)
        connors = (rsi + streak_rsi + pct_rank) / 3.0
        return connors.fillna(50.0)
    except Exception:
        return pd.Series(50.0, index=close.index)

def calc_vwap_bands(df: pd.DataFrame, vwap: pd.Series, mult: float = 1.0) -> Tuple[pd.Series, pd.Series]:
    """VWAP Bands: VWAP ± ATR*mult로 지지/저항 동적 밴드."""
    try:
        close = df["Close"].astype(float)
        atr = calc_atr_wilder(df, 14)
        upper = vwap + atr * mult
        lower = vwap - atr * mult
        return upper, lower
    except Exception:
        return vwap, vwap

def calc_liquidity_sweep_detector(df: pd.DataFrame, lookback: int = 20) -> pd.DataFrame:
    """유동성 스윕(Stop Hunt) 탐지: 전고/전저 스윕 후 즉시 반전 -> 적중율 높은 단기 반전 신호"""
    try:
        high = df["High"].astype(float)
        low = df["Low"].astype(float)
        close = df["Close"].astype(float)
        vol = df["Volume"].astype(float).fillna(0)
        vol_ma = vol.rolling(20).mean()
        sweeps = []
        for i in range(lookback, len(df)):
            curr_high = high.iloc[i]
            curr_low = low.iloc[i]
            prev_high_max = high.iloc[i-lookback:i].max()
            prev_low_min = low.iloc[i-lookback:i].min()
            # Bearish Sweep: 고점 돌파 후 즉시 하락 마감 + 거래량 증가
            is_bear_sweep = (curr_high > prev_high_max * 1.001) and (close.iloc[i] < high.iloc[i] - (high.iloc[i]-low.iloc[i])*0.6) and (vol.iloc[i] > vol_ma.iloc[i]*1.3)
            is_bull_sweep = (curr_low < prev_low_min * 0.999) and (close.iloc[i] > low.iloc[i] + (high.iloc[i]-low.iloc[i])*0.6) and (vol.iloc[i] > vol_ma.iloc[i]*1.3)
            if is_bear_sweep:
                sweeps.append((df.index[i], 'bear_sweep', curr_high))
            elif is_bull_sweep:
                sweeps.append((df.index[i], 'bull_sweep', curr_low))
        return pd.DataFrame(sweeps, columns=["date","type","price"]) if sweeps else pd.DataFrame(columns=["date","type","price"])
    except Exception:
        return pd.DataFrame(columns=["date","type","price"])

def calc_order_block_fvg_advanced(df: pd.DataFrame, lookback: int = 120) -> Dict:
    """고도화된 Order Block + Fair Value Gap 탐지: 적중율 65%+ 설계
    FVG: 3캔들 중 중간 캔들이 겹치지 않는 불균형 구간 -> 가격 메우기 확률 높음
    OrderBlock: 강한 충격 이전 마지막 반대 캔들
    """
    try:
        sub = df.tail(min(len(df), lookback)).copy()
        if len(sub) < 10:
            return {"fvg_bull": [], "fvg_bear": [], "ob_bull": [], "ob_bear": []}
        fvg_bull = []
        fvg_bear = []
        ob_bull = []
        ob_bear = []
        high = sub["High"].astype(float)
        low = sub["Low"].astype(float)
        close = sub["Close"].astype(float)
        open_ = sub["Open"].astype(float)
        for i in range(1, len(sub)-1):
            # Bullish FVG: low[i+1] > high[i-1] (상승 불균형)
            if low.iloc[i+1] > high.iloc[i-1]:
                fvg_bull.append({"x0": sub.index[i-1], "x1": sub.index[i+1], "y0": high.iloc[i-1], "y1": low.iloc[i+1], "mid": (high.iloc[i-1]+low.iloc[i+1])/2})
            # Bearish FVG: high[i+1] < low[i-1]
            if high.iloc[i+1] < low.iloc[i-1]:
                fvg_bear.append({"x0": sub.index[i-1], "x1": sub.index[i+1], "y0": low.iloc[i-1], "y1": high.iloc[i-1], "mid": (low.iloc[i-1]+high.iloc[i+1])/2 if False else (low.iloc[i-1]+high.iloc[i+1])/2})
            # Order Block: 강한 상승 직전 마지막 음봉
            if close.iloc[i+1] > high.iloc[i-1] * 1.01 and open_.iloc[i] > close.iloc[i]:
                # i is bearish before impulse
                ob_bull.append({"x": sub.index[i], "y0": low.iloc[i], "y1": high.iloc[i], "type": "bull_ob"})
            if close.iloc[i+1] < low.iloc[i-1] * 0.99 and open_.iloc[i] < close.iloc[i]:
                ob_bear.append({"x": sub.index[i], "y0": low.iloc[i], "y1": high.iloc[i], "type": "bear_ob"})
        return {"fvg_bull": fvg_bull[-6:], "fvg_bear": fvg_bear[-6:], "ob_bull": ob_bull[-6:], "ob_bear": ob_bear[-6:]}
    except Exception:
        return {"fvg_bull": [], "fvg_bear": [], "ob_bull": [], "ob_bear": []}

def calc_bayesian_confluence_score(modules: Dict[str, float], hit_rates: Dict[str, float], regime: str) -> Dict:
    """베이지안 가중 컨플루언스: 과거 적중율로 가중치 동적 조정 + 레짐별 보정
    modules: {"momentum": 70, "volume": ...}
    hit_rates: {"momentum": 0.62, ...} 과거 적중율
    regime: 추세장/박스권 등
    반환: {"score": 0~100, "prob": 0~1, "weights": {...}}
    """
    try:
        base_weights = {
            "momentum": 0.20, "volume": 0.15, "timing": 0.18, "quality": 0.08, "value": 0.07, "fib": 0.12,
            "fisher": 0.07, "kama": 0.05, "chop": 0.04, "connors": 0.04
        }
        # 레짐별 가중치 보정
        regime_adj = {
            "추세장": {"momentum": 1.3, "kama": 1.4, "chop": 0.6, "timing": 1.2},
            "고변동 추세": {"momentum": 1.2, "volume": 1.3, "fisher": 1.2},
            "박스권": {"connors": 1.5, "fisher": 1.3, "timing": 1.4, "momentum": 0.7},
            "박스권(스퀴즈)": {"squeeze": 1.5, "chop": 1.4},
        }
        adj = regime_adj.get(regime, {})
        adjusted_weights = {}
        for k, w in base_weights.items():
            # hit_rate로 베이지안 보정: 0.5 기준, 0.6이면 1.2배, 0.4면 0.8배
            hr = hit_rates.get(k, 0.52)
            hr_mult = 0.6 + hr  # 0.5->1.1, 0.6->1.2, 0.4->1.0
            reg_mult = adj.get(k, 1.0)
            adjusted_weights[k] = w * hr_mult * reg_mult

        # 정규화
        total = sum(adjusted_weights.values())
        if total > 0:
            for k in adjusted_weights:
                adjusted_weights[k] /= total

        score = 0.0
        prob = 0.0
        for k, v in modules.items():
            w = adjusted_weights.get(k, 0.08)
            score += float(v) * w
            prob += (float(v)/100.0) * w

        # 신뢰구간: 분산이 작으면 좁음, 크면 넓음
        vals = list(modules.values())
        variance = float(np.var(vals)) if len(vals)>1 else 100.0
        se = np.sqrt(variance) / 20.0
        ci_low = max(0.0, prob - se*1.2)
        ci_high = min(1.0, prob + se*1.2)

        return {"score": float(np.clip(score,0,100)), "prob": float(np.clip(prob,0,1)), "prob_percent": round(float(prob*100),1),
                "ci_low": ci_low, "ci_high": ci_high, "weights": adjusted_weights, "regime": regime}
    except Exception as e:
        return {"score": 50.0, "prob": 0.5, "prob_percent": 50.0, "ci_low":0.35, "ci_high":0.65, "weights":{}, "regime":regime, "error":str(e)}

@st.cache_data(show_spinner=False, ttl=1800)  # [P1] 순수연산 캐시 — 결과 dict/df는 picklable, TTL 내 재호출 시 재계산 생략
def compute_indicators_upgraded(df: pd.DataFrame) -> Dict:
    """업그레이드된 통합 지표 계산기.

    v23 차트팩: EMA21/50/200, HMA55, Keltner, Donchian, PSAR, MFI,
    StochRSI, Anchored VWAP까지 한 번에 계산해 중복 계산을 줄입니다.
    """
    close = df["Close"].astype(float)
    vol = df["Volume"].astype(float).fillna(0)

    ma20 = close.rolling(20, min_periods=1).mean()
    ma60 = close.rolling(60, min_periods=1).mean()
    ma120 = close.rolling(120, min_periods=1).mean()
    ema9 = close.ewm(span=9, adjust=False, min_periods=1).mean()
    ema21 = close.ewm(span=21, adjust=False, min_periods=1).mean()
    ema50 = close.ewm(span=50, adjust=False, min_periods=1).mean()
    ema200 = close.ewm(span=200, adjust=False, min_periods=1).mean()
    hma55 = calc_hma(close, 55)

    atr = calc_atr_wilder(df, 14)
    rsi = calc_rsi_wilder(close, 14)
    macd, signal, hist = calc_macd(close)
    bb_mid, bb_upper, bb_lower, bb_width, pct_b = calc_bbands(close)
    kc_mid, kc_upper, kc_lower = calc_keltner_channel(df, 20, 1.5)
    dc_high, dc_low, dc_mid = calc_donchian_channel(df, 20)
    vwap = calc_vwap(df)
    avwap = calc_anchored_vwap(df, 120)
    vwma20 = calc_vwma(df, 20)
    vwma60 = calc_vwma(df, 60)
    zlema34 = calc_zlema(close, 34)
    t3_8 = calc_t3(close, 8, 0.7)
    obv = calc_obv(df)
    mfi = calc_mfi(df, 14)
    stoch_k, stoch_d = calc_stoch_rsi(rsi, 14, 3, 3)
    psar = calc_psar(df)

    adx, plus_di, minus_di = calc_adx_wilder(df, 14)
    ch_long, ch_short = calc_chandelier_exit(df, atr, 22, 3.0)
    cpr_levels = calc_cpr_levels(df)

    vol20 = vol.rolling(20, min_periods=1).mean()
    vol50 = vol.rolling(50, min_periods=1).mean()
    zeros = pd.Series(0.0, index=df.index)

    supertrend, trend_dir = calc_supertrend(df, period=10, multiplier=3.0)
    sqz_val, sqz_on, _ = calc_squeeze_momentum(df, bb_period=20, bb_mult=2.0, kc_period=20, kc_mult=1.5)

    # ── [ADVANCED UPGRADE v2] 신규 지표 — 예측율/적중율 향상용
    try:
        fisher, fisher_signal = calc_fisher_transform(close, 10)
    except Exception:
        fisher, fisher_signal = pd.Series(0.0, index=df.index), pd.Series(0.0, index=df.index)
    try:
        kama = calc_kama(close, 10, 2, 30)
    except Exception:
        kama = close.ewm(span=21, adjust=False).mean()
    try:
        chop = calc_choppiness_index(df, 14)
    except Exception:
        chop = pd.Series(50.0, index=df.index)
    try:
        er = calc_efficiency_ratio(close, 10)
    except Exception:
        er = pd.Series(0.5, index=df.index)
    try:
        connors_rsi = calc_connors_rsi(close, 3, 2, 100)
    except Exception:
        connors_rsi = pd.Series(50.0, index=df.index)
    try:
        vwap_upper, vwap_lower = calc_vwap_bands(df, vwap, 1.0)
    except Exception:
        vwap_upper, vwap_lower = vwap, vwap
    try:
        liquidity_sweeps = calc_liquidity_sweep_detector(df, 20)
    except Exception:
        liquidity_sweeps = pd.DataFrame(columns=["date","type","price"])
    try:
        smc_fvg_ob = calc_order_block_fvg_advanced(df, 120)
    except Exception:
        smc_fvg_ob = {"fvg_bull": [], "fvg_bear": [], "ob_bull": [], "ob_bear": []}

    # ── [ADVANCED v3] 퀀트 랩 신규 지표
    try:
        cvd = calc_cvd(df)
    except Exception:
        cvd = pd.Series(0.0, index=df.index)
    try:
        of_imb = calc_order_flow_imbalance(df, 20)
    except Exception:
        of_imb = pd.Series(1.0, index=df.index)
    try:
        pd_zones = calc_premium_discount_zones(df, 120)
    except Exception:
        pd_zones = {"high": np.nan, "low": np.nan, "mid": np.nan, "range": np.nan}
    try:
        eqh_eql = calc_equal_highs_lows(df, 0.0015, 80)
    except Exception:
        eqh_eql = {"eqh": [], "eql": []}
    try:
        breaker_blocks = calc_breaker_blocks(df, 100)
    except Exception:
        breaker_blocks = {"breakers": []}
    try:
        hurst = calc_hurst_exponent(close, 100)
    except Exception:
        hurst = 0.5
    try:
        kalman_trend, kalman_vel = calc_kalman_trend(close)
    except Exception:
        kalman_trend, kalman_vel = close, pd.Series(0, index=df.index)

    return {
        "close": close, "vol": vol, "ma20": ma20, "ma60": ma60, "ma120": ma120,
        "ema9": ema9, "ema21": ema21, "ema50": ema50, "ema200": ema200, "hma55": hma55,
        "atr": atr, "rsi": rsi, "macd": macd, "signal": signal, "hist": hist,
        "bb_mid": bb_mid, "bb_upper": bb_upper, "bb_lower": bb_lower, "bb_width": bb_width, "pct_b": pct_b,
        "kc_mid": kc_mid, "kc_upper": kc_upper, "kc_lower": kc_lower,
        "dc_high": dc_high, "dc_low": dc_low, "dc_mid": dc_mid,
        "vwap": vwap, "avwap": avwap, "vwma20": vwma20, "vwma60": vwma60, "zlema34": zlema34, "t3_8": t3_8,
        "ch_long": ch_long, "ch_short": ch_short, "cpr_levels": cpr_levels,
        "obv": obv, "mfi": mfi, "stoch_k": stoch_k, "stoch_d": stoch_d,
        "vol20": vol20, "vol50": vol50, "vol_ratio": vol / (vol20 + 1e-9),
        "adx": adx, "plus_di": plus_di, "minus_di": minus_di,
        "foreign_net": zeros.copy(), "institution_net": zeros.copy(), "individual_net": zeros.copy(),
        "supertrend": supertrend, "trend_dir": trend_dir,
        "sqz_val": sqz_val, "sqz_on": sqz_on, "psar": psar,
        # ── Advanced v2 ──
        "fisher": fisher, "fisher_signal": fisher_signal,
        "kama": kama, "chop": chop, "er": er, "connors_rsi": connors_rsi,
        "vwap_upper": vwap_upper, "vwap_lower": vwap_lower,
        "liquidity_sweeps": liquidity_sweeps, "smc_fvg_ob": smc_fvg_ob,
        # ── Advanced v3 ──
        "cvd": cvd, "of_imbalance": of_imb, "pd_zones": pd_zones, "eqh_eql": eqh_eql,
        "breaker_blocks": breaker_blocks, "hurst": hurst, "kalman_trend": kalman_trend, "kalman_vel": kalman_vel,
    }


# ═══════════════════════════════════════════════════════════════
# ELITE MASTER — Smart Money Concepts & VSA
# ═══════════════════════════════════════════════════════════════


"""
🦅 ELITE TRADER MASTER - 스마트머니 콘셉트(SMC), 와이코프, VSA 통합 분석 엔진
"""

def detect_smc_and_vsa(df, lookback=100):
    """
    세력의 흔적(Order Block, CHoCH, BOS)과 VSA(거래량 스프레드 분석)를 찾아냅니다.
    """
    sub = df.tail(min(len(df), lookback)).copy()
    if len(sub) < 20:
        return {'signals': [], 'lines': [], 'zones': []}

    signals = []  # 매수/매도 마커 (Selling Climax, Spring 등)
    lines = []    # 구조 파괴 선 (CHoCH, BOS)
    zones = []    # 오더블록(세력 매집/분배 구간)

    # 1. VSA (Volume Spread Analysis) - 와이코프 패턴 기반 매수/매도 타점
    vol_ma = sub['Volume'].rolling(20).mean()

    for i in range(20, len(sub)):
        idx = sub.index[i]
        vol = sub['Volume'].iloc[i]
        v_ma = vol_ma.iloc[i]
        o, h, l, c = sub['Open'].iloc[i], sub['High'].iloc[i], sub['Low'].iloc[i], sub['Close'].iloc[i]
        spread = h - l

        # 조건 1: Selling Climax (투매 절정 - 세력의 매집 시작점)
        if vol > v_ma * 2.0 and c > l + spread * 0.5 and o > l + spread * 0.5:
            if sub['Close'].iloc[i] < sub['Close'].iloc[i - 5]:
                signals.append({'date': idx, 'price': l, 'type': 'buy', 'label': '투매절정(SC)', 'color': '#00d4a8', 'desc': '개인의 투매를 세력이 받아낸 매집 신호'})

        # 조건 2: Buying Climax (매수 절정 - 세력의 차익 실현)
        elif vol > v_ma * 2.0 and c < h - spread * 0.5 and o < h - spread * 0.5:
            if sub['Close'].iloc[i] > sub['Close'].iloc[i - 5]:
                signals.append({'date': idx, 'price': h, 'type': 'sell', 'label': '매수절정(BC)', 'color': '#ff4d6d', 'desc': '개인의 추격 매수에 세력이 물량을 떠넘긴 신호'})

        # 조건 3: Spring / Upthrust (속임수 트랩)
        prev_lows = sub['Low'].iloc[i - 10:i].min()
        if l < prev_lows and c > prev_lows and vol > v_ma * 1.2:
            signals.append({'date': idx, 'price': l, 'type': 'buy', 'label': '스프링(Trap)', 'color': '#f59e0b', 'desc': '전저점을 깨서 개인 손절을 유도한 뒤 말아올린 초강력 매수 타점'})

    # 2. SMC (Smart Money Concepts) - 시장 구조 파괴 (CHoCH, BOS) 및 오더블록
    highs = []
    lows = []
    for i in range(5, len(sub) - 5):
        if sub['High'].iloc[i] == sub['High'].iloc[i - 5:i + 6].max():
            highs.append((sub.index[i], sub['High'].iloc[i], i))
        if sub['Low'].iloc[i] == sub['Low'].iloc[i - 5:i + 6].min():
            lows.append((sub.index[i], sub['Low'].iloc[i], i))

    # 강세장 전환 (Bullish CHoCH) & 오더블록 식별
    if len(highs) >= 2 and len(lows) >= 2:
        last_high = highs[-1]
        last_low = lows[-1]
        current_close = sub['Close'].iloc[-1]

        # 하락하던 중 이전 고점을 돌파 (CHoCH)
        if current_close > last_high[1]:
            lines.append({'x0': last_high[0], 'y0': last_high[1], 'x1': sub.index[-1], 'y1': last_high[1], 'label': '강세 전환 (CHoCH)', 'color': '#22d3ee'})

            ob_start_idx = last_low[2] - 3
            ob_end_idx = last_low[2]
            if ob_start_idx >= 0:
                ob_high = sub['High'].iloc[ob_start_idx:ob_end_idx + 1].max()
                ob_low = sub['Low'].iloc[ob_start_idx:ob_end_idx + 1].min()
                zones.append({'x0': sub.index[ob_start_idx], 'x1': sub.index[-1], 'y0': ob_low, 'y1': ob_high, 'color': 'rgba(0, 212, 168, 0.08)', 'label': '강세 오더블록 (매수 타점)'})

        # 상승하던 중 이전 저점을 붕괴 (Bearish CHoCH)
        elif current_close < last_low[1]:
            lines.append({'x0': last_low[0], 'y0': last_low[1], 'x1': sub.index[-1], 'y1': last_low[1], 'label': '약세 전환 (CHoCH)', 'color': '#ff4d6d'})

            ob_start_idx = last_high[2] - 3
            ob_end_idx = last_high[2]
            if ob_start_idx >= 0:
                ob_high = sub['High'].iloc[ob_start_idx:ob_end_idx + 1].max()
                ob_low = sub['Low'].iloc[ob_start_idx:ob_end_idx + 1].min()
                zones.append({'x0': sub.index[ob_start_idx], 'x1': sub.index[-1], 'y0': ob_low, 'y1': ob_high, 'color': 'rgba(255, 77, 109, 0.08)', 'label': '약세 오더블록 (매도 타점)'})

    return {'signals': signals, 'lines': lines, 'zones': zones}


# ═══════════════════════════════════════════════════════════════
# ELLIOTT WAVE MASTER — Fractal multi-cycle analysis
# ═══════════════════════════════════════════════════════════════


"""
🌊 ELLIOTT WAVE MASTER - 엘리어트 파동 심층 분석 엔진
   (프랙탈 멀티 사이클 & 지정 기간 완벽 지원본)
"""


# 스샷과 동일한 색상 테마 적용
COLOR_MAJOR_UP = 'rgba(255, 60, 60, 0.85)'   # 굵은 빨간선 (상위 상승파동)
COLOR_MAJOR_DN = 'rgba(60, 130, 255, 0.85)'  # 굵은 파란선 (상위 하락/조정파동)
COLOR_MINOR = 'rgba(200, 200, 200, 0.95)'    # 얇은 흰/회색선 (하위 파동)
COLOR_OVAL = 'rgba(255, 182, 193, 0.25)'     # 핑크색 조정구간 하이라이트

FIB_KEY_RATIOS = [0.236, 0.382, 0.500, 0.618, 0.764, 0.786, 0.854, 1.000, 1.272, 1.618, 2.618]

def get_elliott_pivots(df, is_kr, calc_atr, build_pivot_candidates, filter_pivots_for_krx, lookback=260):
    sub = df.copy()  # lookback 제한 없이 전체 기간 사용
    if len(sub) < 30:
        return []
    pivots = build_pivot_candidates(sub, orders=(5, 8, 13, 21))
    pivots = filter_pivots_for_krx(sub, pivots, is_kr=is_kr)
    for p in pivots:
        p['date'] = sub.index[p['idx']]
    return pivots

def force_fit_5_waves(sub_df, start_idx, end_idx, is_up):
    """지정된 구간 내에서 강제로 1,2,3,4,5 하위 파동 구조를 추출합니다."""
    chunk = sub_df.loc[start_idx:end_idx]
    if len(chunk) < 6:
        return []

    pts = [{'date': start_idx, 'price': chunk.loc[start_idx, 'Low' if is_up else 'High'], 'label': '0'}]
    times = chunk.index.tolist()
    step = len(times) // 5

    for i in range(1, 5):
        slice_idx = times[i * step: (i + 1) * step]
        if not slice_idx:
            slice_idx = [times[i * step - 1]]

        if (i % 2 == 1):  # 1, 3파 (추세방향)
            best_idx = chunk.loc[slice_idx, 'High' if is_up else 'Low'].idxmax() if is_up else chunk.loc[slice_idx, 'Low'].idxmin()
            pts.append({'date': best_idx, 'price': chunk.loc[best_idx, 'High' if is_up else 'Low'], 'label': str(i)})
        else:  # 2, 4파 (조정방향)
            best_idx = chunk.loc[slice_idx, 'Low' if is_up else 'High'].idxmin() if is_up else chunk.loc[slice_idx, 'High'].idxmax()
            pts.append({'date': best_idx, 'price': chunk.loc[best_idx, 'Low' if is_up else 'High'], 'label': str(i)})

    pts.append({'date': end_idx, 'price': chunk.loc[end_idx, 'High' if is_up else 'Low'], 'label': '5'})
    return pts

def force_fit_3_waves(sub_df, start_idx, end_idx, is_up):
    """지정된 구간 내에서 강제로 A, B, C 하위 파동 구조를 추출합니다."""
    chunk = sub_df.loc[start_idx:end_idx]
    if len(chunk) < 4:
        return []

    pts = [{'date': start_idx, 'price': chunk.loc[start_idx, 'High' if not is_up else 'Low'], 'label': '0'}]
    times = chunk.index.tolist()
    step = len(times) // 3

    # A파
    slice_a = times[step:step * 2]
    if not slice_a:
        slice_a = [times[step - 1]]
    best_a = chunk.loc[slice_a, 'Low' if not is_up else 'High'].idxmin() if not is_up else chunk.loc[slice_a, 'High'].idxmax()
    pts.append({'date': best_a, 'price': chunk.loc[best_a, 'Low' if not is_up else 'High'], 'label': 'A'})

    # B파 (트랩)
    slice_b = times[step * 2:-1]
    if not slice_b:
        slice_b = [times[-2]]
    best_b = chunk.loc[slice_b, 'High' if not is_up else 'Low'].idxmax() if not is_up else chunk.loc[slice_b, 'Low'].idxmin()
    pts.append({'date': best_b, 'price': chunk.loc[best_b, 'High' if not is_up else 'Low'], 'label': 'B'})

    # C파
    pts.append({'date': end_idx, 'price': chunk.loc[end_idx, 'Low' if not is_up else 'High'], 'label': 'C'})
    return pts

def extract_multi_cycles(df, pivots):
    """
    [핵심 로직] 전체 기간의 상위/하위 파동을 반복(135ABC-135ABC...)하여 분해합니다.
    [패치] 마지막 파동이 차트 끝부분(최근)까지 도달하지 못하는 문제 해결.
    """
    cycles = []
    if len(pivots) < 2:
        return cycles

    # 상위 파동(Major Waves)을 찾기 위해 큰 피벗만 추림
    major_pivots = [pivots[0]]
    for p in pivots[1:]:
        if p['score'] > 50:  # 신뢰도 높은 굵직한 피벗만 선택
            if major_pivots[-1]['type'] != p['type']:
                major_pivots.append(p)

    if len(major_pivots) < 2:
        major_pivots = pivots  # 피벗이 부족하면 전체 피벗 사용

    # 분석이 중간에 끊기지 않도록, 마지막 피벗과 차트 맨 끝단(현재가)을 강제로 연결
    if major_pivots[-1]['date'] < df.index[-1]:
        last_type = 'H' if major_pivots[-1]['type'] == 'L' else 'L'
        last_price = df.iloc[-1]['High'] if last_type == 'H' else df.iloc[-1]['Low']
        major_pivots.append({'idx': len(df) - 1, 'date': df.index[-1], 'price': last_price, 'type': last_type, 'score': 100})

    for i in range(len(major_pivots) - 1):
        p_start = major_pivots[i]
        p_end = major_pivots[i + 1]

        is_up = p_end['price'] > p_start['price']

        if is_up:
            sub_waves = force_fit_5_waves(df, p_start['date'], p_end['date'], is_up=True)
            cycle_type = 'Motive (1-2-3-4-5)'
        else:
            sub_waves = force_fit_3_waves(df, p_start['date'], p_end['date'], is_up=False)
            cycle_type = 'Corrective (A-B-C)'

        if sub_waves:
            cycles.append({
                'type': cycle_type,
                'is_up': is_up,
                'start_date': p_start['date'],
                'end_date': p_end['date'],
                'start_price': p_start['price'],
                'end_price': p_end['price'],
                'sub_waves': sub_waves
            })

    return cycles

def analyze_elliott_waves(df, ind, is_kr, current_price, calc_atr, build_pivot_candidates, filter_pivots_for_krx, detect_local_extrema, lookback=260):
    """메인 분석 함수. 현재 국면 분석과 전체 멀티 사이클을 모두 반환합니다."""
    sub = df.copy()
    if len(sub) < 30:
        return {'available': False, 'reason': '데이터 부족'}

    pivots = build_pivot_candidates(sub, orders=(3, 5, 8, 13, 21))
    pivots = filter_pivots_for_krx(sub, pivots, is_kr=is_kr)
    for p in pivots:
        p['date'] = sub.index[p['idx']]
    if len(pivots) < 4:
        return {'available': False, 'reason': '피벗 부족'}

    # 1. 전체 구간 멀티 사이클 (프랙탈 반복 구조) 추출
    multi_cycles = extract_multi_cycles(sub, pivots)

    # 2. 현재 상태(가장 마지막 사이클) 심층 분석
    current_cycle = multi_cycles[-1] if multi_cycles else None

    if not current_cycle:
        return {'available': False, 'reason': '파동 사이클 식별 실패'}

    cw_type = current_cycle['type']
    is_bull = current_cycle['is_up']

    # B파 트랩 및 패턴(지그재그/플랫/확장) 판별
    cor_analysis = {'available': False}
    if cw_type == 'Corrective (A-B-C)':
        sw = current_cycle['sub_waves']
        if len(sw) == 4:  # 0, A, B, C
            am = abs(sw[1]['price'] - sw[0]['price'])
            bm = abs(sw[2]['price'] - sw[1]['price'])
            cm = abs(sw[3]['price'] - sw[2]['price'])
            br = bm / (am + 1e-9)

            p_type, p_desc = "미정", "혼조세"
            if br < 0.618:
                p_type, p_desc = "지그재그형 (5-3-5)", "B파 반등이 얕고 C파 하락이 매우 깊은 강력한 조정입니다."
            elif br <= 1.05:
                p_type, p_desc = "플랫형 (3-3-5)", "B파가 A파를 대부분 되돌리는 수평 박스권 형태입니다."
            else:
                p_type, p_desc = "확장/불규칙형 (Expanded)", "B파가 기존 고점을 돌파해 완벽한 '불 트랩(Bull Trap)'을 형성한 뒤 폭락하는 가장 위험한 패턴입니다."

            cor_analysis = {
                'available': True, 'pattern_type': p_type, 'pattern_desc': p_desc,
                'a_move': am, 'b_retrace': br,
                'c_target': sw[2]['price'] - am if not is_bull else sw[2]['price'] + am
            }

    return {
        'available': True,
        'multi_cycles': multi_cycles,
        'current_cycle': current_cycle,
        'corrective': cor_analysis,
        'current_price': current_price,
        'trend_bias': 'up' if is_bull else 'down',
        'confidence': 85.0 if len(multi_cycles) >= 2 else 50.0
    }

def build_commentary(analysis, unit, fmt_price):
    mc = analysis['multi_cycles']
    cc = analysis['current_cycle']
    cor = analysis.get('corrective', {})

    motive_cnt = sum(1 for c in mc if c['is_up'])
    corr_cnt = sum(1 for c in mc if not c['is_up'])

    secs = []
    secs.append({
        'title': '1) 프랙탈 파동 구조 (전체 요약)',
        'body': f"분석 기간 동안 **상위 상승파동 {motive_cnt}개, 상위 하락파동 {corr_cnt}개**의 순환 사이클(135ABC 반복)이 식별되었습니다.\n\n이는 엘리어트 파동이론의 핵심인 **'상위 파동 속에 하위 파동이 존재한다(Fractal)'**는 대원칙을 차트에 그대로 투영한 결과입니다. 차트의 굵은 선은 상위 파동을, 얇은 선은 하위 파동을 의미합니다."
    })

    phase = "충동파 (1-2-3-4-5 진행)" if cc['is_up'] else "조정파 (A-B-C 진행)"
    secs.append({
        'title': '2) 현재 국면 (최근 사이클 상태)',
        'body': f"현재 시장은 **상위 {phase}** 국면에 진입해 있습니다.\n\n- 시작점: {cc['start_date'].strftime('%Y-%m-%d')} ({fmt_price(cc['start_price'])}{unit})\n- 추세 방향: {'📈 강세장' if cc['is_up'] else '📉 약세/조정장'}\n- 하위 파동 진행률: {len(cc['sub_waves'])-1}파 진행 (마지막까지 추적 완료)"
    })

    if cor.get('available'):
        secs.append({
            'title': '3) 🚨 조정파동 B파(트랩) 및 ABC 패턴 정밀 분석',
            'body': f"현재 식별된 조정 패턴은 **{cor['pattern_type']}**입니다.\n{cor['pattern_desc']}\n\n**B파 되돌림 비율**: A파의 {cor['b_retrace']*100:.1f}%\n\n*(이론 통찰: 조정파동의 B파는 기존 상위 추세 방향으로 다시 움직이며 투자자들을 안심시키는 완벽한 **속임수(Trap)** 역할을 합니다. B파 반등에 속아 추격 매수하지 않도록 극도로 주의해야 하며, C파 투매 목표가({fmt_price(cor['c_target'])}{unit} 부근)까지 인내해야 합니다.)*"
        })
    else:
        secs.append({
            'title': '3) 충동파(1-3-5) 대응 전략',

# [CHART_TITLE_SEARCH_FUNC] 차트제목검색: 엘리어트 프랙탈 멀티사이클 차트 / 엘리어트 프랙탈 분석
# [POSFUNC_ELLIOTT_CHART] 엘리어트 차트 파동 라벨 위치: render_elliott_chart() 안의 yshift/텍스트 x/y를 조정하세요.
            'body': "현재 상위 상승 사이클 진행 중입니다.\n\n**이론 통찰**:\n- **2파 눌림**: 1파를 전부 되돌리지 않는 선에서 최고의 매수 기회입니다.\n- **3파 폭발**: 가장 길고 강력한 주추세이므로 섣부른 익절 없이 끝까지 홀딩해야 합니다.\n- **5파 상투**: 보조지표 다이버전스가 자주 발생하며 군중의 탐욕이 극에 달하는 시점입니다. 이때 분할 익절을 준비해야 합니다."
        })

    secs.append({
        'title': '4) 분석의 한계와 실전 적용',
        'body': "본 엔진은 '프랙탈 구조'와 'B파 트랩' 이론을 로직화하여 차트에 분홍색 조정 구간과 함께 시각화했습니다.\n다만, 엘리어트 파동이론은 언제든 연장(Extension)과 미달(Failure) 등 변칙이 발생할 수 있으므로 절대 맹신해선 안 되며, 포지션 사이징 및 피보나치 수평 지지/저항선과 반드시 결합하여 사용하세요."
    })

    return secs

def render_elliott_chart(df, ind, analysis, display_name, unit, P, FONT_MONO, esc, fmt_price, st, go, make_subplots, mobile=False, chart_mode="프랙탈 이론 뷰"):
    # [엘리어트차트-튜닝] 엘리어트 차트 전용 튜닝 함수
    # 초보자 안내: 엘리어트/프랙탈 파동 차트입니다.
    # - display_name: 종목명
    # - analysis: 파동 분석 결과
    # - title, banner, margin, height를 바꾸면 이 차트의 전체 스타일이 바뀝니다.
    mc = analysis['multi_cycles']
    sub = df.copy()

    fig = make_subplots(rows=2, cols=1, shared_xaxes=True, vertical_spacing=(0.090 if not mobile else 0.075), row_heights=[0.72, 0.28])

    # 캔들스틱 (파동 선이 돋보이도록 캔들 불투명도 조절)
    fig.add_trace(go.Candlestick(x=sub.index, open=sub['Open'], high=sub['High'], low=sub['Low'], close=sub['Close'], increasing_line_color=P['up'], decreasing_line_color=P['dn'], increasing_fillcolor='rgba(255,77,109,0.5)', decreasing_fillcolor='rgba(77,171,247,0.5)', opacity=0.7, showlegend=False), row=1, col=1)
    fig = add_current_position_marker(fig, sub.index[-1], float(sub["Close"].iloc[-1]), row=1, col=1, label="파동 현재가", price_fmt=",.0f", opinion=build_current_position_opinion(sub, ind, panel="elliott", value=float(sub["Close"].iloc[-1])))

    # 멀티 사이클 순회하며 차트 그리기
    for cycle in mc:
        is_up = cycle['is_up']
        sw = cycle['sub_waves']

        # 1. 핑크색 조정구간 하이라이트
        if is_up and len(sw) == 6:
            # 2파 조정구간 하이라이트
            x0, x1 = sw[1]['date'], sw[3]['date']
            y0, y1 = sw[2]['price'] * 0.95, sw[1]['price'] * 1.05
            fig.add_shape(type="circle", xref="x", yref="y", x0=x0, y0=y0, x1=x1, y1=y1, fillcolor=COLOR_OVAL, line_color="rgba(255,100,100,0.2)", layer="below", row=1, col=1)
            # 4파 조정구간 하이라이트
            x0, x1 = sw[3]['date'], sw[5]['date']
            y0, y1 = sw[4]['price'] * 0.95, sw[3]['price'] * 1.05
            fig.add_shape(type="circle", xref="x", yref="y", x0=x0, y0=y0, x1=x1, y1=y1, fillcolor=COLOR_OVAL, line_color="rgba(255,100,100,0.2)", layer="below", row=1, col=1)

        elif not is_up and len(sw) == 4:
            # A, B 파동 전체(트랩구간) 하이라이트
            x0, x1 = sw[0]['date'], sw[2]['date']
            y0, y1 = sw[1]['price'] * 0.95, sw[0]['price'] * 1.05
            fig.add_shape(type="circle", xref="x", yref="y", x0=x0, y0=y0, x1=x1, y1=y1, fillcolor=COLOR_OVAL, line_color="rgba(255,100,100,0.2)", layer="below", row=1, col=1)
            # 텍스트로 '조정파동' 명시
            # [CHART_TITLE_SEARCH: 엘리어트 프랙탈 멀티사이클 차트 / 엘리어트 프랙탈 분석] 아래 [BOXPOS_052] 박스/풍선 위치 코드입니다. 이 차트 제목으로 검색하면 바로 찾을 수 있습니다.
            # [BOXPOS_052_ELLIOTT_render_elliott_chart] 엘리어트: 조정파동 Trap 라벨 | 위치수정: x/y(기준좌표), ax/ay(화살표 박스 픽셀오프셋), xshift/yshift, xanchor/yanchor를 조정. xref/yref="paper"는 0~1 화면비율, xref/yref="x/y"는 날짜·가격/지표값입니다.
            fig.add_annotation(x=sw[1]['date'], y=sw[0]['price'] * 1.08, text="<b>조정파동 (Trap)</b>", showarrow=False, font=dict(color="rgba(255,100,100,0.9)", size=14), row=1, col=1)

        # 2. 하위 파동 (얇은 선) 그리기
        xs = [p['date'] for p in sw]
        ys = [p['price'] for p in sw]
        fig.add_trace(go.Scatter(x=xs, y=ys, mode='lines', line=dict(color=COLOR_MINOR, width=1.5), hoverinfo='skip', showlegend=False), row=1, col=1)

        # 하위 파동 번호/알파벳 라벨 붙이기 (파동 선분의 중간에 표기)
        for i in range(1, len(sw)):
            p_prev = sw[i-1]
            p_curr = sw[i]
            lbl = p_curr['label']
            
            mid_date = p_prev['date'] + (p_curr['date'] - p_prev['date']) / 2
            mid_price = (p_prev['price'] + p_curr['price']) / 2
            
            offset = 20 if lbl in ['1', '3', '5', 'B'] else -20
            # [CHART_TITLE_SEARCH: 엘리어트 프랙탈 멀티사이클 차트 / 엘리어트 프랙탈 분석] 아래 [BOXPOS_053] 박스/풍선 위치 코드입니다. 이 차트 제목으로 검색하면 바로 찾을 수 있습니다.
            # [BOXPOS_053_ELLIOTT_render_elliott_chart] 엘리어트: 하위 파동 번호 라벨 | 위치수정: x/y(기준좌표), ax/ay(화살표 박스 픽셀오프셋), xshift/yshift, xanchor/yanchor를 조정. xref/yref="paper"는 0~1 화면비율, xref/yref="x/y"는 날짜·가격/지표값입니다.
            fig.add_annotation(x=mid_date, y=mid_price, text=f"<b>{lbl}파</b>", showarrow=False, yshift=offset, font=dict(size=11, color=COLOR_MINOR), row=1, col=1)

        # 3. 상위 파동 (굵은 선) 그리기
        major_color = COLOR_MAJOR_UP if is_up else COLOR_MAJOR_DN
        major_text = "<b>상위파동 (Motive)</b>" if is_up else "<b>상위파동 (Corrective)</b>"
        fig.add_trace(go.Scatter(x=[cycle['start_date'], cycle['end_date']], y=[cycle['start_price'], cycle['end_price']], mode='lines', line=dict(color=major_color, width=4), hoverinfo='skip', showlegend=False), row=1, col=1)

        # 상위 파동 방향 라벨
        mid_date = cycle['start_date'] + (cycle['end_date'] - cycle['start_date']) / 2
        mid_price = (cycle['start_price'] + cycle['end_price']) / 2
        # [CHART_TITLE_SEARCH: 엘리어트 프랙탈 멀티사이클 차트 / 엘리어트 프랙탈 분석] 아래 [BOXPOS_054] 박스/풍선 위치 코드입니다. 이 차트 제목으로 검색하면 바로 찾을 수 있습니다.
        # [BOXPOS_054_ELLIOTT_render_elliott_chart] 엘리어트: 주요 상승/조정 파동 라벨 | 위치수정: x/y(기준좌표), ax/ay(화살표 박스 픽셀오프셋), xshift/yshift, xanchor/yanchor를 조정. xref/yref="paper"는 0~1 화면비율, xref/yref="x/y"는 날짜·가격/지표값입니다.
        fig.add_annotation(x=mid_date, y=mid_price, text=major_text, showarrow=False, font=dict(size=13, color=major_color), yshift=30 if is_up else -30, row=1, col=1)

    _elliott_margin = dict(l=ELLIOTT_TUNE['MARGIN_LEFT'], r=ELLIOTT_TUNE['MARGIN_RIGHT'], t=max(ELLIOTT_TUNE['MARGIN_TOP'], 138), b=ELLIOTT_TUNE['MARGIN_BOTTOM']) if not mobile else dict(l=25, r=16, t=104, b=46)
    fig.update_layout(template='plotly_dark', height=(860 if mobile else 1090), paper_bgcolor=P['bg_base'], plot_bgcolor=P['bg_panel'], font=dict(color=P['txt'], family=FONT_MONO, size=(ELLIOTT_TUNE['FONT_SIZE_MOBILE'] if mobile else ELLIOTT_TUNE['FONT_SIZE_PC'])), margin=_elliott_margin, title=dict(text=f"{display_name} · Multi-Cycle Fractal Model (1-3-5 135ABC 반복)", font=dict(size=(ELLIOTT_TUNE['TITLE_SIZE_MOBILE'] if mobile else ELLIOTT_TUNE['TITLE_SIZE_PC']), color=P['accent'])), xaxis_rangeslider_visible=False, showlegend=False)

    # X축 표시 범위: 엘리어트 파동의 향후 진행 여지를 보기 위해 마지막 봉 이후 1개월까지 확장
    _elliott_x_end = pd.Timestamp(sub.index[-1]) + pd.DateOffset(months=1)
    fig.update_xaxes(range=[sub.index[0], _elliott_x_end])
    for r in [1, 2]:
        fig.update_xaxes(row=r, col=1, showgrid=False, showticklabels=True, tickformatstops=HTS_TICKFORMATSTOPS, nticks=30, tickangle=-45, automargin=True)
        fig.update_yaxes(row=r, col=1, gridcolor='rgba(255,255,255,0.07)')
    fig.update_yaxes(title_text='Volume', row=2, col=1)

    pt = f"{sub.index[0].strftime('%Y-%m-%d')} ~ {sub.index[-1].strftime('%Y-%m-%d')}"
    add_row_banner(fig, "yaxis", "① 엘리어트 프랙탈 멀티사이클", [("상위 상승파동", COLOR_MAJOR_UP), ("상위 조정파동", COLOR_MAJOR_DN), ("하위파동", COLOR_MINOR), ("조정/트랩", COLOR_OVAL)], pt, font_size=ELLIOTT_TUNE["BANNER_FONT_SIZE"])
    add_row_banner(fig, "yaxis2", "② 거래량", [("Volume", P["accent"])], "파동 진행 중 거래량 확인")
    fig = apply_smart_annotation_layout(fig, sub, mobile=mobile, reserve_right_rail=True, chart_name="elliott")
    fig = cleanup_old_chart_annotations(
        fig, sub, recent_bars=45,
        keep_keywords=["긴급 매수", "긴급 매도", "현재", "현재가", "파동 현재가", "135ABC", "1·3·5", "A·B·C", "1파", "3파", "5파", "A파", "B파", "C파", "<b>1</b>", "<b>3</b>", "<b>5</b>", "<b>A</b>", "<b>B</b>", "<b>C</b>", "조정파동", "상위파동"]
    )
    return fig

def render_elliott_tab(df, ind, display_name, unit, is_kr, compact_mode, current_price, atr, P, FONT_MONO, esc, fmt_price, st, go, make_subplots, render_section_title, render_report_card, render_info_lines, render_dashboard_cards, render_kpi_cards, render_figure_export_buttons, calc_atr, build_pivot_candidates, filter_pivots_for_krx, detect_local_extrema):

    analysis = analyze_elliott_waves(df, ind, is_kr, current_price, calc_atr, build_pivot_candidates, filter_pivots_for_krx, detect_local_extrema, lookback=300)

    if not analysis.get('available'):
        render_section_title("엘리어트 프랙탈 분석", "파동 구조 자동 식별")
        st.warning("🌊 파동 구조 식별 불가. 조회가 가능한 파동 피벗이 충분하지 않습니다.")
        return

    mc = analysis['multi_cycles']
    cc = analysis['current_cycle']

    render_section_title("프랙탈 구조 파동 요약 (전체 기간)")
    sc = [
        {'icon': '🔄', 'title': '탐지된 사이클', 'value': f"총 {len(mc)}개 식별", 'caption': '135ABC 무한 반복 모델', 'help': '지정된 전체 기간 동안 순환된 파동의 개수입니다.', 'message': '상위파동과 하위파동의 프랙탈 구조 적용 완료', 'status': 'good'},
        {'icon': '📍', 'title': '현재 상위 추세', 'value': '상승 충동파' if cc['is_up'] else '하락 조정파', 'caption': f"시작일: {cc['start_date'].strftime('%Y-%m-%d')}", 'help': '마지막으로 감지된 상위 파동의 방향입니다. 끝단(현재)까지 분석되었습니다.', 'message': '', 'status': 'good' if cc['is_up'] else 'warn'},
        {'icon': '🧩', 'title': '현재 하위 진행', 'value': f"{len(cc['sub_waves'])-1}파동 진행중", 'caption': '세부 추세', 'help': '마지막 상위 파동 내부의 하위 파동 진행 상태입니다.', 'message': '', 'status': 'info'}
    ]
    render_dashboard_cards(sc, cols_per_row=(1 if compact_mode else 3))

    render_section_title("엘리어트 프랙탈 멀티사이클 차트")
    st.info("💡 **지정 기간 100% 반영 & 끝단 연결**: 굵은 선은 상위 파동, 얇은 선은 하위 파동을 의미하며, 분홍색 원형 영역은 조정 및 트랩(Trap) 구간을 나타냅니다. X축 월간 레이블도 촘촘하게 개선되었습니다.")

    fig = render_elliott_chart(df, ind, analysis, display_name, unit, P, FONT_MONO, esc, fmt_price, st, go, make_subplots, mobile=compact_mode)
    render_figure_export_buttons(fig, f"{display_name}_fractal_wave")
    render_draggable_plotly_chart(fig, use_container_width=True)
    render_chart_box_meaning_panel("elliott", expanded=True, technical_lines=[f"현재 파동 편향: {analysis.get('trend_bias', 'N/A')}", f"파동 신뢰도: {analysis.get('confidence', 0):.0f}점", f"현재가: {fmt_price(analysis.get('current_price', current_price))}{unit}"], conclusion="파동 위치를 기준으로 추격/눌림/방어 구간을 구분합니다.")
    st.divider()

    render_section_title("프랙탈 및 조정파동 심층 리포트")
    secs = build_commentary(analysis, unit, fmt_price)
    for sec in secs:
        render_report_card(sec['title'], sec['body'], icon='🌊')


# ═══════════════════════════════════════════════════════════════
# COMPANY ANALYSIS — Fundamental analysis engine
# ═══════════════════════════════════════════════════════════════


"""
🏢 COMPANY ANALYSIS — 전문가용 기업(펀더멘털) 분석 엔진
"""

def _safe(v, default=np.nan):
    try:
        if v is None:
            return default
        f = float(v)
        return f if np.isfinite(f) else default
    except Exception:
        return default

def _as_pct(v):
    f = _safe(v)
    if not np.isfinite(f):
        return np.nan
    return f * 100.0

def fmt_money(x, is_kr=True):
    f = _safe(x)
    if not np.isfinite(f):
        return "N/A"
    sign = "-" if f < 0 else ""
    a = abs(f)
    if is_kr:
        if a >= 1e12: return f"{sign}{a/1e12:,.2f}조원"
        if a >= 1e8: return f"{sign}{a/1e8:,.0f}억원"
        if a >= 1e4: return f"{sign}{a/1e4:,.0f}만원"
        return f"{sign}{a:,.0f}원"
    else:
        if a >= 1e12: return f"{sign}${a/1e12:,.2f}T"
        if a >= 1e9: return f"{sign}${a/1e9:,.2f}B"
        if a >= 1e6: return f"{sign}${a/1e6:,.2f}M"
        return f"{sign}${a:,.0f}"

def fmt_num(x, suffix="", nd=2):
    f = _safe(x)
    if not np.isfinite(f): return "N/A"
    return f"{f:,.{nd}f}{suffix}"

def fmt_pct(x, nd=1, signed=False):
    f = _safe(x)
    if not np.isfinite(f): return "N/A"
    if signed: return f"{f:+.{nd}f}%"
    return f"{f:.{nd}f}%"

def _get_row(df, names):
    if df is None or not isinstance(df, pd.DataFrame) or df.empty:
        return None
    idx_lower = {str(i).strip().lower(): i for i in df.index}
    for nm in names:
        key = nm.strip().lower()
        if key in idx_lower:
            try:
                s = df.loc[idx_lower[key]]
                return s
            except Exception:
                continue
    for nm in names:
        key = nm.strip().lower()
        for low, orig in idx_lower.items():
            if key in low:
                try:
                    return df.loc[orig]
                except Exception:
                    continue
    return None

@st.cache_data(show_spinner=False, ttl=3600)
def fetch_company_fundamentals(symbol: str) -> dict:
    out = {"available": False, "info": {}, "fin": None, "bs": None, "cf": None,
           "currency": "", "fin_currency": ""}
    try:
        tkr = yf.Ticker(symbol)
        info = {}
        try:
            info = tkr.info or {}
        except Exception:
            info = {}
        if not info or len([k for k in info if info.get(k) is not None]) < 3:
            try:
                info = tkr.get_info() or info
            except Exception:
                pass
        fin = None; bs = None; cf = None
        try: fin = tkr.financials
        except Exception: fin = None
        if fin is None or (isinstance(fin, pd.DataFrame) and fin.empty):
            try: fin = tkr.income_stmt
            except Exception: fin = None
        try: bs = tkr.balance_sheet
        except Exception: bs = None
        try: cf = tkr.cashflow
        except Exception: cf = None
        has_info = bool(info) and any(info.get(k) is not None for k in
                                      ["marketCap", "trailingPE", "regularMarketPrice", "currentPrice", "longName"])
        has_fin = isinstance(fin, pd.DataFrame) and not fin.empty
        out.update({
            "available": bool(has_info or has_fin),
            "info": info,
            "fin": fin if isinstance(fin, pd.DataFrame) else None,
            "bs": bs if isinstance(bs, pd.DataFrame) else None,
            "cf": cf if isinstance(cf, pd.DataFrame) else None,
            "currency": str(info.get("currency", "")),
            "fin_currency": str(info.get("financialCurrency", info.get("currency", ""))),
        })
    except Exception as e:
        out["error"] = str(e)
    return out

def _bs_value(bs, names):
    s = _get_row(bs, names)
    if s is None or len(s) == 0: return np.nan
    try: return _safe(s.iloc[0])
    except Exception: return np.nan

def _fin_value(fin, names, col_idx=0):
    s = _get_row(fin, names)
    if s is None or len(s) == 0: return np.nan
    try: return _safe(s.iloc[col_idx])
    except Exception: return np.nan

def extract_metrics(data: dict, current_price: float) -> dict:
    info = data.get("info", {}) or {}
    bs = data.get("bs"); fin = data.get("fin"); cf = data.get("cf")
    m = {}; notes = {}
    m["price"] = _safe(info.get("currentPrice", info.get("regularMarketPrice", current_price)), current_price)
    price = m["price"]
    m["market_cap"] = _safe(info.get("marketCap"))
    m["enterprise_value"] = _safe(info.get("enterpriseValue"))
    m["shares"] = _safe(info.get("sharesOutstanding") or info.get("impliedSharesOutstanding"))
    m["beta"] = _safe(info.get("beta"))
    m["w52_high"] = _safe(info.get("fiftyTwoWeekHigh"))
    m["w52_low"] = _safe(info.get("fiftyTwoWeekLow"))
    m["ma50"] = _safe(info.get("fiftyDayAverage"))
    m["ma200"] = _safe(info.get("twoHundredDayAverage"))
    shares = m["shares"]; mcap = m["market_cap"]
    net_income = _safe(info.get("netIncomeToCommon"))
    if not np.isfinite(net_income):
        net_income = _fin_value(fin, ["Net Income Common Stockholders", "Net Income",
                                      "Net Income From Continuing Operation Net Minority Interest"])
    equity = _bs_value(bs, ["Stockholders Equity", "Common Stock Equity",
                            "Total Equity Gross Minority Interest"])
    total_assets = _bs_value(bs, ["Total Assets"])
    revenue = _safe(info.get("totalRevenue"))
    if not np.isfinite(revenue):
        revenue = _fin_value(fin, ["Total Revenue", "Operating Revenue"])
    op_income = _fin_value(fin, ["Operating Income", "Total Operating Income As Reported", "EBIT"])
    gross_profit = _fin_value(fin, ["Gross Profit"])
    m["net_income"] = net_income; m["equity"] = equity
    per = _safe(info.get("trailingPE"))
    eps = _safe(info.get("trailingEps") or info.get("epsTrailingTwelveMonths"))
    if not np.isfinite(eps) and np.isfinite(net_income) and np.isfinite(shares) and shares > 0:
        eps = net_income / shares; notes["eps"] = "calc"
    if not np.isfinite(per):
        if np.isfinite(mcap) and np.isfinite(net_income) and net_income > 0:
            per = mcap / net_income; notes["per"] = "calc"
        elif np.isfinite(eps) and eps > 0 and np.isfinite(price):
            per = price / eps; notes["per"] = "calc"
    m["per"] = per; m["eps"] = eps
    m["forward_per"] = _safe(info.get("forwardPE"))
    m["forward_eps"] = _safe(info.get("forwardEps") or info.get("epsForward"))
    pbr = _safe(info.get("priceToBook"))
    bvps = _safe(info.get("bookValue"))
    if not np.isfinite(bvps) and np.isfinite(equity) and np.isfinite(shares) and shares > 0:
        bvps = equity / shares; notes["book_value"] = "calc"
    if not np.isfinite(pbr):
        if np.isfinite(mcap) and np.isfinite(equity) and equity > 0:
            pbr = mcap / equity; notes["pbr"] = "calc"
        elif np.isfinite(bvps) and bvps > 0 and np.isfinite(price):
            pbr = price / bvps; notes["pbr"] = "calc"
    m["pbr"] = pbr; m["book_value"] = bvps
    psr = _safe(info.get("priceToSalesTrailing12Months"))
    if not np.isfinite(psr) and np.isfinite(mcap) and np.isfinite(revenue) and revenue > 0:
        psr = mcap / revenue; notes["psr"] = "calc"
    m["psr"] = psr
    m["peg"] = _safe(info.get("pegRatio") or info.get("trailingPegRatio"))
    m["ev_ebitda"] = _safe(info.get("enterpriseToEbitda"))
    m["ev_rev"] = _safe(info.get("enterpriseToRevenue"))
    roe = _as_pct(info.get("returnOnEquity"))
    if not np.isfinite(roe) and np.isfinite(net_income) and np.isfinite(equity) and equity > 0:
        roe = net_income / equity * 100; notes["roe"] = "calc"
    m["roe"] = roe
    roa = _as_pct(info.get("returnOnAssets"))
    if not np.isfinite(roa) and np.isfinite(net_income) and np.isfinite(total_assets) and total_assets > 0:
        roa = net_income / total_assets * 100; notes["roa"] = "calc"
    m["roa"] = roa
    gm = _as_pct(info.get("grossMargins"))
    if not np.isfinite(gm) and np.isfinite(gross_profit) and np.isfinite(revenue) and revenue > 0:
        gm = gross_profit / revenue * 100; notes["gross_margin"] = "calc"
    m["gross_margin"] = gm
    opm = _as_pct(info.get("operatingMargins"))
    if not np.isfinite(opm) and np.isfinite(op_income) and np.isfinite(revenue) and revenue > 0:
        opm = op_income / revenue * 100; notes["op_margin"] = "calc"
    m["op_margin"] = opm
    nm = _as_pct(info.get("profitMargins"))
    if not np.isfinite(nm) and np.isfinite(net_income) and np.isfinite(revenue) and revenue > 0:
        nm = net_income / revenue * 100; notes["net_margin"] = "calc"
    m["net_margin"] = nm
    m["ebitda_margin"] = _as_pct(info.get("ebitdaMargins"))
    rg = np.nan
    r0 = _fin_value(fin, ["Total Revenue", "Operating Revenue"], 0)
    r1 = _fin_value(fin, ["Total Revenue", "Operating Revenue"], 1)
    if np.isfinite(r0) and np.isfinite(r1) and r1 > 0:
        rg = (r0 / r1 - 1) * 100; notes["rev_growth"] = "calc"
    else:
        rg = _as_pct(info.get("revenueGrowth"))
    m["rev_growth"] = rg
    eg = np.nan
    n0 = _fin_value(fin, ["Net Income Common Stockholders", "Net Income"], 0)
    n1 = _fin_value(fin, ["Net Income Common Stockholders", "Net Income"], 1)
    if np.isfinite(n0) and np.isfinite(n1) and n1 > 0:
        eg = (n0 / n1 - 1) * 100; notes["earn_growth"] = "calc"
    else:
        eg = _as_pct(info.get("earningsGrowth"))
    m["earn_growth"] = eg
    m["earn_q_growth"] = _as_pct(info.get("earningsQuarterlyGrowth"))
    de = _safe(info.get("debtToEquity"))
    total_debt = _safe(info.get("totalDebt"))
    if not np.isfinite(total_debt):
        total_debt = _bs_value(bs, ["Total Debt"])
    total_liab = _bs_value(bs, ["Total Liabilities Net Minority Interest",
                                "Total Liabilities", "Total Liab"])
    de_final = np.nan
    if np.isfinite(total_liab) and np.isfinite(equity) and equity > 0:
        de_final = total_liab / equity * 100; notes["debt_to_equity"] = "calc(부채총계)"
    elif np.isfinite(total_debt) and np.isfinite(equity) and equity > 0:
        de_final = total_debt / equity * 100; notes["debt_to_equity"] = "calc(총차입금)"
    elif np.isfinite(de):
        de_final = de * 100 if de < 5 else de
    m["debt_to_equity"] = de_final
    m["current_ratio"] = _safe(info.get("currentRatio"))
    m["quick_ratio"] = _safe(info.get("quickRatio"))
    m["total_cash"] = _safe(info.get("totalCash")) if np.isfinite(_safe(info.get("totalCash"))) else _bs_value(bs, ["Cash And Cash Equivalents", "Cash Cash Equivalents And Short Term Investments"])
    m["total_debt"] = total_debt
    m["total_revenue"] = revenue
    m["ebitda"] = _safe(info.get("ebitda")) if np.isfinite(_safe(info.get("ebitda"))) else _fin_value(fin, ["EBITDA", "Normalized EBITDA"])
    m["fcf"] = _safe(info.get("freeCashflow")) if np.isfinite(_safe(info.get("freeCashflow"))) else _fin_value(cf, ["Free Cash Flow"])
    m["op_cf"] = _safe(info.get("operatingCashflow")) if np.isfinite(_safe(info.get("operatingCashflow"))) else _fin_value(cf, ["Operating Cash Flow", "Cash Flow From Continuing Operating Activities"])
    dy = _safe(info.get("dividendYield"))
    div_rate = _safe(info.get("dividendRate") or info.get("trailingAnnualDividendRate"))
    dy_calc = np.nan
    if np.isfinite(div_rate) and np.isfinite(price) and price > 0:
        dy_calc = div_rate / price * 100
    if not np.isfinite(dy):
        dy = dy_calc
        if np.isfinite(dy): notes["div_yield"] = "calc"
    else:
        if np.isfinite(dy_calc) and (dy > 40 or (dy_calc > 0 and abs(dy - dy_calc) / dy_calc > 3)):
            dy = dy_calc; notes["div_yield"] = "calc"
    m["div_yield"] = dy
    m["div_rate"] = div_rate
    m["payout"] = _as_pct(info.get("payoutRatio"))
    m["div_5y_avg"] = _safe(info.get("fiveYearAvgDividendYield"))
    m["held_insiders"] = _as_pct(info.get("heldPercentInsiders"))
    m["held_inst"] = _as_pct(info.get("heldPercentInstitutions"))
    m["reco_key"] = str(info.get("recommendationKey", "none"))
    m["reco_mean"] = _safe(info.get("recommendationMean"))
    m["n_analysts"] = _safe(info.get("numberOfAnalystOpinions"))
    m["target_mean"] = _safe(info.get("targetMeanPrice"))
    m["target_high"] = _safe(info.get("targetHighPrice"))
    m["target_low"] = _safe(info.get("targetLowPrice"))
    m["target_median"] = _safe(info.get("targetMedianPrice"))
    m["_notes"] = notes
    return m

def _score_lower_better(v, good, bad):
    if not np.isfinite(v): return None
    if v <= 0: return 40.0
    if v <= good: return 100.0
    if v >= bad: return 10.0
    return float(100 - (v - good) / (bad - good) * 90)

def _score_higher_better(v, bad, good):
    if not np.isfinite(v): return None
    if v <= bad: return 10.0
    if v >= good: return 100.0
    return float(10 + (v - bad) / (good - bad) * 90)

def _avg(vals):
    xs = [x for x in vals if x is not None and np.isfinite(x)]
    return float(np.mean(xs)) if xs else np.nan

def compute_fundamental_scores(m: dict) -> dict:
    val = _avg([_score_lower_better(m["per"], 10, 40), _score_lower_better(m["pbr"], 1.0, 6.0),
                _score_lower_better(m["psr"], 1.0, 10.0), _score_lower_better(m["peg"], 1.0, 3.0),
                _score_lower_better(m["ev_ebitda"], 8, 25)])
    prof = _avg([_score_higher_better(m["roe"], 5, 20), _score_higher_better(m["roa"], 2, 12),
                 _score_higher_better(m["op_margin"], 3, 25), _score_higher_better(m["net_margin"], 2, 20),
                 _score_higher_better(m["gross_margin"], 15, 50)])
    grow = _avg([_score_higher_better(m["rev_growth"], -5, 25), _score_higher_better(m["earn_growth"], -10, 30),
                 _score_higher_better(m["earn_q_growth"], -10, 30)])
    stab = _avg([_score_lower_better(m["debt_to_equity"], 50, 250),
                 _score_higher_better(m["current_ratio"], 1.0, 2.5),
                 _score_higher_better(m["quick_ratio"], 0.7, 2.0)])
    div = _avg([_score_higher_better(m["div_yield"], 0.5, 5.0),
                (None if not np.isfinite(m["payout"]) else (
                    100.0 if 25 <= m["payout"] <= 60 else
                    70.0 if 10 <= m["payout"] < 25 or 60 < m["payout"] <= 80 else 35.0))])
    parts = {"밸류에이션": val, "수익성": prof, "성장성": grow, "안정성": stab, "배당": div}
    weights = {"밸류에이션": 0.25, "수익성": 0.30, "성장성": 0.20, "안정성": 0.15, "배당": 0.10}
    num, den = 0.0, 0.0
    for k, w in weights.items():
        if parts[k] is not None and np.isfinite(parts[k]):
            num += parts[k] * w; den += w
    total = float(num / den) if den > 0 else np.nan
    if not np.isfinite(total): grade, eng, desc = "평가불가", "N/A", "공시 데이터가 부족해 펀더멘털 종합 평가가 어렵습니다."
    elif total >= 80: grade, eng, desc = "최우량", "A+", "밸류·수익성·재무가 두루 탄탄한 우량 펀더멘털입니다."
    elif total >= 70: grade, eng, desc = "우량", "A", "전반적으로 양호한 펀더멘털을 보유했습니다."
    elif total >= 60: grade, eng, desc = "양호", "B", "준수한 편이나 일부 항목은 점검이 필요합니다."
    elif total >= 50: grade, eng, desc = "보통", "C", "강점과 약점이 혼재합니다."
    elif total >= 40: grade, eng, desc = "주의", "D", "여러 지표가 평균 이하입니다."
    else: grade, eng, desc = "취약", "E", "펀더멘털이 전반적으로 약합니다."
    return {"parts": parts, "total": total, "grade": grade, "eng": eng, "desc": desc}

def _interp_per(v):
    if not np.isfinite(v): return "데이터 없음", "info"
    if v <= 0: return "적자 또는 음수 EPS로 PER 의미가 낮습니다.", "warn"
    if v < 10: return "이익 대비 주가가 낮은 편(저평가 가능).", "good"
    if v < 25: return "시장 평균 수준의 밸류에이션입니다.", "info"
    if v < 40: return "다소 고평가 구간.", "warn"
    return "상당히 고평가 구간.", "bad"

def _interp_pbr(v):
    if not np.isfinite(v): return "데이터 없음", "info"
    if v < 1: return "순자산보다 시총이 낮음(저평가 신호).", "good"
    if v < 3: return "적정~보통 수준.", "info"
    if v < 6: return "자산 대비 다소 비싼 편.", "warn"
    return "자산 대비 매우 높은 평가.", "bad"

def _interp_roe(v):
    if not np.isfinite(v): return "데이터 없음", "info"
    if v >= 20: return "자기자본 대비 이익창출력이 매우 우수합니다.", "good"
    if v >= 10: return "양호한 자본효율성입니다.", "good"
    if v >= 5: return "보통 수준의 수익성입니다.", "info"
    if v >= 0: return "수익성이 낮은 편입니다.", "warn"
    return "자기자본 손실(적자) 상태입니다.", "bad"

def _interp_growth(v):
    if not np.isfinite(v): return "데이터 없음", "info"
    if v >= 20: return "고성장 구간입니다.", "good"
    if v >= 5: return "안정적 성장세입니다.", "good"
    if v >= 0: return "저성장 또는 정체 구간입니다.", "warn"
    return "역성장(감소) 구간입니다.", "bad"

def _interp_de(v):
    if not np.isfinite(v): return "데이터 없음", "info"
    if v < 50: return "부채 부담이 낮아 재무가 매우 안정적입니다.", "good"
    if v < 100: return "부채비율이 양호한 수준입니다.", "good"
    if v < 200: return "부채비율이 다소 높습니다.", "warn"
    return "부채비율이 높아 재무 리스크에 유의해야 합니다.", "bad"

_RECO_KR = {
    "strong_buy": ("적극 매수", "good"), "buy": ("매수", "good"),
    "outperform": ("시장수익 상회", "good"), "hold": ("중립(보유)", "warn"),
    "neutral": ("중립", "warn"), "underperform": ("시장수익 하회", "bad"),
    "sell": ("매도", "bad"), "strong_sell": ("적극 매도", "bad"), "none": ("의견 없음", "info"),
}

def _financial_trend_chart(data, is_kr, P, FONT_MONO):
    # 초보자 안내: 연간 실적(매출/영업이익/순이익) 막대 차트입니다.
    # - marker_color: 막대 색상
    # - barmode='group': 막대를 나란히 표시
    # - height, margin, title 배너를 바꾸면 카드형 차트 느낌이 달라집니다.
    fin = data.get("fin")
    if fin is None or not isinstance(fin, pd.DataFrame) or fin.empty: return None
    rev = _get_row(fin, ["Total Revenue", "TotalRevenue", "Revenue", "Operating Revenue"])
    op = _get_row(fin, ["Operating Income", "OperatingIncome", "Operating Income Loss"])
    ni = _get_row(fin, ["Net Income", "NetIncome", "Net Income Common Stockholders"])
    if rev is None and ni is None: return None
    # 최근 4개 연도를 시간순으로 정렬하고 '년' 접미사를 붙여 Plotly가 연도를
    # 날짜축으로 오인해 막대 폭을 거의 0으로 렌더링하는 문제를 방지합니다.
    raw_cols = list(fin.columns)
    try:
        cols = sorted(raw_cols, key=lambda c: pd.Timestamp(c))[-4:]
    except Exception:
        cols = raw_cols[:4][::-1]
    years = []
    for c in cols:
        try:
            year_text = str(pd.Timestamp(c).year)
        except Exception:
            year_text = str(c)[:4]
        years.append(f"{year_text}년")
    # 막대 위치는 0,1,2,3의 숫자 좌표로 고정하고 연도는 ticktext로만 표시합니다.
    # 브라우저/Plotly 버전에 관계없이 날짜축 자동 추론이 개입할 여지를 완전히 제거합니다.
    year_x = list(range(len(years)))

    def series_vals(s):
        if s is None: return [np.nan] * len(cols)
        return [_safe(s.get(c)) for c in cols]
    unit_div = 1e8 if is_kr else 1e9
    unit_lbl = "억원" if is_kr else "B$"
    rev_v = [x / unit_div if np.isfinite(x) else None for x in series_vals(rev)]
    op_v = [x / unit_div if np.isfinite(x) else None for x in series_vals(op)]
    ni_v = [x / unit_div if np.isfinite(x) else None for x in series_vals(ni)]
    # 유효한 실적값이 하나도 없으면 빈 차트를 만들지 않습니다.
    if not any(v is not None and np.isfinite(v) for series in (rev_v, op_v, ni_v) for v in series):
        return None

    fig = go.Figure()
    fig.add_trace(go.Bar(
        name="매출", x=year_x, y=rev_v, marker_color=P["accent"],
        marker_line=dict(color="rgba(255,255,255,0.30)", width=0.8),
        text=[f"{v:,.0f}" if v is not None and np.isfinite(v) else "" for v in rev_v],
        textposition="outside", cliponaxis=False, customdata=years,
        hovertemplate="<b>%{customdata}</b><br>매출: %{y:,.0f}" + unit_lbl + "<extra></extra>"
    ))
    fig.add_trace(go.Bar(
        name="영업이익", x=year_x, y=op_v, marker_color=P["up"],
        marker_line=dict(color="rgba(255,255,255,0.30)", width=0.8),
        text=[f"{v:,.0f}" if v is not None and np.isfinite(v) else "" for v in op_v],
        textposition="outside", cliponaxis=False, customdata=years,
        hovertemplate="<b>%{customdata}</b><br>영업이익: %{y:,.0f}" + unit_lbl + "<extra></extra>"
    ))
    fig.add_trace(go.Bar(
        name="순이익", x=year_x, y=ni_v, marker_color=P["warn"],
        marker_line=dict(color="rgba(255,255,255,0.30)", width=0.8),
        text=[f"{v:,.0f}" if v is not None and np.isfinite(v) else "" for v in ni_v],
        textposition="outside", cliponaxis=False, customdata=years,
        hovertemplate="<b>%{customdata}</b><br>순이익: %{y:,.0f}" + unit_lbl + "<extra></extra>"
    ))
    try:
        _last_year = year_x[-1]
        _last_rev = rev_v[-1] if rev_v else None
        _last_ni = ni_v[-1] if ni_v else None
        _msg = "흑자 기반" if (_last_ni is not None and np.isfinite(_last_ni) and _last_ni > 0) else "이익 안정성 점검"
        if _last_rev is not None and np.isfinite(_last_rev):
            # [CHART_TITLE_SEARCH: 기업 펀더멘털 분석 / 연간 실적 추이] 아래 [BOXPOS_055] 박스/풍선 위치 코드입니다. 이 차트 제목으로 검색하면 바로 찾을 수 있습니다.
            # [BOXPOS_055_FUNDAMENTAL__financial_trend_chart] 기업분석: 최근 실적 풍선 | 위치수정: x/y(기준좌표), ax/ay(화살표 박스 픽셀오프셋), xshift/yshift, xanchor/yanchor를 조정. xref/yref="paper"는 0~1 화면비율, xref/yref="x/y"는 날짜·가격/지표값입니다.
            fig.add_annotation(x=_last_year, y=_last_rev, text=f"📍 최근 실적<br>{_msg}", showarrow=True, arrowhead=2, ax=35, ay=-45, font=dict(size=10, color=P["accent"], family=FONT_MONO), bgcolor="rgba(5,9,17,0.92)", bordercolor=P["accent"], borderwidth=1)
    except Exception:
        pass
    # 연간 실적 막대 차트 스타일
    fig.update_layout(
        template="plotly_dark", height=430, barmode="group", bargap=0.22, bargroupgap=0.08,
        paper_bgcolor="rgba(0,0,0,0)", plot_bgcolor=P["bg_panel"],
        font=dict(color=P["txt"], family=FONT_MONO, size=12),
        margin=dict(l=58, r=28, t=76, b=52),
        title=None, hovermode="x unified",
        # 핵심 수정: 숫자 좌표에 막대를 놓고 연도는 ticktext로만 표시합니다.
        xaxis=dict(
            type="linear", range=[-0.6, max(len(year_x) - 0.4, 0.6)],
            tickmode="array", tickvals=year_x, ticktext=years,
            showgrid=False, tickfont=dict(size=11, color=P["txt"]),
            fixedrange=True,
        ),
        yaxis=dict(
            gridcolor="rgba(255,255,255,0.10)", zeroline=True,
            zerolinecolor="rgba(255,255,255,0.35)", automargin=True,
            title=dict(text=unit_lbl), fixedrange=True,
        ),
        legend=dict(
            orientation="h", x=1.0, xanchor="right", y=1.16, yanchor="bottom",
            bgcolor="rgba(5,9,17,0.68)", bordercolor="rgba(148,163,184,0.22)", borderwidth=1,
        ),
        uniformtext=dict(minsize=8, mode="hide"),
    )
    fig = add_figure_banner(fig, f"연간 실적 추이 (단위: {unit_lbl})", [("매출", P['accent']), ("영업이익", P['up']), ("순이익", P['warn'])], note='최근 4개 연도 성장성과 이익 체력 비교', y=1.16)
    return fig

def _radar_chart(scores, P, FONT_MONO):
    # 초보자 안내: 레이더 차트입니다.
    # - fillcolor: 내부 채우기 색
    # - line color/width: 외곽선 색과 굵기
    # - radialaxis / angularaxis: 눈금/축 글자 스타일
    parts = scores["parts"]
    cats = list(parts.keys())
    vals = [parts[c] if (parts[c] is not None and np.isfinite(parts[c])) else 0 for c in cats]
    fig = go.Figure()
    fig.add_trace(go.Scatterpolar(r=vals + [vals[0]], theta=cats + [cats[0]], fill="toself",
                                  fillcolor="rgba(99,179,237,0.16)", line=dict(color=P["accent"], width=2),
                                  marker=dict(color=P["accent"], size=6),
                                  hovertemplate="%{theta}: %{r:.0f}점<extra></extra>"))
    _avg = float(np.nanmean(vals)) if vals else 0.0
    # [CHART_TITLE_SEARCH: 기업 펀더멘털 분석 / 5대 영역 종합 진단] 아래 [BOXPOS_056] 박스/풍선 위치 코드입니다. 이 차트 제목으로 검색하면 바로 찾을 수 있습니다.
    # [BOXPOS_056_FUNDAMENTAL__radar_chart] 기업분석: 밸류에이션 점수 박스 | 위치수정: x/y(기준좌표), ax/ay(화살표 박스 픽셀오프셋), xshift/yshift, xanchor/yanchor를 조정. xref/yref="paper"는 0~1 화면비율, xref/yref="x/y"는 날짜·가격/지표값입니다.
    fig.add_annotation(x=0.5, y=1.06, xref="paper", yref="paper", showarrow=False, text=f"<b>📍 현재 밸류에이션 점수 {_avg:.0f}</b><br><span style='font-size:10px'>고평가·저평가·재무질 동시 확인</span>", font=dict(size=11, color=P["accent"], family=FONT_MONO), bgcolor="rgba(5,9,17,0.90)", bordercolor=P["accent"], borderwidth=1)
    fig.update_layout(polar=dict(bgcolor="rgba(0,0,0,0)",
                                  radialaxis=dict(visible=True, range=[0, 100], gridcolor="rgba(255,255,255,0.10)", tickfont=dict(color=P["txt2"], size=10)),
                                  angularaxis=dict(tickfont=dict(color=P["txt"], size=12, family=FONT_MONO))),
                      paper_bgcolor="rgba(0,0,0,0)", plot_bgcolor="rgba(0,0,0,0)",
                      height=385, margin=dict(l=30, r=30, t=60, b=30), showlegend=False,
                      font=dict(color=P["txt"], family=FONT_MONO))
    return fig

def _price_range_chart(m, current_price, P, FONT_MONO, unit):
    """52주 저점~고점 범위에서 현재가의 상대 위치를 보여주는 가격 범위 게이지."""
    lo, hi = m["w52_low"], m["w52_high"]
    if not (np.isfinite(lo) and np.isfinite(hi)) or hi <= lo:
        return None

    pos = float(np.clip((current_price - lo) / (hi - lo) * 100, 0, 100))
    _zone = "상단 과열권" if pos >= 80 else "하단 저평가/반등권" if pos <= 25 else "중립권"
    zone_color = P["dn"] if pos >= 80 else P["up"] if pos <= 25 else P["accent"]

    fig = go.Figure()

    # 0~100% 구간을 네 영역으로 나눠 빈 차트처럼 보이지 않는 명확한 가격 게이지를 구성합니다.
    zone_specs = [
        (0, 25, "rgba(16,185,129,0.28)", "저평가/반등"),
        (25, 60, "rgba(56,189,248,0.20)", "중립 하단"),
        (60, 80, "rgba(245,158,11,0.22)", "중립 상단"),
        (80, 100, "rgba(244,63,94,0.26)", "과열/부담"),
    ]
    for x0, x1, fill, label in zone_specs:
        fig.add_shape(
            type="rect", xref="x", yref="y",
            x0=x0, x1=x1, y0=-0.16, y1=0.16,
            fillcolor=fill, line=dict(color="rgba(255,255,255,0.10)", width=1),
            layer="below",
        )
        fig.add_annotation(
            x=(x0 + x1) / 2, y=0.30, xref="x", yref="y",
            text=label, showarrow=False,
            font=dict(size=10, color=P["txt2"], family=FONT_MONO),
        )

    # 전체 범위선과 저점→현재가 진행선을 별도로 그려 현재 위치를 직관적으로 표시합니다.
    fig.add_trace(go.Scatter(
        x=[0, 100], y=[0, 0], mode="lines",
        line=dict(color="rgba(148,163,184,0.65)", width=5),
        hoverinfo="skip", showlegend=False, name="52주 전체 범위",
    ))
    fig.add_trace(go.Scatter(
        x=[0, pos], y=[0, 0], mode="lines",
        line=dict(color=zone_color, width=8),
        hoverinfo="skip", showlegend=False, name="현재가까지의 위치",
    ))

    # 저점/고점 끝단과 현재 위치를 모두 명시적인 마커로 표시합니다.
    fig.add_trace(go.Scatter(
        x=[0, 100], y=[0, 0], mode="markers",
        marker=dict(symbol=["circle", "circle"], size=[11, 11], color=[P["up"], P["dn"]], line=dict(color="#ffffff", width=1.2)),
        text=[f"52주 저점: {lo:,.0f}{unit}", f"52주 고점: {hi:,.0f}{unit}"],
        hovertemplate="%{text}<extra></extra>",
        showlegend=False, name="52주 저점/고점",
    ))
    fig.add_trace(go.Scatter(
        x=[pos], y=[0], mode="markers",
        marker=dict(symbol="diamond", size=20, color=zone_color, line=dict(color="#ffffff", width=1.8)),
        text=[f"현재가 {current_price:,.0f}{unit}<br>52주 범위 위치 {pos:.1f}%<br>판정: {_zone}"],
        hovertemplate="%{text}<extra></extra>",
        showlegend=False, name="현재가 위치",
    ))

    fig.add_annotation(
        x=0, y=-0.32, xref="x", yref="y",
        text=f"저점 {lo:,.0f}{unit}", showarrow=False, xanchor="left",
        font=dict(size=10, color=P["up"], family=FONT_MONO),
    )
    fig.add_annotation(
        x=100, y=-0.32, xref="x", yref="y",
        text=f"고점 {hi:,.0f}{unit}", showarrow=False, xanchor="right",
        font=dict(size=10, color=P["dn"], family=FONT_MONO),
    )
    fig.add_annotation(
        x=pos, y=0, xref="x", yref="y",
        text=f"<b>현재 {pos:.0f}%</b><br>{_zone}",
        showarrow=True, arrowhead=2, arrowsize=0.8, arrowwidth=1.2,
        ax=0, ay=-52,
        font=dict(size=10, color=zone_color, family=FONT_MONO),
        bgcolor="rgba(5,9,17,0.94)", bordercolor=zone_color,
        borderwidth=1.2, borderpad=4,
    )

    fig.update_layout(
        template="plotly_dark", height=245,
        paper_bgcolor="rgba(0,0,0,0)", plot_bgcolor=P["bg_panel"],
        font=dict(color=P["txt"], family=FONT_MONO),
        margin=dict(l=34, r=34, t=76, b=42),
        title=None, showlegend=False, hovermode="closest", hoverdistance=50,
        xaxis=dict(
            range=[-3, 103], showgrid=False, zeroline=False,
            tickmode="array", tickvals=[0, 25, 50, 75, 100],
            ticktext=["0%", "25%", "50%", "75%", "100%"],
            tickfont=dict(size=10, color=P["txt2"]), fixedrange=True,
        ),
        yaxis=dict(range=[-0.50, 0.50], visible=False, fixedrange=True),
    )
    fig = add_figure_banner(
        fig,
        f"52주 가격 밴드 내 현재가 위치 ({pos:.0f}%)",
        [("현재가", zone_color), ("52주 저점", P['up']), ("52주 고점", P['dn'])],
        note=f"현재 구간: {_zone}", y=1.08,
        title_max_chars=34, note_max_chars=26,
    )
    return fig



