def infer_domestic_peers(symbol: str, info: dict, max_peers: int = 6) -> List[str]:
    sym = str(symbol).upper().strip()
    if sym in KOREAN_PEER_MAP_BY_SYMBOL:
        return [x for x in KOREAN_PEER_MAP_BY_SYMBOL[sym] if x != sym][:max_peers]
    sector = str((info or {}).get("sector", ""))
    peers = KOREAN_PEER_FALLBACK_BY_SECTOR.get(sector, [])
    return [x for x in peers if x != sym][:max_peers]

@st.cache_data(show_spinner=False, ttl=6 * 3600)
def fetch_competitor_snapshot(tickers: Tuple[str, ...]) -> pd.DataFrame:
    """경쟁사 핵심 밸류에이션 스냅샷.

    국내 .KS/.KQ 종목은 Yahoo info에서 PER/PBR이 비는 경우가 많아,
    fetch_company_fundamentals + extract_metrics로 재무제표 기반 보정 계산을 수행합니다.
    """
    rows = []
    for tk in tickers:
        try:
            data = fetch_company_fundamentals(tk)
            info = data.get("info", {}) if isinstance(data, dict) else {}
            raw_price = _safe(info.get("currentPrice", info.get("regularMarketPrice")))
            m = extract_metrics(data, raw_price if np.isfinite(raw_price) else np.nan) if data.get("available") else {}
            rows.append({
                "Ticker": tk,
                "기업명": info.get("shortName") or info.get("longName") or tk,
                "섹터": info.get("sector", ""),
                "산업": info.get("industry", ""),
                "시가총액": _safe(m.get("market_cap", info.get("marketCap"))),
                "EV": _safe(m.get("enterprise_value", info.get("enterpriseValue"))),
                "PER": _safe(m.get("per", info.get("trailingPE"))),
                "Forward PER": _safe(m.get("forward_per", info.get("forwardPE"))),
                "PBR": _safe(m.get("pbr", info.get("priceToBook"))),
                "PSR": _safe(m.get("psr", info.get("priceToSalesTrailing12Months"))),
                "EV/EBITDA": _safe(m.get("ev_ebitda", info.get("enterpriseToEbitda"))),
                "ROE(%)": _safe(m.get("roe")),
                "영업이익률(%)": _safe(m.get("op_margin")),
                "매출성장률(%)": _safe(m.get("rev_growth")),
            })
        except Exception:
            continue
    return pd.DataFrame(rows)

def _median_col(df: pd.DataFrame, col: str, min_n: int = 2):
    if df is None or df.empty or col not in df.columns:
        return np.nan
    xs = pd.to_numeric(df[col], errors="coerce")
    xs = xs[(xs > 0) & np.isfinite(xs)]
    return float(xs.median()) if len(xs) >= min_n else np.nan

def compute_company_value_projection(m: dict, domestic_df: pd.DataFrame, overseas_df: pd.DataFrame, is_kr: bool) -> Dict:
    price = _safe(m.get("price")); shares = _safe(m.get("shares")); mcap = _safe(m.get("market_cap"))
    debt = _safe(m.get("total_debt"), 0.0); cash = _safe(m.get("total_cash"), 0.0)
    ev = _safe(m.get("enterprise_value")); revenue = _safe(m.get("total_revenue")); ebitda = _safe(m.get("ebitda")); fcf = _safe(m.get("fcf"))
    eps = _safe(m.get("eps")); fwd_eps = _safe(m.get("forward_eps"))
    if not np.isfinite(mcap) and np.isfinite(price) and np.isfinite(shares): mcap = price * shares
    net_debt = (debt if np.isfinite(debt) else 0) - (cash if np.isfinite(cash) else 0)
    if not np.isfinite(ev) and np.isfinite(mcap): ev = mcap + net_debt
    all_peers = pd.concat([domestic_df if isinstance(domestic_df, pd.DataFrame) else pd.DataFrame(), overseas_df if isinstance(overseas_df, pd.DataFrame) else pd.DataFrame()], ignore_index=True)
    peer_per = _median_col(all_peers, "Forward PER")
    if not np.isfinite(peer_per): peer_per = _median_col(all_peers, "PER")
    peer_ev_ebitda = _median_col(all_peers, "EV/EBITDA"); peer_psr = _median_col(all_peers, "PSR")
    growths = [safe_float(m.get(k), np.nan)/100 for k in ["rev_growth", "earn_growth", "earn_q_growth"] if np.isfinite(safe_float(m.get(k), np.nan))]
    peer_growth = _median_col(all_peers, "매출성장률(%)", min_n=1)
    if np.isfinite(peer_growth): growths.append(peer_growth/100)
    growth = float(np.clip(np.nanmedian(growths) if growths else 0.04, -0.05, 0.16))
    discount = 0.095 if is_kr else 0.085; terminal_g = 0.020 if is_kr else 0.025
    cur_prices, cur_reasons = [], []
    if np.isfinite(eps) and eps > 0 and np.isfinite(peer_per): cur_prices.append(eps*peer_per); cur_reasons.append(f"EPS×Peer PER {peer_per:.1f}")
    if np.isfinite(revenue) and revenue > 0 and np.isfinite(shares) and shares > 0 and np.isfinite(peer_psr): cur_prices.append((revenue/shares)*peer_psr); cur_reasons.append(f"SPS×Peer PSR {peer_psr:.1f}")
    if np.isfinite(ebitda) and ebitda > 0 and np.isfinite(shares) and shares > 0 and np.isfinite(peer_ev_ebitda):
        eq = ebitda*peer_ev_ebitda-net_debt
        if eq > 0: cur_prices.append(eq/shares); cur_reasons.append(f"EBITDA×Peer EV/EBITDA {peer_ev_ebitda:.1f}")
    current_fair = float(np.nanmean(cur_prices)) if cur_prices else np.nan
    fut_prices, fut_reasons = [], []
    base_eps = fwd_eps if np.isfinite(fwd_eps) and fwd_eps > 0 else eps
    if np.isfinite(base_eps) and base_eps > 0 and np.isfinite(peer_per): fut_prices.append(base_eps*((1+growth)**3)*peer_per); fut_reasons.append("3년 EPS 성장×Peer PER")
    if np.isfinite(ebitda) and ebitda > 0 and np.isfinite(peer_ev_ebitda) and np.isfinite(shares) and shares > 0:
        eq = ebitda*((1+growth)**3)*peer_ev_ebitda-net_debt
        if eq > 0: fut_prices.append(eq/shares); fut_reasons.append("3년 EBITDA 성장×Peer EV/EBITDA")
    if np.isfinite(fcf) and fcf > 0 and np.isfinite(shares) and shares > 0 and discount > terminal_g:
        pv=0.0; f=fcf
        for y in range(1,6):
            f *= (1+growth); pv += f/((1+discount)**y)
        tv = f*(1+terminal_g)/(discount-terminal_g); eq = pv + tv/((1+discount)**5) - net_debt
        if eq > 0: fut_prices.append(eq/shares); fut_reasons.append("FCF DCF")
    future_fair = float(np.nanmean(fut_prices)) if fut_prices else np.nan
    return {"market_cap": mcap, "enterprise_value": ev, "net_debt": net_debt, "current_fair_price": current_fair, "future_fair_price": future_fair, "growth": growth, "discount": discount, "terminal_g": terminal_g, "peer_per": peer_per, "peer_ev_ebitda": peer_ev_ebitda, "peer_psr": peer_psr, "current_reasons": cur_reasons, "future_reasons": fut_reasons, "upside_current": (current_fair/price-1)*100 if np.isfinite(current_fair) and np.isfinite(price) and price>0 else np.nan, "upside_future": (future_fair/price-1)*100 if np.isfinite(future_fair) and np.isfinite(price) and price>0 else np.nan}

def render_company_value_and_peer_section(symbol: str, info: dict, m: dict, display_name: str, is_kr: bool, unit: str, P, FONT_MONO, fmt_price, abbreviate_num, render_section_title, render_dashboard_cards, render_info_lines, compact_mode=False):
    render_section_title("⑥ 현재/미래 기업가치 & 경쟁사 비교", "EV·시가총액·Peer Multiple·DCF를 결합해 현재 기업가치와 미래 기업가치를 추정하고, 국내/해외 경쟁사와 비교합니다.")
    domestic_peers = infer_domestic_peers(symbol, info)
    overseas_peers = infer_overseas_peers(symbol, info) if 'infer_overseas_peers' in globals() else []
    with st.spinner("국내/해외 경쟁사 밸류에이션 수집 중..."):
        domestic_df = fetch_competitor_snapshot(tuple(domestic_peers)) if domestic_peers else pd.DataFrame()
        overseas_df = fetch_peer_snapshot(tuple(overseas_peers)) if overseas_peers and 'fetch_peer_snapshot' in globals() else pd.DataFrame()

    # Peer의 기업명/섹터/산업 정보가 누락되는 경우 현재 조회 기업의 분류로 보정 표시합니다.
    parent_sector = str(info.get("sector", "") or "동일 섹터 추정")
    parent_industry = str(info.get("industry", "") or "동일 산업 추정")
    for _df in [domestic_df, overseas_df]:
        if isinstance(_df, pd.DataFrame) and not _df.empty:
            for _col, _fallback in [("기업명", None), ("섹터", parent_sector), ("산업", parent_industry)]:
                if _col not in _df.columns:
                    _df[_col] = _fallback if _fallback is not None else "N/A"
                else:
                    _df[_col] = _df[_col].replace([None, "", "nan", "None"], np.nan)
                    _df[_col] = _df[_col].fillna(_fallback if _fallback is not None else _df.get("Ticker", "N/A"))
    val = compute_company_value_projection(m, domestic_df, overseas_df, is_kr)
    cur_status = "good" if np.isfinite(val["upside_current"]) and val["upside_current"] >= 15 else "warn" if np.isfinite(val["upside_current"]) and val["upside_current"] >= -10 else "bad" if np.isfinite(val["upside_current"]) else "info"
    fut_status = "good" if np.isfinite(val["upside_future"]) and val["upside_future"] >= 25 else "warn" if np.isfinite(val["upside_future"]) and val["upside_future"] >= -5 else "bad" if np.isfinite(val["upside_future"]) else "info"
    render_dashboard_cards([
        {"icon": "🏢", "title": "현재 시장 기업가치", "value": fmt_money(val["enterprise_value"], is_kr), "caption": f"시총 {fmt_money(val['market_cap'], is_kr)} / 순차입금 {fmt_money(val['net_debt'], is_kr)}", "help": "EV = 시가총액 + 순차입금", "status": "info"},
        {"icon": "💎", "title": "현재 적정 주가", "value": f"{fmt_price(val['current_fair_price'])}{unit}" if np.isfinite(val["current_fair_price"]) else "N/A", "caption": f"현재가 대비 {val['upside_current']:+.1f}%" if np.isfinite(val["upside_current"]) else "상승여력 N/A", "message": ", ".join(val.get("current_reasons", [])[:2]), "status": cur_status},
        {"icon": "🔮", "title": "미래 적정 주가", "value": f"{fmt_price(val['future_fair_price'])}{unit}" if np.isfinite(val["future_fair_price"]) else "N/A", "caption": f"3년 성장가정 {val['growth']*100:.1f}% / 현재가 대비 {val['upside_future']:+.1f}%" if np.isfinite(val["upside_future"]) else f"3년 성장가정 {val['growth']*100:.1f}%", "message": ", ".join(val.get("future_reasons", [])[:2]), "status": fut_status},
        {"icon": "🌐", "title": "Peer 중앙 배수", "value": f"PER {val['peer_per']:.1f}" if np.isfinite(val["peer_per"]) else "PER N/A", "caption": f"EV/EBITDA {val['peer_ev_ebitda']:.1f} / PSR {val['peer_psr']:.1f}" if np.isfinite(val["peer_ev_ebitda"]) else "EV/EBITDA N/A", "status": "info"},
    ], cols_per_row=(1 if compact_mode else 4))
    render_info_lines("기업가치 해석", [
        f"현재 시장 EV는 {fmt_money(val['enterprise_value'], is_kr)}입니다.",
        f"경쟁사 배수 기반 현재 적정 주가는 {fmt_price(val['current_fair_price'])}{unit}입니다." if np.isfinite(val["current_fair_price"]) else "현재 적정 주가 산출 데이터가 부족합니다.",
        f"미래 적정 주가는 3년 성장률 {val['growth']*100:.1f}%를 가정해 {fmt_price(val['future_fair_price'])}{unit}로 계산됩니다." if np.isfinite(val["future_fair_price"]) else "미래 적정 주가 산출 데이터가 부족합니다.",
        "국내/해외 Peer는 산업 구조와 성장률 차이를 감안해 참고용으로 해석해야 합니다.",
    ], icon="🧭")
    def format_peer(df):
        if df is None or df.empty:
            return pd.DataFrame()
        out = df.copy()
        # 시가총액 기준 내림차순 정렬: 큰 회사 → 작은 회사
        if "시가총액" in out.columns:
            out["_mcap_raw"] = pd.to_numeric(out["시가총액"], errors="coerce")
            out = out.sort_values("_mcap_raw", ascending=False, na_position="last").reset_index(drop=True)
        else:
            out["_mcap_raw"] = np.nan

        fx_krw_usd = 1380.0  # 표시용 환율 가정. 정밀 환산보다 비교 가독성이 목적.
        def is_kr_ticker(tk):
            t = str(tk).upper()
            return t.endswith(".KS") or t.endswith(".KQ")
        def fmt_dual_cap(v, tk):
            f = _safe(v)
            if not np.isfinite(f) or f <= 0:
                return "자료없음"
            if is_kr_ticker(tk):
                krw_eok = f / 1e8
                usd_eok = (f / fx_krw_usd) / 1e8
            else:
                usd_eok = f / 1e8
                krw_eok = (f * fx_krw_usd) / 1e8
            return f"{krw_eok:,.0f}억원({usd_eok:,.0f}억불)"
        def fmt_ratio(x, kind="ratio", roe=None):
            f = _safe(x)
            if np.isfinite(f) and f > 0:
                return f"{f:.2f}"
            if kind == "per":
                r = _safe(roe)
                if np.isfinite(r) and r < 0:
                    return "적자"
                return "이익없음/자료없음"
            if kind == "forward":
                return "추정없음"
            if kind == "ev_ebitda":
                return "EBITDA없음/자료없음"
            return "자료없음"
        if "Ticker" not in out.columns:
            out["Ticker"] = ""
        if "시가총액" in out.columns:
            out["시가총액"] = [fmt_dual_cap(v, tk) for v, tk in zip(out["시가총액"], out["Ticker"])]
        if "EV" in out.columns:
            out["EV"] = [fmt_dual_cap(v, tk) for v, tk in zip(out["EV"], out["Ticker"])]
        if "PER" in out.columns:
            roe_series = out["ROE(%)"] if "ROE(%)" in out.columns else pd.Series([np.nan]*len(out))
            out["PER"] = [fmt_ratio(v, "per", r) for v, r in zip(out["PER"], roe_series)]
        if "Forward PER" in out.columns:
            out["Forward PER"] = out["Forward PER"].apply(lambda x: fmt_ratio(x, "forward"))
        if "EV/EBITDA" in out.columns:
            out["EV/EBITDA"] = out["EV/EBITDA"].apply(lambda x: fmt_ratio(x, "ev_ebitda"))
        for col in ["PBR", "PSR", "ROE(%)", "영업이익률(%)", "매출성장률(%)"]:
            if col in out.columns:
                out[col] = out[col].apply(lambda x: f"{_safe(x):.2f}" if np.isfinite(_safe(x)) else "자료없음")
        for col in ["기업명", "섹터", "산업", "거래소"]:
            if col in out.columns:
                out[col] = out[col].replace([None, "", "nan", "None", np.nan], "자료없음")
        return out.drop(columns=["_mcap_raw"], errors="ignore")
    # Peer 데이터 품질 팩트체크
    def valid_ratio_count(df, cols):
        if df is None or df.empty:
            return 0, 0
        total = len(df) * len(cols)
        ok = 0
        for col in cols:
            if col in df.columns:
                vals = pd.to_numeric(df[col], errors="coerce")
                ok += int(((vals > 0) & np.isfinite(vals)).sum())
        return ok, total
    d_ok, d_total = valid_ratio_count(domestic_df, ["PER", "PBR", "PSR", "EV/EBITDA"])
    o_ok, o_total = valid_ratio_count(overseas_df, ["PER", "PBR", "PSR", "EV/EBITDA"])
    render_dashboard_cards([
        {"icon": "🇰🇷", "title": "국내 Peer 데이터 품질", "value": f"{d_ok}/{d_total}" if d_total else "N/A", "caption": "PER/PBR/PSR/EV·EBITDA 유효값", "status": "good" if d_total and d_ok/d_total >= 0.55 else "warn" if d_total else "info"},
        {"icon": "🌎", "title": "해외 Peer 데이터 품질", "value": f"{o_ok}/{o_total}" if o_total else "N/A", "caption": "PER/PBR/PSR/EV·EBITDA 유효값", "status": "good" if o_total and o_ok/o_total >= 0.55 else "warn" if o_total else "info"},
    ], cols_per_row=(1 if compact_mode else 2))

    st.markdown("**🇰🇷 국내 경쟁사 비교**")
    dshow = format_peer(domestic_df)
    if not dshow.empty:
        st.dataframe(dshow, width='stretch', hide_index=True)
        st.caption("국내 Peer의 PER/PBR이 N/A인 경우 Yahoo 원천 데이터 또는 해당 기업의 순손실/자본잠식/재무제표 누락 가능성이 있습니다. 가능한 경우 재무제표 기반으로 보정 계산했습니다.")
    else:
        st.info("국내 경쟁사 데이터를 충분히 가져오지 못했습니다.")

    st.markdown("**🌎 해외 경쟁사 비교**")
    oshow = format_peer(overseas_df)
    if not oshow.empty:
        st.dataframe(oshow, width='stretch', hide_index=True)
    else:
        st.info("해외 경쟁사 데이터를 충분히 가져오지 못했습니다.")

def render_company_analysis_tab(symbol, display_name, is_kr, unit, current_price,
                                P, FONT_MONO, fmt_price, abbreviate_num, esc,
                                render_section_title, render_dashboard_cards,
                                render_kpi_cards, render_report_card, render_info_lines,
                                compact_mode=False):
    render_section_title("기업 펀더멘털 분석", "밸류에이션·수익성·성장성·재무안정성·배당·애널리스트 컨센서스를 종합해 기업의 '체력'을 진단합니다.")
    with st.spinner("기업 재무 데이터 수집 중..."):
        data = fetch_company_fundamentals(symbol)
    if not data.get("available"):
        st.warning(f"📭 '{display_name}' 의 펀더멘털 데이터를 충분히 가져오지 못했습니다.\n\n"
                   "원인: ① 일부 해외/소형주·암호화폐는 재무 공시가 없음 ② yfinance 일시적 제한 ③ 네트워크 문제.\n"
                   "잠시 후 다시 시도하거나, 6자리 코드(국내) / 정확한 티커(해외)로 조회해 보세요.")
        return
    info = data.get("info", {}) or {}
    m = extract_metrics(data, current_price)
    scores = compute_fundamental_scores(m)
    cp = m["price"] if np.isfinite(m["price"]) else current_price
    grade_status = ("good" if scores["eng"] in ["A+", "A"] else
                    "warn" if scores["eng"] in ["B", "C"] else
                    "bad" if scores["eng"] in ["D", "E"] else "info")
    total_txt = f"{scores['total']:.0f}점" if np.isfinite(scores["total"]) else "N/A"
    render_dashboard_cards([
        {"icon": "🏅", "title": "펀더멘털 종합 등급",
         "value": f"{scores['grade']} ({scores['eng']})", "caption": f"종합점수 {total_txt} / 100",
         "help": "밸류에이션·수익성·성장성·안정성·배당 5개 영역을 가중합산한 펀더멘털 종합 등급입니다.",
         "message": scores["desc"], "status": grade_status},
        {"icon": "💰", "title": "시가총액",
         "value": fmt_money(m["market_cap"], is_kr),
         "caption": f"발행주식 {abbreviate_num(m['shares'])}주" if np.isfinite(m["shares"]) else "발행주식 N/A",
         "help": "기업의 시장 가치 총액입니다.", "message": f"베타 {fmt_num(m['beta'])}" if np.isfinite(m["beta"]) else "", "status": "info"},
        {"icon": "🏢", "title": "섹터 / 산업",
         "value": str(info.get("sector", "N/A")), "caption": str(info.get("industry", "")),
         "help": "기업이 속한 산업 분류입니다.", "status": "info"},
    ], cols_per_row=(1 if compact_mode else 3))
    render_section_title("핵심 투자지표")
    
    # ── [HTS 고도화] 핵심 투자 지표별 산출식, 수치대입, 전문가 실시간 평가 빌드 ──
    # PER 도움말
    per_val_txt = fmt_num(m["per"])
    per_help = f"📊 **PER (Price to Earnings Ratio - 주가수익비율): {per_val_txt}배**\n\n"
    per_help += "#### 📊 1. 공식 및 실제 수치 대입 연산\n"
    per_help += "기업의 주가가 1주당 벌어들이는 이익(EPS)의 몇 배로 거래되고 있는지를 나타냅니다.\n"
    per_help += "- 공식: `PER` = `현재 주가` ÷ `주당순이익(EPS)`\n"
    per_help += f"  - 대입: `{fmt_price(cp)}{unit}` ÷ `{fmt_num(m['eps'])}{unit}` = **{per_val_txt} 배**\n"
    per_help += f"  - 선행 PER (Forward PER) = **{fmt_num(m['forward_per'])} 배** (예상 EPS 기준)\n\n"
    per_help += "#### 👨‍🔬 2. 주식 전문가 입장의 평가\n"
    if np.isfinite(m["per"]):
        if m["per"] < 12:
            per_help += "🟢 **[평가: 절대 저평가]** PER 배수가 12배 미만으로 시장 및 동종업계 대비 **매우 매력적인 저평가 상태**입니다. 실적의 지속성만 입증된다면 하방 경직성이 보장되는 우수한 안전 마진을 가지고 있습니다."
        elif m["per"] > 30:
            per_help += "🔴 **[평가: 성장 프리미엄/고평가]** PER 배수가 30배 초과로 시장 평균 대비 **고평가 경계선**에 진입했습니다. 미래 매출 및 이익 성장성(성장률)이 가파르게 확인되지 않는다면 주가 급락 이격조정 리스크가 있습니다."
        else:
            per_help += "🟡 **[평가: 적정 수준 가치]** 주가 대비 이익률이 시장 평균 범위 내에서 **안정적이고 적정 수준의 멀티플**을 부여받고 있습니다. 이 경우 재무 안정성과 수급 흐름 위주의 판단이 타당합니다."
    else:
        per_help += "적용 가능한 PER 데이터가 부족합니다."

    # PBR 도움말
    pbr_val_txt = fmt_num(m["pbr"])
    pbr_help = f"🏦 **PBR (Price to Book Ratio - 주가순자산비율): {pbr_val_txt}배**\n\n"
    pbr_help += "#### 📊 1. 공식 및 실제 수치 대입 연산\n"
    pbr_help += "기업의 현재 주가가 기업 청산 가치인 1주당 순자산(BPS) 대비 몇 배 수준인지를 측정합니다.\n"
    pbr_help += "- 공식: `PBR` = `현재 주가` ÷ `주당순자산(BPS)`\n"
    per_bps_temp = m['book_value'] if np.isfinite(m['book_value']) else 1.0
    pbr_help += f"  - 대입: `{fmt_price(cp)}{unit}` ÷ `{fmt_price(per_bps_temp)}{unit}` = **{pbr_val_txt} 배**\n\n"
    pbr_help += "#### 👨‍🔬 2. 주식 전문가 입장의 평가\n"
    if np.isfinite(m["pbr"]):
        if m["pbr"] < 1.0:
            pbr_help += "🟢 **[평가: 자산가치 대비 극심한 저평가]** PBR 배수가 1.0배 미만으로, 현재 주가가 **청산가치에도 미치지 못하는 극도의 저평가 상태**입니다. 자산 가치의 훼손 가능성이 없다면 가치주 투자 관점에서 훌륭한 매수 기회입니다."
        elif m["pbr"] > 4.0:
            pbr_help += "🔴 **[평가: 무형자산 가치 집중형/고평가]** PBR 배수가 4.0배 이상으로 높은 수준입니다. 유형 자산보다 기술력, 브랜드, 플랫폼 등 **무형자산의 성장 프리미엄**이 주가에 크게 반영되어 있으므로, ROE 등 수익성 지표를 필히 연계해 보아야 합니다."
        else:
            pbr_help += "🟡 **[평가: 무난한 자산 배수]** 장부가치 비율이 무난한 정상 궤도 내에 있습니다. 급격한 지지선 붕괴 위험이 낮으며 평이한 지지력을 보입니다."
    else:
        pbr_help += "적용 가능한 PBR 데이터가 부족합니다."

    # ROE 도움말
    roe_val_txt = fmt_pct(m["roe"])
    roe_help = f"📈 **ROE (Return On Equity - 자기자본이익률): {roe_val_txt}**\n\n"
    roe_help += "#### 📊 1. 공식 및 실제 수치 대입 연산\n"
    roe_help += "주주들이 투자한 자기자본을 활용해 기업이 1년에 몇 %의 영업 성과 및 순이익을 창출했는지 측정하는 **최우선 수익성 지표**입니다.\n"
    roe_help += "- 공식: `ROE` = (순이익 ÷ 자기자본) × 100%\n"
    roe_help += f"  - 계산 결과: **{roe_val_txt}** (자기자본 대비 이 비율만큼의 복리 이익 창출)\n\n"
    roe_help += "#### 👨‍🔬 2. 주식 전문가 입장의 평가\n"
    if np.isfinite(m["roe"]):
        if m["roe"] >= 15.0:
            roe_help += "🟢 **[평가: 초우량 자본 효율성]** ROE가 15% 이상으로 **주주 자금 활용 능력이 매우 막강**한 초우량 수익성 기업입니다. 이런 높은 자본 효율성은 워렌 버핏이 가장 선호하는 기업 유형에 해당하며, 고마진 독과점 사업 모델을 지니고 있을 확률이 큽니다."
        elif m["roe"] < 6.0:
            roe_help += "🔴 **[평가: 자본 효율성 취약]** ROE가 6% 미만으로 **은행 예금 금리 수준에도 미치지 못하는 낮은 자본 운영 상태**입니다. 사업 모델의 근본적인 경쟁력 약화 상태일 수 있으며, 개선 징후가 없는 한 주가 멀티플의 저평가가 해소되기 어렵습니다."
        else:
            roe_help += "🟡 **[평가: 평균적 자본 운영]** 6%~15%의 평균적인 자본 효율성을 보입니다. 자본 효율성이 하향 추세가 아닌 횡보/우상향하고 있는지 시계열을 관찰하는 것이 좋습니다."
    else:
        roe_help += "적용 가능한 ROE 데이터가 부족합니다."

    # 배당수익률 도움말
    div_val_txt = fmt_pct(m["div_yield"])
    div_help = f"💵 **배당수익률 (Dividend Yield): {div_val_txt}**\n\n"
    div_help += "#### 📊 1. 공식 및 실제 수치 대입 연산\n"
    div_help += "현재 주가 대비 1년간 주주에게 환원하는 배당금의 현금 비율을 측정하는 주주환원 지표입니다.\n"
    div_help += "- 공식: `배당수익률` = `주당 연간 배당금` ÷ `현재가` × 100%\n"
    div_help += f"  - 계산 결과: **{div_val_txt}**\n\n"
    div_help += "#### 👨‍🔬 2. 주식 전문가 입장의 평가\n"
    if np.isfinite(m["div_yield"]):
        if m["div_yield"] >= 4.5:
            div_help += "🟢 **[평가: 매력적인 고배당 메리트]** 배당수익률이 4.5% 이상으로, **강력한 주주환원과 하방 주가 경직성**을 제공해 주는 고배당 매력주입니다. 금리 인하기나 약세장에서 훌륭한 피난처가 되며 복리 투자에 매우 유리합니다."
        elif m["div_yield"] == 0:
            div_help += "🟡 **[평가: 무배당/재투자형 성장주]** 배당 성향이 전혀 없습니다. 벌어들인 이익을 배당으로 주는 대신 **연구 개발(R&D)이나 시설 투자에 재투자하여 기업 가치를 높이려는 전형적인 고성장주**에 가깝습니다. 주가 상승을 통한 자본 이득에 집중하십시오."
        else:
            div_help += "🟡 **[평가: 일반 배당금 수준]** 평이한 시장 평균 수준의 배당 흐름입니다. 주주 환원 성향이 견조한지 점검용으로 좋습니다."
    else:
        div_help += "적용 가능한 배당 데이터가 부족합니다."

    # EPS 도움말
    eps_val_txt = f"{fmt_num(m['eps'])}{unit}"
    eps_help = f"🏅 **EPS (Earnings Per Share - 주당순이익): {eps_val_txt}**\n\n"
    eps_help += "#### 📊 1. 공식 및 실제 수치 대입 연산\n"
    eps_help += "기업이 발행한 주식 1주가 벌어들인 순이익 크기로, 가치 평가의 가장 원초적인 분모 가격입니다.\n"
    eps_help += "- 공식: `EPS` = `당기순이익` ÷ `총 발행주식수`\n"
    eps_help += f"  - 계산 결과: **{eps_val_txt}**\n\n"
    eps_help += "#### 👨‍🔬 2. 주식 전문가 입장의 평가\n"
    if np.isfinite(m["eps"]):
        if m["eps"] > 0:
            eps_help += "🟢 **[평가: 흑자 지속 구조]** 주당순이익이 플러스를 유지하여 **영업 흑자 펀더멘털**을 매끄럽게 유지하고 있습니다. 이 EPS가 전분기, 전년 동기 대비 우상향하고 있다면 강력한 이익 성장 사이클에 진입한 것입니다."
        else:
            eps_help += "🔴 **[평가: 적자 전환 리스크]** 주당순이익이 마이너스 상태로 **당기순손실(적자) 상태**입니다. 사업의 마진 훼손이나 일시적 대규모 비용 처리가 일어난 것인지 확인해야 하며, 밸류에이션 평가가 극도로 어렵습니다."
    else:
        eps_help += "적용 가능한 EPS 데이터가 부족합니다."

    render_kpi_cards([
        {"title": "현재가", "value": f"{fmt_price(cp)}{unit}", "help": f"야후파이낸스를 통해 {local_now_str} 기준 실시간 연산된 주가입니다.", "mode": "text"},
        {"title": "PER", "value": per_val_txt, "help": per_help, "mode": "text"},
        {"title": "PBR", "value": pbr_val_txt, "help": pbr_help, "mode": "text"},
        {"title": "ROE", "value": roe_val_txt, "help": roe_help, "mode": "text"},
        {"title": "배당수익률", "value": div_val_txt, "help": div_help, "mode": "text"},
        {"title": "EPS", "value": eps_val_txt, "help": eps_help, "mode": "text"},
    ], cols_per_row=(2 if compact_mode else 6))
    rng_fig = _price_range_chart(m, cp, P, FONT_MONO, unit)
    if rng_fig is not None:
        render_draggable_plotly_chart(rng_fig, use_container_width=True)
        render_chart_box_meaning_panel("fundamental_range", expanded=False, technical_lines=[f"현재가: {fmt_price(cp)}{unit}", f"52주 저점: {fmt_price(m.get('w52_low', np.nan))}{unit}", f"52주 고점: {fmt_price(m.get('w52_high', np.nan))}{unit}"], conclusion="현재 주가가 52주 범위에서 어느 정도 부담 구간인지 확인합니다.")
        st.divider()
    render_section_title("5대 영역 종합 진단")
    cL, cR = st.columns([1, 1])
    with cL:
        render_draggable_plotly_chart(_radar_chart(scores, P, FONT_MONO), use_container_width=True)
        render_chart_box_meaning_panel("fundamental_radar", expanded=False, technical_lines=[f"종합 펀더멘털 점수: {scores.get('total', 0):.0f}점", "5대 영역 중 약한 축을 먼저 점검해야 합니다."], conclusion="기업의 체력과 밸류에이션 균형을 확인합니다.")
        st.divider()
    with cR:
        for name, sc in scores["parts"].items():
            with st.container(border=True):
                t1, t2 = st.columns([3, 1])
                t1.markdown(f"**{name}**")
                t2.markdown(f"**{sc:.0f}점**" if (sc is not None and np.isfinite(sc)) else "**N/A**")
                st.progress(max(0.0, min(100.0, float(sc))) / 100.0 if (sc is not None and np.isfinite(sc)) else 0.0)
    # 밸류에이션
    render_section_title("① 밸류에이션 (Valuation)")
    per_msg, per_st = _interp_per(m["per"])
    pbr_msg, pbr_st = _interp_pbr(m["pbr"])
    render_dashboard_cards([
        {"icon": "📊", "title": "PER", "value": fmt_num(m["per"]), "caption": f"선행 PER {fmt_num(m['forward_per'])}",
         "help": "이익 대비 주가.", "message": per_msg, "status": per_st},
        {"icon": "🏦", "title": "PBR", "value": fmt_num(m["pbr"]), "caption": f"BPS {fmt_num(m['book_value'])}",
         "help": "순자산 대비 주가.", "message": pbr_msg, "status": pbr_st},
        {"icon": "💵", "title": "PSR", "value": fmt_num(m["psr"]), "caption": f"EV/Revenue {fmt_num(m['ev_rev'])}",
         "help": "매출 대비 주가.", "message": "매출 대비 저평가 신호." if (np.isfinite(m["psr"]) and m["psr"] < 1.5) else "매출 대비 보통~고평가." if np.isfinite(m["psr"]) else "데이터 없음",
         "status": "good" if (np.isfinite(m["psr"]) and m["psr"] < 1.5) else "warn" if np.isfinite(m["psr"]) else "info"},
        {"icon": "⚖️", "title": "EV/EBITDA · PEG", "value": fmt_num(m["ev_ebitda"]), "caption": f"PEG {fmt_num(m['peg'])}",
         "help": "EV/EBITDA는 기업가치 대비 영업현금창출력.", "status": "good" if (np.isfinite(m["peg"]) and 0 < m["peg"] < 1.0) else "info"},
    ], cols_per_row=(1 if compact_mode else 4))
    # 수익성
    render_section_title("② 수익성 (Profitability)")
    roe_msg, roe_st = _interp_roe(m["roe"])
    render_dashboard_cards([
        {"icon": "🔥", "title": "ROE", "value": fmt_pct(m["roe"]), "caption": f"ROA {fmt_pct(m['roa'])}",
         "help": "자기자본 대비 순이익.", "message": roe_msg, "status": roe_st},
        {"icon": "🏭", "title": "영업이익률", "value": fmt_pct(m["op_margin"]), "caption": f"매출총이익률 {fmt_pct(m['gross_margin'])}",
         "help": "본업으로 버는 마진.", "status": "good" if (np.isfinite(m["op_margin"]) and m["op_margin"] >= 15) else "warn" if np.isfinite(m["op_margin"]) else "info"},
        {"icon": "💎", "title": "순이익률", "value": fmt_pct(m["net_margin"]), "caption": f"EBITDA 마진 {fmt_pct(m['ebitda_margin'])}",
         "help": "최종적으로 손에 남는 이익률입니다.", "status": "good" if (np.isfinite(m["net_margin"]) and m["net_margin"] >= 10) else "warn" if np.isfinite(m["net_margin"]) else "info"},
    ], cols_per_row=(1 if compact_mode else 3))
    # 성장성
    render_section_title("③ 성장성 (Growth)")
    rg_msg, rg_st = _interp_growth(m["rev_growth"])
    eg_msg, eg_st = _interp_growth(m["earn_growth"])
    render_dashboard_cards([
        {"icon": "📈", "title": "매출 성장률 (YoY)", "value": fmt_pct(m["rev_growth"], signed=True),
         "caption": "전년 대비 매출 증감", "help": "외형 성장 속도입니다.", "message": rg_msg, "status": rg_st},
        {"icon": "🚀", "title": "이익 성장률 (YoY)", "value": fmt_pct(m["earn_growth"], signed=True),
         "caption": f"분기 이익성장 {fmt_pct(m['earn_q_growth'], signed=True)}", "help": "이익 증가 속도입니다.",
         "message": eg_msg, "status": eg_st},
        {"icon": "🧭", "title": "성장 vs 밸류 (PEG)", "value": fmt_num(m["peg"]),
         "caption": "성장 대비 PER", "help": "PEG = PER ÷ 이익성장률. 1 이하면 성장 대비 저평가.",
         "status": "good" if (np.isfinite(m["peg"]) and 0 < m["peg"] < 1) else "info"},
    ], cols_per_row=(1 if compact_mode else 3))
    # 재무 안정성
    render_section_title("④ 재무 안정성 (Financial Health)")
    de_msg, de_st = _interp_de(m["debt_to_equity"])
    cr = m["current_ratio"]
    render_dashboard_cards([
        {"icon": "🏗", "title": "부채비율 (D/E)", "value": fmt_pct(m["debt_to_equity"]) if np.isfinite(m["debt_to_equity"]) else "N/A",
         "caption": f"총부채 {fmt_money(m['total_debt'], is_kr)}", "help": "자기자본 대비 부채.",
         "message": de_msg, "status": de_st},
        {"icon": "💧", "title": "유동/당좌비율", "value": fmt_num(cr) if np.isfinite(cr) else "N/A",
         "caption": f"당좌비율 {fmt_num(m['quick_ratio'])}", "help": "단기 부채 상환 능력.",
         "status": "good" if (np.isfinite(cr) and cr >= 1.5) else "warn" if np.isfinite(cr) else "info"},
        {"icon": "🏦", "title": "현금 & 현금흐름", "value": fmt_money(m["total_cash"], is_kr),
         "caption": f"잉여현금흐름 {fmt_money(m['fcf'], is_kr)}", "help": "보유 현금과 잉여현금흐름(FCF).",
         "status": "good" if (np.isfinite(m["fcf"]) and m["fcf"] > 0) else "warn" if np.isfinite(m["fcf"]) else "info"},
    ], cols_per_row=(1 if compact_mode else 3))
    # 배당
    render_section_title("⑤ 배당 (Dividend)")
    has_div = np.isfinite(m["div_yield"]) and m["div_yield"] > 0
    if has_div:
        payout_ok = np.isfinite(m["payout"]) and 0 < m["payout"] <= 70
        render_dashboard_cards([
            {"icon": "💸", "title": "배당수익률", "value": fmt_pct(m["div_yield"]),
             "caption": f"주당 배당금 {fmt_num(m['div_rate'])}", "help": "연 배당 ÷ 주가.",
             "status": "good" if m["div_yield"] >= 3 else "info"},
            {"icon": "🔁", "title": "배당성향 (Payout)", "value": fmt_pct(m["payout"]),
             "caption": f"5년 평균 배당수익률 {fmt_num(m['div_5y_avg'])}%", "help": "순이익 중 배당으로 지급하는 비율.",
             "status": "good" if payout_ok else "warn" if np.isfinite(m["payout"]) else "info"},
        ], cols_per_row=(1 if compact_mode else 2))
    else:
        st.info("이 기업은 현재 배당이 없거나 배당 데이터가 확인되지 않습니다.")
    # 재무제표 추이
    render_section_title("연간 실적 추이")
    trend_fig = _financial_trend_chart(data, is_kr, P, FONT_MONO)
    if trend_fig is not None:
        # 다른 기업분석 차트의 저장된 축 범위가 잘못 복원되지 않도록 고유 키를 사용합니다.
        render_draggable_plotly_chart(trend_fig, use_container_width=True, chart_key="fundamental_financial_trend_v2")
        render_chart_box_meaning_panel("fundamental_trend", expanded=False, technical_lines=["최근 연간 매출·이익 추세를 확인합니다.", "실적이 우상향이면 기술적 반등 신뢰도가 높아집니다."], conclusion="주가 상승이 실적 개선과 동행하는지 확인합니다.")
        st.divider()
    else:
        st.info("연간 재무제표 데이터를 가져오지 못했습니다.")
    # 애널리스트
    render_section_title("애널리스트 컨센서스")
    reco_kr, reco_st = _RECO_KR.get(m["reco_key"], ("의견 없음", "info"))
    n_an = int(m["n_analysts"]) if np.isfinite(m["n_analysts"]) else 0
    if np.isfinite(m["target_mean"]) and m["target_mean"] > 0 and np.isfinite(cp) and cp > 0:
        upside = (m["target_mean"] / cp - 1) * 100
        up_msg = f"평균 목표가까지 상승여력 {upside:+.1f}%"
        up_st = "good" if upside >= 10 else "warn" if upside >= -5 else "bad"
    else:
        upside = np.nan; up_msg = "목표주가 데이터가 없습니다."; up_st = "info"
    render_dashboard_cards([
        {"icon": "🗣", "title": "투자의견 컨센서스", "value": reco_kr,
         "caption": f"분석가 {n_an}명 / 평점 {fmt_num(m['reco_mean'])}", "help": "1(적극매수)~5(적극매도) 척도.",
         "status": reco_st},
        {"icon": "🎯", "title": "평균 목표주가", "value": f"{fmt_price(m['target_mean'])}{unit}" if np.isfinite(m["target_mean"]) else "N/A",
         "caption": f"최고 {fmt_price(m['target_high'])} / 최저 {fmt_price(m['target_low'])}{unit}" if np.isfinite(m["target_high"]) else "범위 N/A",
         "help": "분석가들의 평균 목표주가입니다.", "message": up_msg, "status": up_st},
        {"icon": "👥", "title": "지분 구조", "value": f"기관 {fmt_pct(m['held_inst'])}",
         "caption": f"내부자 {fmt_pct(m['held_insiders'])}", "help": "기관·내부자 보유 비중입니다.", "status": "info"},
    ], cols_per_row=(1 if compact_mode else 3))

    render_company_value_and_peer_section(symbol, info, m, display_name, is_kr, unit, P, FONT_MONO, fmt_price, abbreviate_num, render_section_title, render_dashboard_cards, render_info_lines, compact_mode=compact_mode)
    st.divider()
    # 종합 코멘트
    render_section_title("기업분석 종합 코멘트")
    strengths, weaknesses = [], []
    if np.isfinite(m["roe"]) and m["roe"] >= 12: strengths.append(f"ROE {m['roe']:.1f}%로 자본효율성이 우수")
    if np.isfinite(m["op_margin"]) and m["op_margin"] >= 15: strengths.append(f"영업이익률 {m['op_margin']:.1f}%로 본업 경쟁력 양호")
    if np.isfinite(m["rev_growth"]) and m["rev_growth"] >= 10: strengths.append(f"매출 성장률 {m['rev_growth']:+.1f}%로 외형 성장 지속")
    if np.isfinite(m["debt_to_equity"]) and m["debt_to_equity"] < 80: strengths.append(f"부채비율 {m['debt_to_equity']:.0f}%로 재무 안정")
    if has_div and m["div_yield"] >= 3: strengths.append(f"배당수익률 {m['div_yield']:.1f}%로 주주환원 매력")
    if np.isfinite(m["per"]) and 0 < m["per"] < 12: strengths.append(f"PER {m['per']:.1f}배로 이익 대비 저평가 가능")
    if np.isfinite(m["per"]) and m["per"] > 40: weaknesses.append(f"PER {m['per']:.1f}배로 고평가 부담")
    if np.isfinite(m["debt_to_equity"]) and m["debt_to_equity"] >= 200: weaknesses.append(f"부채비율 {m['debt_to_equity']:.0f}%로 재무 리스크 유의")
    if np.isfinite(m["rev_growth"]) and m["rev_growth"] < 0: weaknesses.append(f"매출 성장률 {m['rev_growth']:+.1f}%로 역성장")
    if np.isfinite(m["net_margin"]) and m["net_margin"] < 0: weaknesses.append("순이익 적자 상태")
    if np.isfinite(m["current_ratio"]) and m["current_ratio"] < 1.0: weaknesses.append(f"유동비율 {m['current_ratio']:.2f}로 단기 유동성 주의")
    if np.isfinite(m["payout"]) and m["payout"] > 90: weaknesses.append(f"배당성향 {m['payout']:.0f}%로 배당 지속성 점검 필요")
    if not strengths: strengths.append("뚜렷한 강점 지표가 데이터상 확인되지 않습니다.")
    if not weaknesses: weaknesses.append("뚜렷한 약점 지표는 데이터상 확인되지 않습니다.")
    render_info_lines("✅ 펀더멘털 강점", strengths, icon="💪")
    render_info_lines("⚠️ 점검 포인트", weaknesses, icon="🔍")
    summary = (f"<strong>{esc(display_name)}</strong>의 펀더멘털 종합 등급은 "
               f"<strong>{scores['grade']} ({scores['eng']})</strong> · 종합점수 <strong>{total_txt}</strong>입니다. "
               f"{esc(scores['desc'])} 밸류에이션 {scores['parts']['밸류에이션']:.0f}점, 수익성 {scores['parts']['수익성']:.0f}점, "
               f"성장성 {scores['parts']['성장성']:.0f}점, 안정성 {scores['parts']['안정성']:.0f}점"
               + (f", 배당 {scores['parts']['배당']:.0f}점" if scores['parts']['배당'] is not None and np.isfinite(scores['parts']['배당']) else "")
               + f"으로 평가됩니다. "
               + (f"애널리스트 평균 목표주가는 {fmt_price(m['target_mean'])}{unit}로 현재가 대비 상승여력 {upside:+.1f}% 수준입니다. " if np.isfinite(upside) else "")
               + "펀더멘털은 기업의 '체력'이며, 실제 매매 타이밍은 기술적 분석 탭과 반드시 함께 판단하세요.").replace("nan점", "N/A")
    render_report_card("기업분석 한 줄 결론", summary, icon="🏢")
    biz = info.get("longBusinessSummary")
    if biz:
        with st.expander("📄 사업 개요 (회사 설명 · 원문)", expanded=False):
            st.write(str(biz))
            web = info.get("website")
            if web:
                st.markdown(f"🌐 [{web}]({web})")
    st.caption("데이터 출처: yfinance(Yahoo Finance). 본 분석은 투자 참고용입니다.")



