        fig.add_trace(go.Scatter(x=df.index, y=fisher*10+50, mode="lines", name="Fisher*10+50", line=dict(color="#38bdf8", width=1.2), showlegend=False), row=2, col=1)
        fig.add_hline(y=20, line_color="rgba(0,212,168,0.5)", line_dash="dash", row=2, col=1)
