def calc_seasonality_score(df: pd.DataFrame, lookback_years: int = 5) -> Dict:
    """계절성 점수: 과거 동일 월/요일 수익률 평균으로 계절성 편향 측정"""
    try:
        close = df["Close"].astype(float)
        ret = close.pct_change()
        month = df.index.month
        dotw = df.index.dayofweek
        curr_month = int(df.index[-1].month)
        curr_dow = int(df.index[-1].dayofweek)
        month_hist = ret[month==curr_month].tail(lookback_years*21)  # 21 trading days per month approx
        dow_hist = ret[dotw==curr_dow].tail(lookback_years*52)
        month_avg = float(month_hist.mean()*100) if len(month_hist)>5 else 0.0
        dow_avg = float(dow_hist.mean()*100) if len(dow_hist)>5 else 0.0
        month_win = float((month_hist>0).mean()*100) if len(month_hist)>5 else 50.0
        return {"month_avg": month_avg, "dow_avg": dow_avg, "month_win_rate": month_win, "sample": len(month_hist)}
    except Exception:
        return {"month_avg": 0.0, "dow_avg": 0.0, "month_win_rate": 50.0, "sample": 0}

def calc_intermarket_correlation(df: pd.DataFrame, benchmark_symbol: str = "SPY", period: int = 60) -> Dict:
    """인터마켓 상관: 벤치마크(SPY, QQQ, 달러, 금)와의 상관으로 리스크 온/오프 판단"""
    try:
        # 간소화: 자체 수익률의 모멘텀과 변동성으로 시장 레짐 추정, 실제 외부 데이터는 yfinance로 추후 확장 가능
        close = df["Close"].astype(float)
        ret = close.pct_change().rolling(period).mean().iloc[-1]
        vol = close.pct_change().rolling(period).std().iloc[-1]
        # 60일 수익률이 양수면 리스크온, 음수면 리스크오프
        risk_on = float(ret) > 0
        return {"risk_on": risk_on, "return_60d": float(ret*100), "vol_60d": float(vol*100), "benchmark": benchmark_symbol}
    except Exception:
        return {"risk_on": True, "return_60d": 0.0, "vol_60d": 1.0, "benchmark": benchmark_symbol}

def calc_volatility_targeting_position_size(atr: float, close: float, target_vol: float = 0.015) -> float:
    """변동성 타깃팅: 목표 변동성 1.5%에 맞춘 포지션 사이즈 계산"""
    try:
        if close <=0 or atr <=0:
            return 1.0
        # 포지션 = target_vol / (ATR/Close)
        vol_pct = atr / close
        size = target_vol / vol_pct if vol_pct>0 else 1.0
        return float(np.clip(size, 0.2, 3.0))
    except Exception:
        return 1.0

def calc_dynamic_kelly_with_drawdown_control(win_rate: float, avg_win: float, avg_loss: float, current_dd: float, max_dd_limit: float = 0.15) -> Dict:
    """동적 Kelly + MDD 제어: Kelly% * (1 - DD/DD_limit) 로 MDD 커지면 베팅 축소"""
    try:
        if avg_loss ==0:
            kelly = 0.0
        else:
            b = avg_win / abs(avg_loss) if avg_loss!=0 else 1.5
            p = win_rate
            q = 1-p
            kelly = p - q/b if b!=0 else 0.0
        kelly = float(np.clip(kelly, 0, 0.25))  # 최대 25% 제한
        dd = abs(current_dd)
        dd_factor = max(0.2, 1 - dd / max_dd_limit) if max_dd_limit>0 else 1.0
        adjusted = kelly * dd_factor
        # Half-Kelly 보수적
        half_kelly = adjusted * 0.5
        return {"full_kelly": kelly, "adjusted_kelly": adjusted, "half_kelly": half_kelly, "dd_factor": dd_factor}
    except Exception:
        return {"full_kelly": 0.05, "adjusted_kelly": 0.05, "half_kelly": 0.025, "dd_factor": 1.0}

def calc_mtf_sync_score(df: pd.DataFrame, ind: Dict) -> Dict:
    """MTF 동기화 점수: 일봉/주봉/월봉 추세가 모두 같은 방향이면 80점+, 2개 일치 60점, 불일치 30점"""
    try:
        close = ind["close"].astype(float)
        ma20 = ind["ma20"].astype(float)
        ma60 = ind["ma60"].astype(float)
        ema200 = ind.get("ema200", close.ewm(span=200).mean()).astype(float)
        # 일봉
        daily_up = (close.iloc[-1] > ma20.iloc[-1] > ma60.iloc[-1]) and (close.iloc[-1] > ema200.iloc[-1])
        # 주봉 근사: 5일 평균
        weekly_close = close.rolling(5).mean()
        weekly_ma20 = weekly_close.rolling(20).mean()
        weekly_ma60 = weekly_close.rolling(60).mean()
        weekly_up = (weekly_close.iloc[-1] > weekly_ma20.iloc[-1] > weekly_ma60.iloc[-1]) if len(weekly_close)>60 else daily_up
        # 월봉 근사: 21일 평균
        monthly_close = close.rolling(21).mean()
        monthly_ma20 = monthly_close.rolling(20).mean()
        monthly_up = (monthly_close.iloc[-1] > monthly_ma20.iloc[-1]) if len(monthly_close)>40 else daily_up

        sync_count = sum([daily_up, weekly_up, monthly_up])
        if sync_count == 3:
            score = 85
            label = "3중 정배열 (일+주+월) — 최강 추세"
        elif sync_count == 2:
            score = 62
            label = "2중 정배열 — 추세 우위"
        elif sync_count == 1:
            score = 42
            label = "단일 정배열 — 혼조"
        else:
            score = 28
            label = "역배열 — 방어 우선"

        return {"daily_up": daily_up, "weekly_up": weekly_up, "monthly_up": monthly_up, "sync_count": sync_count, "score": score, "label": label}
    except Exception:
        return {"daily_up": False, "weekly_up": False, "monthly_up": False, "sync_count": 0, "score": 50, "label": "계산 불가"}

