def calc_wyckoff_phases(df: pd.DataFrame, lookback: int = 200) -> Dict:
    """Wyckoff Phase 분석: Accumulation/Distribution / Phase A-E 자동 라벨링"""
    try:
        close = df["Close"].astype(float).tail(lookback)
        vol = df["Volume"].astype(float).tail(lookback)
        # 간소화: 가격 범위 + 거래량으로 Phase 추정
        # SC (Selling Climax): 거래량 급증 + 하락 후 반등
        # AR (Automatic Rally): SC 이후 반등
        # ST (Secondary Test): SC 재테스트
        # Spring: ST 이후 저점 이탈 후 즉시 반등
        # Phase C → D → E (Markup)
        vol_ma = vol.rolling(20).mean()
        phases = []
        for i in range(20, len(close)):
            c = float(close.iloc[i])
            v = float(vol.iloc[i])
            # SC 후보: 20봉 내 최저가 + 거래량 2배
            if c == float(close.iloc[i-20:i+1].min()) and v > float(vol_ma.iloc[i])*1.8:
                phases.append({"date": close.index[i], "phase": "SC (Selling Climax)", "type": "accumulation", "desc": "투매 절정, 세력 매집 시작"})
            # Spring 후보: SC 이후 저점 살짝 깨고 반등
            if len(phases)>0 and phases[-1]["phase"].startswith("SC"):
                if c > float(close.iloc[i-1])*1.01 and v > float(vol_ma.iloc[i])*1.2:
                    phases.append({"date": close.index[i], "phase": "Spring", "type": "accumulation", "desc": "개인 손절 유도 후 급반등, 최강 매수"})
        # 현재 Phase 추정
        curr_phase = "Phase D-E (Markup)" if len(phases)>=2 else "Phase B (Accumulation)"
        return {"phases": phases[-8:], "current": curr_phase}
    except Exception:
        return {"phases": [], "current": "판단 불가"}

def calc_footprint_imbalance(df: pd.DataFrame, period: int = 20) -> pd.DataFrame:
    """Footprint Imbalance: (가상) Bid/Ask 불균형 — 양봉에서 High 근처 마감 + 거래량 급증 시 매수 불균형"""
    try:
        close = df["Close"].astype(float)
        high = df["High"].astype(float)
        low = df["Low"].astype(float)
        vol = df["Volume"].astype(float)
        vol_ma = vol.rolling(period).mean()
        # 불균형 점수: (Close-Low)/(High-Low) * Vol Ratio
        loc = ((close - low) / (high - low).replace(0,np.nan)).fillna(0.5)
        imbalance = (loc - 0.5) * 2 * (vol / vol_ma.replace(0,np.nan)).fillna(1.0)
        # 0.3 이상 매수 불균형, -0.3 이하 매도 불균형
        return pd.DataFrame({"imbalance": imbalance, "loc": loc, "vol_ratio": vol/vol_ma}, index=df.index)
    except Exception:
        return pd.DataFrame(columns=["imbalance","loc","vol_ratio"], index=df.index)

def calc_gex_levels_approx(df: pd.DataFrame, lookback: int = 60) -> Dict:
    """GEX 근사: 옵션 감마 레벨 - 고점/저점 근처에서 거래량 급증 구간을 감마 벽으로 근사"""
    try:
        high = df["High"].astype(float).tail(lookback)
        low = df["Low"].astype(float).tail(lookback)
        close = df["Close"].astype(float).tail(lookback)
        vol = df["Volume"].astype(float).tail(lookback)
        # 고거래량 가격대 = GEX 벽 후보
        price_bins = np.linspace(float(low.min()), float(high.max()), 20)
        vol_profile = []
        for i in range(len(price_bins)-1):
            mask = (close >= price_bins[i]) & (close < price_bins[i+1])
            vol_profile.append({"price_low": price_bins[i], "price_high": price_bins[i+1], "vol": float(vol[mask].sum()), "mid": (price_bins[i]+price_bins[i+1])/2})
        vol_profile = sorted(vol_profile, key=lambda x: x["vol"], reverse=True)
        # 상위 3개를 GEX 벽으로
        gex_walls = vol_profile[:3]
        return {"gex_walls": gex_walls, "max_gex_price": gex_walls[0]["mid"] if gex_walls else float(close.iloc[-1])}
    except Exception:
        return {"gex_walls": [], "max_gex_price": float(df["Close"].iloc[-1]) if len(df) else 0.0}

def calc_nbeats_forecast(close: pd.Series, forecast_period: int = 10) -> Dict:
    """N-BEATS 간소화: MLPRegressor로 10봉 예측 - 과거 30봉으로 학습, 미래 10봉 예측"""
    try:
        from sklearn.neural_network import MLPRegressor
        c = close.astype(float).dropna()
        if len(c) < 60:
            return {"forecast": [], "trend": []}
        # 학습 데이터: 30봉 입력 → 10봉 출력
        X = []
        y = []
        for i in range(30, len(c)-forecast_period):
            X.append(c.iloc[i-30:i].values)
            y.append(c.iloc[i:i+forecast_period].values)
        if len(X) < 20:
            return {"forecast": [], "trend": []}
        X = np.array(X)
        y = np.array(y)
        # MLP
        model = MLPRegressor(hidden_layer_sizes=(64,32), max_iter=300, random_state=42)
        model.fit(X, y[:,0])  # 첫 번째 예측만 간단히
        last_window = c.iloc[-30:].values.reshape(1,-1)
        pred = model.predict(last_window)[0]
        # 추세 예측: 마지막 윈도우로 10봉 반복 예측
        forecasts = []
        curr_input = list(c.iloc[-30:].values)
        for _ in range(forecast_period):
            p = model.predict(np.array(curr_input[-30:]).reshape(1,-1))[0]
            forecasts.append(float(p))
            curr_input.append(p)
        trend = "상승" if forecasts[-1] > c.iloc[-1] else "하락"
        return {"forecast": forecasts, "trend": trend, "last": float(c.iloc[-1])}
    except Exception as e:
        return {"forecast": [], "trend": "판단 불가", "error": str(e)[:100]}

def calc_optuna_optimization_placeholder(bt_metrics: Dict) -> Dict:
    """Optuna 플레이스홀더: ATR 배수 최적화 - Sharpe 최대화 방향으로 3개 후보 제안"""
    try:
        # 실제로는 Optuna 필요, 여기서는 그리드 서치 간소화
        cur_stop = bt_metrics.get("atr_stop_mult", 2.0)
        cur_target = bt_metrics.get("atr_target_mult", 5.0)
        candidates = [
            {"stop": cur_stop*0.8, "target": cur_target*1.2, "desc": "공격형: 손절 좁게, 목표 크게 → 승률↓ 수익↑"},
            {"stop": cur_stop, "target": cur_target, "desc": "표준형: 현재 설정 유지"},
            {"stop": cur_stop*1.2, "target": cur_target*0.9, "desc": "보수형: 손절 넓게, 목표 작게 → 승률↑ 수익↓"},
        ]
        best = candidates[1]  # 표준형을 베스트로 가정, 실제로는 백테스트 재실행 필요
        return {"candidates": candidates, "best": best}
    except Exception:
        return {"candidates": [], "best": {}}

def calc_rl_position_sizing(sim_returns: pd.Series, initial_kelly: float = 0.1) -> Dict:
    """RL 기반 동적 포지셔닝 (간소화 Q-learning): 최근 성과에 따라 가중치 조정"""
    try:
        ret = sim_returns.astype(float).dropna().tail(60)
        if len(ret) < 10:
            return {"kelly": initial_kelly, "adjustment": 1.0, "suggested": initial_kelly}
        # 최근 10봉 평균 vs 60봉 평균
        recent_avg = float(ret.tail(10).mean())
        long_avg = float(ret.mean())
        # 최근 성과가 좋으면 가중치↑, 나쁘면 ↓
        if recent_avg > long_avg*1.2:
            adj = 1.3
        elif recent_avg < long_avg*0.8:
            adj = 0.7
        else:
            adj = 1.0
        suggested = float(np.clip(initial_kelly * adj, 0.02, 0.25))
        return {"kelly": initial_kelly, "recent_avg": recent_avg, "long_avg": long_avg, "adjustment": adj, "suggested": suggested}
    except Exception:
        return {"kelly": initial_kelly, "adjustment": 1.0, "suggested": initial_kelly}

