def calc_footprint_heatmap_data(df: pd.DataFrame, bins: int = 20) -> Dict:
    """Footprint 히트맵 데이터: 가격대별 Bid/Ask 불균형 히트맵용"""
    try:
        close = df["Close"].astype(float)
        high = df["High"].astype(float)
        low = df["Low"].astype(float)
        vol = df["Volume"].astype(float)
        # 가격대별 불균형 축적
        price_min = float(low.tail(60).min())
        price_max = float(high.tail(60).max())
        edges = np.linspace(price_min, price_max, bins+1)
        heatmap = np.zeros((60, bins))  # 60봉 x bins
        sub = df.tail(60)
        for i, (_, row) in enumerate(sub.iterrows()):
            c = float(row["Close"])
            h = float(row["High"])
            l = float(row["Low"])
            v = float(row["Volume"])
            loc = (c - l) / (h - l) if h!=l else 0.5
            imbalance = (loc - 0.5) * 2  # -1~+1
            # 해당 가격대에 imbalance * vol 가중
            bin_idx = int(np.digitize(c, edges)) -1
            bin_idx = max(0, min(bins-1, bin_idx))
            heatmap[i, bin_idx] = imbalance * (v / (vol.tail(60).mean()+1e-9))
        return {"heatmap": heatmap, "edges": edges, "dates": sub.index}
    except Exception:
        return {"heatmap": np.zeros((20,20)), "edges": np.linspace(0,100,21), "dates": df.index[-20:]}

def calc_order_book_depth_heatmap(df: pd.DataFrame, levels: int = 10) -> Dict:
    """오더북 깊이 히트맵 (근사): 고점/저점 근처 거래량 밀집으로 호가창 불균형 근사"""
    try:
        close = df["Close"].astype(float).tail(levels*6)
        high = df["High"].astype(float).tail(levels*6)
        low = df["Low"].astype(float).tail(levels*6)
        # 간단히 최근 고저의 분포로 깊이 근사
        price_min = float(low.min())
        price_max = float(high.max())
        edges = np.linspace(price_min, price_max, levels+1)
        bid_depth = np.random.uniform(0.5, 1.5, levels)  # 실제로는 호가 API 필요, 여기서는 플레이스홀더 + 거래량 기반 가중
        ask_depth = np.random.uniform(0.5, 1.5, levels)
        # 거래량 가중으로 조정
        vol = df["Volume"].astype(float).tail(levels*6).mean()
        # 현재가 근처에 깊이 높게
        curr = float(close.iloc[-1])
        for i in range(levels):
            mid = (edges[i]+edges[i+1])/2
            dist = abs(mid - curr) / (price_max - price_min + 1e-9)
            bid_depth[i] *= max(0.3, 1 - dist)
            ask_depth[i] *= max(0.3, 1 - dist)
        return {"edges": edges, "bid_depth": bid_depth, "ask_depth": ask_depth, "current": curr}
    except Exception:
        return {"edges": np.linspace(0,100,11), "bid_depth": np.zeros(10), "ask_depth": np.zeros(10), "current": 0.0}

def calc_gex_actual_levels(df: pd.DataFrame, lookback: int = 60) -> Dict:
    """GEX 실제 근사 고도화: 양봉 거래량 = Call 감마, 음봉 거래량 = Put 감마 로 근사, Net GEX 계산"""
    try:
        close = df["Close"].astype(float).tail(lookback)
        open_ = df["Open"].astype(float).tail(lookback)
        high = df["High"].astype(float).tail(lookback)
        low = df["Low"].astype(float).tail(lookback)
        vol = df["Volume"].astype(float).tail(lookback)
        # Call Gamma ≈ 양봉 거래량, Put Gamma ≈ 음봉 거래량
        call_vol = vol.where(close > open_, 0)
        put_vol = vol.where(close < open_, 0)
        # 가격대별 GEX
        price_min = float(low.min())
        price_max = float(high.max())
        bins = 15
        edges = np.linspace(price_min, price_max, bins+1)
        call_gex = np.zeros(bins)
        put_gex = np.zeros(bins)
        for i in range(bins):
            mask = (close >= edges[i]) & (close < edges[i+1])
            call_gex[i] = float(call_vol[mask].sum())
            put_gex[i] = float(put_vol[mask].sum())
        net_gex = call_gex - put_gex
        # GEX 벽: Net GEX 절대값 큰 가격대
        gex_levels = []
        for i in range(bins):
            gex_levels.append({"price_low": edges[i], "price_high": edges[i+1], "mid": (edges[i]+edges[i+1])/2, "call_gex": call_gex[i], "put_gex": put_gex[i], "net_gex": net_gex[i]})
        gex_levels = sorted(gex_levels, key=lambda x: abs(x["net_gex"]), reverse=True)[:5]
        return {"levels": gex_levels, "call_gex": call_gex, "put_gex": put_gex, "net_gex": net_gex, "edges": edges}
    except Exception:
        return {"levels": [], "call_gex": np.zeros(15), "put_gex": np.zeros(15), "net_gex": np.zeros(15), "edges": np.linspace(0,100,16)}

def calc_tide_transformer_forecast(close: pd.Series, forecast_period: int = 10) -> Dict:
    """TiDE Transformer 간소화: Attention 유사 가중 + Trend/Seasonal 분해로 10봉 예측"""
    try:
        # TiDE: 시간 종속 + 공변량, 여기서는 간소화: Trend(EMA) + Seasonal(잔차) + Attention(최근 가중)
        c = close.astype(float).dropna()
        if len(c) < 60:
            return {"forecast": [], "trend": "판단 불가"}
        # Trend: EMA 21
        trend = c.ewm(span=21).mean()
        seasonal = c - trend
        # Attention: 최근 10봉에 더 높은 가중치
        weights = np.exp(np.linspace(-1, 0, 10))  # 최근이 더 큰 가중
        weights = weights / weights.sum()
        recent_seasonal = seasonal.tail(10).values
        seasonal_bias = float(np.dot(recent_seasonal, weights))
        # 예측: Trend 연장 + Seasonal bias
        last_trend = float(trend.iloc[-1])
        trend_slope = float(trend.iloc[-1] - trend.iloc[-2])
        forecasts = []
        for i in range(1, forecast_period+1):
            f = last_trend + trend_slope * i * 1.1 + seasonal_bias * (0.8**i)
            forecasts.append(float(f))
        trend_dir = "상승" if forecasts[-1] > c.iloc[-1] else "하락"
        return {"forecast": forecasts, "trend": trend_dir, "last": float(c.iloc[-1]), "seasonal_bias": seasonal_bias}
    except Exception as e:
        return {"forecast": [], "trend": "판단 불가", "error": str(e)[:100]}

def calc_cvar_expected_shortfall(returns: pd.Series, alpha: float = 0.05) -> Dict:
    """CVaR / Expected Shortfall: VaR를 초과하는 손실의 평균 - 리스크 관리"""
    try:
        r = returns.astype(float).dropna()
        if len(r) < 20:
            return {"var": 0.0, "cvar": 0.0}
        var = float(r.quantile(alpha))
        cvar = float(r[r <= var].mean()) if len(r[r <= var])>0 else var
        return {"var": var, "cvar": cvar, "var_pct": var*100, "cvar_pct": cvar*100}
    except Exception:
        return {"var": 0.0, "cvar": 0.0, "var_pct": 0.0, "cvar_pct": 0.0}

def calc_risk_parity_weights(returns: pd.DataFrame) -> pd.Series:
    """Risk Parity: 각 자산의 리스크 기여도가 동일하도록 가중치 계산 (간소화)"""
    try:
        # 단일 자산이면 1.0
        if returns.shape[1] <=1:
            return pd.Series([1.0], index=returns.columns)
        cov = returns.cov()
        inv_vol = 1 / returns.std()
        weights = inv_vol / inv_vol.sum()
        return weights.fillna(0)
    except Exception:
        return pd.Series(1.0, index=returns.columns[:1])

