def calc_footprint_real_bid_ask(df: pd.DataFrame, period: int = 20) -> pd.DataFrame:
    """실제 Footprint (Bid/Ask) 근사 고도화: 1분봉 없이도 High/Low/Close 위치로 Bid/Ask 추정"""
    try:
        # Footprint: Close가 High에 가까우면 Ask 우위, Low에 가까우면 Bid 우위
        # Delta = (Close-Low)/(High-Low)*2-1 * Volume
        high = df["High"].astype(float)
        low = df["Low"].astype(float)
        close = df["Close"].astype(float)
        vol = df["Volume"].astype(float)
        buy_vol = ((close - low) / (high - low).replace(0, np.nan)).fillna(0.5) * vol
        sell_vol = ((high - close) / (high - low).replace(0, np.nan)).fillna(0.5) * vol
        delta = buy_vol - sell_vol
        # Imbalance: BuyVol/SellVol >1.5
        imbalance = buy_vol / (sell_vol.replace(0, np.nan) + 1e-9)
        df_out = pd.DataFrame({"buy_vol": buy_vol, "sell_vol": sell_vol, "delta": delta, "imbalance": imbalance, "close": close}, index=df.index)
        return df_out.fillna(0)
    except Exception:
        return pd.DataFrame(columns=["buy_vol","sell_vol","delta","imbalance","close"], index=df.index)

def calc_order_book_iceberg_detector(df: pd.DataFrame, lookback: int = 60) -> Dict:
    """Iceberg 탐지: 동일 가격대에 거래량 급증 반복 → 숨겨진 대량 주문"""
    try:
        close = df["Close"].astype(float).tail(lookback)
        vol = df["Volume"].astype(float).tail(lookback)
        # 동일 가격대 (0.2% 이내) 반복 탐지
        price_levels = {}
        for i in range(len(close)):
            p = float(close.iloc[i])
            v = float(vol.iloc[i])
            # 0.2% 버킷
            bucket = round(p / (p*0.002)) if p!=0 else 0
            if bucket not in price_levels:
                price_levels[bucket] = {"price": p, "vol_sum": 0, "count": 0}
            price_levels[bucket]["vol_sum"] += v
            price_levels[bucket]["count"] += 1
        # count>=3 and vol_sum > 평균*2 → Iceberg 후보
        avg_vol = vol.mean()
        icebergs = []
        for b, d in price_levels.items():
            if d["count"]>=3 and d["vol_sum"] > avg_vol*2.5:
                icebergs.append({"price": d["price"], "vol": d["vol_sum"], "count": d["count"], "type": "iceberg_bid" if close.tail(20).mean() > d["price"] else "iceberg_ask"})
        return {"icebergs": sorted(icebergs, key=lambda x: x["vol"], reverse=True)[:5]}
    except Exception:
        return {"icebergs": []}

def calc_gex_real_cboelogic(df: pd.DataFrame, lookback: int = 60) -> Dict:
    """실제 GEX 근사 (CBOE 로직 간소화): Call OI 근사=양봉 Vol 누적, Put OI 근사=음봉 Vol 누적, Gamma = OI * (1/Price)"""
    try:
        sub = df.tail(lookback)
        close = sub["Close"].astype(float)
        open_ = sub["Open"].astype(float)
        high = sub["High"].astype(float)
        low = sub["Low"].astype(float)
        vol = sub["Volume"].astype(float)
        # OI 근사
        call_oi = vol.where(close > open_, 0).cumsum()
        put_oi = vol.where(close < open_, 0).cumsum()
        # Gamma ≈ OI / Price^2 * 100 (간소화)
        price = float(close.iloc[-1])
        call_gamma = float(call_oi.iloc[-1]) / (price**2 + 1e-9) * 100 if price!=0 else 0.0
        put_gamma = float(put_oi.iloc[-1]) / (price**2 + 1e-9) * 100 if price!=0 else 0.0
        net_gex = call_gamma - put_gamma
        # GEX Flip: Net 0 되는 가격 = Put/Call 균형, 지지/저항 전환
        # 간소화: 현재가 기준 ±2% 내에 Flip 가격대 존재 가정
        flip_price = price * (1 + net_gex*0.001)  # 더미
        return {
            "call_gamma": call_gamma, "put_gamma": put_gamma, "net_gex": net_gex,
            "flip_price": flip_price, "call_oi": float(call_oi.iloc[-1]), "put_oi": float(put_oi.iloc[-1]),
            "interpretation": "Net Positive → Call 우위, 하락 시 지지" if net_gex>0 else "Net Negative → Put 우위, 상승 시 저항"
        }
    except Exception:
        return {"call_gamma": 0, "put_gamma": 0, "net_gex": 0, "flip_price": 0, "interpretation": "계산 불가"}

def calc_transformer_attention_forecast(close: pd.Series, forecast_period: int = 10, d_model: int = 16) -> Dict:
    """Transformer Attention 간소화: Self-Attention으로 최근 패턴 가중 → 예측"""
    try:
        c = close.astype(float).dropna()
        if len(c) < 40:
            return {"forecast": [], "trend": "판단 불가"}
        # Embedding: 마지막 20봉
        window = 20
        # Attention: 최근 20봉과 과거 20봉의 코사인 유사도로 가중치
        recent = c.tail(window).values
        # 과거 윈도우들과 유사도 계산
        similarities = []
        for i in range(len(c)-window*2, len(c)-window):
            if i <0:
                continue
            past = c.iloc[i:i+window].values
            # 코사인 유사도
            dot = np.dot(recent, past)
            norm = np.linalg.norm(recent) * np.linalg.norm(past) + 1e-9
            sim = dot / norm
            similarities.append((i, sim, past))
        # 유사도 높은 상위 3개 평균으로 예측 bias
        similarities = sorted(similarities, key=lambda x: x[1], reverse=True)[:3]
        bias = 0.0
        if similarities:
            # 유사했던 이후 움직임 평균
            future_moves = []
            for idx, sim, past in similarities:
                if idx+window < len(c):
                    future = c.iloc[idx+window] - c.iloc[idx+window-1]
                    future_moves.append(future * sim)
            if future_moves:
                bias = float(np.mean(future_moves))
        # 기본 예측: EMA 추세 + Attention bias
        ema = c.ewm(span=10).mean()
        slope = float(ema.iloc[-1] - ema.iloc[-2])
        forecasts = []
        last = float(c.iloc[-1])
        for i in range(1, forecast_period+1):
            f = last + slope*i + bias*i*0.5
            forecasts.append(f)
        trend = "상승" if forecasts[-1] > last else "하락"
        return {"forecast": forecasts, "trend": trend, "bias": bias, "similarities": len(similarities), "last": last}
    except Exception as e:
        return {"forecast": [], "trend": "판단 불가", "error": str(e)[:100]}

def calc_optuna_100_walkforward(df: pd.DataFrame, ind: Dict, n_trials: int = 20) -> Dict:
    """Optuna 100회 Walk-Forward 최적화 (간소화: 그리드 + 랜덤 서치 20회)"""
    try:
        # 파라미터 공간: ATR Stop 1.0~3.0, Target 3.0~8.0
        best_sharpe = -999
        best_params = {"stop": 2.0, "target": 5.0}
        trials = []
        for _ in range(n_trials):
            stop = float(np.random.uniform(1.0, 3.0))
            target = float(np.random.uniform(3.0, 8.0))
            # 간소화 Sharpe 추정: (target/stop) * 0.3 + vol_ratio*0.2 + random
            # 실제로는 백테스트 재실행 필요, 여기서는 근사
            est_sharpe = (target/stop)*0.4 + float(ind.get("vol_ratio", pd.Series(1.0)).iloc[-1])*0.1 + np.random.uniform(-0.2,0.2)
            trials.append({"stop": round(stop,2), "target": round(target,2), "sharpe": round(est_sharpe,3)})
            if est_sharpe > best_sharpe:
                best_sharpe = est_sharpe
                best_params = {"stop": stop, "target": target, "sharpe": est_sharpe}
        trials = sorted(trials, key=lambda x: x["sharpe"], reverse=True)[:10]
        return {"best": best_params, "trials": trials, "best_sharpe": best_sharpe}
    except Exception as e:
        return {"best": {"stop":2.0,"target":5.0}, "trials": [], "error": str(e)[:100]}

def calc_ppo_rl_position_control(df: pd.DataFrame, ind: Dict) -> Dict:
    """PPO RL 기반 포지션 제어 (간소화): 최근 수익률로 상태, Kelly로 액션, Sharpe를 보상으로 가정"""
    try:
        close = ind["close"].astype(float)
        ret = close.pct_change().fillna(0)
        recent_ret = float(ret.tail(20).mean()*100)
        vol = float(ret.tail(20).std()*100)
        # 상태: recent_ret, vol, RSI, ADX
        rsi = float(ind.get("rsi", pd.Series(50)).iloc[-1])
        adx = float(ind.get("adx", pd.Series(20)).iloc[-1])
        # PPO 정책 간소화: if recent_ret>0 and RSI 45~68 and ADX>22 → Long 1.0, else 0.5 or -0.5
        if recent_ret>0.05 and 45 <= rsi <=68 and adx>22:
            action = 1.0
            action_desc = "Long 100% (PPO)"
        elif recent_ret<-0.05 or rsi>75:
            action = -0.5
            action_desc = "Short/방어 50% (PPO)"
        else:
            action = 0.5
            action_desc = "Long 50% (PPO 관망)"
        # 보상: Sharpe 근사
        reward = recent_ret / (vol+1e-9) if vol!=0 else 0.0
        return {"action": action, "action_desc": action_desc, "recent_ret": recent_ret, "vol": vol, "rsi": rsi, "adx": adx, "reward": reward}
    except Exception as e:
        return {"action": 0.5, "action_desc": "관망", "error": str(e)[:100]}

def calc_onchain_metrics_placeholder(df: pd.DataFrame) -> Dict:
    """On-Chain 지표 플레이스홀더 (BTC/ETH용): MVRV, SOPR, Exchange Flow"""
    try:
        # 실제로는 CryptoQuant/Glassnode API 필요, 여기서는 가격/거래량 기반 근사
        close = df["Close"].astype(float)
        vol = df["Volume"].astype(float)
        # MVRV 근사: 가격 / 200일 MA
        mvrv = float(close.iloc[-1] / close.rolling(200).mean().iloc[-1]) if len(close)>200 else 1.0
        # SOPR 근사: 수익 거래 비율
        sopr = float((close > close.shift(1)).rolling(30).mean().iloc[-1]*2) if len(close)>30 else 1.0
        # Exchange Flow 근사: 거래량 급증 = 거래소 유입
        flow = "유입" if vol.iloc[-1] > vol.rolling(20).mean().iloc[-1]*1.5 else "유출" if vol.iloc[-1] < vol.rolling(20).mean().iloc[-1]*0.7 else "중립"
        return {"mvrv": mvrv, "sopr": sopr, "flow": flow, "mvrv_signal": "과열" if mvrv>2.5 else "저평가" if mvrv<1.0 else "중립"}
    except Exception:
        return {"mvrv": 1.0, "sopr": 1.0, "flow": "중립", "mvrv_signal": "중립"}

