def calc_multi_horizon_ensemble(df: pd.DataFrame, ind: Dict, horizons: List[int] = [5,10,20,30]) -> Dict:
    """멀티-호라이즌 앙상블: 5,10,20,30봉 후 예측 모델 각각 학습 → 가중 평균으로 단기/중장기 예측"""
    try:
        results = {}
        for h in horizons:
            res = train_xgboost_ensemble(df, ind, forward_n=h) if 'train_xgboost_ensemble' in globals() else train_ensemble_model(df, ind, forward_n=h)
            if res.get("available"):
                results[h] = res
        # 앙상블 가중치: 단기는 5봉 가중치 높게, 장기는 30봉 낮게 (단기 적중율 우선)
        weights = {5: 0.35, 10: 0.30, 20: 0.20, 30: 0.15}
        avg_cv = float(np.mean([r.get("mean_cv_acc",0) for r in results.values()])) if results else 0.0
        # 예측: 각 모델의 확률 가중 평균 (여기서는 CV 정확도로 가중)
        return {"horizons": results, "weights": weights, "mean_cv": avg_cv, "best_horizon": max(results.items(), key=lambda x: x[1].get("mean_cv_acc",0))[0] if results else 10}
    except Exception as e:
        return {"horizons": {}, "weights": {}, "mean_cv": 0.0, "error": str(e)[:200]}

def calc_regime_specific_models(df: pd.DataFrame, ind: Dict, regime: str) -> Dict:
    """레짐별 특화 모델: 추세장에서는 모멘텀/KAMA/ER 가중, 박스권에서는 Connors/Fisher/타이밍 가중 모델 따로 학습"""
    try:
        # 레짐에 따라 피처 필터링
        feats = build_prob_feature_matrix(df, ind)
        if feats.empty:
            return {"available": False}
        # 레짐별 샘플만 사용: 예를 들어 추세장에서는 chop_trending=1인 샘플만
        if regime in ["추세장", "고변동 추세"]:
            filtered_idx = feats[feats.get("chop_trending", pd.Series(0, index=feats.index))==1].index if "chop_trending" in feats.columns else feats.index
        elif regime in ["박스권", "박스권(스퀴즈)"]:
            filtered_idx = feats[feats.get("chop_choppy", pd.Series(0, index=feats.index))==1].index if "chop_choppy" in feats.columns else feats.index
        else:
            filtered_idx = feats.index

        # 해당 레짐 샘플로만 모델 학습
        from sklearn.ensemble import GradientBoostingClassifier
        close = ind["close"].astype(float).reindex(df.index)
        fwd_ret = (close.shift(-10) / close - 1.0)
        y = (fwd_ret > 0).astype(int)
        valid_idx = feats.index.intersection(filtered_idx)
        valid_idx = valid_idx[feats.loc[valid_idx].notna().all(axis=1) & y.loc[valid_idx].notna()]
        if len(valid_idx) < 60:
            return {"available": False, "reason": "레짐 샘플 부족"}
        X = feats.loc[valid_idx]
        y_v = y.loc[valid_idx]
        clf = GradientBoostingClassifier(random_state=42, n_estimators=80)
        clf.fit(X, y_v)
        acc = float((clf.predict(X) == y_v).mean())
        return {"available": True, "model": clf, "acc": acc, "regime": regime, "n_samples": len(X), "feature_names": X.columns.tolist()}
    except Exception as e:
        return {"available": False, "error": str(e)[:200]}

def calc_meta_learner_weights(ensemble_results: Dict, regime: str, recent_performance: Dict) -> Dict:
    """메타-러너: 각 모델의 최근 성과(CV 정확도 + 최근 20봉 적중율)로 가중치 동적 조정"""
    try:
        # ensemble_results: {"horizons": {5: {...}, 10: {...}, ...}, "weights": {...}}
        # recent_performance: {"model_name": {"recent_acc": 0.62, "cv_acc": 0.65}}
        base_weights = ensemble_results.get("weights", {5:0.35,10:0.30,20:0.20,30:0.15})
        # 레짐 보정
        regime_mult = {"추세장": {5:0.8,10:1.0,20:1.3,30:1.2}, "박스권": {5:1.3,10:1.2,20:0.8,30:0.7}}
        mult = regime_mult.get(regime, {})
        adjusted = {}
        total = 0.0
        for h, w in base_weights.items():
            # 최근 성과 보정 (있다면)
            recent = recent_performance.get(str(h), {}).get("recent_acc", 0.55) if isinstance(recent_performance, dict) else 0.55
            recent_mult = 0.7 + recent  # 0.55→1.25, 0.65→1.35
            reg_mult = mult.get(h, 1.0)
            adjusted[h] = w * recent_mult * reg_mult
            total += adjusted[h]
        # 정규화
        if total>0:
            for h in adjusted:
                adjusted[h] /= total
        return {"weights": adjusted, "regime": regime, "total": total}
    except Exception as e:
        return {"weights": {5:0.35,10:0.30,20:0.20,30:0.15}, "error": str(e)[:100]}

def calc_advanced_risk_optimization(bt: Dict, df: pd.DataFrame, ind: Dict) -> Dict:
    """고급 리스크 최적화: Kelly + Risk Parity + CVaR + Vol Targeting + MDD 제어를 하나의 효율적 프론티어로"""
    try:
        close = ind["close"].astype(float)
        ret = close.pct_change().fillna(0)
        cvar = calc_cvar_expected_shortfall(ret, 0.05)
        # Vol Targeting
        atr = float(ind.get("atr", pd.Series(0)).iloc[-1] if "atr" in ind else 0)
        last_close = float(close.iloc[-1])
        vol_target_size = calc_volatility_targeting_position_size(atr, last_close, 0.015)
        # Kelly
        win_rate = bt.get("win_rate",50)/100.0
        avg_win = 0.08
        avg_loss = 0.04
        current_dd = bt.get("max_dd", -0.05)
        kelly = calc_dynamic_kelly_with_drawdown_control(win_rate, avg_win, avg_loss, current_dd, 0.15)
        # Risk Parity (단일 자산이므로 1.0, 다자산이면 계산)
        risk_parity = 1.0

        # 최종 최적 가중치: Vol Targeting * Kelly Half * (1 - CVaR_penalty) * Risk Parity
        cvar_penalty = max(0.5, 1 + cvar.get("cvar",0)*2)  # CVaR가 -3%면 1-0.06=0.94
        final_size = vol_target_size * kelly.get("half_kelly",0.05)*10 * cvar_penalty * risk_parity
        final_size = float(np.clip(final_size, 0.1, 2.5))

        return {
            "vol_target_size": vol_target_size,
            "kelly": kelly,
            "cvar": cvar,
            "risk_parity": risk_parity,
            "cvar_penalty": cvar_penalty,
            "final_size": final_size,
            "interpretation": f"Vol {vol_target_size:.2f}x * Kelly Half {kelly.get('half_kelly',0)*100:.1f}% * CVaR Penalty {cvar_penalty:.2f} = 최종 {final_size:.2f}x"
        }
    except Exception as e:
        return {"final_size": 1.0, "error": str(e)[:200]}

