def calc_earnings_surprise_score(df: pd.DataFrame) -> Dict:
    """어닝 서프라이즈: 최근 실적 발표 후 갭 + 거래량 기반 점수화"""
    try:
        close = df["Close"].astype(float)
        vol = df["Volume"].astype(float)
        ret = close.pct_change()
        # 갭: Open - Prev Close가 3% 이상 + Vol 2배
        gap = (df["Open"].astype(float) - close.shift(1)) / close.shift(1).replace(0,np.nan)
        vol_ma = vol.rolling(20).mean()
        surprise_dates = []
        for i in range(1, len(df)):
            if abs(float(gap.iloc[i])) > 0.03 and float(vol.iloc[i]) > float(vol_ma.iloc[i])*1.8:
                surprise_dates.append({"date": df.index[i], "gap": float(gap.iloc[i])*100, "type": "positive" if float(gap.iloc[i])>0 else "negative"})
        last_surprise = surprise_dates[-1] if surprise_dates else None
        score = 70 if last_surprise and last_surprise["type"]=="positive" else 30 if last_surprise and last_surprise["type"]=="negative" else 50
        return {"surprises": surprise_dates[-5:], "last": last_surprise, "score": score}
    except Exception:
        return {"surprises": [], "last": None, "score": 50}

def calc_analyst_consensus_score() -> Dict:
    """애널리스트 컨센서스 (플레이스홀더, 실제로는 Yahoo Finance analyst_info 필요)"""
    try:
        # 더미: 랜덤하게 Strong Buy / Buy / Hold / Sell 분포, 실제로는 API
        import random
        cons = random.choice(["Strong Buy","Buy","Hold","Sell"])
        score_map = {"Strong Buy": 80, "Buy": 65, "Hold": 50, "Sell": 30, "Strong Sell": 20}
        return {"consensus": cons, "score": score_map.get(cons,50)}
    except Exception:
        return {"consensus": "Hold", "score": 50}

def calc_short_interest_score(df: pd.DataFrame) -> Dict:
    """숏 인터레스트 근사: 20일 평균 대비 거래량 급증 + 하락 후 반등 시 숏 커버링 가능성"""
    try:
        close = df["Close"].astype(float)
        vol = df["Volume"].astype(float)
        ret_20 = close.pct_change(20).iloc[-1]
        vol_ratio = float(vol.iloc[-1] / vol.rolling(20).mean().iloc[-1]) if vol.rolling(20).mean().iloc[-1]!=0 else 1.0
        # 하락 -10% 후 거래량 급증 + 양봉 = 숏 커버링
        short_cover = (ret_20 < -0.10) and (vol_ratio > 1.5) and (close.iloc[-1] > df["Open"].iloc[-1])
        score = 70 if short_cover else 50
        return {"short_cover": short_cover, "vol_ratio": vol_ratio, "ret_20": float(ret_20*100), "score": score}
    except Exception:
        return {"short_cover": False, "vol_ratio": 1.0, "ret_20": 0.0, "score": 50}

def calc_institutional_ownership_score() -> Dict:
    """기관 소유 비중 (플레이스홀더)"""
    try:
        import random
        inst_pct = random.uniform(40, 85)
        score = 60 + (inst_pct-60)*0.5  # 60% 기준
        return {"inst_pct": inst_pct, "score": float(np.clip(score,0,100))}
    except Exception:
        return {"inst_pct": 60.0, "score": 60.0}

def calc_funding_rate_score(df: pd.DataFrame) -> Dict:
    """코인 펀딩비 근사: 가격 급등 + 거래량 급증 + 양봉 연속 시 펀딩비 과열"""
    try:
        close = df["Close"].astype(float)
        vol = df["Volume"].astype(float)
        ret_7 = close.pct_change(7).iloc[-1]
        # 펀딩비 0.1% 이상 과열 가정
        funding = float(ret_7 * 0.3)  # 간소화: 7일 수익률의 30%를 펀딩비로 근사
        funding = np.clip(funding, -0.005, 0.005)  # -0.5% ~ +0.5%
        signal = "과열" if funding>0.001 else "저평가" if funding<-0.001 else "중립"
        score = 30 if funding>0.001 else 70 if funding<-0.001 else 50
        return {"funding_rate": funding*100, "signal": signal, "score": score, "ret_7": float(ret_7*100)}
    except Exception:
        return {"funding_rate": 0.0, "signal": "중립", "score": 50, "ret_7": 0.0}

def calc_open_interest_score(df: pd.DataFrame) -> Dict:
    """코인 OI 근사: 거래량 누적 + 가격 추세로 OI 추세 추정"""
    try:
        close = df["Close"].astype(float)
        vol = df["Volume"].astype(float)
        # OI 근사: Vol 누적 * 가격 방향
        oi = (vol * (1 if close.iloc[-1] > close.iloc[-2] else -0.2)).cumsum().tail(60)
        oi_trend = "상승" if oi.iloc[-1] > oi.iloc[-5] else "하락"
        # 가격 상승 + OI 상승 = 추세 지속, 가격 상승 + OI 하락 = 추세 약화
        price_trend = "상승" if close.iloc[-1] > close.iloc[-5] else "하락"
        if price_trend=="상승" and oi_trend=="상승":
            signal = "추세 지속 강함"
            score = 70
        elif price_trend=="상승" and oi_trend=="하락":
            signal = "추세 약화 Div"
            score = 40
        else:
            signal = "중립"
            score = 50
        return {"oi": float(oi.iloc[-1]), "oi_trend": oi_trend, "price_trend": price_trend, "signal": signal, "score": score}
    except Exception:
        return {"oi": 0.0, "oi_trend": "중립", "price_trend": "중립", "signal": "중립", "score": 50}

def calc_long_short_ratio_score(df: pd.DataFrame) -> Dict:
    """롱숏 비율 근사: 양봉 비율 + 거래량 비율로 롱/숏 쏠림 측정"""
    try:
        close = df["Close"].astype(float)
        open_ = df["Open"].astype(float)
        vol = df["Volume"].astype(float)
        last_20 = df.tail(20)
        long_count = (last_20["Close"] > last_20["Open"]).sum()
        short_count = 20 - long_count
        long_vol = vol.tail(20)[close.tail(20) > open_.tail(20)].sum()
        short_vol = vol.tail(20)[close.tail(20) < open_.tail(20)].sum()
        ratio = long_vol / (short_vol+1e-9) if short_vol!=0 else 1.5
        signal = "롱 과열" if ratio>1.8 else "숏 과열" if ratio<0.6 else "균형"
        score = 30 if ratio>1.8 else 70 if ratio<0.6 else 50
        return {"long_count": int(long_count), "short_count": int(short_count), "ratio": float(ratio), "signal": signal, "score": score}
    except Exception:
        return {"long_count": 10, "short_count": 10, "ratio": 1.0, "signal": "균형", "score": 50}

def calc_liquidation_levels_map(df: pd.DataFrame, lookback: int = 60) -> Dict:
    """청산 맵: 고점/저점 근처 거래량 밀집 구간을 청산 레벨로 근사"""
    try:
        high = df["High"].astype(float).tail(lookback)
        low = df["Low"].astype(float).tail(lookback)
        close = df["Close"].astype(float).tail(lookback)
        vol = df["Volume"].astype(float).tail(lookback)
        price_min = float(low.min())
        price_max = float(high.max())
        bins = np.linspace(price_min, price_max, 25)
        liq_vol = np.zeros(24)
        for i in range(len(bins)-1):
            mask = (close >= bins[i]) & (close < bins[i+1])
            liq_vol[i] = float(vol[mask].sum())
        # 상위 5개가 청산 밀집
        top_idx = np.argsort(liq_vol)[-5:][::-1]
        levels = []
        for idx in top_idx:
            levels.append({"price_low": bins[idx], "price_high": bins[idx+1], "mid": (bins[idx]+bins[idx+1])/2, "vol": liq_vol[idx], "type": "long_liquidation" if (bins[idx]+bins[idx+1])/2 < float(close.iloc[-1]) else "short_liquidation"})
        return {"levels": levels, "max_liq_price": levels[0]["mid"] if levels else float(close.iloc[-1])}
    except Exception:
        return {"levels": [], "max_liq_price": float(df["Close"].iloc[-1]) if len(df) else 0.0}

def calc_mayer_multiple_puell_multiple(df: pd.DataFrame) -> Dict:
    """Mayer Multiple & Puell Multiple (코인): 200일 MA 대비 가격, 일일 발행량 가치 / 연평균"""
    try:
        close = df["Close"].astype(float)
        ma200 = close.rolling(200).mean()
        mayer = float(close.iloc[-1] / ma200.iloc[-1]) if len(close)>200 and ma200.iloc[-1]!=0 else 1.0
        # Puell 근사: 거래량 * 가격 / 365일 평균
        vol = df["Volume"].astype(float)
        daily_issuance_value = close * vol / 1e6  # 간소화
        puell = float(daily_issuance_value.tail(1).values[0] / daily_issuance_value.rolling(365).mean().tail(1).values[0]) if len(daily_issuance_value)>365 else 1.0
        mayer_signal = "과열" if mayer>2.4 else "저평가" if mayer<0.8 else "중립"
        puell_signal = "과열" if puell>4 else "저평가" if puell<0.5 else "중립"
        score = 30 if mayer>2.4 else 70 if mayer<0.8 else 50
        return {"mayer": mayer, "puell": puell, "mayer_signal": mayer_signal, "puell_signal": puell_signal, "score": score}
    except Exception:
        return {"mayer": 1.0, "puell": 1.0, "mayer_signal": "중립", "puell_signal": "중립", "score": 50}

