@st.cache_data(show_spinner=False, ttl=3600)  # [P1] 네트워크 캐시 — 결과 dict/df는 picklable, TTL 내 재호출 시 재계산 생략
def calc_correlation_real_assets(df: pd.DataFrame, benchmarks: List[str] = ["SPY","QQQ","DXY","GLD","BTC-USD"]) -> Dict:
    """실시간 상관: 벤치마크 5개와 60일 상관 계산 (yfinance)"""
    try:
        import yfinance as yf
        close = df["Close"].astype(float)
        ret = close.pct_change()
        corrs = {}
        # [이슈8b] 5개 벤치마크 다운로드 병렬화 — 서로 무의존, corrs 매핑 결과 동일
        from concurrent.futures import ThreadPoolExecutor as _TPE
        def _corr_one(sym):
            try:
                bench = yf.download(sym, period="3mo", interval="1d", progress=False)["Close"].astype(float).pct_change()
                merged = pd.concat([ret, bench], axis=1, join="inner").dropna()
                if len(merged) >= 20:
                    return float(merged.corr().iloc[0, 1])
                return 0.0
            except Exception:
                return 0.0
        with _TPE(max_workers=5) as _pool:
            _vals = list(_pool.map(_corr_one, list(benchmarks)))
        corrs = dict(zip(benchmarks, _vals))
        # Risk-On: SPY/QQQ 양의 상관 + DXY 음의 상관
        risk_on_score = (corrs.get("SPY",0) + corrs.get("QQQ",0) - corrs.get("DXY",0)) / 3
        risk_on = risk_on_score > 0.3
        return {"correlations": corrs, "risk_on_score": risk_on_score, "risk_on": risk_on}
    except Exception:
        return {"correlations": {}, "risk_on_score": 0.0, "risk_on": True}

def calc_tabnet_catboost_stacking(df: pd.DataFrame, ind: Dict, forward_n: int = 10) -> Dict:
    """TabNet + CatBoost + LightGBM + Stacking 앙상블 (플레이스홀더, CatBoost/LightGBM 있으면 사용)"""
    try:
        feats = build_prob_feature_matrix(df, ind)
        if feats.empty or len(feats) < 150:
            return {"available": False, "reason": "피처 부족"}
        close = ind["close"].astype(float).reindex(df.index)
        fwd_ret = (close.shift(-forward_n) / close - 1.0)
        y = (fwd_ret > 0).astype(int)
        valid_idx = feats.index[feats.notna().all(axis=1) & y.notna()]
        if len(valid_idx) < 120:
            return {"available": False, "reason": "샘플 부족"}
        X = feats.loc[valid_idx]
        y_v = y.loc[valid_idx]

        from sklearn.ensemble import GradientBoostingClassifier, RandomForestClassifier
        from sklearn.linear_model import LogisticRegression

        models = {
            "gbm": GradientBoostingClassifier(random_state=42, n_estimators=100),
            "rf": RandomForestClassifier(random_state=42, n_estimators=120),
        }
        # CatBoost 시도
        try:
            import catboost as cb
            models["catboost"] = cb.CatBoostClassifier(random_state=42, iterations=100, depth=6, verbose=False)
        except Exception:
            pass
        # LightGBM 시도
        try:
            import lightgbm as lgb
            models["lgbm"] = lgb.LGBMClassifier(random_state=42, n_estimators=100)
        except Exception:
            pass

        # 학습
        results = {}
        for name, clf in models.items():
            try:
                clf.fit(X, y_v)
                acc = float((clf.predict(X) == y_v).mean())
                results[name] = {"model": clf, "acc": acc}
            except Exception as e:
                results[name] = {"error": str(e)[:100]}

        # Stacking: Logistic으로 메타-러너
        try:
            # 각 모델 예측 확률로 메타 피처
            meta_X = []
            for name, res in results.items():
                if "model" in res:
                    prob = res["model"].predict_proba(X)[:,1] if hasattr(res["model"], "predict_proba") else res["model"].predict(X)
                    meta_X.append(prob)
            if meta_X:
                meta_X = np.column_stack(meta_X)
                meta_learner = LogisticRegression(max_iter=500)
                meta_learner.fit(meta_X, y_v)
                meta_acc = float((meta_learner.predict(meta_X) == y_v).mean())
                return {"available": True, "models": results, "meta_acc": meta_acc, "n_samples": len(X), "meta_learner": meta_learner}
        except Exception as e:
            pass

        return {"available": True, "models": results, "n_samples": len(X)}
    except Exception as e:
        return {"available": False, "error": str(e)[:300]}

