def render_triple_barrier_backtest_improvement(bt: Dict, df: pd.DataFrame):
    """트리플 배리어 개선 (중복 방지용 재정의)"""
    try:
        with st.container(border=True):
            st.markdown("#### 🧪 Triple Barrier & 변동성 타깃팅 개선 (적중율 향상 제안)")
            st.markdown("**개선안:** CHOP <38.2 → 목표 7*ATR, ER <0.25 진입 금지, Connors <10 + KAMA 상회 추가매수, FVG mid 목표 조정")
            c1,c2,c3 = st.columns(3)
            c1.metric("Sharpe", f"{bt.get('sharpe',0):.2f}", "목표 +0.3")
            c2.metric("MDD", f"{bt.get('max_dd',0)*100:.1f}%", "목표 -4%p")
            c3.metric("Win%", f"{bt.get('win_rate',0):.1f}%", "목표 +3%p")
    except Exception as e:
        st.caption(f"Triple Barrier 오류: {e}")

