if scan_btn and enable_scanner:
    krx_scan_df = load_krx_stocks()
    if krx_scan_df is not None and not krx_scan_df.empty and FDR_AVAILABLE:
        target = krx_scan_df.copy()
        if scan_market != "전체":
            target = target[target['Market'].astype(str).str.contains(scan_market, na=False)]
        target = target.head(scan_limit)
        # ── [P1-7] 스캐너 병렬화: 종목별 score_symbol_scanner를 ThreadPool(4)로 병렬 실행
        # score_symbol_scanner 내부에는 st 호출이 없고, 다운로드는 @st.cache_data(yf_download_safe) 경유라 스레드 안전.
        # 결과 리스트는 어차피 종합점수로 정렬되므로 완료 순서 무관 — 기존 출력과 동일.
        from concurrent.futures import ThreadPoolExecutor, as_completed
        _scan_rows = list(target.iterrows())
        results = []
        with st.sidebar:
            prog = st.progress(0)
            status_box = st.empty()
        def _scan_one(item):
            _, row = item
            return row.get('Name', ''), score_symbol_scanner(row, start_date, end_date)
        with ThreadPoolExecutor(max_workers=4) as _scan_pool:
            _futures = [_scan_pool.submit(_scan_one, item) for item in _scan_rows]
            for i, _fut in enumerate(as_completed(_futures), start=1):
                try:
                    _name, res = _fut.result()
                except Exception:
                    _name, res = "", None  # 기존과 동일하게 실패 종목은 건씀뜀
                if res is not None:
                    results.append(res)
                status_box.caption(f"스캔 중: {_name} ({i}/{len(target)})")
                prog.progress(int(i / max(len(target), 1) * 100))
        status_box.empty()
        prog.empty()
        st.session_state.scanner_results = pd.DataFrame(results).sort_values('종합점수', ascending=False).reset_index(drop=True) if results else pd.DataFrame()
        st.session_state.scanner_meta = {"market": scan_market, "limit": scan_limit, "from": str(start_date), "to": str(end_date)}
    else:
        st.session_state.scanner_results = pd.DataFrame()
        st.session_state.scanner_meta = {"error": "스캐너 실행 불가"}

