# 금일/현재 대응 결론: 앱의 최우선 목적(추매/매도/관망)을 상단에 명확히 표시
if elite_priority_mode and elite_model.get("strong_buy"):
    today_decision = {"action": "금일 추매/매수 검토", "grade": "긴급 매수관찰", "status": "good", "reason": ", ".join(elite_model.get("buy_points", [])[:2]) or "엘리트 복합 매수조건 충족"}
elif elite_priority_mode and elite_model.get("strong_sell"):
    today_decision = {"action": "금일 매도/손절 우선", "grade": "긴급 방어", "status": "bad", "reason": ", ".join(elite_model.get("sell_points", [])[:2]) or "엘리트 복합 위험조건 충족"}
elif trade_plan["signal_grade"] in ["A", "B"] and scenario["bull_prob"] > scenario["bear_prob"] + 8 and analysis_reliability["score"] >= 65:
    today_decision = {"action": "눌림 확인 후 분할매수", "grade": "매수대기", "status": "good", "reason": trade_plan["tactical"]}
elif trade_plan["signal_grade"] in ["D"] or scenario["bear_prob"] > scenario["bull_prob"] + 8:
    today_decision = {"action": "신규매수 금지·방어", "grade": "매도/관망", "status": "bad", "reason": "하락 시나리오 또는 지지 이탈 리스크 우세"}
else:
    today_decision = {"action": "관망", "grade": "확인 대기", "status": "warn", "reason": "매수/매도 우위가 충분히 강하지 않습니다."}

# 신뢰도가 낮은 분석은 과도한 매수등급을 방지하고, 펀더멘털 과열/취약은 점수에 직접 반영
reliability_penalty = max(0.0, (70.0 - analysis_reliability["score"]) * 0.18)
if elite_priority_mode:
    # 엘리트강사 이론 1순위 모드: 기존 종합점수보다 엘리트 모델을 더 크게 반영
    blended_score = base_final_score * 0.35 + elite_model["score"] * 0.65
else:
    blended_score = base_final_score
final_score = round(float(np.clip(blended_score + fund_risk_adj["adj"] - reliability_penalty, 0, 100)), 1)
