    _mtf_boost = mtf_alignment.get("confidence_boost", 0)
    if _mtf_boost != 0:
        # score와 prob에 반영
        confluence_score["score"] = float(np.clip(confluence_score.get("score",50) + _mtf_boost, 0, 100))
        _p = confluence_score.get("prob", confluence_score["score"]/100.0)
        confluence_score["prob"] = float(np.clip(_p + _mtf_boost/100.0, 0.05, 0.95))
        confluence_score["prob_percent"] = round(confluence_score["prob"]*100,1)
        # CI도 소폭 조정
        confluence_score["prob_ci_lower"] = float(np.clip(confluence_score.get("prob_ci_lower", _p-0.15) + _mtf_boost/200.0, 0.0, 1.0))
        confluence_score["prob_ci_upper"] = float(np.clip(confluence_score.get("prob_ci_upper", _p+0.15) + _mtf_boost/200.0, 0.0, 1.0))

    # OBV / 수급 다이버전스 선행 신호 반영 (확률 가산)
    _div_boost = 0
