    if obv_divergence.get("type") == "bullish_regular":
        _div_boost += 6
        _div_reasons.append(f"OBV Bullish Divergence (+6) — {obv_divergence.get('message','')[:60]}")
    elif obv_divergence.get("type") == "bearish_regular":
        _div_boost -= 7
        _div_reasons.append(f"OBV Bearish Divergence (-7)")
    
    if smart_flow_div.get("type") in ["bullish_regular", "bullish_turning"]:
        _div_boost += 7
        _div_reasons.append(f"수급 Bullish Divergence (+7)")
    elif smart_flow_div.get("type") in ["bearish_regular", "bearish_turning"]:
        _div_boost -= 8
        _div_reasons.append(f"수급 Bearish Divergence (-8)")

