        confluence_score["prob_percent"] = round(confluence_score["prob"]*100,1)
        confluence_score["reasons"] = (confluence_score.get("reasons", [])[:4] + _div_reasons)[:6]
        confluence_score["divergence_boost"] = _div_boost

