def get_streak_days(series):
    if len(series)==0:
        return 0
    streak=0
    sign=1 if series.iloc[-1]>=0 else -1
    for v in series.values[::-1]:
        if (1 if v>=0 else -1)==sign:
            streak+=1
        else:
            break
    return streak*sign
