# [이슈7A] 전방참조 수정 — 이 함수는 원래 호출부(약 200줄 아래)보다 뒤에 정의돼 첫 실행 시
# name 'build_integrated_comprehensive_report' is not defined 오류가 났음. 정의를 호출부 앞으로 이동(본문 무수정).
def build_integrated_comprehensive_report(
    display_name: str,
    df: pd.DataFrame,
    ind: Dict,
    main_fib: Dict,
    recent_fib: Optional[Dict],
    level_table: pd.DataFrame,
    focus_fib: Dict,
    fib_template: Dict,
    confluence: List[Dict],
    best_pattern: Optional[Dict],
    pattern_result: Dict,
    trend_ctx: Dict,
    regime: Dict,
    factors: Dict,
    fib_score: float,
    elite_model: Dict,
    confluence_score: Dict,
    trade_plan: Dict,
    scenario: Dict,
    rsi_divergence: Dict,
    obv_divergence: Dict,
    smart_flow_div: Dict,
    mtf_alignment: Dict,
    smc_analysis: Dict,
    flow_div: Dict,
    flow_bias: str,
    investment_rating: Dict,
    final_score: float,
    today_decision: Dict,
    analysis_reliability: Dict,
    fund_risk_adj: Dict,
    position_sizing: Dict,
    alerts: List,
    unit: str,
    global_valuation: Optional[Dict] = None,  # [통합고도화] 밸류에이션 괴리 모듈
    bt: Optional[Dict] = None,               # [통합고도화] 백테스트 검증 모듈
) -> Dict:
    """
    모든 분석 모듈을 유기적으로 통합해 최종 종합 리포트를 생성.
    - 각 모듈의 점수/확률을 가중 평균해 통합 확률/점수 산출
    - 서사형 요약, 강점/약점, 리스크, 액션 플랜 포함
    """
    try:
        price = float(ind["close"].iloc[-1])
        atr = float(ind["atr"].iloc[-1])

        # ── 1. 모듈별 점수 정규화 (0~100) ──
        modules = {}

        # 추세 구조
        try:
            struct = trend_ctx.get("structure","")
            if "상승 정배열" in struct:
                modules["추세구조"] = 80
            elif "하락 역배열" in struct:
                modules["추세구조"] = 20
            else:
                modules["추세구조"] = 50
        except:
            modules["추세구조"] = 50

        # 레짐
        try:
            reg_name = regime.get("regime","")
            if "강한 추세장" in reg_name:
                modules["레짐"] = 80
            elif "추세장" in reg_name:
                modules["레짐"] = 70
            elif "박스권" in reg_name or "스퀴즈" in reg_name:
                modules["레짐"] = 50
            elif "하락" in reg_name:
                modules["레짐"] = 25
            elif "고변동" in reg_name:
                modules["레짐"] = 40
            else:
                modules["레짐"] = 50
        except:
            modules["레짐"] = 50

        # 멀티팩터
        try:
            modules["모멘텀"] = float(factors.get("momentum",50))
            modules["거래량"] = float(factors.get("volume",50))
            modules["타이밍"] = float(factors.get("timing",50))
            modules["재무"] = float(factors.get("quality",50))
            modules["밸류"] = float(factors.get("value",50))
            modules["피보위치"] = float(fib_score)
        except:
            pass

        # 엘리트 모델 (확률 기반)
        try:
            modules["엘리트"] = float(elite_model.get("score",50))
            elite_prob = float(elite_model.get("prob", modules["엘리트"]/100.0))
        except:
            modules["엘리트"] = 50
            elite_prob = 0.5

        # 컨플루언스
        try:
            modules["컨플루언스"] = float(confluence_score.get("score",50))
            confl_prob = float(confluence_score.get("prob", modules["컨플루언스"]/100.0))
        except:
            modules["컨플루언스"] = 50
            confl_prob = 0.5

        # 시나리오 (상승 확률)
        try:
            modules["시나리오_상승"] = float(scenario.get("bull_prob",33))
        except:
            modules["시나리오_상승"] = 33

        # 패턴
        try:
            if best_pattern:
                pd_dir = best_pattern.get("direction","중립")
                pd_conf = float(best_pattern.get("confidence",50))
                if pd_dir == "상승":
                    modules["패턴"] = 50 + pd_conf*0.3
                elif pd_dir == "하락":
                    modules["패턴"] = 50 - pd_conf*0.3
                else:
                    modules["패턴"] = 50
            else:
                modules["패턴"] = 50
        except:
            modules["패턴"] = 50

        # MTF
        try:
            if mtf_alignment.get("available"):
                if mtf_alignment.get("alignment"):
                    modules["MTF"] = 65 if mtf_alignment.get("weekly_trend")=="상승" else 45
                    if mtf_alignment.get("weekly_trend")=="상승" and mtf_alignment.get("daily_trend")=="상승":
                        modules["MTF"] = 75
                    elif mtf_alignment.get("weekly_trend")=="하락" and mtf_alignment.get("daily_trend")=="하락":
                        modules["MTF"] = 25
                else:
                    # 충돌 시 40점으로 낮춤
                    modules["MTF"] = 40
            else:
                modules["MTF"] = 50
        except:
            modules["MTF"] = 50

        # ── [통합고도화] 단기 스윙 피보 반영: 장기 70% + 단기 30% (동일 fib_position_score 재사용) ──
        try:
            if recent_fib and float(recent_fib.get("range", 0) or 0) > 0:
                _rr = (price - float(recent_fib["low"])) / float(recent_fib["range"])
                _rfs = float(fib_position_score(_rr))
                modules["피보위치"] = float(0.7 * modules.get("피보위치", float(fib_score)) + 0.3 * _rfs)
        except Exception:
            pass

        # ── [통합고도화] SMC·유동성 (오더블록/미충족 FVG 방향 우세) ──
        try:
            _smc = smc_analysis if isinstance(smc_analysis, dict) else {}
            if _smc.get("available") and (_smc.get("order_blocks") or _smc.get("fvgs")):
                _b = sum(1 for ob in (_smc.get("order_blocks") or []) if ob.get("type") == "bullish")
                _s = sum(1 for ob in (_smc.get("order_blocks") or []) if ob.get("type") == "bearish")
                _b += sum(1 for f in (_smc.get("fvgs") or []) if f.get("type") == "bullish")
                _s += sum(1 for f in (_smc.get("fvgs") or []) if f.get("type") == "bearish")
                modules["SMC유동성"] = float(np.clip(50 + (_b - _s) * 9, 0, 100))
            else:
                modules["SMC유동성"] = 50.0
        except Exception:
            modules["SMC유동성"] = 50.0

        # ── [통합고도화] 수급 흐름 (flow_div 다이버전스 + 외/기 5봉 편향) ──
        try:
            _fs = 50.0
            _fdt = (flow_div or {}).get("type") if isinstance(flow_div, dict) else None
            if _fdt == "bullish":
                _fs += 15
            elif _fdt == "bearish":
                _fs -= 15
            elif _fdt == "turning_positive":
                _fs += 8
            elif _fdt == "turning_negative":
                _fs -= 8
            if flow_bias == "순유입 우위":
                _fs += 10
            elif flow_bias == "순유출 우위":
                _fs -= 10
            modules["수급흐름"] = float(np.clip(_fs, 0, 100))
        except Exception:
            modules["수급흐름"] = 50.0

        # ── [통합고도화] 밸류에이션 괴리 (복합 적정가 대비 — 데이터 있을 때만 모듈 생성) ──
        try:
            _gv = global_valuation if isinstance(global_valuation, dict) else {}
            _fv = float(_gv.get("fair_value") or 0) if _gv.get("available") else 0.0
            if _fv > 0 and price > 0:
                _dev = (_fv - price) / price
                modules["밸류에이션괴리"] = float(np.clip(50.0 + _dev * 150.0, 0, 100))
        except Exception:
            modules.pop("밸류에이션괴리", None)

        # ── [통합고도화] 백테스트 검증 (공유 사전계산 bt — 진입 신호 있을 때만 모듈 생성) ──
        try:
            _bt = bt if isinstance(bt, dict) else {}
            if int(_bt.get("trades") or 0) > 0:
                _bs = 50.0
                _bs += (float(_bt.get("win_rate", 0) or 0) - 50.0) * 0.6   # 승률% 50% 기준 (최대 ±30)
                _bs += 12.0 if float(_bt.get("strategy_return", 0) or 0) > float(_bt.get("buyhold_return", 0) or 0) else -12.0
                _bs += 6.0 if float(_bt.get("max_dd", 0) or 0) > -0.15 else -6.0
                if float(_bt.get("sharpe", 0) or 0) >= 1.0:
                    _bs += 6.0
                elif float(_bt.get("sharpe", 0) or 0) < 0:
                    _bs -= 6.0
                if ((_bt.get("walk_forward") or {}).get("overfit_risk") == "높음"):
                    _bs -= 8.0
                modules["백테스트검증"] = float(np.clip(_bs, 0, 100))
        except Exception:
            modules.pop("백테스트검증", None)

        # ── [통합고도화] 패턴 합의 (best_pattern 외 전체 패턴의 방향 합의도) ──
        try:
            _plist = (pattern_result or {}).get("patterns") if isinstance(pattern_result, dict) else None
            if isinstance(_plist, list) and _plist:
                _pb = sum(1 for p in _plist if str(p.get("direction", "")) == "상승")
                _ps = sum(1 for p in _plist if str(p.get("direction", "")) == "하락")
                modules["패턴합의"] = float(np.clip(50.0 + (_pb - _ps) / max(1, len(_plist)) * 45.0, 0, 100))
        except Exception:
            modules.pop("패턴합의", None)

        # 다이버전스 (선행)
        try:
            div_score = 50
            if rsi_divergence.get("type") == "bullish_regular":
                div_score += 10
            elif rsi_divergence.get("type") == "bearish_regular":
                div_score -= 10
            if obv_divergence.get("type") == "bullish_regular":
                div_score += 8
            elif obv_divergence.get("type") == "bearish_regular":
                div_score -= 8
            if smart_flow_div.get("type") in ["bullish_regular","bullish_turning"]:
                div_score += 8
            elif smart_flow_div.get("type") in ["bearish_regular","bearish_turning"]:
                div_score -= 8
            modules["다이버전스"] = float(np.clip(div_score,0,100))
        except:
            modules["다이버전스"] = 50

        # 고적중률 모듈 (전세계 승률 60%+ 전략)
        try:
            # high_hitrate가 전역에 있으면 사용, 없으면 50
            _hh = 0
            try:
                _hh_dict = globals().get('high_hitrate') or locals().get('high_hitrate')
                if isinstance(_hh_dict, dict):
                    _hh = _hh_dict.get('score',50)
                else:
                    # 직접 계산 시도
                    _hh_dict = compute_high_hitrate_confluence(df, ind, level_table) if 'compute_high_hitrate_confluence' in globals() else {"score":50}
                    _hh = _hh_dict.get('score',50)
            except:
                _hh = 50
            modules["고적중률"] = float(np.clip(_hh,0,100))
        except:
            modules["고적중률"] = 50

        # ── 2. 가중치 정의 (레짐에 따라 자동 조정) ──
        base_weights = {
            "추세구조": 0.09,
            "레짐": 0.07,
            "모멘텀": 0.09,
            "거래량": 0.06,
            "타이밍": 0.07,
            "재무": 0.03,
            "밸류": 0.03,
            "피보위치": 0.05,
            "엘리트": 0.13,
            "컨플루언스": 0.08,
            "시나리오_상승": 0.04,
            "패턴": 0.03,
            "MTF": 0.04,
            "다이버전스": 0.03,
            "고적중률": 0.16,
            # ── [통합고도화] 신규 모듈 가중치 (총합 1.22 → 아래 정규화로 자동 조정) ──
            "SMC유동성": 0.06,
            "수급흐름": 0.05,
            "밸류에이션괴리": 0.04,
            "백테스트검증": 0.05,
            "패턴합의": 0.02,
        }

        # 레짐 기반 가중치 자동 전환
        reg_name = regime.get("regime","")
        weights = base_weights.copy()
        if "추세" in reg_name:
            # 추세장: 추세추종형 가중 ↑, 평균회귀 ↓
            weights["추세구조"] += 0.03
            weights["모멘텀"] += 0.02
            weights["엘리트"] += 0.02
            weights["타이밍"] -= 0.02
            weights["피보위치"] -= 0.01
        elif "박스" in reg_name or "스퀴즈" in reg_name:
            # 횡보장: 평균회귀형 우대
            weights["타이밍"] += 0.03
            weights["피보위치"] += 0.02
            weights["패턴"] += 0.02
            weights["모멘텀"] -= 0.02
            weights["추세구조"] -= 0.02

        # [통합고도화] 데이터 부재로 생성 안 된 조걸부 모듈(밸류에이션/백테스트/패턴합의)은 가중치에서 제외 후 재정규화
        weights = {k: v for k, v in weights.items() if k in modules}
        # 정규화
        total_w = sum(weights.values())
        weights = {k: v/total_w for k,v in weights.items()}

        # ── 3. 통합 점수/확률 계산 ──
        integrated_score = 0.0
        for k,w in weights.items():
            v = modules.get(k,50)
            # 시나리오_상승은 확률이므로 0~100 유지
            integrated_score += v * w

        # 확률은 엘리트+컨플루언스+시나리오 중심으로 가중 평균
        prob_weights = {
            "엘리트": 0.33,
            "컨플루언스": 0.23,
            "시나리오_상승": 0.19,
            "MTF": 0.09,
            "다이버전스": 0.09,
            "SMC유동성": 0.035,   # [통합고도화]
            "수급흐름": 0.035,     # [통합고도화]
        }
        integrated_prob = 0.0
        pw_total = 0.0
        for k,w in prob_weights.items():
            if k not in modules:  # [통합고도화] 미생성 조걸부 모듈은 블렌드에서 제외
                continue
            if k == "시나리오_상승":
                v = modules.get(k,50)/100.0
            elif k in ["엘리트","컨플루언스"]:
                # 이미 확률로 변환
                if k == "엘리트":
                    v = elite_prob
                else:
                    v = confl_prob
            else:
                v = modules.get(k,50)/100.0
            integrated_prob += v * w
            pw_total += w
        integrated_prob = integrated_prob / pw_total if pw_total>0 else 0.5

        # 신뢰구간: 각 모듈 분산 기반 근사
        vals = [modules.get(k,50)/100.0 for k in modules]
        std = float(np.std(vals)) if len(vals)>1 else 0.15
        ci_low = max(0.05, integrated_prob - std*0.8)
        ci_high = min(0.95, integrated_prob + std*0.8)

        # 최종 등급/액션 결정 (기존 등급 로직 재사용)
        if integrated_score >= 78:
            final_grade = "강력매수"
            final_action = "적극 매수/보유"
            final_status = "good"
        elif integrated_score >= 65:
            final_grade = "매수"
            final_action = "눌림/돌파 시 분할 매수"
            final_status = "good"
        elif integrated_score >= 50:
            final_grade = "중립"
            final_action = "관망/확인 후 진입"
            final_status = "warn"
        elif integrated_score >= 35:
            final_grade = "비중축소"
            final_action = "방어/비중 축소"
            final_status = "warn"
        else:
            final_grade = "매도우위"
            final_action = "매도/방어 우선"
            final_status = "bad"

        # ── 4. 강점/약점 분석 ──
        sorted_modules = sorted(modules.items(), key=lambda x: x[1], reverse=True)
        strengths = [f"{k} {v:.0f}점" for k,v in sorted_modules[:4] if v>=65]
        weaknesses = [f"{k} {v:.0f}점" for k,v in sorted_modules[-4:] if v<=45]
        # ── [통합고도화] 4-2. 신호 합의도 (모듈 점수 분산 기반) ──
        _mv = [float(v) / 100.0 for v in modules.values()]
        consensus_std = float(np.std(_mv)) if len(_mv) > 1 else 0.0
        if consensus_std <= 0.12:
            consensus_label, consensus_status = "강한 합의", "good"
        elif consensus_std <= 0.20:
            consensus_label, consensus_status = "보통 합의", "warn"
        else:
            consensus_label, consensus_status = "혼조·충돌", "bad"

        # ── [통합고도화] 4-3. 교차 검증 매트릭스 (통합 판정 ↔ 개별 분석 정합성) ──
        def _gdir(g):
            g = str(g or "")
            if "강력매수" in g or ("매수" in g and "비중" not in g) or g == "상승":
                return "상승"
            if "매도" in g or "축소" in g or "방어" in g or g == "하락":
                return "하락"
            return "중립"

        def _verdict(a, b):
            if a == "중립" or b == "중립":
                return "🟡 부분일치"
            return "✅ 일치" if a == b else "🔴 충돌"

        int_dir = _gdir(final_grade)
        cross_checks = []
        try:
            _irg = investment_rating.get("grade", "") if isinstance(investment_rating, dict) else ""
            if _irg:
                cross_checks.append({"검증 항목": "통합 판정 ↔ AI 투자등급", "A": f"{final_grade}({int_dir})", "B": f"{_irg}({_gdir(_irg)})", "판정": _verdict(int_dir, _gdir(_irg))})
        except Exception:
            pass
        try:
            _td = today_decision if isinstance(today_decision, dict) else {}
            _td_dir = {"good": "상승", "bad": "하락", "warn": "중립"}.get(str(_td.get("status", "warn")), "중립")
            cross_checks.append({"검증 항목": "통합 판정 ↔ 오늘의 결정", "A": f"{final_grade}({int_dir})", "B": f"{_td.get('grade','-')}·{str(_td.get('action','-'))[:18]}({_td_dir})", "판정": _verdict(int_dir, _td_dir)})
        except Exception:
            pass
        try:
            _e_sc = float(elite_model.get("score", 50))
            _e_dir = "상승" if _e_sc >= 65 else "하락" if _e_sc <= 40 else "중립"
            _c_sc = float(confluence_score.get("score", 50))
            _c_dir = "상승" if _c_sc >= 65 else "하락" if _c_sc <= 40 else "중립"
            cross_checks.append({"검증 항목": "엘리트 ↔ 컨플루언스", "A": f"엘리트 {elite_model.get('grade','-')}({_e_dir})", "B": f"컨플루언스 {confluence_score.get('label','-')}({_c_dir})", "판정": _verdict(_e_dir, _c_dir)})
        except Exception:
            pass
        try:
            _btd = bt if isinstance(bt, dict) else {}
            if int(_btd.get("trades") or 0) > 0:
                _edge = "우위" if float(_btd.get("strategy_return", 0) or 0) > float(_btd.get("buyhold_return", 0) or 0) else "열위"
                _agree = (_edge == "우위" and int_dir == "상승") or (_edge == "열위" and int_dir == "하락")
                cross_checks.append({"검증 항목": "통합 판정 ↔ 백테스트 엣지", "A": f"{final_grade}({int_dir})", "B": f"전략 {_edge} · 승률 {float(_btd.get('win_rate',0)):.0f}% · {int(_btd.get('trades',0))}회 · 과적합 {(_btd.get('walk_forward') or {}).get('overfit_risk','-')}", "판정": "✅ 일치" if _agree else ("🟡 부분일치" if int_dir == "중립" else "🔴 충돌")})
            else:
                cross_checks.append({"검증 항목": "통합 판정 ↔ 백테스트 엣지", "A": f"{final_grade}({int_dir})", "B": "기간 내 진입 신호 없음", "판정": "ℹ️ 참고"})
        except Exception:
            pass
        try:
            _ma = mtf_alignment if isinstance(mtf_alignment, dict) else {}
            if _ma.get("available"):
                _wt = str(_ma.get("weekly_trend", ""))
                _w_dir = "상승" if "상승" in _wt else "하락" if "하락" in _wt else "중립"
                cross_checks.append({"검증 항목": "통합 판정 ↔ 주봉 추세(MTF)", "A": f"{final_grade}({int_dir})", "B": f"주봉 {_wt or '-'}({_w_dir})", "판정": _verdict(int_dir, _w_dir)})
        except Exception:
            pass


        # ── 5. 서사형 요약 생성 ──
        summary_lines = []
        summary_lines.append(f"{display_name}는 현재 **{trend_ctx.get('structure','중립')}** 구조, 레짐은 **{regime.get('regime','전환 국면')}**입니다.")
        summary_lines.append(f"엘리트 모델은 **{elite_model.get('grade','중립')}** ({elite_model.get('prob_percent', elite_model.get('score',50)):.0f}% 확률), 컨플루언스는 **{confluence_score.get('label','보통')}** ({confluence_score.get('prob_percent', confluence_score.get('score',50)):.0f}%)입니다.")
        if focus_fib:
            summary_lines.append(f"핵심 피보 레벨은 **Fib {focus_fib.get('ratio')} ({fmt_price(focus_fib.get('price',0))}{unit})** , 현재가는 스윙 내 { ( (price - main_fib['low'])/(main_fib['range']+1e-9)*100 ):.1f}% 위치입니다.")
        if best_pattern:
            summary_lines.append(f"대표 차트 패턴은 **{best_pattern.get('name')}** / 방향 {best_pattern.get('direction')} / 신뢰도 {best_pattern.get('confidence',0):.0f}점 / 단계 {best_pattern.get('stage', best_pattern.get('status','관찰'))}입니다.")
        if mtf_alignment.get("available"):
            if mtf_alignment.get("alignment"):
                summary_lines.append(f"MTF: 일봉 **{mtf_alignment.get('daily_trend')}** vs 주봉 **{mtf_alignment.get('weekly_trend')}** 일치 → 신뢰도 +{mtf_alignment.get('confidence_boost',0)}")
            else:
                summary_lines.append(f"MTF: **추세 충돌** — 일봉 {mtf_alignment.get('daily_trend')} vs 주봉 {mtf_alignment.get('weekly_trend')} 불일치 → {mtf_alignment.get('conflict_warning','주의')}")
        if rsi_divergence.get("type") != "none" or obv_divergence.get("type") != "none" or smart_flow_div.get("type") not in ["none","",None]:
            div_msgs = []
            if rsi_divergence.get("type") != "none":
                div_msgs.append(f"RSI {rsi_divergence.get('type')}")
            if obv_divergence.get("type") != "none":
                div_msgs.append(f"OBV {obv_divergence.get('type')}")
            if smart_flow_div.get("type") not in ["none","",None]:
                div_msgs.append(f"수급 {smart_flow_div.get('type')}")
            summary_lines.append(f"선행 다이버전스: {', '.join(div_msgs)} 감지 — 가격보다 거래량/수급이 먼저 방향 전환 중입니다.")
        summary_lines.append(f"시나리오는 상승 {scenario.get('bull_prob',0):.0f}% / 횡보 {scenario.get('base_prob',0):.0f}% / 하락 {scenario.get('bear_prob',0):.0f}%이며, 통합 점수는 **{integrated_score:.1f}점**, 상승 확률은 **{integrated_prob*100:.1f}% (CI {ci_low*100:.0f}~{ci_high*100:.0f}%)**입니다.")

        summary_lines.append(f"모듈 간 신호 합의도는 **{consensus_label}** (편차 {consensus_std*100:.0f}pp · 총 {len(modules)}개 모듈)입니다.")
        try:
            _smc_d = smc_analysis if isinstance(smc_analysis, dict) else {}
            if _smc_d.get("available") and (_smc_d.get("order_blocks") or _smc_d.get("fvgs")):
                summary_lines.append(f"SMC·유동성: {_smc_d.get('message','')}")
        except Exception:
            pass
        try:
            if isinstance(flow_div, dict) and flow_div.get("available") and flow_div.get("type") not in (None, "none"):
                summary_lines.append(f"수급 흐름: {flow_div.get('type')} — {str(flow_div.get('message',''))[:70]}")
        except Exception:
            pass
        try:
            _gv2 = global_valuation if isinstance(global_valuation, dict) else {}
            _fv2 = float(_gv2.get("fair_value") or 0) if _gv2.get("available") else 0.0
            if _fv2 > 0 and price > 0:
                summary_lines.append(f"복합 적정가 {fmt_price(_fv2)}{unit} 대비 현재가는 {(_fv2 / price - 1) * 100:+.1f}% 괴리입니다.")
        except Exception:
            pass
        try:
            _bt3 = bt if isinstance(bt, dict) else {}
            if int(_bt3.get("trades") or 0) > 0:
                summary_lines.append(f"백테스트 검증: 승률 {float(_bt3.get('win_rate',0)):.0f}% / 전략 {float(_bt3.get('strategy_return',0))*100:+.1f}% vs 보유 {float(_bt3.get('buyhold_return',0))*100:+.1f}% / 과적합 위험 {(_bt3.get('walk_forward') or {}).get('overfit_risk','-')}")
        except Exception:
            pass

        # ── 6. 리스크 요약 ──
        risk_lines = []
        if analysis_reliability.get("score",100) < 70:
            risk_lines.append(f"분석 신뢰도 {analysis_reliability.get('score',0):.0f}점 — {', '.join(analysis_reliability.get('warnings',[])[:2])}")
        if fund_risk_adj.get("adj",0) < -3:
            risk_lines.append(f"펀더멘털 리스크: {', '.join(fund_risk_adj.get('reasons',[])[:2])}")
        if mtf_alignment.get("alignment") == False:
            risk_lines.append(mtf_alignment.get("conflict_warning","추세 충돌"))
        if scenario.get("bear_prob",0) > 40:
            risk_lines.append(f"하락 시나리오 확률 {scenario.get('bear_prob',0):.0f}%로 방어 필요")
        # ── [통합고도화] 신규 모듈 기반 리스크 경보 ──
        try:
            _gvr = global_valuation if isinstance(global_valuation, dict) else {}
            _fvr = float(_gvr.get("fair_value") or 0) if _gvr.get("available") else 0.0
            if _fvr > 0 and price > 0:
                _devr = (_fvr - price) / price
                if _devr < -0.20:
                    risk_lines.append(f"적정가 대비 고평가 괴리 {_devr*100:.1f}% — 밸류에이션 부담")
                elif _devr > 0.30:
                    risk_lines.append(f"적정가 대비 대폭 저평가({_devr*100:+.1f}%) — 밸류 트랩 여부도 함께 점검")
        except Exception:
            pass
        if consensus_status == "bad":
            risk_lines.append(f"모듈 간 신호 혼조 (편차 {consensus_std*100:.0f}pp) — 방향성 확신이 낮은 구간")
        try:
            _btr = bt if isinstance(bt, dict) else {}
            if int(_btr.get("trades") or 0) > 0 and (_btr.get("walk_forward") or {}).get("overfit_risk") == "높음":
                risk_lines.append("백테스트 walk-forward 과적합 위험 '높음' — 전략 신뢰 할인 필요")
        except Exception:
            pass
        if modules.get("SMC유동성", 50) <= 35:
            risk_lines.append("SMC·유동성: 하방 오더블록/FVG 우세 — 하방 유동성 쏠림 주의")
        # alerts 중 hot
        for sev, icon, msg in alerts:
            if sev == "hot":
                risk_lines.append(f"{icon} {msg}")

        # ── 7. 최종 액션 플랜 (Phase 5 수치화 재사용) ──
        action_plan = {
            "integrated_score": integrated_score,
            "integrated_prob": integrated_prob,
            "ci_low": ci_low,
            "ci_high": ci_high,
            "grade": final_grade,
            "action": final_action,
            "status": final_status,
            "reduce_pct": trade_plan.get("reduce_pct",0),
            "add_buy_pct": trade_plan.get("add_buy_pct",0),
            "add_buy_condition": trade_plan.get("add_buy_condition","-"),
            "stop_condition": trade_plan.get("stop_execution_condition","-"),
            "support1": trade_plan.get("support1"),
            "resist1": trade_plan.get("resist1"),
            "stop": trade_plan.get("stop"),
            "target1": trade_plan.get("target1"),
            "target2": trade_plan.get("target2"),
            "target3": trade_plan.get("target3"),
        }

        return {
            "modules": modules,
            "weights": weights,
            "integrated_score": integrated_score,
            "integrated_prob": integrated_prob,
            "ci_low": ci_low,
            "ci_high": ci_high,
            "final_grade": final_grade,
            "final_action": final_action,
            "final_status": final_status,
            "summary_lines": summary_lines,
            "strengths": strengths,
            "weaknesses": weaknesses,
            "risk_lines": risk_lines[:6],
            "action_plan": action_plan,
            "consensus_std": consensus_std,
            "consensus_label": consensus_label,
            "consensus_status": consensus_status,
            "cross_checks": cross_checks,
            "price": price,
            "atr": atr,
        }
    except Exception as e:
        return {
            "modules": {},
            "weights": {},
            "integrated_score": 50.0,
            "integrated_prob": 0.5,
            "ci_low": 0.35,
            "ci_high": 0.65,
            "final_grade": "중립",
            "final_action": "관망",
            "final_status": "warn",
            "summary_lines": [f"통합 분석 오류: {e}"],
            "strengths": [],
            "weaknesses": [],
            "risk_lines": [],
            "action_plan": {},
            "consensus_std": 0.0,
            "consensus_label": "중립",
            "consensus_status": "warn",
            "cross_checks": [],
            "price": 0,
            "atr": 0,
            "error": str(e),
        }


