                        if cur_price is None:
                            cur_price = pf_avg
                            prev_price = pf_avg

                        # 해외 주식 원화 환산 처리 (기존 로직 유지)
                        if not is_kr_pf and pf_avg > cur_price * 100:
                            rate = fetch_usd_krw_rate()
                            cur_price *= rate
                            prev_price *= rate

                        # NXT/KRX 정보 저장
                        _cur_nxt = krx_nxt_info.get("nxt") if is_kr_pf else None
                        _cur_krx = krx_nxt_info.get("krx") if is_kr_pf else None
                        _cur_integrated = krx_nxt_info.get("integrated") if is_kr_pf else cur_price

                        exists = False
                        for item in st.session_state.portfolio:
                            if item["name"] == pf_name:
                                item["qty"] = int(pf_qty)
                                item["avg"] = float(pf_avg)
                                item["cur"] = float(cur_price)
                                item["prev"] = float(prev_price)
