            if st.session_state.portfolio:
                total_investment = sum([float(e["avg"]) * int(e["qty"]) for e in st.session_state.portfolio])
                total_current_val = sum([float(e["cur"]) * int(e["qty"]) for e in st.session_state.portfolio])
                total_pnl = total_current_val - total_investment
                total_return_pct = (total_current_val / total_investment - 1) * 100 if total_investment > 0 else 0

                st.markdown("<h4 style='color:#38bdf8; margin-top:20px;'>💎 종합 포트폴리오 요약</h4>", unsafe_allow_html=True)
                render_dashboard_cards([
                    {"icon": "🏦", "title": "총 매입 금액", "value": f"{total_investment:,.0f}", "caption": "원금 총액", "status": "info"},
                    {"icon": "📈", "title": "총 평가 금액", "value": f"{total_current_val:,.0f}", "caption": "현재 잔고 가치", "status": "good" if total_return_pct >= 0 else "bad"},
                    {"icon": "💰", "title": "총 평가 손익", "value": f"{total_pnl:+,.0f}", "caption": f"수익률 {total_return_pct:+.2f}%", "status": "good" if total_pnl > 0 else "bad"},
                ], cols_per_row=(1 if compact_mode else 3))

