                render_dashboard_cards(rebalance["cards"], cols_per_row=(1 if compact_mode else 3))

                st.markdown("<h4 style='color:#38bdf8; margin-top:20px;'>🔍 개별 포지션 심층 분석 및 실시간 에디터</h4>", unsafe_allow_html=True)
                st.markdown("<span style='font-size:15px;color:#cbd5e1;'>※ <span style='background-color:rgba(251,191,36,0.25);color:white;padding:2px 4px;border-radius:3px;'>노란색 틴트 셀</span>(종목명, 잔고수량, 매입가)을 <b>더블클릭</b>하여 직접 간편수정하고 엔터를 치세요. 이후 아래 저장 버튼을 누르면 AI 분석이 갱신됩니다.</span>", unsafe_allow_html=True)

                master_df_list = []
                pf_pie_labels = []
                pf_pie_values = []

                for e in st.session_state.portfolio:
                    nm = str(e.get("name", ""))
                    qt = int(e.get("qty", 0))
                    av = float(e.get("avg", 0))
                    cu = float(e.get("cur", 0))
                    pr = float(e.get("prev", cu))
                    # NXT/KRX 분리 가격 (없으면 cur로 fallback)
                    cu_nxt = float(e.get("cur_nxt", cu))
                    cu_krx = float(e.get("cur_krx", cu))
                    cu_int = float(e.get("cur_integrated", cu))

                    pnl_amt = (cu - av) * qt
                    pnl_pct = (cu / av - 1) * 100 if av > 0 else 0.0
                    cur_val = cu * qt
                    weight = (cur_val / total_current_val) * 100 if total_current_val > 0 else 0

                    day_change = cu - pr
                    day_change_pct = (cu / pr - 1) * 100 if pr > 0 else 0.0

                    if pnl_pct >= 20: grade, action = "S", "트레일링 스탑 가동 후 수익 극대화"
                    elif pnl_pct >= 8: grade, action = "A", "일부 익절 후 추세 보유 검토"
                    elif pnl_pct >= 2: grade, action = "B", "양호. 본절 컷 설정 후 보유"
                    elif pnl_pct > -3: grade, action = "C", "중립/횡보. 변동성 유의"
                    elif pnl_pct > -10:
                        if weight > 30: grade, action = "D", "리스크 경고. 기술적 반등 시 비중 축소"
                        else: grade, action = "D", "추가 하락 시 손절선 엄수"
